static void orlix_tcti_guest_profile_matches_elf_auxv(struct kunit *test)
{
	const unsigned long previous_unproved_hwcap =
		HWCAP_FP | HWCAP_ASIMD | HWCAP_AES | HWCAP_PMULL |
		HWCAP_SHA1 | HWCAP_SHA2 | HWCAP_CRC32 | HWCAP_SHA3 |
		HWCAP_SM3 | HWCAP_SM4 | HWCAP_SHA512;

	KUNIT_EXPECT_EQ(test, 8, ORLIX_EL0_ARCH_MAJOR);
	KUNIT_EXPECT_EQ(test, 0, ORLIX_EL0_ARCH_MINOR);
	KUNIT_EXPECT_EQ(test, 0UL, (unsigned long)ELF_HWCAP);
	KUNIT_EXPECT_NE(test, previous_unproved_hwcap,
			(unsigned long)ELF_HWCAP);
	KUNIT_EXPECT_EQ(test, 0UL, (unsigned long)ELF_HWCAP2);
}

static void orlix_tcti_complete_target_inventory_is_kernel_visible(
	struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, 4350U, ORLIX_TCTI_A64_GENERATED_SOURCE_COUNT);
	KUNIT_EXPECT_EQ(test, 0U,
			ORLIX_TCTI_A64_GENERATED_CLASSIFICATION_COMPLETE);
	KUNIT_EXPECT_EQ(test, 0U, ORLIX_TCTI_A64_GENERATED_ISA_COMPLETE);
	KUNIT_EXPECT_EQ(test, (size_t)ORLIX_TCTI_A64_GENERATED_SOURCE_COUNT,
			ARRAY_SIZE(orlix_tcti_a64_generated_rows));
	KUNIT_EXPECT_STREQ(test, "vFATAp1-A",
			  ORLIX_TCTI_A64_GENERATED_ARCHITECTURE);
	KUNIT_EXPECT_STREQ(test, "818", ORLIX_TCTI_A64_GENERATED_BUILD);
	KUNIT_EXPECT_STREQ(test, "2026-06_rel",
			  ORLIX_TCTI_A64_GENERATED_REFERENCE);
	KUNIT_EXPECT_STREQ(test, "2.9.5", ORLIX_TCTI_A64_GENERATED_SCHEMA);
	KUNIT_EXPECT_STREQ(test,
			  "a1ad2c6538a47cd97d8762791ac5af88"
			  "bce1d5f6aff096c9b77aef853e76acfe",
			  ORLIX_TCTI_A64_GENERATED_INSTRUCTIONS_SHA256);
}

static void orlix_tcti_runtime_profile_uses_full_target_without_promotion(
	struct kunit *test)
{
	struct orlix_tcti_runtime_projection_result projection = { };

	KUNIT_EXPECT_EQ(test, 0,
			orlix_tcti_runtime_projection_audit(&projection));
	KUNIT_EXPECT_EQ(test, (size_t)4350, projection.target_leaf_count);
	KUNIT_EXPECT_EQ(test,
			(size_t)(ORLIX_TCTI_A64_GENERATED_SOURCE_COUNT -
				 ORLIX_TCTI_A64_GENERATED_UNCLASSIFIED_COUNT),
			projection.classified_leaf_count);
	KUNIT_EXPECT_EQ(test, (size_t)4350, projection.unproved_leaf_count);
	KUNIT_EXPECT_EQ(test, 0UL, projection.proved_hwcap);
	KUNIT_EXPECT_EQ(test, 0UL, projection.proved_hwcap2);
	KUNIT_EXPECT_EQ(test, (size_t)11, projection.mapping_count);
	KUNIT_EXPECT_EQ(test, (size_t)0,
			projection.missing_feature_mapping_count);
	KUNIT_EXPECT_EQ(test, (size_t)11,
			projection.unadvertised_mapping_count);
	KUNIT_EXPECT_EQ(test, (size_t)11,
			projection.unadvertised_incomplete_feature_count);
}

static struct orlix_tcti_runtime_projection_leaf *
orlix_tcti_runtime_projection_complete_test_ledger(struct kunit *test,
	const char *const *first_feature, const char *const *second_feature)
{
	struct orlix_tcti_runtime_projection_leaf *leaves;
	size_t index;

	leaves = kunit_kcalloc(test, ORLIX_TCTI_RUNTIME_PROJECTION_MAX_TARGET_LEAVES,
			       sizeof(*leaves), GFP_KERNEL);
	if (!leaves)
		return NULL;
	for (index = 0; index < ORLIX_TCTI_RUNTIME_PROJECTION_MAX_TARGET_LEAVES;
	     index++) {
		leaves[index].name = "PINNED_SOURCE_LEAF";
		leaves[index].classification =
			ORLIX_TCTI_RUNTIME_LEAF_REQUIRED_EL0;
		leaves[index].proof = "resolved-proof";
		leaves[index].source_bound = true;
		leaves[index].proved = true;
	}
	leaves[0].features = first_feature;
	leaves[0].feature_count = 1;
	leaves[1].features = first_feature;
	leaves[1].feature_count = 1;
	leaves[2].features = second_feature;
	leaves[2].feature_count = 1;
	return leaves;
}

static void orlix_tcti_runtime_projection_rejects_advertised_incomplete_feature(
	struct kunit *test)
{
	static const char *const first_feature[] = { "FEAT_FIRST" };
	static const char *const second_feature[] = { "FEAT_SECOND" };
	static const struct orlix_tcti_runtime_projection_capability capabilities[] = {
		{ ORLIX_TCTI_RUNTIME_CAPABILITY_HWCAP, BIT(0), "FEAT_FIRST" },
		{ ORLIX_TCTI_RUNTIME_CAPABILITY_HWCAP, BIT(1), "FEAT_SECOND" },
	};
	struct orlix_tcti_runtime_projection_leaf *leaves;
	struct orlix_tcti_runtime_projection_ledger ledger;
	const struct orlix_tcti_runtime_projection_profile profile = {
		.hwcap = BIT(1),
	};
	struct orlix_tcti_runtime_projection_result projection = { };

	leaves = orlix_tcti_runtime_projection_complete_test_ledger(test,
			first_feature, second_feature);
	KUNIT_ASSERT_NOT_NULL(test, leaves);
	leaves[2].source_bound = false;
	ledger = (struct orlix_tcti_runtime_projection_ledger) {
		.leaves = leaves,
		.leaf_count = ORLIX_TCTI_RUNTIME_PROJECTION_MAX_TARGET_LEAVES,
		.target_leaf_count = ORLIX_TCTI_RUNTIME_PROJECTION_MAX_TARGET_LEAVES,
	};

	KUNIT_EXPECT_EQ(test, -EINVAL, orlix_tcti_runtime_projection_audit_ledger(
			&ledger, &profile, capabilities, ARRAY_SIZE(capabilities),
			&projection));
	KUNIT_EXPECT_EQ(test, BIT(1), projection.advertised_without_proof_hwcap);
	KUNIT_EXPECT_EQ(test, (size_t)ORLIX_TCTI_RUNTIME_PROJECTION_MAX_TARGET_LEAVES,
			projection.target_leaf_count);
	KUNIT_EXPECT_EQ(test, (size_t)1, projection.unproved_leaf_count);
	KUNIT_EXPECT_EQ(test,
			(size_t)ORLIX_TCTI_RUNTIME_PROJECTION_MAX_TARGET_LEAVES - 1,
			projection.source_bound_leaf_count);
}

static void orlix_tcti_runtime_projection_keeps_unadvertised_gap_in_target(
	struct kunit *test)
{
	static const char *const first_feature[] = { "FEAT_FIRST" };
	static const char *const second_feature[] = { "FEAT_SECOND" };
	static const struct orlix_tcti_runtime_projection_capability capabilities[] = {
		{ ORLIX_TCTI_RUNTIME_CAPABILITY_HWCAP, BIT(0), "FEAT_FIRST" },
		{ ORLIX_TCTI_RUNTIME_CAPABILITY_HWCAP, BIT(1), "FEAT_SECOND" },
	};
	struct orlix_tcti_runtime_projection_leaf *leaves;
	struct orlix_tcti_runtime_projection_ledger ledger;
	const struct orlix_tcti_runtime_projection_profile profile = {
		.hwcap = BIT(0),
	};
	struct orlix_tcti_runtime_projection_result projection = { };

	leaves = orlix_tcti_runtime_projection_complete_test_ledger(test,
			first_feature, second_feature);
	KUNIT_ASSERT_NOT_NULL(test, leaves);
	leaves[2].classification = ORLIX_TCTI_RUNTIME_LEAF_UNCLASSIFIED;
	leaves[2].proof = NULL;
	leaves[2].source_bound = false;
	leaves[2].proved = false;
	ledger = (struct orlix_tcti_runtime_projection_ledger) {
		.leaves = leaves,
		.leaf_count = ORLIX_TCTI_RUNTIME_PROJECTION_MAX_TARGET_LEAVES,
		.target_leaf_count = ORLIX_TCTI_RUNTIME_PROJECTION_MAX_TARGET_LEAVES,
	};

	KUNIT_ASSERT_EQ(test, 0, orlix_tcti_runtime_projection_audit_ledger(
			&ledger, &profile, capabilities, ARRAY_SIZE(capabilities),
			&projection));
	KUNIT_EXPECT_EQ(test, (size_t)ORLIX_TCTI_RUNTIME_PROJECTION_MAX_TARGET_LEAVES,
			projection.target_leaf_count);
	KUNIT_EXPECT_EQ(test, (size_t)1, projection.unproved_leaf_count);
	KUNIT_EXPECT_EQ(test, (size_t)1,
			projection.unadvertised_incomplete_feature_count);
	KUNIT_EXPECT_EQ(test, (size_t)1, projection.unadvertised_mapping_count);
}

static void orlix_tcti_runtime_projection_initializes_rejected_ledger_result(
	struct kunit *test)
{
	static const char *const first_feature[] = { "FEAT_FIRST" };
	static const struct orlix_tcti_runtime_projection_leaf leaf = {
		.name = "REDUCED_SOURCE_LEAF",
		.features = first_feature,
		.feature_count = ARRAY_SIZE(first_feature),
		.classification = ORLIX_TCTI_RUNTIME_LEAF_REQUIRED_EL0,
		.proof = "resolved-proof",
		.source_bound = true,
		.proved = true,
	};
	static const struct orlix_tcti_runtime_projection_capability capability = {
		.word = ORLIX_TCTI_RUNTIME_CAPABILITY_HWCAP,
		.bit = BIT(0),
		.feature = "FEAT_FIRST",
	};
	const struct orlix_tcti_runtime_projection_ledger ledger = {
		.leaves = &leaf,
		.leaf_count = 1,
		.target_leaf_count = 1,
	};
	const struct orlix_tcti_runtime_projection_profile profile = {
		.hwcap = BIT(0),
	};
	struct orlix_tcti_runtime_projection_result projection;

	memset(&projection, 0xff, sizeof(projection));
	KUNIT_EXPECT_EQ(test, -EINVAL, orlix_tcti_runtime_projection_audit_ledger(
			&ledger, &profile, &capability, 1, &projection));
	KUNIT_EXPECT_EQ(test, BIT(0), projection.advertised_hwcap);
	KUNIT_EXPECT_EQ(test, 0UL, projection.advertised_hwcap2);
	KUNIT_EXPECT_EQ(test, (size_t)1, projection.target_leaf_count);
	KUNIT_EXPECT_EQ(test, (size_t)0, projection.mapping_count);
	KUNIT_EXPECT_EQ(test, (size_t)0, projection.unproved_leaf_count);
	KUNIT_EXPECT_EQ(test, 0UL, projection.advertised_without_proof_hwcap);
}

static unsigned long orlix_tcti_isa_extension_hwcap(
	enum orlix_tcti_isa_extension extension)
{
	switch (extension) {
	case ORLIX_TCTI_ISA_BASE:
		return 0;
	case ORLIX_TCTI_ISA_FP:
		return HWCAP_FP;
	case ORLIX_TCTI_ISA_ASIMD:
		return HWCAP_ASIMD;
	case ORLIX_TCTI_ISA_AES:
		return HWCAP_AES;
	case ORLIX_TCTI_ISA_SHA:
		return HWCAP_SHA1 | HWCAP_SHA2;
	case ORLIX_TCTI_ISA_SHA512:
		return HWCAP_SHA512;
	case ORLIX_TCTI_ISA_SHA3:
		return HWCAP_SHA3;
	case ORLIX_TCTI_ISA_SM3:
		return HWCAP_SM3;
	case ORLIX_TCTI_ISA_SM4:
		return HWCAP_SM4;
	case ORLIX_TCTI_ISA_PMULL:
		return HWCAP_PMULL;
	case ORLIX_TCTI_ISA_CRC32:
		return HWCAP_CRC32;
	case ORLIX_TCTI_ISA_EXTENSION_COUNT:
		return 0;
	}
	return 0;
}

static void orlix_tcti_isa_coverage_inventory_is_machine_auditable(struct kunit *test)
{
	bool extension_present[ORLIX_TCTI_ISA_EXTENSION_COUNT] = {};
	unsigned long covered_hwcap = 0;
	size_t gaps = 0;
	size_t i;
	size_t j;

	KUNIT_ASSERT_EQ(test, (size_t)ORLIX_TCTI_ISA_FAMILY_COUNT,
			ARRAY_SIZE(orlix_tcti_isa_coverage));

	for (i = 0; i < ARRAY_SIZE(orlix_tcti_isa_coverage); i++) {
		const struct orlix_tcti_isa_family_coverage *family =
			&orlix_tcti_isa_coverage[i];

		KUNIT_EXPECT_EQ(test, (int)i, (int)family->id);
		KUNIT_EXPECT_NOT_NULL(test, family->name);
		KUNIT_EXPECT_NOT_NULL(test, family->decoder);
		KUNIT_EXPECT_NOT_NULL(test, family->kunit);
		KUNIT_EXPECT_NE(test, '\0', family->name[0]);
		KUNIT_EXPECT_NE(test, '\0', family->decoder[0]);
		if (family->status == ORLIX_TCTI_ISA_LOCAL_COVERAGE_COMPLETE) {
			KUNIT_EXPECT_NE(test, '\0', family->kunit[0]);
		} else {
			gaps++;
		}

		for (j = i + 1; j < ARRAY_SIZE(orlix_tcti_isa_coverage); j++)
			KUNIT_EXPECT_NE(test, 0, strcmp(family->name,
						       orlix_tcti_isa_coverage[j].name));
	}

	for (i = 0; i < ARRAY_SIZE(orlix_tcti_isa_coverage); i++) {
		const struct orlix_tcti_isa_family_coverage *family =
			&orlix_tcti_isa_coverage[i];

		KUNIT_ASSERT_LT(test, family->extension,
			ORLIX_TCTI_ISA_EXTENSION_COUNT);
		extension_present[family->extension] = true;
		covered_hwcap |= orlix_tcti_isa_extension_hwcap(family->extension);
	}
	for (i = 0; i < ARRAY_SIZE(extension_present); i++)
		KUNIT_EXPECT_TRUE_MSG(test, extension_present[i],
			"OrlixTCTI ISA extension %zu has no coverage row", i);
	KUNIT_EXPECT_EQ(test,
		(unsigned long)(HWCAP_FP | HWCAP_ASIMD | HWCAP_AES |
			HWCAP_PMULL | HWCAP_SHA1 | HWCAP_SHA2 | HWCAP_CRC32 |
			HWCAP_SHA3 | HWCAP_SM3 | HWCAP_SM4 | HWCAP_SHA512),
		covered_hwcap);
	KUNIT_EXPECT_EQ(test, 0UL, (unsigned long)ELF_HWCAP);

	kunit_info(test,
		   "OrlixTCTI local decoder-family coverage: %zu/%zu covered, %zu gaps",
		   ARRAY_SIZE(orlix_tcti_isa_coverage) - gaps,
		   ARRAY_SIZE(orlix_tcti_isa_coverage), gaps);
	KUNIT_EXPECT_EQ(test,
			(size_t)ORLIX_TCTI_ISA_EXPECTED_LOCAL_DECODER_GAPS,
			gaps);
}

static void orlix_tcti_configured_profile_encodings_are_decoded(struct kunit *test)
{
	size_t unsupported = 0;
	size_t i;

	for (i = 0; i < ARRAY_SIZE(orlix_tcti_a64_encoding_inventory); i++) {
		const struct orlix_tcti_a64_encoding_inventory_entry *encoding =
			&orlix_tcti_a64_encoding_inventory[i];
		struct orlix_tcti_decoded_instruction decoded;

		KUNIT_ASSERT_EQ_MSG(test, encoding->pattern,
			encoding->witness & encoding->mask,
			"configured A64 witness violates %s", encoding->name);
		decoded = orlix_tcti_decode_aarch64(encoding->witness);
		if (decoded.decode_class != ORLIX_TCTI_DECODE_UNSUPPORTED)
			continue;
		if (!strcmp(encoding->name, "SYSL_RC_systeminstrs"))
			continue;
		kunit_err(test, "configured A64 encoding is unsupported: %s (%#x)",
			  encoding->name, encoding->witness);
		unsupported++;
	}

	kunit_info(test, "OrlixTCTI configured A64 encodings: %zu/%zu decoded, %zu gaps",
		   ARRAY_SIZE(orlix_tcti_a64_encoding_inventory) - unsupported,
		   ARRAY_SIZE(orlix_tcti_a64_encoding_inventory), unsupported);
	KUNIT_EXPECT_EQ(test, 0UL, (unsigned long)unsupported);

	for (i = 0; i < ARRAY_SIZE(orlix_tcti_a64_unsupported_encoding_inventory);
	     i++) {
		const struct orlix_tcti_a64_encoding_inventory_entry *encoding =
			&orlix_tcti_a64_unsupported_encoding_inventory[i];
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(encoding->witness);

		KUNIT_EXPECT_TRUE_MSG(test,
			decoded.decode_class == ORLIX_TCTI_DECODE_UNSUPPORTED ||
			decoded.decode_class == ORLIX_TCTI_DECODE_UNDEFINED,
			"non-EL0 or undefined A64 encoding was accepted: %s class=%u",
			encoding->name, decoded.decode_class);
	}
}

static const struct orlix_tcti_a64_condition_inventory_entry *
orlix_tcti_test_find_inventory_condition(const char *name)
{
	size_t i;

	for (i = 0; i < ARRAY_SIZE(orlix_tcti_a64_condition_inventory); i++)
		if (!strcmp(name, orlix_tcti_a64_condition_inventory[i].name))
			return &orlix_tcti_a64_condition_inventory[i];

	return NULL;
}

static const struct orlix_tcti_a64_encoding_inventory_entry *
orlix_tcti_test_find_inventory_encoding(const char *name)
{
	size_t i;

	for (i = 0; i < ARRAY_SIZE(orlix_tcti_a64_encoding_inventory); i++)
		if (!strcmp(name, orlix_tcti_a64_encoding_inventory[i].name))
			return &orlix_tcti_a64_encoding_inventory[i];
	for (i = 0; i < ARRAY_SIZE(orlix_tcti_a64_unsupported_encoding_inventory); i++)
		if (!strcmp(name,
			    orlix_tcti_a64_unsupported_encoding_inventory[i].name))
			return &orlix_tcti_a64_unsupported_encoding_inventory[i];

	return NULL;
}

static void orlix_tcti_positive_pair_inventory_uses_nonoverlap_registers(
	struct kunit *test)
{
	size_t overlap_sensitive_witnesses = 0;
	size_t i;

	for (i = 0; i < ARRAY_SIZE(orlix_tcti_a64_encoding_inventory); i++) {
		const struct orlix_tcti_a64_encoding_inventory_entry *encoding =
			&orlix_tcti_a64_encoding_inventory[i];
		u32 instruction;
		u8 mode;
		u8 rn;
		u8 rt;
		u8 rt2;

		if (strcmp(encoding->operation_id, "LDNP_fpsimd") &&
		    strcmp(encoding->operation_id, "LDP_fpsimd") &&
		    strcmp(encoding->operation_id, "STP_fpsimd"))
			continue;

		instruction = encoding->witness;
		mode = (instruction >> 23) & 0x3U;
		if (!(instruction & BIT(22)) && mode != 1 && mode != 3)
			continue;

		overlap_sensitive_witnesses++;
		rn = (instruction >> 5) & 0x1fU;
		rt = instruction & 0x1fU;
		rt2 = (instruction >> 10) & 0x1fU;

		KUNIT_EXPECT_EQ_MSG(test, (u8)0, rt,
			"positive pair witness has unexpected Rt: %s",
			encoding->name);
		KUNIT_EXPECT_EQ_MSG(test, (u8)1, rn,
			"positive pair witness has unexpected Rn: %s",
			encoding->name);
		KUNIT_EXPECT_EQ_MSG(test, (u8)2, rt2,
			"positive pair witness has unexpected Rt2: %s",
			encoding->name);
	}

	KUNIT_ASSERT_GT(test, overlap_sensitive_witnesses, (size_t)0);
}

static bool orlix_tcti_test_inventory_condition_holds(
	const struct orlix_tcti_a64_condition_inventory_entry *condition,
	u32 instruction)
{
	switch (condition->kind) {
	case ORLIX_TCTI_A64_CONDITION_RM_NOT_31:
		return ((instruction >> 16) & 0x1fU) != 31;
	case ORLIX_TCTI_A64_CONDITION_IMMH_NOT_ZERO:
		return ((instruction >> 19) & 0xfU) != 0;
	case ORLIX_TCTI_A64_CONDITION_OPTION_NOT_3:
		return ((instruction >> 13) & 0x7U) != 3;
	case ORLIX_TCTI_A64_CONDITION_RT_BELOW_24:
		return (instruction & 0x1fU) < 24;
	case ORLIX_TCTI_A64_CONDITION_SYSTEM_ENCODING: {
		u32 op1 = (instruction >> 16) & 0x7U;
		u32 op2 = (instruction >> 5) & 0x7U;

		return op1 != 0 || op2 > 2;
	}
	}

	return false;
}

static bool orlix_tcti_test_required_inventory_accepts(u32 instruction)
{
	size_t i;

	for (i = 0; i < ARRAY_SIZE(orlix_tcti_a64_encoding_inventory); i++) {
		const struct orlix_tcti_a64_encoding_inventory_entry *encoding =
			&orlix_tcti_a64_encoding_inventory[i];
		const struct orlix_tcti_a64_condition_inventory_entry *condition;

		if ((instruction & encoding->mask) != encoding->pattern)
			continue;
		condition = orlix_tcti_test_find_inventory_condition(encoding->name);
		if (!condition ||
		    orlix_tcti_test_inventory_condition_holds(condition, instruction))
			return true;
	}

	return false;
}

static size_t orlix_tcti_test_condition_false_variant_count(
	enum orlix_tcti_a64_condition_kind kind)
{
	switch (kind) {
	case ORLIX_TCTI_A64_CONDITION_RM_NOT_31:
	case ORLIX_TCTI_A64_CONDITION_OPTION_NOT_3:
		return 1;
	case ORLIX_TCTI_A64_CONDITION_IMMH_NOT_ZERO:
	case ORLIX_TCTI_A64_CONDITION_RT_BELOW_24:
		return 8;
	case ORLIX_TCTI_A64_CONDITION_SYSTEM_ENCODING:
		return 48;
	}

	return 0;
}

static u32 orlix_tcti_test_condition_false_variant(
	enum orlix_tcti_a64_condition_kind kind, u32 witness, size_t variant)
{
	switch (kind) {
	case ORLIX_TCTI_A64_CONDITION_RM_NOT_31:
		return (witness & ~(0x1fU << 16)) | (31U << 16);
	case ORLIX_TCTI_A64_CONDITION_IMMH_NOT_ZERO:
		return (witness & ~(0x7fU << 16)) | ((u32)variant << 16);
	case ORLIX_TCTI_A64_CONDITION_OPTION_NOT_3:
		return (witness & ~(0x7U << 13)) | (3U << 13);
	case ORLIX_TCTI_A64_CONDITION_RT_BELOW_24:
		return (witness & ~0x1fU) | (24U + (u32)variant);
	case ORLIX_TCTI_A64_CONDITION_SYSTEM_ENCODING: {
		u32 crm = (u32)(variant / 3);
		u32 op2 = (u32)(variant % 3);

		return (witness & ~((0x7U << 16) | (0xfU << 8) |
				    (0x7U << 5))) |
		       (crm << 8) | (op2 << 5);
	}
	}

	return witness;
}

static void orlix_tcti_configured_profile_leaf_conditions_are_exact(
	struct kunit *test)
{
	size_t checked = 0;
	size_t i;

	for (i = 0; i < ARRAY_SIZE(orlix_tcti_a64_condition_inventory); i++) {
		const struct orlix_tcti_a64_condition_inventory_entry *condition =
			&orlix_tcti_a64_condition_inventory[i];
		const struct orlix_tcti_a64_encoding_inventory_entry *encoding =
			orlix_tcti_test_find_inventory_encoding(condition->name);
		size_t variants;
		size_t variant;

		KUNIT_ASSERT_NOT_NULL_MSG(test, encoding,
			"missing condition source %s", condition->name);
		KUNIT_ASSERT_TRUE_MSG(test,
			orlix_tcti_test_inventory_condition_holds(condition,
						     encoding->witness),
			"condition witness rejected for %s", condition->name);
		variants = orlix_tcti_test_condition_false_variant_count(condition->kind);
		KUNIT_ASSERT_GT_MSG(test, variants, 0UL,
			"unknown condition kind for %s", condition->name);

		for (variant = 0; variant < variants; variant++) {
			u32 instruction = orlix_tcti_test_condition_false_variant(
				condition->kind, encoding->witness, variant);
			bool expected =
				orlix_tcti_test_required_inventory_accepts(instruction);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);

			KUNIT_EXPECT_EQ_MSG(test, encoding->pattern,
				instruction & encoding->mask,
				"condition variant left %s encoding space",
				condition->name);
			KUNIT_EXPECT_FALSE_MSG(test,
				orlix_tcti_test_inventory_condition_holds(condition,
							     instruction),
				"condition variant remained valid for %s",
				condition->name);
			KUNIT_EXPECT_EQ_MSG(test, expected,
				decoded.decode_class != ORLIX_TCTI_DECODE_UNSUPPORTED,
				"condition routing mismatch for %s variant %zu (%#x)",
				condition->name, variant, instruction);
			checked++;
		}
	}

	kunit_info(test, "OrlixTCTI Arm leaf conditions: %zu predicates, %zu false variants checked",
		   ARRAY_SIZE(orlix_tcti_a64_condition_inventory), checked);
}

static u32 orlix_tcti_test_encode_exception_generation(u8 op1, u16 imm16, u8 ll)
{
	return 0xd4000000U | ((u32)op1 << 21) | ((u32)imm16 << 5) | ll;
}

static void orlix_tcti_decode_covers_complete_exception_generation_family(
	struct kunit *test)
{
	static const u16 boundary_immediates[] = {
		0, 1, 0x7fff, 0x8000, U16_MAX,
	};
	static const struct {
		u8 op1;
		u8 ll;
		enum orlix_tcti_decode_class decode_class;
	} el0_exits[] = {
		{ 0, 1, ORLIX_TCTI_DECODE_SVC },
		{ 1, 0, ORLIX_TCTI_DECODE_BRK },
		{ 2, 0, ORLIX_TCTI_DECODE_HLT },
	};
	u32 imm;
	u8 op1;
	u8 ll;

	for (imm = 0; imm <= U16_MAX; imm++) {
		unsigned int exit;

		for (exit = 0; exit < ARRAY_SIZE(el0_exits); exit++) {
			u32 instruction = orlix_tcti_test_encode_exception_generation(
				el0_exits[exit].op1, imm, el0_exits[exit].ll);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);

			if (decoded.decode_class != el0_exits[exit].decode_class ||
			    decoded.instruction != instruction ||
			    decoded.imm16 != imm) {
				KUNIT_FAIL(test,
					   "EL0 exception mismatch op1=%u ll=%u imm=%#x instruction=%#x class=%u decoded_instruction=%#x decoded_imm=%#x",
					   el0_exits[exit].op1,
					   el0_exits[exit].ll, imm, instruction,
					   decoded.decode_class,
					   decoded.instruction, decoded.imm16);
				return;
			}
		}
	}

	for (op1 = 0; op1 < 8; op1++) {
		for (ll = 0; ll < 4; ll++) {
			unsigned int boundary;

			if ((op1 == 0 && ll == 1) ||
			    (op1 == 1 && ll == 0) ||
			    (op1 == 2 && ll == 0))
				continue;

			for (boundary = 0;
			     boundary < ARRAY_SIZE(boundary_immediates);
			     boundary++) {
				u32 instruction =
					orlix_tcti_test_encode_exception_generation(
						op1,
						boundary_immediates[boundary], ll);
				struct orlix_tcti_decoded_instruction decoded =
					orlix_tcti_decode_aarch64(instruction);

				if (decoded.decode_class != ORLIX_TCTI_DECODE_UNSUPPORTED &&
				    decoded.decode_class != ORLIX_TCTI_DECODE_UNDEFINED) {
					KUNIT_FAIL(test,
						   "accepted non-EL0 exception op1=%u ll=%u imm=%#x instruction=%#x class=%u",
						   op1, ll,
						   boundary_immediates[boundary],
						   instruction, decoded.decode_class);
					return;
				}
				if (decoded.instruction != instruction) {
					KUNIT_FAIL(test,
						   "exception instruction mismatch op1=%u ll=%u imm=%#x expected=%#x actual=%#x",
						   op1, ll,
						   boundary_immediates[boundary],
						   instruction,
						   decoded.instruction);
					return;
				}
			}
		}
	}
}

