static u32 orlix_tcti_test_load_literal_instruction(bool simd_fp, u8 opc,
					      s32 imm19, u8 rt)
{
	return 0x18000000U | ((u32)opc << 30) |
	       (simd_fp ? BIT(26) : 0) |
	       (((u32)imm19 & 0x7ffffU) << 5) | rt;
}

static void orlix_tcti_decode_exhaustive_load_literal_family(struct kunit *test)
{
	static const s32 immediates[] = {
		-(s32)BIT(18), -(s32)BIT(18) + 1, -1, 0, 1, BIT(18) - 2,
		BIT(18) - 1,
	};
	u8 simd_fp;
	u8 opc;
	size_t i;

	for (simd_fp = 0; simd_fp < 2; simd_fp++) {
		for (opc = 0; opc < 4; opc++) {
			for (i = 0; i < ARRAY_SIZE(immediates); i++) {
				struct orlix_tcti_decoded_instruction decoded;
				bool legal = !simd_fp || opc < 3;

				decoded = orlix_tcti_decode_aarch64(
					orlix_tcti_test_load_literal_instruction(
						simd_fp, opc, immediates[i], 17));
				if (!legal) {
					KUNIT_EXPECT_EQ(test,
						ORLIX_TCTI_DECODE_UNSUPPORTED,
						decoded.decode_class);
					continue;
				}

				KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL,
						decoded.decode_class);
				KUNIT_EXPECT_EQ(test, 17, decoded.rt);
				KUNIT_EXPECT_EQ(test,
						(s64)immediates[i] * sizeof(u32),
						decoded.memory_offset);
				KUNIT_EXPECT_EQ(test, simd_fp, decoded.simd_fp);
				KUNIT_EXPECT_EQ(test, opc == 3,
						decoded.prefetch);
				KUNIT_EXPECT_EQ(test, opc != 3, decoded.load);

				if (simd_fp) {
					KUNIT_EXPECT_EQ(test, 1U << (opc + 2),
							decoded.access_size);
					KUNIT_EXPECT_EQ(test,
							decoded.access_size,
							decoded.result_size);
				} else if (opc == 0) {
					KUNIT_EXPECT_EQ(test, sizeof(u32),
							decoded.access_size);
					KUNIT_EXPECT_EQ(test, sizeof(u32),
							decoded.result_size);
				} else if (opc == 1) {
					KUNIT_EXPECT_EQ(test, sizeof(u64),
							decoded.access_size);
					KUNIT_EXPECT_EQ(test, sizeof(u64),
							decoded.result_size);
				} else if (opc == 2) {
					KUNIT_EXPECT_EQ(test, sizeof(u32),
							decoded.access_size);
					KUNIT_EXPECT_EQ(test, sizeof(u64),
							decoded.result_size);
					KUNIT_EXPECT_TRUE(test,
							decoded.sign_extend_load);
				}
			}
		}
	}
}

static void orlix_tcti_decode_load_literal_all_fields(struct kunit *test)
{
	u8 rt;
	u8 bit;

	for (rt = 0; rt < 32; rt++) {
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(orlix_tcti_test_load_literal_instruction(
				false, 0, 0, rt));

		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL,
				decoded.decode_class);
		KUNIT_EXPECT_EQ(test, rt, decoded.rt);
	}

	for (bit = 0; bit < 19; bit++) {
		s32 immediate = BIT(bit);
		struct orlix_tcti_decoded_instruction decoded;

		decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_load_literal_instruction(
			false, 0, immediate, 0));
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL,
				decoded.decode_class);
		KUNIT_EXPECT_EQ(test,
				bit == 18 ? -(s64)BIT(18) * sizeof(u32) :
					    (s64)immediate * sizeof(u32),
				decoded.memory_offset);
	}
}

static void orlix_tcti_decode_load_literal_fixed_mask_boundaries(
	struct kunit *test)
{
	const u32 fixed_mask = 0x3b000000U;
	const u32 instruction =
		orlix_tcti_test_load_literal_instruction(false, 0, 0, 0);
	u8 bit;

	for (bit = 0; bit < 32; bit++) {
		struct orlix_tcti_decoded_instruction decoded;

		if (!(fixed_mask & BIT(bit)))
			continue;

		decoded = orlix_tcti_decode_aarch64(instruction ^ BIT(bit));
		KUNIT_EXPECT_NE(test, ORLIX_TCTI_DECODE_LOAD_LITERAL,
				decoded.decode_class);
	}
}

static void orlix_tcti_decode_recognizes_load_literal_class(struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;

	decoded = orlix_tcti_decode_aarch64(0x18000000U); /* ldr w0, . */
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL, decoded.decode_class);
	KUNIT_EXPECT_EQ(test, 4, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 4, decoded.result_size);

	decoded = orlix_tcti_decode_aarch64(0x58000021U); /* ldr x1, .+4 */
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL, decoded.decode_class);
	KUNIT_EXPECT_EQ(test, 1, decoded.rt);
	KUNIT_EXPECT_EQ(test, 4LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, 8, decoded.access_size);

	decoded = orlix_tcti_decode_aarch64(0x98ffffe2U); /* ldrsw x2, .-4 */
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL, decoded.decode_class);
	KUNIT_EXPECT_EQ(test, -4LL, decoded.memory_offset);
	KUNIT_EXPECT_TRUE(test, decoded.sign_extend_load);

	decoded = orlix_tcti_decode_aarch64(0xd8000000U); /* prfm pldl1keep, . */
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL, decoded.decode_class);
	KUNIT_EXPECT_TRUE(test, decoded.prefetch);
	KUNIT_EXPECT_FALSE(test, decoded.load);

	decoded = orlix_tcti_decode_aarch64(0x1c000003U); /* ldr s3, . */
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL, decoded.decode_class);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 4, decoded.access_size);

	decoded = orlix_tcti_decode_aarch64(0x5c000004U); /* ldr d4, . */
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL, decoded.decode_class);
	KUNIT_EXPECT_EQ(test, 8, decoded.access_size);

	decoded = orlix_tcti_decode_aarch64(0x9c000005U); /* ldr q5, . */
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL, decoded.decode_class);
	KUNIT_EXPECT_EQ(test, 16, decoded.access_size);

	decoded = orlix_tcti_decode_aarch64(0xdc000000U);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED, decoded.decode_class);
}

static void orlix_tcti_gadget_executes_load_literal_state_transitions(struct kunit *test)
{
	struct orlix_tcti_gadget_word
		program[ORLIX_TCTI_SINGLE_INSTRUCTION_PROGRAM_WORDS];
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = { 0 };
	unsigned long fault_address = 0;
	unsigned long mapped;
	u64 value = 0x8877665544332211ULL;
	s32 signed_value = -12345;
	size_t word_count;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	ret = orlix_tcti_write_user_data(current->mm, mapped + 128, &value,
				   sizeof(value));
	KUNIT_ASSERT_EQ(test, 0, ret);
	regs.pc = mapped + 64;
	decoded = orlix_tcti_decode_aarch64(0x58000200U); /* ldr x0, .+64 */
	ret = orlix_tcti_lower_decoded_instruction(&decoded, program,
					     ARRAY_SIZE(program), &word_count);
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_execute_gadget_program(current->mm, &regs, program,
					  word_count, &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, value, regs.regs[0]);
	KUNIT_EXPECT_EQ(test, mapped + 68, regs.pc);
	KUNIT_EXPECT_EQ(test, mapped + 128, fault_address);

	ret = orlix_tcti_write_user_data(current->mm, mapped + 132, &signed_value,
				   sizeof(signed_value));
	KUNIT_ASSERT_EQ(test, 0, ret);
	regs.pc = mapped + 68;
	decoded = orlix_tcti_decode_aarch64(0x98000201U); /* ldrsw x1, .+64 */
	ret = orlix_tcti_lower_decoded_instruction(&decoded, program,
					     ARRAY_SIZE(program), &word_count);
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_execute_gadget_program(current->mm, &regs, program,
					  word_count, &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, (u64)(s64)signed_value, regs.regs[1]);
	KUNIT_EXPECT_EQ(test, mapped + 72, regs.pc);

	regs.pc = mapped + 72;
	decoded = orlix_tcti_decode_aarch64(0xd8000000U);
	ret = orlix_tcti_lower_decoded_instruction(&decoded, program,
					     ARRAY_SIZE(program), &word_count);
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_execute_gadget_program(NULL, &regs, program, word_count,
					  &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, mapped + 76, regs.pc);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_gadget_executes_complete_load_literal_family(
	struct kunit *test)
{
	static const struct {
		bool simd_fp;
		u8 opc;
		bool prefetch;
		u64 expected_low;
		u64 expected_high;
	} cases[] = {
		{ false, 0, false, 0x89abcdefULL, 0 },
		{ false, 1, false, 0x8877665589abcdefULL, 0 },
		{ false, 2, false, 0xffffffff89abcdefULL, 0 },
		{ false, 3, true, 0, 0 },
		{ true, 0, false, 0x89abcdefULL, 0 },
		{ true, 1, false, 0x8877665589abcdefULL, 0 },
		{ true, 2, false, 0x8877665589abcdefULL,
		  0x0123456789abcdefULL },
	};
	const u64 memory[2] = {
		0x8877665589abcdefULL,
		0x0123456789abcdefULL,
	};
	unsigned long mapped;
	unsigned long target;
	size_t i;
	int ret;

	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));
	target = mapped + 256;
	ret = orlix_tcti_write_user_data(current->mm, target, memory, sizeof(memory));
	KUNIT_ASSERT_EQ(test, 0, ret);

	for (i = 0; i < ARRAY_SIZE(cases); i++) {
		struct orlix_tcti_gadget_word
			program[ORLIX_TCTI_SINGLE_INSTRUCTION_PROGRAM_WORDS];
		struct orlix_tcti_decoded_instruction decoded;
		struct pt_regs regs;
		unsigned long fault_address = ~0UL;
		size_t word_count = 0;

		memset(&regs, 0, sizeof(regs));
		regs.pc = mapped + 128;
		regs.regs[7] = 0xa5a5a5a5a5a5a5a5ULL;
		regs.regs[9] = 0x1122334455667788ULL;
		regs.sp = 0x8877665544332210ULL;
		regs.pstate = PSR_N_BIT | PSR_C_BIT;
		current->thread.user_simd[14] = 0xa5a5a5a5a5a5a5a5ULL;
		current->thread.user_simd[15] = 0x5a5a5a5a5a5a5a5aULL;
		current->thread.user_simd[62] = 0x0f1e2d3c4b5a6978ULL;
		current->thread.user_simd[63] = 0x8796a5b4c3d2e1f0ULL;

		decoded = orlix_tcti_decode_aarch64(
			orlix_tcti_test_load_literal_instruction(cases[i].simd_fp,
				cases[i].opc, 32, 7));
		KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_LOAD_LITERAL,
				decoded.decode_class);
		ret = orlix_tcti_lower_decoded_instruction(&decoded, program,
				ARRAY_SIZE(program), &word_count);
		KUNIT_ASSERT_EQ(test, 0, ret);
		ret = orlix_tcti_execute_gadget_program(current->mm, &regs, program,
				word_count, &fault_address);

		KUNIT_ASSERT_EQ(test, 0, ret);
		KUNIT_EXPECT_EQ(test, mapped + 132, regs.pc);
		KUNIT_EXPECT_EQ(test, 0x1122334455667788ULL, regs.regs[9]);
		KUNIT_EXPECT_EQ(test, 0x8877665544332210ULL, regs.sp);
		KUNIT_EXPECT_EQ(test, PSR_N_BIT | PSR_C_BIT, regs.pstate);
		KUNIT_EXPECT_EQ(test, 0x0f1e2d3c4b5a6978ULL,
				current->thread.user_simd[62]);
		KUNIT_EXPECT_EQ(test, 0x8796a5b4c3d2e1f0ULL,
				current->thread.user_simd[63]);

		if (cases[i].prefetch) {
			KUNIT_EXPECT_EQ(test, 0xa5a5a5a5a5a5a5a5ULL,
					regs.regs[7]);
			KUNIT_EXPECT_EQ(test, 0xa5a5a5a5a5a5a5a5ULL,
					current->thread.user_simd[14]);
			KUNIT_EXPECT_EQ(test, 0x5a5a5a5a5a5a5a5aULL,
					current->thread.user_simd[15]);
			KUNIT_EXPECT_EQ(test, ~0UL, fault_address);
		} else if (cases[i].simd_fp) {
			KUNIT_EXPECT_EQ(test, 0xa5a5a5a5a5a5a5a5ULL,
					regs.regs[7]);
			KUNIT_EXPECT_EQ(test, cases[i].expected_low,
					current->thread.user_simd[14]);
			KUNIT_EXPECT_EQ(test, cases[i].expected_high,
					current->thread.user_simd[15]);
			KUNIT_EXPECT_EQ(test, target, fault_address);
		} else {
			KUNIT_EXPECT_EQ(test, cases[i].expected_low,
					regs.regs[7]);
			KUNIT_EXPECT_EQ(test, 0xa5a5a5a5a5a5a5a5ULL,
					current->thread.user_simd[14]);
			KUNIT_EXPECT_EQ(test, 0x5a5a5a5a5a5a5a5aULL,
					current->thread.user_simd[15]);
			KUNIT_EXPECT_EQ(test, target, fault_address);
		}
	}

	{
		struct orlix_tcti_gadget_word
			program[ORLIX_TCTI_SINGLE_INSTRUCTION_PROGRAM_WORDS];
		struct orlix_tcti_decoded_instruction decoded;
		struct pt_regs regs;
		unsigned long fault_address = 0;
		size_t word_count = 0;

		memset(&regs, 0, sizeof(regs));
		regs.pc = mapped + 128;
		regs.regs[30] = 0x1122334455667788ULL;
		regs.sp = 0x8877665544332210ULL;
		decoded = orlix_tcti_decode_aarch64(
			orlix_tcti_test_load_literal_instruction(false, 0, 32, 31));
		ret = orlix_tcti_lower_decoded_instruction(&decoded, program,
				ARRAY_SIZE(program), &word_count);
		KUNIT_ASSERT_EQ(test, 0, ret);
		ret = orlix_tcti_execute_gadget_program(current->mm, &regs, program,
				word_count, &fault_address);
		KUNIT_ASSERT_EQ(test, 0, ret);
		KUNIT_EXPECT_EQ(test, 0x1122334455667788ULL, regs.regs[30]);
		KUNIT_EXPECT_EQ(test, 0x8877665544332210ULL, regs.sp);
		KUNIT_EXPECT_EQ(test, mapped + 132, regs.pc);
		KUNIT_EXPECT_EQ(test, target, fault_address);
	}

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_gadget_reports_load_literal_faults(struct kunit *test)
{
	static const struct {
		bool simd_fp;
		u8 opc;
	} cases[] = {
		{ false, 0 },
		{ true, 2 },
	};
	unsigned long mapped;
	size_t i;
	int ret;

	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_NONE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	for (i = 0; i < ARRAY_SIZE(cases); i++) {
		struct orlix_tcti_gadget_word
			program[ORLIX_TCTI_SINGLE_INSTRUCTION_PROGRAM_WORDS];
		struct orlix_tcti_decoded_instruction decoded;
		struct pt_regs regs;
		unsigned long fault_address = 0;
		size_t word_count = 0;

		memset(&regs, 0, sizeof(regs));
		regs.pc = mapped;
		regs.regs[7] = 0x1122334455667788ULL;
		current->thread.user_simd[14] = 0x0123456789abcdefULL;
		current->thread.user_simd[15] = 0xfedcba9876543210ULL;
		decoded = orlix_tcti_decode_aarch64(
			orlix_tcti_test_load_literal_instruction(cases[i].simd_fp,
				cases[i].opc, 0, 7));
		ret = orlix_tcti_lower_decoded_instruction(&decoded, program,
				ARRAY_SIZE(program), &word_count);
		KUNIT_ASSERT_EQ(test, 0, ret);
		ret = orlix_tcti_execute_gadget_program(current->mm, &regs, program,
				word_count, &fault_address);

		KUNIT_EXPECT_EQ(test, -EACCES, ret);
		KUNIT_EXPECT_EQ(test, mapped, fault_address);
		KUNIT_EXPECT_EQ(test, mapped, regs.pc);
		KUNIT_EXPECT_EQ(test, 0x1122334455667788ULL, regs.regs[7]);
		KUNIT_EXPECT_EQ(test, 0x0123456789abcdefULL,
				current->thread.user_simd[14]);
		KUNIT_EXPECT_EQ(test, 0xfedcba9876543210ULL,
				current->thread.user_simd[15]);
	}

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_decode_recognizes_load_store_pair_class(struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;

	decoded = orlix_tcti_decode_aarch64(0x28000440U); /* stnp w0, w1, [x2] */
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_EQ(test, 4, decoded.access_size);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET,
			decoded.memory_index_mode);

	decoded = orlix_tcti_decode_aarch64(0xa84110a3U); /* ldnp x3, x4, [x5, #16] */
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_TRUE(test, decoded.load);
	KUNIT_EXPECT_EQ(test, 16LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, 8, decoded.access_size);

	decoded = orlix_tcti_decode_aarch64(0x2c000440U); /* stnp s0, s1, [x2] */
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 4, decoded.access_size);

	decoded = orlix_tcti_decode_aarch64(0x68400440U);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED, decoded.decode_class);

	decoded = orlix_tcti_decode_aarch64(0xa9be7bfdU);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_EQ(test, 29U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 30U, decoded.rt2);
	KUNIT_EXPECT_EQ(test, 31U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 8U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, -32LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_MEMORY_INDEX_PRE,
			decoded.memory_index_mode);

	decoded = orlix_tcti_decode_aarch64(0x69402c09U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_TRUE(test, decoded.load);
	KUNIT_EXPECT_TRUE(test, decoded.sign_extend_load);
	KUNIT_EXPECT_EQ(test, 9U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 11U, decoded.rt2);
	KUNIT_EXPECT_EQ(test, 0U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 4U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 8U, decoded.result_size);
	KUNIT_EXPECT_EQ(test, 0LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET,
			decoded.memory_index_mode);

	decoded = orlix_tcti_decode_aarch64(0xa8c27bfdU);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_TRUE(test, decoded.load);
	KUNIT_EXPECT_EQ(test, 29U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 30U, decoded.rt2);
	KUNIT_EXPECT_EQ(test, 31U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 8U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 32LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_MEMORY_INDEX_POST,
			decoded.memory_index_mode);

	decoded = orlix_tcti_decode_aarch64(0xa9016ffcU);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_EQ(test, 28U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 27U, decoded.rt2);
	KUNIT_EXPECT_EQ(test, 31U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 8U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 16LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET,
			decoded.memory_index_mode);

	decoded = orlix_tcti_decode_aarch64(0x6d0123e9U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 9U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 8U, decoded.rt2);
	KUNIT_EXPECT_EQ(test, 31U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 8U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 16LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET,
			decoded.memory_index_mode);

	decoded = orlix_tcti_decode_aarch64(0xad400901U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_TRUE(test, decoded.load);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 1U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 2U, decoded.rt2);
	KUNIT_EXPECT_EQ(test, 8U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 16U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 0LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET,
			decoded.memory_index_mode);

	decoded = orlix_tcti_decode_aarch64(0xad0103e2U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 2U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 0U, decoded.rt2);
	KUNIT_EXPECT_EQ(test, 31U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 16U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 32LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET,
			decoded.memory_index_mode);

	decoded = orlix_tcti_decode_aarch64(0xadbf03e1U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 1U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 0U, decoded.rt2);
	KUNIT_EXPECT_EQ(test, 31U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 16U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, -32LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_MEMORY_INDEX_PRE,
			decoded.memory_index_mode);

	decoded = orlix_tcti_decode_aarch64(0xad0583e1U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 1U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 0U, decoded.rt2);
	KUNIT_EXPECT_EQ(test, 31U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 16U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 176LL, decoded.memory_offset);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET,
			decoded.memory_index_mode);
}

static u32 orlix_tcti_test_encode_load_store_pair(bool simd_fp, u8 opc, u8 mode,
	bool load, s8 immediate, u8 rt, u8 rt2, u8 rn)
{
	return 0x28000000U | ((u32)opc << 30) |
		(simd_fp ? BIT(26) : 0) | ((u32)mode << 23) |
		(load ? BIT(22) : 0) |
		(((u32)immediate & 0x7fU) << 15) | ((u32)rt2 << 10) |
		((u32)rn << 5) | rt;
}

static bool orlix_tcti_test_load_store_pair_shape_is_valid(bool simd_fp, u8 opc,
	u8 mode, bool load)
{
	(void)load;
	if (simd_fp)
		return true;
	if (opc != 1)
		return true;
	return mode != 0;
}

static void orlix_tcti_decode_exhaustive_load_store_pair_family(struct kunit *test)
{
	u8 simd_fp;
	u8 opc;
	u8 mode;
	u8 load;

	for (simd_fp = 0; simd_fp < 2; simd_fp++) {
		for (opc = 0; opc < 4; opc++) {
			for (mode = 0; mode < 4; mode++) {
				for (load = 0; load < 2; load++) {
					s16 immediate;

					for (immediate = -64; immediate < 64;
					     immediate++) {
						u32 instruction =
							orlix_tcti_test_encode_load_store_pair(
								simd_fp, opc, mode, load,
								(s8)immediate, 0, 2, 1);
						struct orlix_tcti_decoded_instruction decoded =
							orlix_tcti_decode_aarch64(instruction);
						u8 access_size;

						if (!orlix_tcti_test_load_store_pair_shape_is_valid(
							    simd_fp, opc, mode, load)) {
							KUNIT_EXPECT_EQ(test,
								ORLIX_TCTI_DECODE_UNSUPPORTED,
								decoded.decode_class);
							continue;
						}
						if (simd_fp)
							access_size = opc == 3 ?
								16U : BIT(opc + 2);
						else if (opc == 1 && !load)
							access_size = sizeof(u64);
						else if (opc >= 2)
							access_size = sizeof(u64);
						else
							access_size = sizeof(u32);
						KUNIT_EXPECT_EQ(test,
							ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
							decoded.decode_class);
						KUNIT_EXPECT_EQ(test, load, decoded.load);
						KUNIT_EXPECT_EQ(test, simd_fp,
							decoded.simd_fp);
						KUNIT_EXPECT_EQ(test, 0, decoded.rt);
						KUNIT_EXPECT_EQ(test, 2, decoded.rt2);
						KUNIT_EXPECT_EQ(test, 1, decoded.rn);
						KUNIT_EXPECT_EQ(test, access_size,
							decoded.access_size);
						KUNIT_EXPECT_EQ(test,
							!simd_fp && opc == 1 && load,
							decoded.sign_extend_load);
						KUNIT_EXPECT_EQ(test,
							!simd_fp && opc == 1 && load ?
								sizeof(u64) : access_size,
							decoded.result_size);
						KUNIT_EXPECT_EQ(test,
							!simd_fp && opc == 1 && !load,
							decoded.allocation_tag_store);
						KUNIT_EXPECT_EQ(test,
							(s64)immediate *
							(!simd_fp && opc == 1 && !load ?
								16U : access_size),
							decoded.memory_offset);
						KUNIT_EXPECT_EQ(test,
							mode == 1 ? ORLIX_TCTI_MEMORY_INDEX_POST :
							mode == 3 ? ORLIX_TCTI_MEMORY_INDEX_PRE :
							ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET,
							decoded.memory_index_mode);
					}
				}
			}
		}
	}
}

static void orlix_tcti_decode_load_store_pair_all_register_fields(struct kunit *test)
{
	u8 reg;

	for (reg = 0; reg < 32; reg++) {
		struct orlix_tcti_decoded_instruction decoded;
		u8 companion = reg == 2 ? 3 : 2;

		decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
			false, 2, 2, true, 0, reg, companion, 1));
		KUNIT_EXPECT_EQ(test, reg, decoded.rt);
		companion = reg == 0 ? 1 : 0;
		decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
			false, 2, 2, true, 0, companion, reg, 1));
		KUNIT_EXPECT_EQ(test, reg, decoded.rt2);
		decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
			false, 2, 2, true, 0, 0, 2, reg));
		KUNIT_EXPECT_EQ(test, reg, decoded.rn);
	}
}

static void orlix_tcti_decode_load_store_pair_fixed_mask_boundaries(
	struct kunit *test)
{
	const u32 instruction = orlix_tcti_test_encode_load_store_pair(
		false, 2, 2, true, 0, 0, 2, 1);
	const u32 fixed_mask = 0x3a000000U;
	u8 bit;

	for (bit = 0; bit < 32; bit++) {
		struct orlix_tcti_decoded_instruction decoded;

		if (!(fixed_mask & BIT(bit)))
			continue;
		decoded = orlix_tcti_decode_aarch64(instruction ^ BIT(bit));
		KUNIT_EXPECT_NE(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
	}
}

static void orlix_tcti_decode_rejects_constrained_unpredictable_pair_overlaps(
	struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;

	/* LDP with a shared destination is constrained unpredictable. */
	decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
		false, 2, 2, true, 0, 3, 3, 4));
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED, decoded.decode_class);

	/* Writeback forms may not overlap the base with either transfer register. */
	decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
		false, 2, 1, true, 1, 4, 2, 4));
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED, decoded.decode_class);
	decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
		false, 2, 3, true, -1, 2, 4, 4));
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED, decoded.decode_class);
	decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
		false, 2, 1, false, 1, 4, 2, 4));
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED, decoded.decode_class);
	decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
		true, 2, 3, false, -1, 2, 4, 4));
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED, decoded.decode_class);

	/* Offset forms do not write back, so a base overlap remains representable. */
	decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
		false, 2, 2, true, 0, 4, 2, 4));
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
			decoded.decode_class);
}

static void orlix_tcti_gadget_executes_non_temporal_simd_pair(struct kunit *test)
{
	struct orlix_tcti_gadget_word
		program[ORLIX_TCTI_SINGLE_INSTRUCTION_PROGRAM_WORDS];
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = { 0 };
	unsigned long fault_address = 0;
	unsigned long mapped;
	u32 first;
	u32 second;
	size_t word_count;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	current->thread.user_simd[0] = 0x11223344ULL;
	current->thread.user_simd[1] = ~0ULL;
	current->thread.user_simd[2] = 0x55667788ULL;
	current->thread.user_simd[3] = ~0ULL;
	regs.regs[2] = mapped + 64;
	regs.pc = 0x1000;
	decoded = orlix_tcti_decode_aarch64(0x2c000440U); /* stnp s0, s1, [x2] */
	ret = orlix_tcti_lower_decoded_instruction(&decoded, program,
					     ARRAY_SIZE(program), &word_count);
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_execute_gadget_program(current->mm, &regs, program,
					  word_count, &fault_address);
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_read_user_data(current->mm, mapped + 64, &first,
				  sizeof(first));
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_read_user_data(current->mm, mapped + 68, &second,
				  sizeof(second));
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x11223344U, first);
	KUNIT_EXPECT_EQ(test, 0x55667788U, second);
	KUNIT_EXPECT_EQ(test, mapped + 64, regs.regs[2]);
	KUNIT_EXPECT_EQ(test, 0x1004ULL, regs.pc);

	current->thread.user_simd[0] = ~0ULL;
	current->thread.user_simd[1] = ~0ULL;
	current->thread.user_simd[2] = ~0ULL;
	current->thread.user_simd[3] = ~0ULL;
	regs.pc = 0x2000;
	decoded = orlix_tcti_decode_aarch64(0x2c400440U); /* ldnp s0, s1, [x2] */
	ret = orlix_tcti_lower_decoded_instruction(&decoded, program,
					     ARRAY_SIZE(program), &word_count);
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_execute_gadget_program(current->mm, &regs, program,
					  word_count, &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x11223344ULL, current->thread.user_simd[0]);
	KUNIT_EXPECT_EQ(test, 0ULL, current->thread.user_simd[1]);
	KUNIT_EXPECT_EQ(test, 0x55667788ULL, current->thread.user_simd[2]);
	KUNIT_EXPECT_EQ(test, 0ULL, current->thread.user_simd[3]);
	KUNIT_EXPECT_EQ(test, mapped + 64, regs.regs[2]);
	KUNIT_EXPECT_EQ(test, 0x2004ULL, regs.pc);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static int orlix_tcti_test_execute_memory_gadget(
	const struct orlix_tcti_decoded_instruction *decoded, struct pt_regs *regs,
	unsigned long *fault_address)
{
	struct orlix_tcti_gadget_word program[ORLIX_TCTI_SINGLE_INSTRUCTION_PROGRAM_WORDS];
	size_t word_count;
	int ret;

	ret = orlix_tcti_lower_decoded_instruction(decoded, program,
		ARRAY_SIZE(program), &word_count);
	if (ret)
		return ret;
	return orlix_tcti_execute_gadget_program(current->mm, regs, program,
		word_count, fault_address);
}

static void orlix_tcti_gadget_executes_complete_load_store_pair_family(
	struct kunit *test)
{
	static const u64 first_value[2] = {
		0x8877665580000001ULL,
		0x0f1e2d3c4b5a6978ULL,
	};
	static const u64 second_value[2] = {
		0x112233447ffffffeULL,
		0x8796a5b4c3d2e1f0ULL,
	};
	unsigned long mapped;
	u8 simd_fp;
	u8 opc;
	u8 mode;
	u8 load;
	int ret;

	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
		MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	for (simd_fp = 0; simd_fp < 2; simd_fp++) {
		for (opc = 0; opc < 4; opc++) {
			for (mode = 0; mode < 4; mode++) {
				for (load = 0; load < 2; load++) {
					struct orlix_tcti_decoded_instruction decoded;
					struct pt_regs regs = { .pc = 0xb000 };
					unsigned long fault_address = 0;
					unsigned long base = mapped + 256;
					unsigned long address;
					u64 observed[2] = {};
					u64 expected_low;
					u8 access_size;
					u32 instruction;

					if (!orlix_tcti_test_load_store_pair_shape_is_valid(
						    simd_fp, opc, mode, load))
						continue;
					instruction = orlix_tcti_test_encode_load_store_pair(
						simd_fp, opc, mode, load, 1, 0, 2, 10);
					decoded = orlix_tcti_decode_aarch64(instruction);
					access_size = decoded.access_size;
					address = mode == 1 ? base :
						base + decoded.memory_offset;
					regs.regs[10] = base;
					memset(current->thread.user_simd, 0,
					       sizeof(current->thread.user_simd));

					if (load) {
						ret = orlix_tcti_write_user_data(current->mm,
							address, first_value, access_size);
						KUNIT_ASSERT_EQ(test, 0, ret);
						ret = orlix_tcti_write_user_data(current->mm,
							address + access_size,
							second_value, access_size);
						KUNIT_ASSERT_EQ(test, 0, ret);
						regs.regs[0] = ~0ULL;
						regs.regs[2] = ~0ULL;
						current->thread.user_simd[0] = ~0ULL;
						current->thread.user_simd[1] = ~0ULL;
						current->thread.user_simd[4] = ~0ULL;
						current->thread.user_simd[5] = ~0ULL;
					} else if (simd_fp) {
						current->thread.user_simd[0] = first_value[0];
						current->thread.user_simd[1] = first_value[1];
						current->thread.user_simd[4] = second_value[0];
						current->thread.user_simd[5] = second_value[1];
					} else {
						regs.regs[0] = first_value[0];
						regs.regs[2] = second_value[0];
					}

					ret = orlix_tcti_test_execute_memory_gadget(&decoded,
						&regs, &fault_address);
					KUNIT_ASSERT_EQ_MSG(test, 0, ret,
						"instruction=%08x", instruction);
					KUNIT_EXPECT_EQ(test, 0xb004ULL, regs.pc);
					KUNIT_EXPECT_EQ(test,
						mode == 1 || mode == 3 ?
							base + decoded.memory_offset : base,
						regs.regs[10]);

					if (load && simd_fp) {
						expected_low = access_size == sizeof(u32) ?
							(u32)first_value[0] : first_value[0];
						KUNIT_EXPECT_EQ(test, expected_low,
							current->thread.user_simd[0]);
						KUNIT_EXPECT_EQ(test,
							access_size == 2 * sizeof(u64) ?
								first_value[1] : 0,
							current->thread.user_simd[1]);
						KUNIT_EXPECT_EQ(test,
							access_size == sizeof(u32) ?
								(u32)second_value[0] :
								second_value[0],
							current->thread.user_simd[4]);
						KUNIT_EXPECT_EQ(test,
							access_size == 2 * sizeof(u64) ?
								second_value[1] : 0,
							current->thread.user_simd[5]);
					} else if (load) {
						if (opc == 1) {
							KUNIT_EXPECT_EQ(test,
								0xffffffff80000001ULL,
								regs.regs[0]);
							KUNIT_EXPECT_EQ(test,
								0x7ffffffeULL,
								regs.regs[2]);
						} else {
							expected_low = access_size ==
								sizeof(u32) ?
								(u32)first_value[0] :
								first_value[0];
							KUNIT_EXPECT_EQ(test, expected_low,
								regs.regs[0]);
							KUNIT_EXPECT_EQ(test,
								access_size == sizeof(u32) ?
									(u32)second_value[0] :
									second_value[0],
								regs.regs[2]);
						}
					} else {
						ret = orlix_tcti_read_user_data(current->mm,
							address, observed, access_size);
						KUNIT_ASSERT_EQ(test, 0, ret);
						KUNIT_EXPECT_EQ(test,
							access_size == sizeof(u32) ?
								(u32)first_value[0] :
								first_value[0], observed[0]);
						KUNIT_EXPECT_EQ(test,
							simd_fp && access_size ==
								2 * sizeof(u64) ?
								first_value[1] : 0,
							observed[1]);
						memset(observed, 0, sizeof(observed));
						ret = orlix_tcti_read_user_data(current->mm,
							address + access_size, observed,
							access_size);
						KUNIT_ASSERT_EQ(test, 0, ret);
						KUNIT_EXPECT_EQ(test,
							access_size == sizeof(u32) ?
								(u32)second_value[0] :
								second_value[0], observed[0]);
						KUNIT_EXPECT_EQ(test,
							simd_fp && access_size ==
								2 * sizeof(u64) ?
								second_value[1] : 0,
							observed[1]);
					}
				}
			}
		}
	}
	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_gadget_reports_load_store_pair_second_fault(
	struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = { .pc = 0xb100 };
	unsigned long fault_address = 0;
	unsigned long mapped;
	u64 observed = 0;
	u64 first = 0x1122334455667788ULL;
	u64 second = 0x8877665544332211ULL;
	int ret;

	mapped = ksys_mmap_pgoff(0, 2 * PAGE_SIZE, PROT_READ | PROT_WRITE,
		MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));
	ret = sys_mprotect(mapped + PAGE_SIZE, PAGE_SIZE, PROT_NONE);
	KUNIT_ASSERT_EQ(test, 0, ret);

	regs.regs[10] = mapped + PAGE_SIZE - 2 * sizeof(u64);
	regs.regs[0] = 0xaaaaaaaaaaaaaaaaULL;
	regs.regs[2] = 0xbbbbbbbbbbbbbbbbULL;
	ret = orlix_tcti_write_user_data(current->mm,
		regs.regs[10] + sizeof(u64), &first,
		sizeof(first));
	KUNIT_ASSERT_EQ(test, 0, ret);
	decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
		false, 2, 3, true, 1, 0, 2, 10));
	ret = orlix_tcti_test_execute_memory_gadget(&decoded, &regs, &fault_address);
	KUNIT_EXPECT_NE(test, 0, ret);
	KUNIT_EXPECT_EQ(test, mapped + PAGE_SIZE, fault_address);
	KUNIT_EXPECT_EQ(test, 0xaaaaaaaaaaaaaaaaULL, regs.regs[0]);
	KUNIT_EXPECT_EQ(test, 0xbbbbbbbbbbbbbbbbULL, regs.regs[2]);
	KUNIT_EXPECT_EQ(test, mapped + PAGE_SIZE - 2 * sizeof(u64),
		regs.regs[10]);
	KUNIT_EXPECT_EQ(test, 0xb100ULL, regs.pc);

	observed = 0;
	ret = orlix_tcti_write_user_data(current->mm,
		regs.regs[10] + sizeof(u64), &observed,
		sizeof(observed));
	KUNIT_ASSERT_EQ(test, 0, ret);
	regs.regs[0] = first;
	regs.regs[2] = second;
	fault_address = 0;
	decoded = orlix_tcti_decode_aarch64(orlix_tcti_test_encode_load_store_pair(
		false, 2, 3, false, 1, 0, 2, 10));
	ret = orlix_tcti_test_execute_memory_gadget(&decoded, &regs, &fault_address);
	KUNIT_EXPECT_NE(test, 0, ret);
	KUNIT_EXPECT_EQ(test, mapped + PAGE_SIZE, fault_address);
	ret = orlix_tcti_read_user_data(current->mm,
		regs.regs[10] + sizeof(u64), &observed,
		sizeof(observed));
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, first, observed);
	KUNIT_EXPECT_EQ(test, mapped + PAGE_SIZE - 2 * sizeof(u64),
		regs.regs[10]);
	KUNIT_EXPECT_EQ(test, 0xb100ULL, regs.pc);

	ret = vm_munmap(mapped, 2 * PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_decode_recognizes_load_store_unsigned_class(struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;

	decoded = orlix_tcti_decode_aarch64(0xf9000bf3U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_UNSIGNED_IMMEDIATE,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_EQ(test, 19U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 31U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 8U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 16LL, decoded.memory_offset);

	decoded = orlix_tcti_decode_aarch64(0xf9456929U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_UNSIGNED_IMMEDIATE,
			decoded.decode_class);
	KUNIT_EXPECT_TRUE(test, decoded.load);
	KUNIT_EXPECT_EQ(test, 9U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 9U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 8U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 0xad0LL, decoded.memory_offset);

	decoded = orlix_tcti_decode_aarch64(0x39470408U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_UNSIGNED_IMMEDIATE,
			decoded.decode_class);
	KUNIT_EXPECT_TRUE(test, decoded.load);
	KUNIT_EXPECT_EQ(test, 8U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 0U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 1U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 0x1c1LL, decoded.memory_offset);

	decoded = orlix_tcti_decode_aarch64(0x3dc00100U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_UNSIGNED_IMMEDIATE,
			decoded.decode_class);
	KUNIT_EXPECT_TRUE(test, decoded.load);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 0U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 8U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 16U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 0LL, decoded.memory_offset);

	decoded = orlix_tcti_decode_aarch64(0x3d8007e1U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_UNSIGNED_IMMEDIATE,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 1U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 31U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 16U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 16LL, decoded.memory_offset);

	decoded = orlix_tcti_decode_aarch64(0xfd005beaU);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_UNSIGNED_IMMEDIATE,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 10U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 31U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 8U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 176LL, decoded.memory_offset);

	decoded = orlix_tcti_decode_aarch64(0xbd01c260U);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_UNSIGNED_IMMEDIATE,
			decoded.decode_class);
	KUNIT_EXPECT_FALSE(test, decoded.load);
	KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	KUNIT_EXPECT_EQ(test, 0U, decoded.rt);
	KUNIT_EXPECT_EQ(test, 19U, decoded.rn);
	KUNIT_EXPECT_EQ(test, 4U, decoded.access_size);
	KUNIT_EXPECT_EQ(test, 0x1c0LL, decoded.memory_offset);
}

static bool orlix_tcti_test_gpr_load_store_variant_is_legal(u8 size, u8 opc)
{
	return opc <= 1 || (opc == 2 && size < 3) ||
	       (opc == 3 && size < 2);
}

static bool orlix_tcti_test_simd_load_store_variant_is_legal(u8 size, u8 opc)
{
	return opc <= 1 || (size == 0 && opc >= 2);
}

static u8 orlix_tcti_test_load_store_access_size(bool simd_fp, u8 size, u8 opc)
{
	if (simd_fp && size == 0 && opc >= 2)
		return 16;
	return 1U << size;
}

static void orlix_tcti_decode_exhaustive_load_store_unsigned_immediate_family(
	struct kunit *test)
{
	u32 imm12;
	u8 simd_fp;
	u8 size;
	u8 opc;

	for (simd_fp = 0; simd_fp < 2; simd_fp++) {
		for (size = 0; size < 4; size++) {
			for (opc = 0; opc < 4; opc++) {
				bool prefetch = !simd_fp && size == 3 && opc == 2;
				bool legal = simd_fp ?
					orlix_tcti_test_simd_load_store_variant_is_legal(size,
									 opc) :
					orlix_tcti_test_gpr_load_store_variant_is_legal(size,
									opc);

				for (imm12 = 0; imm12 < BIT(12); imm12++) {
					u32 instruction = 0x39000000U |
						((u32)size << 30) |
						((u32)simd_fp << 26) |
						((u32)opc << 22) |
						(imm12 << 10) | (9U << 5) | 10U;
					struct orlix_tcti_decoded_instruction decoded =
						orlix_tcti_decode_aarch64(instruction);

					if (prefetch) {
						KUNIT_ASSERT_EQ_MSG(test, ORLIX_TCTI_DECODE_HINT,
								decoded.decode_class,
								"instruction %#x", instruction);
						continue;
					}
					if (!legal) {
						KUNIT_ASSERT_EQ_MSG(test,
								ORLIX_TCTI_DECODE_UNSUPPORTED,
								decoded.decode_class,
								"instruction %#x", instruction);
						continue;
					}

					KUNIT_ASSERT_EQ_MSG(test,
						ORLIX_TCTI_DECODE_LOAD_STORE_UNSIGNED_IMMEDIATE,
						decoded.decode_class,
						"instruction %#x", instruction);
					KUNIT_EXPECT_EQ(test, 9U, decoded.rn);
					KUNIT_EXPECT_EQ(test, 10U, decoded.rt);
					KUNIT_EXPECT_EQ(test, simd_fp, decoded.simd_fp);
					KUNIT_EXPECT_EQ(test,
						orlix_tcti_test_load_store_access_size(simd_fp,
									 size, opc),
						decoded.access_size);
					KUNIT_EXPECT_EQ(test,
						(s64)imm12 * decoded.access_size,
						decoded.memory_offset);
				}
			}
		}
	}
}

static void orlix_tcti_expect_load_store_signed_immediate_shape(
	struct kunit *test, u8 simd_fp, u8 size, u8 opc, u8 mode)
{
	bool prefetch = !simd_fp && size == 3 && opc == 2 && mode == 0;
	bool legal = simd_fp ?
		mode != 2 &&
		orlix_tcti_test_simd_load_store_variant_is_legal(size, opc) :
		orlix_tcti_test_gpr_load_store_variant_is_legal(size, opc);
	u32 imm9;

	for (imm9 = 0; imm9 < BIT(9); imm9++) {
		u32 instruction = 0x38000000U | ((u32)size << 30) |
			((u32)simd_fp << 26) | ((u32)opc << 22) |
			(imm9 << 12) | ((u32)mode << 10) | (9U << 5) | 10U;
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(instruction);

		if (prefetch) {
			KUNIT_ASSERT_EQ_MSG(test, ORLIX_TCTI_DECODE_HINT,
					decoded.decode_class,
					"instruction %#x", instruction);
			continue;
		}
		if (!legal || (!simd_fp && size == 3 && opc == 2)) {
			KUNIT_ASSERT_EQ_MSG(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
					decoded.decode_class,
					"instruction %#x", instruction);
			continue;
		}

		KUNIT_ASSERT_EQ_MSG(test,
			ORLIX_TCTI_DECODE_LOAD_STORE_SIGNED_IMMEDIATE,
			decoded.decode_class, "instruction %#x", instruction);
		KUNIT_EXPECT_EQ(test, 9U, decoded.rn);
		KUNIT_EXPECT_EQ(test, 10U, decoded.rt);
		KUNIT_EXPECT_EQ(test, simd_fp, decoded.simd_fp);
		KUNIT_EXPECT_EQ(test, sign_extend64(imm9, 8),
				 decoded.memory_offset);
		KUNIT_EXPECT_EQ(test,
			mode == 1 ? ORLIX_TCTI_MEMORY_INDEX_POST :
			mode == 3 ? ORLIX_TCTI_MEMORY_INDEX_PRE :
			ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET,
			decoded.memory_index_mode);
	}
}

static void orlix_tcti_decode_exhaustive_load_store_signed_immediate_family(
	struct kunit *test)
{
	u8 simd_fp;
	u8 size;
	u8 opc;
	u8 mode;

	for (simd_fp = 0; simd_fp < 2; simd_fp++)
		for (size = 0; size < 4; size++)
			for (opc = 0; opc < 4; opc++)
				for (mode = 0; mode < 4; mode++)
					orlix_tcti_expect_load_store_signed_immediate_shape(
						test, simd_fp, size, opc, mode);
}

static void orlix_tcti_expect_load_store_register_offset_shape(
	struct kunit *test, u8 simd_fp, u8 size, u8 opc)
{
	bool legal = simd_fp ?
		orlix_tcti_test_simd_load_store_variant_is_legal(size, opc) :
		orlix_tcti_test_gpr_load_store_variant_is_legal(size, opc);
	u8 rm;
	u8 option;
	u8 shift;

	for (rm = 0; rm < 32; rm++) {
		for (option = 0; option < 8; option++) {
			for (shift = 0; shift < 2; shift++) {
				bool valid_option = option == 2 || option == 3 ||
					option == 6 || option == 7;
				bool prefetch = valid_option && !simd_fp &&
					size == 3 && opc == 2;
				u32 instruction = 0x38200800U |
					((u32)size << 30) |
					((u32)simd_fp << 26) |
					((u32)opc << 22) | ((u32)rm << 16) |
					((u32)option << 13) |
					((u32)shift << 12) | (9U << 5) | 10U;
				struct orlix_tcti_decoded_instruction decoded =
					orlix_tcti_decode_aarch64(instruction);

				if (prefetch) {
					KUNIT_ASSERT_EQ_MSG(test, ORLIX_TCTI_DECODE_HINT,
						decoded.decode_class,
						"instruction %#x", instruction);
					continue;
				}
				if (!valid_option || !legal) {
					KUNIT_ASSERT_EQ_MSG(test,
						ORLIX_TCTI_DECODE_UNSUPPORTED,
						decoded.decode_class,
						"instruction %#x", instruction);
					continue;
				}

				KUNIT_ASSERT_EQ_MSG(test,
					ORLIX_TCTI_DECODE_LOAD_STORE_REGISTER_OFFSET,
					decoded.decode_class,
					"instruction %#x", instruction);
				KUNIT_EXPECT_EQ(test, rm, decoded.rm);
				KUNIT_EXPECT_EQ(test, option,
						decoded.offset_extend);
				KUNIT_EXPECT_EQ(test, shift,
						decoded.offset_shift);
			}
		}
	}
}

static void orlix_tcti_decode_exhaustive_load_store_register_offset_family(
	struct kunit *test)
{
	u8 simd_fp;
	u8 size;
	u8 opc;

	for (simd_fp = 0; simd_fp < 2; simd_fp++)
		for (size = 0; size < 4; size++)
			for (opc = 0; opc < 4; opc++)
				orlix_tcti_expect_load_store_register_offset_shape(
					test, simd_fp, size, opc);
}

static void orlix_tcti_decode_load_store_all_register_fields(struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;
	u8 rn;
	u8 rt;
	u8 rm;

	for (rn = 0; rn < 32; rn++) {
		for (rt = 0; rt < 32; rt++) {
			decoded = orlix_tcti_decode_aarch64(0xf9400000U |
						      ((u32)rn << 5) | rt);
			KUNIT_ASSERT_EQ(test,
				ORLIX_TCTI_DECODE_LOAD_STORE_UNSIGNED_IMMEDIATE,
				decoded.decode_class);
			KUNIT_EXPECT_EQ(test, rn, decoded.rn);
			KUNIT_EXPECT_EQ(test, rt, decoded.rt);

			decoded = orlix_tcti_decode_aarch64(0xf8400800U |
						      ((u32)rn << 5) | rt);
			KUNIT_ASSERT_EQ(test,
				ORLIX_TCTI_DECODE_LOAD_STORE_SIGNED_IMMEDIATE,
				decoded.decode_class);
			KUNIT_EXPECT_EQ(test, rn, decoded.rn);
			KUNIT_EXPECT_EQ(test, rt, decoded.rt);
		}
	}

	for (rn = 0; rn < 32; rn++) {
		for (rt = 0; rt < 32; rt++) {
			for (rm = 0; rm < 32; rm++) {
				decoded = orlix_tcti_decode_aarch64(0xf8606800U |
							      ((u32)rm << 16) |
							      ((u32)rn << 5) | rt);
				KUNIT_ASSERT_EQ(test,
					ORLIX_TCTI_DECODE_LOAD_STORE_REGISTER_OFFSET,
					decoded.decode_class);
				KUNIT_EXPECT_EQ(test, rn, decoded.rn);
				KUNIT_EXPECT_EQ(test, rt, decoded.rt);
				KUNIT_EXPECT_EQ(test, rm, decoded.rm);
			}
		}
	}
}

static int orlix_tcti_test_execute_single_instruction(
	u32 instruction, struct pt_regs *regs, unsigned long *fault_address)
{
	struct orlix_tcti_gadget_word program[ORLIX_TCTI_SINGLE_INSTRUCTION_PROGRAM_WORDS];
	struct orlix_tcti_decoded_instruction decoded =
		orlix_tcti_decode_aarch64(instruction);
	size_t word_count;
	int ret;

	ret = orlix_tcti_lower_decoded_instruction(&decoded, program,
					     ARRAY_SIZE(program), &word_count);
	if (ret)
		return ret;
	return orlix_tcti_execute_gadget_program(current->mm, regs, program,
					   word_count, fault_address);
}

static void orlix_tcti_gadget_executes_complete_load_store_register_family(
	struct kunit *test)
{
	struct pt_regs regs = { 0 };
	unsigned long fault_address = 0;
	unsigned long mapped;
	u32 instruction;
	u16 halfword;
	u8 byte;
	int ret;

	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	byte = 0x80;
	ret = orlix_tcti_write_user_data(current->mm, mapped + 31, &byte,
				   sizeof(byte));
	KUNIT_ASSERT_EQ(test, 0, ret);
	regs.regs[9] = mapped + 32;
	regs.pc = 0x1000;
	instruction = 0x38000000U | (2U << 22) | (0x1ffU << 12) |
		      (2U << 10) | (9U << 5) | 10U; /* ldtrsb x10, [x9, #-1] */
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address);
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, (u64)(s64)(s8)byte, regs.regs[10]);
	KUNIT_EXPECT_EQ(test, mapped + 32, regs.regs[9]);
	KUNIT_EXPECT_EQ(test, 0x1004ULL, regs.pc);

	regs.regs[10] = 0xa1b2U;
	instruction = 0x38000000U | (1U << 30) | (2U << 12) |
		      (2U << 10) | (9U << 5) | 10U; /* sttrh w10, [x9, #2] */
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address);
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_read_user_data(current->mm, mapped + 34, &halfword,
				  sizeof(halfword));
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0xa1b2U, halfword);
	KUNIT_EXPECT_EQ(test, mapped + 32, regs.regs[9]);
	KUNIT_EXPECT_EQ(test, 0x1008ULL, regs.pc);

	current->thread.user_simd[0] = 0x1122334455667788ULL;
	instruction = 0x3d000000U | (5U << 10) | (9U << 5);
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address); /* str b0, [x9, #5] */
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_read_user_data(current->mm, mapped + 37, &byte,
				  sizeof(byte));
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x88U, byte);

	halfword = 0x4567U;
	ret = orlix_tcti_write_user_data(current->mm, mapped + 38, &halfword,
				   sizeof(halfword));
	KUNIT_ASSERT_EQ(test, 0, ret);
	current->thread.user_simd[2] = ~0ULL;
	current->thread.user_simd[3] = ~0ULL;
	instruction = 0x7d400000U | (3U << 10) | (9U << 5) | 1U;
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address); /* ldr h1, [x9, #6] */
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x4567ULL, current->thread.user_simd[2]);
	KUNIT_EXPECT_EQ(test, 0ULL, current->thread.user_simd[3]);

	regs.pc = 0x2000;
	instruction = 0xf9800000U | (9U << 5); /* prfm pldl1keep, [x9] */
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x2004ULL, regs.pc);
	instruction = 0xf8800000U | (9U << 5); /* prfum pldl1keep, [x9] */
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x2008ULL, regs.pc);
	instruction = 0xf8a06800U | (10U << 16) | (9U << 5);
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address); /* prfm pldl1keep, [x9, x10] */
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x200cULL, regs.pc);

	regs.regs[9] = 0;
	regs.pc = 0x3000;
	instruction = 0x38000000U | (2U << 30) | (1U << 22) |
		      (2U << 10) | (9U << 5) | 10U; /* ldtr w10, [x9] */
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address);
	KUNIT_EXPECT_EQ(test, -EFAULT, ret);
	KUNIT_EXPECT_EQ(test, 0UL, fault_address);
	KUNIT_EXPECT_EQ(test, 0x3000ULL, regs.pc);
	KUNIT_EXPECT_EQ(test, 0ULL, regs.regs[9]);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

/*
 * These are execution tests rather than another decoder enumeration.  The
 * decoder matrix above already visits every immediate and register-offset
 * encoding.  Keep the state-transition checks here so that the test executes
 * the same lowered instruction path used by the OrlixTCTI engine.
 */
static u32 orlix_tcti_test_encode_gpr_load_store_immediate(u8 size, u8 opc,
					      s16 immediate, u8 mode,
					      u8 rn, u8 rt)
{
	u32 instruction;

	if (mode == ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET && immediate >= 0 &&
	    immediate % (1U << size) == 0 &&
	    immediate / (1U << size) < BIT(12)) {
		instruction = 0x39000000U |
			((u32)size << 30) | ((u32)opc << 22) |
			((u32)(immediate >> size) << 10);
	} else {
		u8 encoding_mode = mode == ORLIX_TCTI_MEMORY_INDEX_POST ? 1U :
			mode == ORLIX_TCTI_MEMORY_INDEX_PRE ? 3U : 0U;

		instruction = 0x38000000U |
			((u32)size << 30) | ((u32)opc << 22) |
			(((u32)immediate & 0x1ffU) << 12) |
			((u32)encoding_mode << 10);
	}

	return instruction | ((u32)rn << 5) | rt;
}

static u32 orlix_tcti_test_encode_gpr_load_store_register_offset(u8 size, u8 opc,
						   u8 rm, u8 option, bool shift,
						   u8 rn, u8 rt)
{
	return 0x38200800U | ((u32)size << 30) | ((u32)opc << 22) |
		((u32)rm << 16) | ((u32)option << 13) |
		(shift ? BIT(12) : 0) | ((u32)rn << 5) | rt;
}

static u64 orlix_tcti_test_load_store_masked_value(u64 value, u8 size)
{
	return size == sizeof(u8) ? (u8)value :
	       size == sizeof(u16) ? (u16)value :
	       size == sizeof(u32) ? (u32)value : value;
}

static void orlix_tcti_gadget_executes_gpr_load_store_immediate_addressing(
	struct kunit *test)
{
	static const u64 values[] = {
		0x8877665544332211ULL,
	};
	static const u8 modes[] = {
		ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET,
		ORLIX_TCTI_MEMORY_INDEX_PRE,
		ORLIX_TCTI_MEMORY_INDEX_POST,
	};
	unsigned long mapped;
	u8 size;
	u8 mode_index;
	u8 load;
	int ret;

	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	for (size = 0; size < 4; size++) {
		u8 access_size = 1U << size;

		for (mode_index = 0; mode_index < ARRAY_SIZE(modes); mode_index++) {
			u8 mode = modes[mode_index];

			for (load = 0; load < 2; load++) {
				struct pt_regs regs = { .pc = 0x7100 };
				unsigned long fault_address = 0;
				unsigned long base = mapped + 128;
				unsigned long address = mode == ORLIX_TCTI_MEMORY_INDEX_POST ?
					base : base + access_size;
				u64 observed = 0;
				u32 instruction;

				regs.regs[9] = base;
				instruction = orlix_tcti_test_encode_gpr_load_store_immediate(
					size, 1, access_size, mode, 9, 10);
				if (load) {
					ret = orlix_tcti_write_user_data(current->mm, address,
							   &values[0], access_size);
					KUNIT_ASSERT_EQ(test, 0, ret);
					regs.regs[10] = ~0ULL;
				} else {
					instruction = orlix_tcti_test_encode_gpr_load_store_immediate(
						size, 0, access_size, mode, 9, 10);
					regs.regs[10] = values[0];
				}

				ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
								   &fault_address);
				KUNIT_ASSERT_EQ_MSG(test, 0, ret,
					"size=%u mode=%u load=%u", size, mode, load);
				KUNIT_EXPECT_EQ(test, 0x7104ULL, regs.pc);
				KUNIT_EXPECT_EQ(test, address, fault_address);
				KUNIT_EXPECT_EQ(test,
					mode == ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET ? base :
					base + access_size, regs.regs[9]);

				if (load) {
					KUNIT_EXPECT_EQ(test,
						orlix_tcti_test_load_store_masked_value(values[0],
									   access_size), regs.regs[10]);
				} else {
					ret = orlix_tcti_read_user_data(current->mm, address,
							  &observed, access_size);
					KUNIT_ASSERT_EQ(test, 0, ret);
					KUNIT_EXPECT_EQ(test,
						orlix_tcti_test_load_store_masked_value(values[0],
									   access_size), observed);
				}
			}
		}
	}

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_gadget_executes_gpr_load_store_register_offsets(
	struct kunit *test)
{
	static const struct {
		u8 option;
		bool shift;
		u64 rm_value;
		s64 offset;
	} cases[] = {
		{ 2, false, 3, 3 }, /* UXTW */
		{ 3, true, 3, 24 }, /* LSL #3 */
		{ 6, false, 0xfffffffdU, -3 }, /* SXTW */
		{ 7, false, (u64)-3, -3 }, /* SXTX */
	};
	unsigned long mapped;
	size_t index;
	int ret;

	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		struct pt_regs regs = { .pc = 0x7200 };
		unsigned long fault_address = 0;
		unsigned long base = mapped + 128;
		unsigned long address = base + cases[index].offset;
		u64 value = 0x8877665544332211ULL;
		u64 observed = 0;
		u32 instruction;

		regs.regs[9] = base;
		regs.regs[11] = cases[index].rm_value;
		ret = orlix_tcti_write_user_data(current->mm, address, &value,
					   sizeof(value));
		KUNIT_ASSERT_EQ(test, 0, ret);
		instruction = orlix_tcti_test_encode_gpr_load_store_register_offset(
			3, 1, 11, cases[index].option, cases[index].shift, 9, 10);
		ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
							   &fault_address);
		KUNIT_ASSERT_EQ_MSG(test, 0, ret, "option=%u", cases[index].option);
		KUNIT_EXPECT_EQ(test, value, regs.regs[10]);
		KUNIT_EXPECT_EQ(test, address, fault_address);
		KUNIT_EXPECT_EQ(test, base, regs.regs[9]);
		KUNIT_EXPECT_EQ(test, 0x7204ULL, regs.pc);

		regs.pc = 0x7204;
		regs.regs[10] = ~value;
		instruction = orlix_tcti_test_encode_gpr_load_store_register_offset(
			3, 0, 11, cases[index].option, cases[index].shift, 9, 10);
		ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
							   &fault_address);
		KUNIT_ASSERT_EQ(test, 0, ret);
		ret = orlix_tcti_read_user_data(current->mm, address, &observed,
					  sizeof(observed));
		KUNIT_ASSERT_EQ(test, 0, ret);
		KUNIT_EXPECT_EQ(test, ~value, observed);
		KUNIT_EXPECT_EQ(test, 0x7208ULL, regs.pc);
	}

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_gadget_load_store_preserves_fault_and_zero_register_state(
	struct kunit *test)
{
	static const struct {
		u8 size;
		u8 opc;
		u64 value;
		u64 expected;
	} signed_loads[] = {
		{ 0, 2, 0x80, 0xffffffffffffff80ULL },
		{ 0, 3, 0x80, 0x00000000ffffff80ULL },
		{ 1, 2, 0x8001, 0xffffffffffff8001ULL },
		{ 1, 3, 0x8001, 0x00000000ffff8001ULL },
		{ 2, 2, 0x80000001, 0xffffffff80000001ULL },
	};
	struct pt_regs regs = { .pc = 0x7300 };
	unsigned long fault_address = 0;
	unsigned long mapped;
	u64 value = 0x80000000ULL;
	u64 observed = ~0ULL;
	u32 instruction;
	size_t index;
	int ret;

	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	/* A sign-extending load to XZR still performs the memory access. */
	ret = orlix_tcti_write_user_data(current->mm, mapped + 16, &value,
				   sizeof(u32));
	KUNIT_ASSERT_EQ(test, 0, ret);
	regs.regs[9] = mapped;
	instruction = orlix_tcti_test_encode_gpr_load_store_immediate(
		2, 2, 16, ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET, 9, 31);
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address);
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x7304ULL, regs.pc);
	KUNIT_EXPECT_EQ(test, mapped + 16, fault_address);
	KUNIT_EXPECT_EQ(test, mapped, regs.regs[9]);

	for (index = 0; index < ARRAY_SIZE(signed_loads); index++) {
		u8 access_size = 1U << signed_loads[index].size;

		ret = orlix_tcti_write_user_data(current->mm, mapped + 48,
					   &signed_loads[index].value, access_size);
		KUNIT_ASSERT_EQ(test, 0, ret);
		regs.regs[10] = ~0ULL;
		instruction = orlix_tcti_test_encode_gpr_load_store_immediate(
			signed_loads[index].size, signed_loads[index].opc, 48,
			ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET, 9, 10);
		ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
							   &fault_address);
		KUNIT_ASSERT_EQ_MSG(test, 0, ret, "size=%u opc=%u",
			signed_loads[index].size, signed_loads[index].opc);
		KUNIT_EXPECT_EQ(test, signed_loads[index].expected, regs.regs[10]);
	}

	/* STR XZR writes architectural zero, independent of stale host state. */
	regs.pc = 0x7304;
	instruction = orlix_tcti_test_encode_gpr_load_store_immediate(
		3, 0, 24, ORLIX_TCTI_MEMORY_INDEX_SIGNED_OFFSET, 9, 31);
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address);
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_read_user_data(current->mm, mapped + 24, &observed,
					  sizeof(observed));
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0ULL, observed);

	/* A pre-indexed fault cannot commit PC, destination, or base writeback. */
	regs.regs[9] = 0;
	regs.regs[10] = 0xfeedfacefeedfaceULL;
	regs.pc = 0x7400;
	fault_address = ~0UL;
	instruction = orlix_tcti_test_encode_gpr_load_store_immediate(
		3, 1, 8, ORLIX_TCTI_MEMORY_INDEX_PRE, 9, 10);
	ret = orlix_tcti_test_execute_single_instruction(instruction, &regs,
						   &fault_address);
	KUNIT_EXPECT_EQ(test, -EFAULT, ret);
	KUNIT_EXPECT_EQ(test, 8UL, fault_address);
	KUNIT_EXPECT_EQ(test, 0ULL, regs.regs[9]);
	KUNIT_EXPECT_EQ(test, 0xfeedfacefeedfaceULL, regs.regs[10]);
	KUNIT_EXPECT_EQ(test, 0x7400ULL, regs.pc);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

