static void orlix_tcti_decode_recognizes_complete_data_processing_1source_family(struct kunit *test)
{
	static const struct {
		u32 instruction;
		enum orlix_tcti_data_processing_1source_op op;
		bool is_64bit;
	} cases[] = {
		{ 0x5ac00020U, ORLIX_TCTI_DP1_RBIT, false },
		{ 0xdac00020U, ORLIX_TCTI_DP1_RBIT, true },
		{ 0x5ac00462U, ORLIX_TCTI_DP1_REV16, false },
		{ 0xdac00462U, ORLIX_TCTI_DP1_REV16, true },
		{ 0x5ac008a4U, ORLIX_TCTI_DP1_REV, false },
		{ 0xdac008a4U, ORLIX_TCTI_DP1_REV32, true },
		{ 0xdac00d08U, ORLIX_TCTI_DP1_REV, true },
		{ 0x5ac010e6U, ORLIX_TCTI_DP1_CLZ, false },
		{ 0xdac010e6U, ORLIX_TCTI_DP1_CLZ, true },
		{ 0x5ac0156aU, ORLIX_TCTI_DP1_CLS, false },
		{ 0xdac0156aU, ORLIX_TCTI_DP1_CLS, true },
	};
	struct orlix_tcti_decoded_instruction decoded;
	size_t index;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		decoded = orlix_tcti_decode_aarch64(cases[index].instruction);
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_DATA_PROCESSING_1SOURCE,
				decoded.decode_class);
		KUNIT_EXPECT_EQ(test, cases[index].op, decoded.dp1_op);
		KUNIT_EXPECT_EQ(test, cases[index].is_64bit, decoded.is_64bit);
	}

	decoded = orlix_tcti_decode_aarch64(0x5ac00c00U);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED, decoded.decode_class);
}

