static void orlix_tcti_decode_recognizes_complete_crc32_family(struct kunit *test)
{
	static const struct {
		u32 instruction;
		enum orlix_tcti_data_processing_2source_op operation;
		u8 access_size;
	} cases[] = {
		{ 0x1ac24020U, ORLIX_TCTI_DP2_CRC32, sizeof(u8) },
		{ 0x1ac24420U, ORLIX_TCTI_DP2_CRC32, sizeof(u16) },
		{ 0x1ac24820U, ORLIX_TCTI_DP2_CRC32, sizeof(u32) },
		{ 0x9ac24c20U, ORLIX_TCTI_DP2_CRC32, sizeof(u64) },
		{ 0x1ac25020U, ORLIX_TCTI_DP2_CRC32C, sizeof(u8) },
		{ 0x1ac25420U, ORLIX_TCTI_DP2_CRC32C, sizeof(u16) },
		{ 0x1ac25820U, ORLIX_TCTI_DP2_CRC32C, sizeof(u32) },
		{ 0x9ac25c20U, ORLIX_TCTI_DP2_CRC32C, sizeof(u64) },
	};
	size_t i;

	for (i = 0; i < ARRAY_SIZE(cases); i++) {
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(cases[i].instruction);

		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_DATA_PROCESSING_2SOURCE,
				decoded.decode_class);
		KUNIT_EXPECT_EQ(test, cases[i].operation, decoded.dp2_op);
		KUNIT_EXPECT_EQ(test, cases[i].access_size, decoded.access_size);
		KUNIT_EXPECT_EQ(test, sizeof(u32), decoded.result_size);
		KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
		KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
		KUNIT_EXPECT_EQ(test, 2U, decoded.rm);
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x9ac24020U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x1ac24c20U).decode_class);
}

