static void orlix_tcti_decode_exhaustive_hint_barrier_cache_family(struct kunit *test)
{
	static const struct {
		u32 pattern;
		enum orlix_tcti_barrier_op operation;
	} barriers[] = {
		{ 0xd503309fU, ORLIX_TCTI_BARRIER_DSB },
		{ 0xd50330bfU, ORLIX_TCTI_BARRIER_DMB },
		{ 0xd50330dfU, ORLIX_TCTI_BARRIER_ISB },
	};
	static const struct {
		u32 pattern;
		enum orlix_tcti_cache_maintenance_op operation;
	} cache_operations[] = {
		{ 0xd50b7520U, ORLIX_TCTI_CACHE_IC_IVAU },
		{ 0xd50b7a20U, ORLIX_TCTI_CACHE_DC_CVAC },
		{ 0xd50b7b20U, ORLIX_TCTI_CACHE_DC_CVAU },
		{ 0xd50b7e20U, ORLIX_TCTI_CACHE_DC_CIVAC },
	};
	u8 immediate;

	for (immediate = 0; immediate < 128; immediate++) {
		u32 instruction = 0xd503201fU | ((u32)immediate << 5);
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(instruction);

		if (orlix_tcti_is_unimplemented_pauth_or_bti_hint(instruction)) {
			KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
					decoded.decode_class);
			continue;
		}
		KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_HINT, decoded.decode_class);
		KUNIT_EXPECT_EQ(test, immediate, decoded.hint_imm);
	}

	for (immediate = 0; immediate < 16; immediate++) {
		u8 index;

		for (index = 0; index < ARRAY_SIZE(barriers); index++) {
			u32 instruction = barriers[index].pattern |
				((u32)immediate << 8);
			bool legal = index == 2 ? immediate == 15 :
				(immediate & 0x3U);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);

			KUNIT_EXPECT_EQ_MSG(test,
				legal ? ORLIX_TCTI_DECODE_BARRIER :
					ORLIX_TCTI_DECODE_UNSUPPORTED,
				decoded.decode_class, "instruction=%08x", instruction);
			if (legal) {
				KUNIT_EXPECT_EQ(test, barriers[index].operation,
					decoded.barrier_op);
				KUNIT_EXPECT_EQ(test, immediate,
					decoded.barrier_option);
			}
		}

		{
			u32 instruction = 0xd503305fU |
				((u32)immediate << 8);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);

			KUNIT_ASSERT_EQ(test,
				ORLIX_TCTI_DECODE_EXCLUSIVE_MONITOR_CLEAR,
				decoded.decode_class);
			KUNIT_EXPECT_EQ(test, immediate, decoded.barrier_option);
		}
	}

	for (immediate = 0; immediate < 16; immediate++) {
		u32 instruction = 0xd503323fU | ((u32)immediate << 8);
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(instruction);
		u8 option = (instruction >> 8) & 0xfU;
		bool legal = (option & 0x3U) == 0x2U;

		KUNIT_EXPECT_EQ_MSG(test,
			legal ? ORLIX_TCTI_DECODE_BARRIER : ORLIX_TCTI_DECODE_UNSUPPORTED,
			decoded.decode_class, "DSB nXS instruction=%08x",
			instruction);
		if (!legal)
			continue;

		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_BARRIER_DSB, decoded.barrier_op);
		KUNIT_EXPECT_EQ(test, option, decoded.barrier_option);
		KUNIT_EXPECT_TRUE(test, decoded.barrier_nxs);
	}

	for (immediate = 0; immediate < ARRAY_SIZE(cache_operations);
	     immediate++) {
		u8 rt;

		for (rt = 0; rt < 32; rt++) {
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(
					cache_operations[immediate].pattern | rt);

			KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_CACHE_MAINTENANCE,
				decoded.decode_class);
			KUNIT_EXPECT_EQ(test, cache_operations[immediate].operation,
				decoded.cache_maintenance_op);
			KUNIT_EXPECT_EQ(test, rt, decoded.rt);
		}
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0xd50b7820U).decode_class);
}

