static bool orlix_tcti_test_load_store_exclusive_shape_is_legal(
	u8 size, bool o2, bool load, bool o1, u8 rs, bool o0, u8 rt2)
{
	if (o2)
		return !o1 && o0 && rs == 31 && rt2 == 31;
	if (o1)
		return size >= 2 && (!load || rs == 31);
	return rt2 == 31 && (!load || rs == 31);
}

static u32 orlix_tcti_test_encode_load_store_exclusive(
	u8 size, bool o2, bool load, bool o1, u8 rs, bool o0, u8 rt2,
	u8 rn, u8 rt)
{
	return 0x08000000U | ((u32)size << 30) | ((u32)o2 << 23) |
	       ((u32)load << 22) | ((u32)o1 << 21) | ((u32)rs << 16) |
	       ((u32)o0 << 15) | ((u32)rt2 << 10) | ((u32)rn << 5) | rt;
}

static void orlix_tcti_expect_load_store_exclusive_control_shape(
	struct kunit *test, u8 size, bool o2, bool load, bool o1)
{
	struct orlix_tcti_decoded_instruction decoded;
	u32 instruction;
	u8 rs;
	u8 o0;
	u8 rt2;

	for (rs = 0; rs < 32; rs++) {
		for (o0 = 0; o0 < 2; o0++) {
			for (rt2 = 0; rt2 < 32; rt2++) {
				bool legal =
					orlix_tcti_test_load_store_exclusive_shape_is_legal(
						size, o2, load, o1, rs, o0, rt2);

				instruction = orlix_tcti_test_encode_load_store_exclusive(
					size, o2, load, o1, rs, o0, rt2, 9, 10);
				decoded = orlix_tcti_decode_aarch64(instruction);
				if (!legal) {
					if (decoded.decode_class ==
					    ORLIX_TCTI_DECODE_LSE_ATOMIC) {
						KUNIT_EXPECT_EQ(test,
							ORLIX_TCTI_LSE_ATOMIC_CAS,
							decoded.lse_atomic_op);
						continue;
					}
					KUNIT_ASSERT_EQ_MSG(test,
						ORLIX_TCTI_DECODE_UNSUPPORTED,
						decoded.decode_class,
						"instruction %#x", instruction);
					continue;
				}

				KUNIT_ASSERT_EQ_MSG(test,
					ORLIX_TCTI_DECODE_LOAD_STORE_EXCLUSIVE,
					decoded.decode_class,
					"instruction %#x", instruction);
				KUNIT_EXPECT_EQ(test, o1 && !o2, decoded.pair);
				KUNIT_EXPECT_EQ(test, !o2, decoded.exclusive);
				KUNIT_EXPECT_EQ(test, load && o0,
						decoded.acquire);
				KUNIT_EXPECT_EQ(test, !load && o0,
						decoded.release);
				KUNIT_EXPECT_EQ(test, rt2, decoded.rt2);
			}
		}
	}
}

static void orlix_tcti_decode_exhaustive_load_store_exclusive_family(
	struct kunit *test)
{
	u8 size;
	u8 o2;
	u8 load;
	u8 o1;

	for (size = 0; size < 4; size++)
		for (o2 = 0; o2 < 2; o2++)
			for (load = 0; load < 2; load++)
				for (o1 = 0; o1 < 2; o1++)
					orlix_tcti_expect_load_store_exclusive_control_shape(
						test, size, o2, load, o1);
}

static void orlix_tcti_decode_load_store_exclusive_all_register_fields(
	struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;
	u8 rn;
	u8 rt;

	for (rn = 0; rn < 32; rn++) {
		for (rt = 0; rt < 32; rt++) {
			decoded = orlix_tcti_decode_aarch64(0xc85f7c00U |
						      ((u32)rn << 5) | rt);
			KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_EXCLUSIVE,
					decoded.decode_class);
			KUNIT_EXPECT_EQ(test, rn, decoded.rn);
			KUNIT_EXPECT_EQ(test, rt, decoded.rt);
		}
	}
}

