static u32 orlix_tcti_test_encode_simd_modimm(bool q, bool op, bool o2, u8 cmode,
				       u8 imm8, u8 rd)
{
	return 0x0f000400U | (q ? BIT(30) : 0) | (op ? BIT(29) : 0) |
	       (o2 ? BIT(11) : 0) | ((u32)cmode << 12) |
	       ((u32)(imm8 & 0xe0U) << 11) | ((u32)(imm8 & 0x1fU) << 5) | rd;
}

static u64 orlix_tcti_test_replicate_simd_immediate(u64 value, u8 element_size)
{
	u8 element_bits = element_size * 8;
	u64 mask = GENMASK_ULL(element_bits - 1, 0);
	u64 result = 0;
	u8 shift;

	for (shift = 0; shift < 64; shift += element_bits)
		result |= (value & mask) << shift;
	return result;
}

static u64 orlix_tcti_test_expand_simd_modimm(u8 cmode, bool op, u8 imm8)
{
	if (cmode <= 7) {
		u8 shift = ((cmode & ~1U) >> 1) * 8;

		return orlix_tcti_test_replicate_simd_immediate((u32)imm8 << shift,
							  sizeof(u32));
	}
	if (cmode <= 11) {
		u8 shift = ((cmode & ~1U) - 8) / 2 * 8;

		return orlix_tcti_test_replicate_simd_immediate((u16)imm8 << shift,
							  sizeof(u16));
	}
	if (cmode == 12 || cmode == 13) {
		u8 shift = cmode == 12 ? 8 : 16;
		u32 lane = ((u32)imm8 << shift) | (BIT(shift) - 1U);

		return orlix_tcti_test_replicate_simd_immediate(lane, sizeof(u32));
	}
	if (cmode == 14 && !op)
		return orlix_tcti_test_replicate_simd_immediate(imm8, sizeof(u8));
	if (cmode == 14) {
		u64 result = 0;
		u8 byte;

		for (byte = 0; byte < 8; byte++) {
			if (imm8 & BIT(byte))
				result |= 0xffULL << (byte * 8);
		}
		return result;
	}
	if (!op) {
		u32 sign = (imm8 >> 7) & 1U;
		u32 exponent_bit = (imm8 >> 6) & 1U;
		u32 fraction = imm8 & 0x3fU;
		u32 lane = (sign << 31) | ((!exponent_bit) << 30) |
			   ((exponent_bit ? 0x1fU : 0) << 25) |
			   (fraction << 19);

		return orlix_tcti_test_replicate_simd_immediate(lane, sizeof(u32));
	}

	return ((u64)((imm8 >> 7) & 1U) << 63) |
	       ((u64)!((imm8 >> 6) & 1U) << 62) |
	       ((u64)(((imm8 >> 6) & 1U) ? 0xffU : 0) << 54) |
	       ((u64)(imm8 & 0x3fU) << 48);
}

static enum orlix_tcti_simd_modified_immediate_op
orlix_tcti_test_simd_modimm_operation(u8 cmode, bool op)
{
	if (cmode <= 11) {
		if (cmode & 1U)
			return op ? ORLIX_TCTI_SIMD_MODIMM_BIC : ORLIX_TCTI_SIMD_MODIMM_ORR;
		return op ? ORLIX_TCTI_SIMD_MODIMM_MVNI : ORLIX_TCTI_SIMD_MODIMM_MOVI;
	}
	if (cmode <= 13)
		return op ? ORLIX_TCTI_SIMD_MODIMM_MVNI : ORLIX_TCTI_SIMD_MODIMM_MOVI;
	return ORLIX_TCTI_SIMD_MODIMM_MOVI;
}

static bool orlix_tcti_test_simd_modimm_is_valid(bool q, bool op, u8 cmode)
{
	return q || !op || cmode != 15;
}

static void orlix_tcti_decode_exhaustive_simd_modimm(struct kunit *test)
{
	bool seen_rd[32] = {};
	u8 q;
	u8 op;
	u8 cmode;

	for (q = 0; q < 2; q++) {
		for (op = 0; op < 2; op++) {
			for (cmode = 0; cmode < 16; cmode++) {
				unsigned int immediate;

				for (immediate = 0; immediate < 256;
				     immediate++) {
					u8 imm8 = immediate;
					u8 rd = immediate & 0x1fU;
					u32 instruction =
						orlix_tcti_test_encode_simd_modimm(
							q, op, false, cmode,
							imm8, rd);
					struct orlix_tcti_decoded_instruction decoded =
						orlix_tcti_decode_aarch64(
							instruction);

					if (!orlix_tcti_test_simd_modimm_is_valid(
						    q, op, cmode)) {
						KUNIT_EXPECT_EQ(
							test,
							ORLIX_TCTI_DECODE_UNSUPPORTED,
							decoded.decode_class);
						continue;
					}

					KUNIT_ASSERT_EQ_MSG(
						test,
						ORLIX_TCTI_DECODE_SIMD_MODIFIED_IMMEDIATE,
						decoded.decode_class,
						"instruction=%#x q=%u op=%u cmode=%u imm8=%#x",
						instruction, q, op, cmode,
						imm8);
					KUNIT_EXPECT_EQ(
						test,
						orlix_tcti_test_simd_modimm_operation(
							cmode, op),
						decoded.simd_modified_immediate_op);
					KUNIT_EXPECT_EQ(
						test,
						orlix_tcti_test_expand_simd_modimm(
							cmode, op, imm8),
						decoded.logical_immediate);
					KUNIT_EXPECT_EQ(test, q ? 16U : 8U,
							decoded.result_size);
					KUNIT_EXPECT_EQ(test,
							decoded.result_size,
							decoded.access_size);
					KUNIT_EXPECT_EQ(test, rd, decoded.rd);
					KUNIT_EXPECT_TRUE(test,
							  decoded.simd_fp);
					seen_rd[rd] = true;
				}
			}
		}
	}

	for (q = 0; q < 32; q++)
		KUNIT_EXPECT_TRUE(test, seen_rd[q]);
}

static void orlix_tcti_decode_rejects_unexposed_simd_modimm_o2(struct kunit *test)
{
	u8 q;
	u8 op;
	u8 cmode;

	for (q = 0; q < 2; q++) {
		for (op = 0; op < 2; op++) {
			for (cmode = 0; cmode < 16; cmode++) {
				unsigned int immediate;

				for (immediate = 0; immediate < 256;
				     immediate++) {
					u32 instruction =
						orlix_tcti_test_encode_simd_modimm(
							q, op, true, cmode,
							immediate,
							immediate & 0x1fU);
					struct orlix_tcti_decoded_instruction decoded =
						orlix_tcti_decode_aarch64(
							instruction);

					KUNIT_EXPECT_EQ(test,
							ORLIX_TCTI_DECODE_UNSUPPORTED,
							decoded.decode_class);
				}
			}
		}
	}
}

static void orlix_tcti_decode_recognizes_complete_simd_scalar_element_dup_family(
	struct kunit *test)
{
	static const struct {
		u32 instruction;
		u8 access_size;
		u8 source_index;
	} cases[] = {
		{ 0x5e1f0420U, sizeof(u8), 15 },
		{ 0x5e1e0420U, sizeof(u16), 7 },
		{ 0x5e1c0420U, sizeof(u32), 3 },
		{ 0x5e180420U, sizeof(u64), 1 },
	};
	size_t i;

	for (i = 0; i < ARRAY_SIZE(cases); i++) {
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(cases[i].instruction);

		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_ELEMENT_MOVE,
			decoded.decode_class);
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ELEMENT_MOVE_DUP,
			decoded.simd_element_move_op);
		KUNIT_EXPECT_TRUE(test, decoded.simd_scalar);
		KUNIT_EXPECT_FALSE(test, decoded.immediate);
		KUNIT_EXPECT_EQ(test, cases[i].access_size, decoded.access_size);
		KUNIT_EXPECT_EQ(test, cases[i].access_size, decoded.result_size);
		KUNIT_EXPECT_EQ(test, cases[i].source_index,
			decoded.simd_source_index);
		KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
		KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
	}
}

static void
orlix_tcti_decode_recognizes_complete_simd_dup_element_family(struct kunit *test)
{
	static const u8 access_sizes[] = {
		sizeof(u8),
		sizeof(u16),
		sizeof(u32),
		sizeof(u64),
	};
	unsigned int q;
	size_t size_index;

	for (q = 0; q < 2; q++) {
		for (size_index = 0; size_index < ARRAY_SIZE(access_sizes);
		     size_index++) {
			u8 access_size = access_sizes[size_index];
			u8 lane_shift = __builtin_ctz((unsigned int)access_size);
			u8 lane_count = 16 / access_size;
			u8 lane;

			if (!q && access_size == sizeof(u64))
				continue;

			for (lane = 0; lane < lane_count; lane++) {
				u8 imm5 = (lane << (lane_shift + 1)) |
					  BIT(lane_shift);
				u32 instruction = 0x0e000400U |
						  (q ? BIT(30) : 0) |
						  ((u32)imm5 << 16) |
						  (4U << 5) | 5U;
				struct orlix_tcti_decoded_instruction decoded =
					orlix_tcti_decode_aarch64(instruction);

				KUNIT_EXPECT_EQ(test,
						ORLIX_TCTI_DECODE_SIMD_VECTOR_ELEMENT_MOVE,
						decoded.decode_class);
				KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ELEMENT_MOVE_DUP,
						decoded.simd_element_move_op);
				KUNIT_EXPECT_FALSE(test, decoded.simd_scalar);
				KUNIT_EXPECT_FALSE(test, decoded.immediate);
				KUNIT_EXPECT_EQ(test, access_size,
						decoded.access_size);
				KUNIT_EXPECT_EQ(test,
						q ? 2 * sizeof(u64) : sizeof(u64),
						decoded.result_size);
				KUNIT_EXPECT_EQ(test, lane,
						decoded.simd_source_index);
				KUNIT_EXPECT_EQ(test, 5U, decoded.rd);
				KUNIT_EXPECT_EQ(test, 4U, decoded.rn);
				KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
			}
		}
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x0e000400U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x4e000400U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x0e080400U).decode_class);
}

