static void
orlix_tcti_decode_recognizes_complete_simd_shift_left_long_family(struct kunit *test)
{
	static const u8 access_sizes[] = {
		sizeof(u8), sizeof(u16), sizeof(u32),
	};
	size_t size_index;
	u8 is_unsigned;
	u8 upper;
	u8 shift;

	for (is_unsigned = 0; is_unsigned < 2; is_unsigned++) {
		for (upper = 0; upper < 2; upper++) {
			for (size_index = 0;
			     size_index < ARRAY_SIZE(access_sizes);
			     size_index++) {
				u8 access_size = access_sizes[size_index];
				u8 element_bits = access_size * 8;

				for (shift = 0; shift < element_bits; shift++) {
					u32 instruction = 0x0f00a400U |
						(is_unsigned ? BIT(29) : 0) |
						(upper ? BIT(30) : 0) |
						((element_bits + shift) << 16) |
						(4U << 5) | 5U;
					struct orlix_tcti_decoded_instruction decoded =
						orlix_tcti_decode_aarch64(instruction);

					KUNIT_EXPECT_EQ(test,
						ORLIX_TCTI_DECODE_SIMD_VECTOR_ELEMENT_MOVE,
						decoded.decode_class);
					KUNIT_EXPECT_EQ(test, 5U, decoded.rd);
					KUNIT_EXPECT_EQ(test, 4U, decoded.rn);
					KUNIT_EXPECT_EQ(test, access_size,
							decoded.access_size);
					KUNIT_EXPECT_EQ(test, 16U,
							decoded.result_size);
					KUNIT_EXPECT_EQ(test, shift,
							decoded.shift_amount);
					KUNIT_EXPECT_EQ(test,
						upper ? sizeof(u64) / access_size : 0,
						decoded.simd_source_index);
					KUNIT_EXPECT_EQ(test,
						is_unsigned ?
						ORLIX_TCTI_SIMD_ELEMENT_MOVE_USHLL :
						ORLIX_TCTI_SIMD_ELEMENT_MOVE_SSHLL,
						decoded.simd_element_move_op);
					KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
				}
			}
		}
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_MODIFIED_IMMEDIATE,
			orlix_tcti_decode_aarch64(0x0f00a400U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_MODIFIED_IMMEDIATE,
			orlix_tcti_decode_aarch64(0x0f07a400U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x0f40a400U).decode_class);
}

static void
orlix_tcti_decode_recognizes_complete_simd_vector_logical_family(struct kunit *test)
{
	u8 operation;
	u8 q;

	for (operation = 0; operation < 8; operation++) {
		for (q = 0; q < 2; q++) {
			u32 instruction = 0x0e201c00U |
				(operation >= 4 ? BIT(29) : 0) |
				((u32)(operation & 0x3U) << 22) |
				(q ? BIT(30) : 0) | (2U << 16) |
				(1U << 5);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);

			KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_LOGICAL,
					decoded.decode_class);
			KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
			KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
			KUNIT_EXPECT_EQ(test, 2U, decoded.rm);
			KUNIT_EXPECT_EQ(test, q ? 16U : 8U,
					decoded.access_size);
			KUNIT_EXPECT_EQ(test, q ? 16U : 8U,
					decoded.result_size);
			KUNIT_EXPECT_EQ(test, operation, decoded.logical_op);
			KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
		}
	}

}

