static void orlix_tcti_decode_recognizes_complete_simd_single_structure_family(
	struct kunit *test)
{
	static const struct {
		u32 instruction;
		enum orlix_tcti_decode_class decode_class;
		u8 access_size;
		u8 lane;
		u8 count;
		bool load;
		bool post_index;
		bool replicate;
		u8 rm;
	} cases[] = {
		{ 0x4d400100U, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		  sizeof(u8), 8, 1, true, false, false, 0 },
		{ 0x4d000100U, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		  sizeof(u8), 8, 1, false, false, false, 0 },
		{ 0x4d405900U, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		  sizeof(u16), 7, 1, true, false, false, 0 },
		{ 0x4d409100U, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		  sizeof(u32), 3, 1, true, false, false, 0 },
		{ 0x4d408500U, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		  sizeof(u64), 1, 1, true, false, false, 0 },
		{ 0x4d600100U, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		  sizeof(u8), 8, 2, true, false, false, 0 },
		{ 0x4d402100U, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		  sizeof(u8), 8, 3, true, false, false, 0 },
		{ 0x4d602100U, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		  sizeof(u8), 8, 4, true, false, false, 0 },
		{ 0x4ddf0100U, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		  sizeof(u8), 8, 1, true, true, false, 31 },
		{ 0x4dc90100U, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		  sizeof(u8), 8, 1, true, true, false, 9 },
		{ 0x4d60e100U, ORLIX_TCTI_DECODE_SIMD_LOAD_REPLICATE,
		  sizeof(u8), 0, 4, true, false, true, 0 },
		{ 0x0d40c100U, ORLIX_TCTI_DECODE_SIMD_LOAD_REPLICATE,
		  sizeof(u8), 0, 1, true, false, true, 0 },
	};
	u32 index;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(cases[index].instruction);

		KUNIT_EXPECT_EQ(test, cases[index].decode_class,
			decoded.decode_class);
		KUNIT_EXPECT_EQ(test, cases[index].access_size,
			decoded.access_size);
		KUNIT_EXPECT_EQ(test, cases[index].lane,
			decoded.simd_lane_index);
		KUNIT_EXPECT_EQ(test, cases[index].count,
			decoded.simd_structure_count);
		KUNIT_EXPECT_EQ(test, cases[index].load, decoded.load);
		KUNIT_EXPECT_EQ(test, cases[index].post_index,
			decoded.memory_index_mode == ORLIX_TCTI_MEMORY_INDEX_POST);
		KUNIT_EXPECT_EQ(test, cases[index].replicate,
			decoded.simd_replicate);
		KUNIT_EXPECT_EQ(test, cases[index].rm, decoded.rm);
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x4d405500U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x4d410100U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x4d00c100U).decode_class);
}

static void orlix_tcti_decode_recognizes_complete_simd_multiple_structure_family(
	struct kunit *test)
{
	static const struct {
		u32 instruction;
		u8 count;
		u8 access_size;
		u8 result_size;
		bool load;
		bool interleaved;
		bool post_index;
		u8 rm;
	} cases[] = {
		{ 0x4c407100U, 1, sizeof(u8), 16, true, false, false, 0 },
		{ 0x0c00a121U, 2, sizeof(u8), 8, false, false, false, 0 },
		{ 0x0c408543U, 2, sizeof(u16), 8, true, true, false, 0 },
		{ 0x0c008965U, 2, sizeof(u32), 8, false, true, false, 0 },
		{ 0x4cdf4d87U, 3, sizeof(u64), 16, true, true, true, 31 },
		{ 0x4c8e45aaU, 3, sizeof(u16), 16, false, true, true, 14 },
		{ 0x4cdf022dU, 4, sizeof(u8), 16, true, true, true, 31 },
		{ 0x4c970ad2U, 4, sizeof(u32), 16, false, true, true, 23 },
		{ 0x4cdf231eU, 4, sizeof(u8), 16, true, false, true, 31 },
	};
	u32 index;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(cases[index].instruction);

		KUNIT_EXPECT_EQ(test,
			ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_MULTIPLE_STRUCTURE,
			decoded.decode_class);
		KUNIT_EXPECT_EQ(test, cases[index].count,
			decoded.simd_structure_count);
		KUNIT_EXPECT_EQ(test, cases[index].access_size,
			decoded.access_size);
		KUNIT_EXPECT_EQ(test, cases[index].result_size,
			decoded.result_size);
		KUNIT_EXPECT_EQ(test, cases[index].load, decoded.load);
		KUNIT_EXPECT_EQ(test, cases[index].interleaved,
			decoded.simd_interleaved);
		KUNIT_EXPECT_EQ(test, cases[index].post_index,
			decoded.memory_index_mode == ORLIX_TCTI_MEMORY_INDEX_POST);
		KUNIT_EXPECT_EQ(test, cases[index].rm, decoded.rm);
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x4c401100U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x4c417100U).decode_class);
}

static u32 orlix_tcti_test_encode_simd_multiple_structure(
	bool q, bool post_index, bool load, u8 rm, u8 opcode, u8 size,
	u8 rn, u8 rt)
{
	return 0x0c000000U | (q ? BIT(30) : 0) |
		(post_index ? BIT(23) : 0) | (load ? BIT(22) : 0) |
		((u32)rm << 16) | ((u32)opcode << 12) |
		((u32)size << 10) | ((u32)rn << 5) | rt;
}

static u8 orlix_tcti_test_simd_multiple_structure_count(u8 opcode)
{
	switch (opcode) {
	case 7:
		return 1;
	case 8:
	case 10:
		return 2;
	case 4:
	case 6:
		return 3;
	case 0:
	case 2:
		return 4;
	default:
		return 0;
	}
}

static void orlix_tcti_decode_exhaustive_simd_multiple_structure_family(
	struct kunit *test)
{
	u32 control;

	for (control = 0; control < BIT(14); control++) {
		u8 size = control & 0x3U;
		u8 opcode = (control >> 2) & 0xfU;
		u8 rm = (control >> 6) & 0x1fU;
		bool load = control & BIT(11);
		bool post_index = control & BIT(12);
		bool q = control & BIT(13);
		u8 count = orlix_tcti_test_simd_multiple_structure_count(opcode);
		bool legal = count && (post_index || !rm);
		u32 instruction = orlix_tcti_test_encode_simd_multiple_structure(
			q, post_index, load, rm, opcode, size, 9, 10);
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(instruction);

		if (!legal) {
			KUNIT_EXPECT_EQ_MSG(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
				decoded.decode_class, "instruction=%08x", instruction);
			continue;
		}

		KUNIT_ASSERT_EQ_MSG(test,
			ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_MULTIPLE_STRUCTURE,
			decoded.decode_class, "instruction=%08x", instruction);
		KUNIT_EXPECT_EQ(test, count, decoded.simd_structure_count);
		KUNIT_EXPECT_EQ(test, q ? 16 : 8, decoded.result_size);
		KUNIT_EXPECT_EQ(test, (u8)BIT(size), decoded.access_size);
		KUNIT_EXPECT_EQ(test, load, decoded.load);
		KUNIT_EXPECT_EQ(test,
			opcode == 0 || opcode == 4 || opcode == 8,
			decoded.simd_interleaved);
		KUNIT_EXPECT_EQ(test, post_index,
			decoded.memory_index_mode == ORLIX_TCTI_MEMORY_INDEX_POST);
		KUNIT_EXPECT_EQ(test, rm, decoded.rm);
	}
}

static bool orlix_tcti_test_simd_single_structure_is_legal(
	bool post_index, bool load, u8 rm, u8 opcode, bool s, u8 size)
{
	u8 base_opcode = opcode & ~1U;

	/* STL1/LDAP1 encode asisdlso D-size with Rm=00001. */
	if (!post_index && rm)
		return rm == 1 && opcode == 4 && size == 1 && !s;
	if (load && !s && (opcode == 6 || opcode == 7))
		return true;
	if (base_opcode == 0)
		return true;
	if (base_opcode == 2)
		return !(size & 1U);
	if (base_opcode == 4)
		return size == 0 || (size == 1 && !s);
	return false;
}

static u32 orlix_tcti_test_encode_simd_single_structure(
	bool q, bool post_index, bool load, bool r, u8 rm, u8 opcode,
	bool s, u8 size, u8 rn, u8 rt)
{
	return 0x0d000000U | (q ? BIT(30) : 0) |
		(post_index ? BIT(23) : 0) | (load ? BIT(22) : 0) |
		(r ? BIT(21) : 0) | ((u32)rm << 16) |
		((u32)opcode << 13) | (s ? BIT(12) : 0) |
		((u32)size << 10) | ((u32)rn << 5) | rt;
}

static void orlix_tcti_decode_exhaustive_simd_single_structure_family(
	struct kunit *test)
{
	u32 control;

	for (control = 0; control < BIT(15); control++) {
		u8 size = control & 0x3U;
		bool s = control & BIT(2);
		u8 opcode = (control >> 3) & 0x7U;
		u8 rm = (control >> 6) & 0x1fU;
		bool r = control & BIT(11);
		bool load = control & BIT(12);
		bool post_index = control & BIT(13);
		bool q = control & BIT(14);
		bool replicate = load && !s &&
			(opcode == 6 || opcode == 7);
		bool legal = orlix_tcti_test_simd_single_structure_is_legal(
			post_index, load, rm, opcode, s, size);
		u32 instruction = orlix_tcti_test_encode_simd_single_structure(
			q, post_index, load, r, rm, opcode, s, size, 9, 10);
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(instruction);

		if (!legal) {
			KUNIT_EXPECT_EQ_MSG(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
				decoded.decode_class, "instruction=%08x", instruction);
			continue;
		}

		KUNIT_ASSERT_EQ_MSG(test,
			replicate ? ORLIX_TCTI_DECODE_SIMD_LOAD_REPLICATE :
				ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
			decoded.decode_class, "instruction=%08x", instruction);
		KUNIT_EXPECT_EQ(test, r ? (opcode & 1U ? 4 : 2) :
			(opcode & 1U ? 3 : 1), decoded.simd_structure_count);
		KUNIT_EXPECT_EQ(test, post_index,
			decoded.memory_index_mode == ORLIX_TCTI_MEMORY_INDEX_POST);
		KUNIT_EXPECT_EQ(test, replicate, decoded.simd_replicate);
		KUNIT_EXPECT_EQ(test, load, decoded.load);
		KUNIT_EXPECT_EQ(test, rm, decoded.rm);
		if (replicate) {
			KUNIT_EXPECT_EQ(test, (u8)BIT(size), decoded.access_size);
			KUNIT_EXPECT_EQ(test, q ? 16 : 8, decoded.result_size);
		} else if ((opcode & ~1U) == 0) {
			KUNIT_EXPECT_EQ(test, sizeof(u8), decoded.access_size);
			KUNIT_EXPECT_EQ(test, (q << 3) | (s << 2) | size,
				decoded.simd_lane_index);
		} else if ((opcode & ~1U) == 2) {
			KUNIT_EXPECT_EQ(test, sizeof(u16), decoded.access_size);
			KUNIT_EXPECT_EQ(test, (q << 2) | (s << 1) | (size >> 1),
				decoded.simd_lane_index);
		} else {
			KUNIT_EXPECT_EQ(test, size ? sizeof(u64) : sizeof(u32),
				decoded.access_size);
			KUNIT_EXPECT_EQ(test, size ? q : (q << 1) | s,
				decoded.simd_lane_index);
		}
	}
}

static void orlix_tcti_decode_simd_structure_all_register_fields(struct kunit *test)
{
	u16 fields;

	for (fields = 0; fields < BIT(10); fields++) {
		u8 rn = (fields >> 5) & 0x1fU;
		u8 rt = fields & 0x1fU;
		struct orlix_tcti_decoded_instruction multiple = orlix_tcti_decode_aarch64(
			orlix_tcti_test_encode_simd_multiple_structure(
				true, true, true, 31, 0, 0, rn, rt));
		struct orlix_tcti_decoded_instruction single = orlix_tcti_decode_aarch64(
			orlix_tcti_test_encode_simd_single_structure(
				true, true, true, true, 31, 0, false, 0,
				rn, rt));

		KUNIT_ASSERT_EQ(test,
			ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_MULTIPLE_STRUCTURE,
			multiple.decode_class);
		KUNIT_EXPECT_EQ(test, rn, multiple.rn);
		KUNIT_EXPECT_EQ(test, rt, multiple.rd);
		KUNIT_ASSERT_EQ(test,
			ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
			single.decode_class);
		KUNIT_EXPECT_EQ(test, rn, single.rn);
		KUNIT_EXPECT_EQ(test, rt, single.rd);
	}
}

static void orlix_tcti_decode_recognizes_complete_simd_ext_family(struct kunit *test)
{
	u8 q;

	for (q = 0; q < 2; q++) {
		u8 vector_bytes = q ? 16 : 8;
		u8 index;

		for (index = 0; index < vector_bytes; index++) {
			u32 instruction = 0x2e000000U | (q ? BIT(30) : 0) |
				(2U << 16) | ((u32)index << 11) |
				(1U << 5);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);

			KUNIT_EXPECT_EQ(test,
				ORLIX_TCTI_DECODE_SIMD_VECTOR_ELEMENT_MOVE,
				decoded.decode_class);
			KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
			KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
			KUNIT_EXPECT_EQ(test, 2U, decoded.rm);
			KUNIT_EXPECT_EQ(test, index, decoded.shift_amount);
			KUNIT_EXPECT_EQ(test, vector_bytes,
					decoded.access_size);
			KUNIT_EXPECT_EQ(test, vector_bytes,
					decoded.result_size);
			KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ELEMENT_MOVE_EXT,
					decoded.simd_element_move_op);
			KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
		}
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x2e004000U).decode_class);
}

