static void orlix_tcti_decode_recognizes_complete_simd_permute_family(
	struct kunit *test)
{
	static const struct {
		u8 encoding;
		enum orlix_tcti_simd_element_move_op operation;
	} operations[] = {
		{ 1, ORLIX_TCTI_SIMD_ELEMENT_MOVE_UZP1 },
		{ 5, ORLIX_TCTI_SIMD_ELEMENT_MOVE_UZP2 },
		{ 2, ORLIX_TCTI_SIMD_ELEMENT_MOVE_TRN1 },
		{ 6, ORLIX_TCTI_SIMD_ELEMENT_MOVE_TRN2 },
		{ 3, ORLIX_TCTI_SIMD_ELEMENT_MOVE_ZIP1 },
		{ 7, ORLIX_TCTI_SIMD_ELEMENT_MOVE_ZIP2 },
	};
	size_t operation_index;
	u8 q;
	u8 size;

	for (operation_index = 0; operation_index < ARRAY_SIZE(operations);
	     operation_index++) {
		for (q = 0; q <= 1; q++) {
			for (size = 0; size <= 3; size++) {
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;

				if (!q && size == 3)
					continue;
				instruction = 0x0e000800U | ((u32)q << 30) |
					      ((u32)size << 22) | (2U << 16) |
					      ((u32)operations[operation_index].encoding << 12) |
					      (1U << 5);
				decoded = orlix_tcti_decode_aarch64(instruction);

				KUNIT_EXPECT_EQ(test,
					ORLIX_TCTI_DECODE_SIMD_VECTOR_ELEMENT_MOVE,
					decoded.decode_class);
				KUNIT_EXPECT_EQ(test,
					operations[operation_index].operation,
					decoded.simd_element_move_op);
				KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
				KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
				KUNIT_EXPECT_EQ(test, 2U, decoded.rm);
				KUNIT_EXPECT_EQ(test, 1U << size,
					decoded.access_size);
				KUNIT_EXPECT_EQ(test, q ? 16U : 8U,
					decoded.result_size);
			}
		}
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x0ec01800U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x0e000800U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x0e004800U).decode_class);
}

