static void orlix_tcti_decode_exhaustive_simd_fp_pairwise(struct kunit *test)
{
	static const struct {
		u32 pattern;
		enum orlix_tcti_simd_reduction_op operation;
	} cases[] = {
		{ 0x7e30d800U, ORLIX_TCTI_SIMD_REDUCTION_FADDP },
		{ 0x7e30c800U, ORLIX_TCTI_SIMD_REDUCTION_FMAXNMP },
		{ 0x7e30f800U, ORLIX_TCTI_SIMD_REDUCTION_FMAXP },
		{ 0x7eb0c800U, ORLIX_TCTI_SIMD_REDUCTION_FMINNMP },
		{ 0x7eb0f800U, ORLIX_TCTI_SIMD_REDUCTION_FMINP },
	};
	unsigned int case_index;
	u8 precision;
	u8 rn;
	u8 rd;

	for (case_index = 0; case_index < ARRAY_SIZE(cases); case_index++) {
		for (precision = 0; precision < 2; precision++) {
			for (rn = 0; rn < 32; rn++) {
				for (rd = 0; rd < 32; rd++) {
					u32 instruction = cases[case_index].pattern |
						((u32)precision << 22) |
						((u32)rn << 5) | rd;
					struct orlix_tcti_decoded_instruction decoded =
						orlix_tcti_decode_aarch64(instruction);

					KUNIT_EXPECT_EQ(
						test, ORLIX_TCTI_DECODE_SIMD_VECTOR_REDUCTION,
						decoded.decode_class);
					KUNIT_EXPECT_EQ(test,
							cases[case_index].operation,
							decoded.simd_reduction_op);
					KUNIT_EXPECT_EQ(test, rd, decoded.rd);
					KUNIT_EXPECT_EQ(test, rn, decoded.rn);
					KUNIT_EXPECT_EQ(test, precision ? 8 : 4,
							decoded.access_size);
					KUNIT_EXPECT_EQ(test, decoded.access_size,
							decoded.result_size);
					KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
				}
			}
		}
		{
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(cases[case_index].pattern ^ BIT(11));

			KUNIT_EXPECT_FALSE(
				test,
				decoded.decode_class == ORLIX_TCTI_DECODE_SIMD_VECTOR_REDUCTION &&
				decoded.simd_reduction_op == cases[case_index].operation);
		}
	}
}

static void
orlix_tcti_decode_recognizes_complete_simd_halving_add_family(struct kunit *test)
{
	u8 operation;
	u8 q;
	u8 size;

	for (operation = 0; operation < 4; operation++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 4; size++) {
				u32 instruction = 0x0e200400U |
					((operation & 1U) ? BIT(29) : 0) |
					((operation & 2U) ? BIT(12) : 0) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | (2U << 16) |
					(1U << 5);
				struct orlix_tcti_decoded_instruction decoded =
					orlix_tcti_decode_aarch64(instruction);

				if (size == 3) {
					KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
							decoded.decode_class);
					continue;
				}

				KUNIT_EXPECT_EQ(test,
					ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
					decoded.decode_class);
				KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
				KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
				KUNIT_EXPECT_EQ(test, 2U, decoded.rm);
				KUNIT_EXPECT_EQ(test, 1U << size,
						decoded.access_size);
				KUNIT_EXPECT_EQ(test, q ? 16U : 8U,
						decoded.result_size);
				KUNIT_EXPECT_EQ(test,
					ORLIX_TCTI_SIMD_ARITH_SHADD + operation,
					decoded.simd_arithmetic_op);
				KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
			}
		}
	}
}

