static void orlix_tcti_decode_recognizes_complete_simd_sha3_family(struct kunit *test)
{
	static const struct {
		u32 instruction;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
		u8 rd;
		u8 rn;
		u8 rm;
		u8 ra;
		u8 shift_amount;
	} cases[] = {
		{ 0xce020c20U, ORLIX_TCTI_SIMD_ARITH_EOR3, 0, 1, 2, 3, 0 },
		{ 0xce668ca4U, ORLIX_TCTI_SIMD_ARITH_RAX1, 4, 5, 6, 0, 0 },
		{ 0xce893507U, ORLIX_TCTI_SIMD_ARITH_XAR, 7, 8, 9, 0, 13 },
		{ 0xce2c356aU, ORLIX_TCTI_SIMD_ARITH_BCAX, 10, 11, 12, 13, 0 },
	};
	size_t index;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(cases[index].instruction);

		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
				decoded.decode_class);
		KUNIT_EXPECT_EQ(test, cases[index].rd, decoded.rd);
		KUNIT_EXPECT_EQ(test, cases[index].rn, decoded.rn);
		KUNIT_EXPECT_EQ(test, cases[index].rm, decoded.rm);
		KUNIT_EXPECT_EQ(test, cases[index].ra, decoded.ra);
		KUNIT_EXPECT_EQ(test, cases[index].shift_amount,
				decoded.shift_amount);
		KUNIT_EXPECT_EQ(test, 16U, decoded.access_size);
		KUNIT_EXPECT_EQ(test, 16U, decoded.result_size);
		KUNIT_EXPECT_EQ(test, cases[index].operation,
				decoded.simd_arithmetic_op);
		KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
		KUNIT_EXPECT_FALSE(test, decoded.simd_scalar);
	}
}

