static void orlix_tcti_decode_exhaustive_simd_sm3_family(struct kunit *test)
{
	static const enum orlix_tcti_simd_vector_arithmetic_op tt_operations[] = {
		ORLIX_TCTI_SIMD_ARITH_SM3TT1A,
		ORLIX_TCTI_SIMD_ARITH_SM3TT1B,
		ORLIX_TCTI_SIMD_ARITH_SM3TT2A,
		ORLIX_TCTI_SIMD_ARITH_SM3TT2B,
	};
	static const u32 tt_patterns[] = {
		0xce408000U,
		0xce408400U,
		0xce408800U,
		0xce408c00U,
	};
	size_t index;

	orlix_tcti_decode_exhaustive_simd_crypto_pattern(
		test, 0xce400000U, 0xffe08000U,
		ORLIX_TCTI_SIMD_ARITH_SM3SS1, true, true, 0, 0);
	for (index = 0; index < ARRAY_SIZE(tt_patterns); index++)
		orlix_tcti_decode_exhaustive_simd_crypto_pattern(
			test, tt_patterns[index], 0xffe0cc00U,
			tt_operations[index], true, false, 12, 2);
	orlix_tcti_decode_exhaustive_simd_crypto_pattern(
		test, 0xce60c000U, 0xffe0fc00U,
		ORLIX_TCTI_SIMD_ARITH_SM3PARTW1, true, false, 0, 0);
	orlix_tcti_decode_exhaustive_simd_crypto_pattern(
		test, 0xce60c400U, 0xffe0fc00U,
		ORLIX_TCTI_SIMD_ARITH_SM3PARTW2, true, false, 0, 0);
}

