static void
orlix_tcti_decode_recognizes_complete_simd_saturating_shift_left_immediate_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0f007400U, false, ORLIX_TCTI_SIMD_ARITH_SQSHL },
		{ 0x0f007400U, true, ORLIX_TCTI_SIMD_ARITH_UQSHL },
		{ 0x0f006400U, true, ORLIX_TCTI_SIMD_ARITH_SQSHLU },
	};
	size_t index;
	u8 scalar;
	u8 q;
	u8 size;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (scalar = 0; scalar < 2; scalar++) {
			for (q = 0; q < 2; q++) {
				if (scalar && q)
					continue;
				for (size = 0; size < 4; size++) {
					u8 access_size = BIT(size);
					u8 lane_bits = access_size * 8;
					u8 shift;

					for (shift = 0; shift < lane_bits; shift++) {
						u32 instruction = cases[index].pattern |
							(cases[index].u ? BIT(29) : 0) |
							(scalar ? BIT(28) | BIT(30) :
							 (q ? BIT(30) : 0)) |
							((u32)(lane_bits + shift) << 16) |
							(1U << 5);
						struct orlix_tcti_decoded_instruction decoded =
							orlix_tcti_decode_aarch64(instruction);

						if (!scalar && !q && size == 3) {
							KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
									decoded.decode_class);
							continue;
						}

						KUNIT_EXPECT_EQ(test,
								ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
								decoded.decode_class);
						KUNIT_EXPECT_EQ(test, access_size,
								decoded.access_size);
						KUNIT_EXPECT_EQ(test,
								scalar ? access_size : (q ? 16U : 8U),
								decoded.result_size);
						KUNIT_EXPECT_EQ(test, shift,
								decoded.shift_amount);
						KUNIT_EXPECT_EQ(test, cases[index].operation,
								decoded.simd_arithmetic_op);
						KUNIT_EXPECT_EQ(test, !!scalar,
								decoded.simd_scalar);
						KUNIT_EXPECT_TRUE(test, decoded.immediate);
					}
				}
			}
		}
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			 orlix_tcti_decode_aarch64(0x0f0f6420U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_3SOURCE,
		orlix_tcti_decode_aarch64(0x1f0f7420U).decode_class);
}

static void orlix_tcti_decode_exhaustive_simd_scalar_sqdm_long(struct kunit *test)
{
	static const struct {
		u32 pattern;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x5e209000U, ORLIX_TCTI_SIMD_ARITH_SQDMLAL },
		{ 0x5e20b000U, ORLIX_TCTI_SIMD_ARITH_SQDMLSL },
		{ 0x5e20d000U, ORLIX_TCTI_SIMD_ARITH_SQDMULL },
	};
	size_t index;
	u8 size;
	u8 reg;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (size = 0; size < 4; size++) {
			for (reg = 0; reg < 32; reg++) {
				u8 rn = (reg + 1) & 0x1fU;
				u8 rm = (reg + 2) & 0x1fU;
				u32 instruction = cases[index].pattern |
						  ((u32)size << 22) |
						  ((u32)rm << 16) |
						  ((u32)rn << 5) | reg;
				struct orlix_tcti_decoded_instruction decoded =
					orlix_tcti_decode_aarch64(instruction);

				if (size != 1 && size != 2) {
					KUNIT_EXPECT_EQ(test,
							ORLIX_TCTI_DECODE_UNSUPPORTED,
							decoded.decode_class);
					continue;
				}
				KUNIT_EXPECT_EQ(test,
						ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
						decoded.decode_class);
				KUNIT_EXPECT_EQ(test, cases[index].operation,
						decoded.simd_arithmetic_op);
				KUNIT_EXPECT_EQ(test, reg, decoded.rd);
				KUNIT_EXPECT_EQ(test, rn, decoded.rn);
				KUNIT_EXPECT_EQ(test, rm, decoded.rm);
				KUNIT_EXPECT_EQ(test, 1U << size,
						decoded.access_size);
				KUNIT_EXPECT_EQ(test, 2U << size,
						decoded.result_size);
				KUNIT_EXPECT_TRUE(test, decoded.simd_scalar);
				KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
			}
		}
	}
}

