static void orlix_tcti_decode_exhaustive_simd_mixed_saturating_add(
	struct kunit *test)
{
	u8 u;
	u8 scalar;
	u8 q;
	u8 size;
	u8 reg;

	for (u = 0; u < 2; u++) {
		for (scalar = 0; scalar < 2; scalar++) {
			for (q = 0; q < 2; q++) {
				for (size = 0; size < 4; size++) {
					for (reg = 0; reg < 32; reg++) {
						u8 rn = (reg + 1) & 0x1fU;
						u32 instruction = 0x0e203800U |
							(u ? BIT(29) : 0) |
							(scalar ? BIT(28) : 0) |
							(q ? BIT(30) : 0) |
							((u32)size << 22) |
							((u32)rn << 5) | reg;
						struct orlix_tcti_decoded_instruction decoded =
							orlix_tcti_decode_aarch64(instruction);
						bool valid = scalar ? q : q || size != 3;
						bool overlaps_fp_fsub =
							scalar && !q && !u && size != 2;

						if (!valid &&
						    decoded.decode_class ==
						    ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC)
							valid = true;
						if (!valid) {
							if (overlaps_fp_fsub) {
								u8 fp_size = size == 3 ?
									sizeof(u16) :
									size ? sizeof(u64) :
									sizeof(u32);

								KUNIT_EXPECT_EQ(
									test,
									ORLIX_TCTI_DECODE_FP_SCALAR_2SOURCE,
									decoded.decode_class);
								KUNIT_EXPECT_EQ(
									test, ORLIX_TCTI_FP2_FSUB,
									decoded.fp2_op);
								KUNIT_EXPECT_EQ(test, reg,
									decoded.rd);
								KUNIT_EXPECT_EQ(test, rn,
									decoded.rn);
								KUNIT_EXPECT_EQ(test, fp_size,
									decoded.access_size);
								KUNIT_EXPECT_EQ(test, fp_size,
									decoded.result_size);
								continue;
							}
							KUNIT_EXPECT_EQ(
								test, ORLIX_TCTI_DECODE_UNSUPPORTED,
								decoded.decode_class);
							continue;
						}
						KUNIT_EXPECT_EQ(
							test,
							ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
							decoded.decode_class);
						KUNIT_EXPECT_EQ(
							test,
							u ? ORLIX_TCTI_SIMD_ARITH_USQADD :
							    ORLIX_TCTI_SIMD_ARITH_SUQADD,
							decoded.simd_arithmetic_op);
						KUNIT_EXPECT_EQ(test, reg, decoded.rd);
						KUNIT_EXPECT_EQ(test, rn, decoded.rn);
						KUNIT_EXPECT_EQ(test, 1U << size,
							decoded.access_size);
						KUNIT_EXPECT_EQ(
							test,
							scalar ? 1U << size : q ? 16U : 8U,
							decoded.result_size);
						KUNIT_EXPECT_EQ(test, !!scalar,
							decoded.simd_scalar);
						KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
					}
				}
			}
		}
	}
}

static void orlix_tcti_decode_exhaustive_simd_pairwise_long(struct kunit *test)
{
	u16 variant;

	for (variant = 0; variant < 1024; variant++) {
		u8 reg = variant & 0x1fU;
		u8 size = (variant >> 5) & 0x3U;
		u8 q = (variant >> 7) & 0x1U;
		u8 u = (variant >> 8) & 0x1U;
		u8 accumulate = (variant >> 9) & 0x1U;
		u8 rn = (reg + 1) & 0x1fU;
		u32 instruction = 0x0e202800U |
			(accumulate ? BIT(14) : 0) | (u ? BIT(29) : 0) |
			(q ? BIT(30) : 0) | ((u32)size << 22) |
			((u32)rn << 5) | reg;
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(instruction);
		enum orlix_tcti_simd_vector_arithmetic_op operation;

		if (size == 3) {
			KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
					decoded.decode_class);
			continue;
		}
		if (accumulate)
			operation = u ? ORLIX_TCTI_SIMD_ARITH_UADALP :
				ORLIX_TCTI_SIMD_ARITH_SADALP;
		else
			operation = u ? ORLIX_TCTI_SIMD_ARITH_UADDLP :
				ORLIX_TCTI_SIMD_ARITH_SADDLP;
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
				decoded.decode_class);
		KUNIT_EXPECT_EQ(test, operation, decoded.simd_arithmetic_op);
		KUNIT_EXPECT_EQ(test, reg, decoded.rd);
		KUNIT_EXPECT_EQ(test, rn, decoded.rn);
		KUNIT_EXPECT_EQ(test, 1U << size, decoded.access_size);
		KUNIT_EXPECT_EQ(test, q ? 16U : 8U, decoded.result_size);
		KUNIT_EXPECT_FALSE(test, decoded.simd_scalar);
		KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	}
}

static void orlix_tcti_decode_exhaustive_simd_fp_three_same(struct kunit *test)
{
	static const struct {
		u32 pattern;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x2ea0d400U, ORLIX_TCTI_SIMD_ARITH_FABD },
		{ 0x2e20ec00U, ORLIX_TCTI_SIMD_ARITH_FACGE },
		{ 0x2ea0ec00U, ORLIX_TCTI_SIMD_ARITH_FACGT },
		{ 0x0e20e400U, ORLIX_TCTI_SIMD_ARITH_FCMEQ },
		{ 0x2e20e400U, ORLIX_TCTI_SIMD_ARITH_FCMGE },
		{ 0x2ea0e400U, ORLIX_TCTI_SIMD_ARITH_FCMGT },
		{ 0x0e20dc00U, ORLIX_TCTI_SIMD_ARITH_FMULX },
		{ 0x0e20fc00U, ORLIX_TCTI_SIMD_ARITH_FRECPS },
		{ 0x0ea0fc00U, ORLIX_TCTI_SIMD_ARITH_FRSQRTS },
		{ 0x2e20d400U, ORLIX_TCTI_SIMD_ARITH_FADDP },
		{ 0x0e20d400U, ORLIX_TCTI_SIMD_ARITH_FADD },
		{ 0x2e20fc00U, ORLIX_TCTI_SIMD_ARITH_FDIV },
		{ 0x2e20c400U, ORLIX_TCTI_SIMD_ARITH_FMAXNMP },
		{ 0x0e20c400U, ORLIX_TCTI_SIMD_ARITH_FMAXNM },
		{ 0x2e20f400U, ORLIX_TCTI_SIMD_ARITH_FMAXP },
		{ 0x0e20f400U, ORLIX_TCTI_SIMD_ARITH_FMAX },
		{ 0x2ea0c400U, ORLIX_TCTI_SIMD_ARITH_FMINNMP },
		{ 0x0ea0c400U, ORLIX_TCTI_SIMD_ARITH_FMINNM },
		{ 0x2ea0f400U, ORLIX_TCTI_SIMD_ARITH_FMINP },
		{ 0x0ea0f400U, ORLIX_TCTI_SIMD_ARITH_FMIN },
		{ 0x0e20cc00U, ORLIX_TCTI_SIMD_ARITH_FMLA },
		{ 0x0ea0cc00U, ORLIX_TCTI_SIMD_ARITH_FMLS },
		{ 0x2e20dc00U, ORLIX_TCTI_SIMD_ARITH_FMUL },
		{ 0x0ea0d400U, ORLIX_TCTI_SIMD_ARITH_FSUB },
	};
	u16 variant;

	for (variant = 0; variant < 16384; variant++) {
		u8 case_index = variant & 0x1fU;
		u8 reg = (variant >> 5) & 0x1fU;
		u8 precision = (variant >> 10) & 0x1U;
		u8 q = (variant >> 11) & 0x1U;
		u8 scalar = (variant >> 12) & 0x1U;
		u8 rn = (reg + 1) & 0x1fU;
		u8 rm = (reg + 2) & 0x1fU;
		u32 instruction;
		struct orlix_tcti_decoded_instruction decoded;
		bool valid;

		if (case_index >= ARRAY_SIZE(cases))
			continue;
		instruction = cases[case_index].pattern | ((u32)rm << 16) |
			((u32)rn << 5) | reg;
		if (precision)
			instruction |= BIT(22);
		if (scalar)
			instruction |= BIT(28);
		if (q)
			instruction |= BIT(30);
		decoded = orlix_tcti_decode_aarch64(instruction);
		if (case_index < 9)
			valid = q || (!scalar && !precision);
		else
			valid = !scalar && (q || !precision);
		if (case_index == 22 && precision && q)
			valid = false;
		if (!valid) {
			KUNIT_EXPECT_TRUE(test,
				decoded.decode_class !=
					ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC ||
				decoded.simd_arithmetic_op !=
					cases[case_index].operation);
			continue;
		}
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
				decoded.decode_class);
		KUNIT_EXPECT_EQ(test, cases[case_index].operation,
				decoded.simd_arithmetic_op);
		KUNIT_EXPECT_EQ(test, reg, decoded.rd);
		KUNIT_EXPECT_EQ(test, rn, decoded.rn);
		KUNIT_EXPECT_EQ(test, rm, decoded.rm);
		KUNIT_EXPECT_EQ(test, precision ? 8U : 4U,
				decoded.access_size);
		KUNIT_EXPECT_EQ(test,
				scalar ? decoded.access_size : q ? 16U : 8U,
				decoded.result_size);
		KUNIT_EXPECT_EQ(test, !!scalar, decoded.simd_scalar);
		KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
	}
}

static void orlix_tcti_decode_exhaustive_simd_fp_scalar_unary(struct kunit *test)
{
	static const struct {
		u32 pattern;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} estimate_cases[] = {
		{ 0x5ea1d800U, ORLIX_TCTI_SIMD_ARITH_FRECPE },
		{ 0x5ea1f800U, ORLIX_TCTI_SIMD_ARITH_FRECPX },
		{ 0x7ea1d800U, ORLIX_TCTI_SIMD_ARITH_FRSQRTE },
	};
	static const u32 disabled_fp16[] = {
		0x5ef9d800U,
		0x5ef9f800U,
		0x7ef9d800U,
	};
	unsigned int case_index;
	u8 size;
	u8 rd;
	u8 rn;

	for (case_index = 0; case_index < ARRAY_SIZE(estimate_cases);
	     case_index++) {
		for (size = 0; size < 2; size++) {
			for (rd = 0; rd < 32; rd++) {
				for (rn = 0; rn < 32; rn++) {
					u32 instruction =
						estimate_cases[case_index].pattern |
						((u32)size << 22) |
						((u32)rn << 5) | rd;
					struct orlix_tcti_decoded_instruction decoded =
						orlix_tcti_decode_aarch64(instruction);

					KUNIT_EXPECT_EQ(test,
						ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
						decoded.decode_class);
					KUNIT_EXPECT_EQ(test,
						estimate_cases[case_index].operation,
						decoded.simd_arithmetic_op);
					KUNIT_EXPECT_EQ(test, rd, decoded.rd);
					KUNIT_EXPECT_EQ(test, rn, decoded.rn);
					KUNIT_EXPECT_EQ(test, size ? 8U : 4U,
						decoded.access_size);
					KUNIT_EXPECT_EQ(test, decoded.access_size,
						decoded.result_size);
					KUNIT_EXPECT_TRUE(test, decoded.simd_scalar);
					KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
				}
			}
		}
	}

	for (rd = 0; rd < 32; rd++) {
		for (rn = 0; rn < 32; rn++) {
			u32 instruction = 0x7e616800U | ((u32)rn << 5) | rd;
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);

			KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
					decoded.decode_class);
			KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ARITH_FCVTXN,
					decoded.simd_arithmetic_op);
			KUNIT_EXPECT_EQ(test, rd, decoded.rd);
			KUNIT_EXPECT_EQ(test, rn, decoded.rn);
			KUNIT_EXPECT_EQ(test, 8U, decoded.access_size);
			KUNIT_EXPECT_EQ(test, 4U, decoded.result_size);
			KUNIT_EXPECT_TRUE(test, decoded.simd_scalar);
			KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
		}
	}

	for (case_index = 0; case_index < ARRAY_SIZE(disabled_fp16);
	     case_index++) {
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(disabled_fp16[case_index]);

		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
				decoded.decode_class);
	}
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x7e616000U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x7e616c00U).decode_class);
}

static void
orlix_tcti_decode_recognizes_complete_simd_scalar_shift_immediate_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		bool left_shift;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0f005400U, false, true, ORLIX_TCTI_SIMD_ARITH_SHL },
		{ 0x0f005400U, true, true, ORLIX_TCTI_SIMD_ARITH_SLI },
		{ 0x0f004400U, true, false, ORLIX_TCTI_SIMD_ARITH_SRI },
		{ 0x0f000400U, false, false, ORLIX_TCTI_SIMD_ARITH_SSHR },
		{ 0x0f000400U, true, false, ORLIX_TCTI_SIMD_ARITH_USHR },
		{ 0x0f001400U, false, false, ORLIX_TCTI_SIMD_ARITH_SSRA },
		{ 0x0f001400U, true, false, ORLIX_TCTI_SIMD_ARITH_USRA },
		{ 0x0f002400U, false, false, ORLIX_TCTI_SIMD_ARITH_SRSHR },
		{ 0x0f002400U, true, false, ORLIX_TCTI_SIMD_ARITH_URSHR },
		{ 0x0f003400U, false, false, ORLIX_TCTI_SIMD_ARITH_SRSRA },
		{ 0x0f003400U, true, false, ORLIX_TCTI_SIMD_ARITH_URSRA },
	};
	size_t index;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		u8 minimum = cases[index].left_shift ? 0 : 1;
		u8 maximum = cases[index].left_shift ? 63 : 64;
		u8 shift;

		for (shift = minimum; shift <= maximum; shift++) {
			u8 immediate = cases[index].left_shift ?
				64 + shift : 128 - shift;
			u32 instruction = cases[index].pattern |
				(cases[index].u ? BIT(29) : 0) |
				BIT(30) | BIT(28) | ((u32)immediate << 16) |
				(1U << 5);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);

			KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
					decoded.decode_class);
			KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
			KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
			KUNIT_EXPECT_EQ(test, 8U, decoded.access_size);
			KUNIT_EXPECT_EQ(test, 8U, decoded.result_size);
			KUNIT_EXPECT_EQ(test, shift, decoded.shift_amount);
			KUNIT_EXPECT_EQ(test, cases[index].operation,
					decoded.simd_arithmetic_op);
			KUNIT_EXPECT_TRUE(test, decoded.simd_scalar);
		}
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_3SOURCE,
		orlix_tcti_decode_aarch64(0x1f7f5420U).decode_class);
}

static void
orlix_tcti_decode_recognizes_complete_simd_shift_left_insert_immediate_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		bool right_insert;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0f005400U, false, false, ORLIX_TCTI_SIMD_ARITH_SHL },
		{ 0x0f005400U, true, false, ORLIX_TCTI_SIMD_ARITH_SLI },
		{ 0x0f004400U, true, true, ORLIX_TCTI_SIMD_ARITH_SRI },
	};
	size_t index;
	u8 q;
	u8 size;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 4; size++) {
				u8 lane_bits = 8U << size;
				u8 minimum = cases[index].right_insert ? 1 : 0;
				u8 maximum = cases[index].right_insert ?
					lane_bits : lane_bits - 1;
				u8 shift;

				for (shift = minimum; shift <= maximum; shift++) {
					u8 immediate = cases[index].right_insert ?
						2 * lane_bits - shift : lane_bits + shift;
					u32 instruction = cases[index].pattern |
						(cases[index].u ? BIT(29) : 0) |
						(q ? BIT(30) : 0) |
						((u32)immediate << 16) | (1U << 5);
					struct orlix_tcti_decoded_instruction decoded =
						orlix_tcti_decode_aarch64(instruction);

					if (!q && size == 3) {
						KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
								decoded.decode_class);
						continue;
					}

					KUNIT_EXPECT_EQ(test,
							ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
							decoded.decode_class);
					KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
					KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
					KUNIT_EXPECT_EQ(test, 1U << size,
							decoded.access_size);
					KUNIT_EXPECT_EQ(test, q ? 16U : 8U,
							decoded.result_size);
					KUNIT_EXPECT_EQ(test, shift, decoded.shift_amount);
					KUNIT_EXPECT_EQ(test, cases[index].operation,
							decoded.simd_arithmetic_op);
				}
			}
		}
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			 orlix_tcti_decode_aarch64(0x0f0f4420U).decode_class);
}

