static void
orlix_tcti_decode_recognizes_complete_simd_scalar_integer_unary_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		u8 minimum_size;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0e20b800U, false, 3, ORLIX_TCTI_SIMD_ARITH_ABS },
		{ 0x0e20b800U, true, 3, ORLIX_TCTI_SIMD_ARITH_NEG },
		{ 0x0e207800U, false, 0, ORLIX_TCTI_SIMD_ARITH_SQABS },
		{ 0x0e207800U, true, 0, ORLIX_TCTI_SIMD_ARITH_SQNEG },
	};
	u8 index;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		u8 size;

		for (size = cases[index].minimum_size; size < 4; size++) {
			u32 instruction = cases[index].pattern | BIT(28) | BIT(30) |
				(cases[index].u ? BIT(29) : 0) |
				((u32)size << 22) | (1U << 5);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);

			KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
					decoded.decode_class);
			KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
			KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
			KUNIT_EXPECT_EQ(test, 1U << size, decoded.access_size);
			KUNIT_EXPECT_EQ(test, 1U << size, decoded.result_size);
			KUNIT_EXPECT_EQ(test, cases[index].operation,
					decoded.simd_arithmetic_op);
			KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
			KUNIT_EXPECT_TRUE(test, decoded.simd_scalar);
		}
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			 orlix_tcti_decode_aarch64(0x1ee0b820U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			 orlix_tcti_decode_aarch64(0x5e20b820U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			 orlix_tcti_decode_aarch64(0x5ee04820U).decode_class);
}

static void
orlix_tcti_decode_recognizes_complete_simd_integer_unary_family(struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		u8 maximum_size;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0e20b800U, false, 3, ORLIX_TCTI_SIMD_ARITH_ABS },
		{ 0x0e20b800U, true, 3, ORLIX_TCTI_SIMD_ARITH_NEG },
		{ 0x0e207800U, false, 3, ORLIX_TCTI_SIMD_ARITH_SQABS },
		{ 0x0e207800U, true, 3, ORLIX_TCTI_SIMD_ARITH_SQNEG },
		{ 0x0e204800U, false, 2, ORLIX_TCTI_SIMD_ARITH_CLS },
		{ 0x0e204800U, true, 2, ORLIX_TCTI_SIMD_ARITH_CLZ },
		{ 0x0e200800U, false, 2, ORLIX_TCTI_SIMD_ARITH_REV64 },
		{ 0x0e200800U, true, 1, ORLIX_TCTI_SIMD_ARITH_REV32 },
	};
	struct {
		u32 instruction;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} byte_cases[] = {
		{ 0x0e201820U, ORLIX_TCTI_SIMD_ARITH_REV16 },
		{ 0x0e205820U, ORLIX_TCTI_SIMD_ARITH_CNT },
		{ 0x2e205820U, ORLIX_TCTI_SIMD_ARITH_NOT },
		{ 0x2e605820U, ORLIX_TCTI_SIMD_ARITH_RBIT },
	};
	size_t index;
	u8 q;
	u8 size;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 4; size++) {
				u32 instruction = cases[index].pattern |
					(cases[index].u ? BIT(29) : 0) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | (1U << 5);
				struct orlix_tcti_decoded_instruction decoded =
					orlix_tcti_decode_aarch64(instruction);
				bool legal = size <= cases[index].maximum_size &&
					(q || size != 3);

				if (!legal) {
					KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
							decoded.decode_class);
					continue;
				}

				KUNIT_EXPECT_EQ(test,
						ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
						decoded.decode_class);
				KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
				KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
				KUNIT_EXPECT_EQ(test, 1U << size,
						decoded.access_size);
				KUNIT_EXPECT_EQ(test, q ? 16U : 8U,
						decoded.result_size);
				KUNIT_EXPECT_EQ(test, cases[index].operation,
						decoded.simd_arithmetic_op);
				KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
			}
		}
	}

	for (index = 0; index < ARRAY_SIZE(byte_cases); index++) {
		for (q = 0; q < 2; q++) {
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(byte_cases[index].instruction |
						     (q ? BIT(30) : 0));

			KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
					decoded.decode_class);
			KUNIT_EXPECT_EQ(test, byte_cases[index].operation,
					decoded.simd_arithmetic_op);
			KUNIT_EXPECT_EQ(test, 1U, decoded.access_size);
			KUNIT_EXPECT_EQ(test, q ? 16U : 8U,
					decoded.result_size);
		}
	}

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x0e605820U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x2ea05820U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			orlix_tcti_decode_aarch64(0x2ea00820U).decode_class);
}

static void
orlix_tcti_decode_recognizes_complete_simd_scalar_compare_zero_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		enum orlix_tcti_simd_vector_compare_op operation;
	} cases[] = {
		{ 0x0e208800U, false, ORLIX_TCTI_SIMD_COMPARE_CMGT },
		{ 0x0e208800U, true, ORLIX_TCTI_SIMD_COMPARE_CMGE },
		{ 0x0e209800U, false, ORLIX_TCTI_SIMD_COMPARE_CMEQ },
		{ 0x0e209800U, true, ORLIX_TCTI_SIMD_COMPARE_CMLE },
		{ 0x0e20a800U, false, ORLIX_TCTI_SIMD_COMPARE_CMLT },
	};
	size_t index;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		u32 instruction = cases[index].pattern | BIT(28) | BIT(30) |
			(cases[index].u ? BIT(29) : 0) | (3U << 22) |
			(1U << 5);
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(instruction);

		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_COMPARE,
				decoded.decode_class);
		KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
		KUNIT_EXPECT_EQ(test, 1U, decoded.rn);
		KUNIT_EXPECT_EQ(test, 8U, decoded.access_size);
		KUNIT_EXPECT_EQ(test, 8U, decoded.result_size);
		KUNIT_EXPECT_EQ(test, cases[index].operation,
				decoded.simd_compare_op);
		KUNIT_EXPECT_TRUE(test, decoded.immediate);
		KUNIT_EXPECT_TRUE(test, decoded.simd_fp);
		KUNIT_EXPECT_TRUE(test, decoded.simd_scalar);
	}

	KUNIT_EXPECT_NE(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_COMPARE,
			 orlix_tcti_decode_aarch64(0x1ee08820U).decode_class);
	KUNIT_EXPECT_NE(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_COMPARE,
			 orlix_tcti_decode_aarch64(0x5ea08820U).decode_class);
	KUNIT_EXPECT_NE(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_COMPARE,
			 orlix_tcti_decode_aarch64(0x7ee0a820U).decode_class);
}

