static void orlix_tcti_decode_recognizes_complete_scvtf_gpr_family(
	struct kunit *test)
{
	static const struct {
		u32 instruction;
		u8 access_size;
		u8 result_size;
	} cases[] = {
		{ 0x1e220080U, sizeof(u32), sizeof(u32) },
		{ 0x9e220080U, sizeof(u64), sizeof(u32) },
		{ 0x1e620080U, sizeof(u32), sizeof(u64) },
		{ 0x9e620080U, sizeof(u64), sizeof(u64) },
	};
	struct orlix_tcti_decoded_instruction decoded;
	size_t index;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		decoded = orlix_tcti_decode_aarch64(cases[index].instruction);
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_FP_INT_CONVERT,
				decoded.decode_class);
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_FP_INT_SCVTF, decoded.fp_int_op);
		KUNIT_EXPECT_EQ(test, 0U, decoded.rd);
		KUNIT_EXPECT_EQ(test, 4U, decoded.rn);
		KUNIT_EXPECT_EQ(test, cases[index].access_size,
				decoded.access_size);
		KUNIT_EXPECT_EQ(test, cases[index].result_size,
				decoded.result_size);
	}
}

