static void orlix_tcti_decode_recognizes_complete_fp_scalar_1source_family(
	struct kunit *test)
{
	static const struct {
		u32 single_pattern;
		u32 double_pattern;
		enum orlix_tcti_fp_scalar_1source_op operation;
	} cases[] = {
		{ 0x1e20c000U, 0x1e60c000U, ORLIX_TCTI_FP1_FABS },
		{ 0x1e214000U, 0x1e614000U, ORLIX_TCTI_FP1_FNEG },
		{ 0x1e21c000U, 0x1e61c000U, ORLIX_TCTI_FP1_FSQRT },
		{ 0x1e244000U, 0x1e644000U, ORLIX_TCTI_FP1_FRINTN },
		{ 0x1e24c000U, 0x1e64c000U, ORLIX_TCTI_FP1_FRINTP },
		{ 0x1e254000U, 0x1e654000U, ORLIX_TCTI_FP1_FRINTM },
		{ 0x1e25c000U, 0x1e65c000U, ORLIX_TCTI_FP1_FRINTZ },
		{ 0x1e264000U, 0x1e664000U, ORLIX_TCTI_FP1_FRINTA },
		{ 0x1e274000U, 0x1e674000U, ORLIX_TCTI_FP1_FRINTX },
		{ 0x1e27c000U, 0x1e67c000U, ORLIX_TCTI_FP1_FRINTI },
	};
	unsigned int case_index;
	u8 reg;

	for (case_index = 0; case_index < ARRAY_SIZE(cases); case_index++) {
		for (reg = 0; reg < 32; reg++) {
			u8 rn = (reg * 13) & 0x1fU;
			u8 precision;

			for (precision = 0; precision < 2; precision++) {
				u32 instruction = cases[case_index].single_pattern |
					((u32)rn << 5) | reg;
				struct orlix_tcti_decoded_instruction decoded;

				if (precision)
					instruction = cases[case_index].double_pattern |
						((u32)rn << 5) | reg;
				decoded = orlix_tcti_decode_aarch64(instruction);

				KUNIT_EXPECT_EQ(test,
					ORLIX_TCTI_DECODE_FP_SCALAR_1SOURCE,
					decoded.decode_class);
				KUNIT_EXPECT_EQ(test, cases[case_index].operation,
					decoded.fp1_op);
				KUNIT_EXPECT_EQ(test, reg, decoded.rd);
				KUNIT_EXPECT_EQ(test, rn, decoded.rn);
				KUNIT_EXPECT_EQ(test, precision ? 8U : 4U,
					decoded.access_size);
				KUNIT_EXPECT_EQ(test, decoded.access_size,
					decoded.result_size);
			}
		}
	}
	for (reg = 0; reg < 32; reg++) {
		u8 rn = (reg * 7) & 0x1fU;
		struct orlix_tcti_decoded_instruction widen = orlix_tcti_decode_aarch64(
			0x1e22c000U | ((u32)rn << 5) | reg);
		struct orlix_tcti_decoded_instruction narrow = orlix_tcti_decode_aarch64(
			0x1e624000U | ((u32)rn << 5) | reg);

		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_1SOURCE,
			widen.decode_class);
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_FP1_FCVT, widen.fp1_op);
		KUNIT_EXPECT_EQ(test, 4U, widen.access_size);
		KUNIT_EXPECT_EQ(test, 8U, widen.result_size);
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_1SOURCE,
			narrow.decode_class);
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_FP1_FCVT, narrow.fp1_op);
		KUNIT_EXPECT_EQ(test, 8U, narrow.access_size);
		KUNIT_EXPECT_EQ(test, 4U, narrow.result_size);
	}
}

static void orlix_tcti_decode_recognizes_complete_fp_compare_family(
	struct kunit *test)
{
	static const u32 compare_cases[] = {
		0x1e212000U, 0x1e212010U, 0x1e202008U, 0x1e202018U,
		0x1e612000U, 0x1e612010U, 0x1e602008U, 0x1e602018U,
	};
	static const u32 conditional_cases[] = {
		0x1e220400U, 0x1e221410U, 0x1e620400U, 0x1e621410U,
	};
	struct orlix_tcti_decoded_instruction decoded;
	size_t index;

	for (index = 0; index < ARRAY_SIZE(compare_cases); index++) {
		decoded = orlix_tcti_decode_aarch64(compare_cases[index]);
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_COMPARE,
				decoded.decode_class);
		KUNIT_EXPECT_FALSE(test, decoded.fp_conditional);
		KUNIT_EXPECT_EQ(test, !!(compare_cases[index] & BIT(4)),
				decoded.fp_signal_all_nans);
	}

	for (index = 0; index < ARRAY_SIZE(conditional_cases); index++) {
		decoded = orlix_tcti_decode_aarch64(conditional_cases[index]);
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_COMPARE,
				decoded.decode_class);
		KUNIT_EXPECT_TRUE(test, decoded.fp_conditional);
		KUNIT_EXPECT_EQ(test, 2U, decoded.rm);
		KUNIT_EXPECT_EQ(test, !!(conditional_cases[index] & BIT(22)),
				decoded.access_size == sizeof(u64));
		KUNIT_EXPECT_EQ(test, !!(conditional_cases[index] & BIT(4)),
				decoded.fp_signal_all_nans);
	}
}

