static void orlix_tcti_resume_user_rejects_non_el0_system_accesses(struct kunit *test)
{
	/*
	 * The pinned AARCHMRS system-accessor reconciliation records the generic
	 * MRS, MSR, SYS, and SYSL forms. SCTLR_EL1 and AT S1E1R require EL1,
	 * while SYSL exercises the generic system-instruction encoding. OrlixTCTI must
	 * reject each unimplemented form in the guest before a host privileged
	 * operation could be attempted.
	 */
	static const struct {
		u32 instruction;
		const char *name;
	} cases[] = {
		{ 0xd5381007U, "mrs x7, sctlr_el1" },
		{ 0xd5181007U, "msr sctlr_el1, x7" },
		{ 0xd5087807U, "at s1e1r, x7" },
		{ 0xd5280007U, "sysl x7, #0, c0, c0, #0" },
	};
	unsigned long old_tls = current->thread.user_tls;
	size_t index;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		struct orlix_tcti_result result;
		struct pt_regs regs = { 0 };
		unsigned long mapped;
		int ret;
		enum orlix_tcti_decode_class decoded_class;

		decoded_class = orlix_tcti_decode_aarch64(cases[index].instruction).decode_class;
		KUNIT_EXPECT_TRUE_MSG(test,
			decoded_class == ORLIX_TCTI_DECODE_UNSUPPORTED ||
			decoded_class == ORLIX_TCTI_DECODE_SYSTEM_REGISTER,
			"%s class=%u", cases[index].name, decoded_class);
		mapped = orlix_tcti_test_map_instructions(test,
			&cases[index].instruction, 1);
		KUNIT_ASSERT_NE(test, 0UL, mapped);
		regs.pc = mapped;
		regs.sp = STACK_TOP - 16;
		regs.pstate = PSR_MODE_EL0t | PSR_N_BIT | PSR_C_BIT;
		regs.syscallno = NO_SYSCALL;
		regs.regs[7] = 0x123456789abcdef0ULL;

		result = orlix_tcti_resume_user(current, &regs, current->mm);

		KUNIT_EXPECT_EQ_MSG(test, ORLIX_TCTI_EXIT_UNSUPPORTED_INSTRUCTION,
			result.reason, "%s", cases[index].name);
		KUNIT_EXPECT_EQ_MSG(test, -EOPNOTSUPP, result.status,
			"%s", cases[index].name);
		KUNIT_EXPECT_EQ_MSG(test, mapped, result.pc, "%s",
			cases[index].name);
		KUNIT_EXPECT_EQ_MSG(test, cases[index].instruction,
			result.instruction, "%s", cases[index].name);
		KUNIT_EXPECT_EQ_MSG(test, mapped, regs.pc, "%s",
			cases[index].name);
		KUNIT_EXPECT_EQ_MSG(test, 0x123456789abcdef0ULL, regs.regs[7],
			"%s", cases[index].name);
		KUNIT_EXPECT_EQ_MSG(test, PSR_MODE_EL0t | PSR_N_BIT | PSR_C_BIT,
			regs.pstate, "%s", cases[index].name);
		KUNIT_EXPECT_EQ_MSG(test, old_tls, current->thread.user_tls,
			"%s", cases[index].name);

		ret = vm_munmap(mapped, PAGE_SIZE);
		KUNIT_EXPECT_EQ(test, 0, ret);
	}
}

static void orlix_tcti_resume_user_executes_branch_sequence(struct kunit *test)
{
	static const u32 instructions[] = {
		0xd2800000U, /* mov x0, #0 */
		0xb4000060U, /* cbz x0, .+12 */
		0xd2800020U, /* mov x0, #1 */
		0x14000002U, /* b .+8 */
		0xd2800540U, /* mov x0, #42 */
		0xd4000001U, /* svc #0 */
	};
	struct orlix_tcti_result result;
	struct pt_regs regs = { 0 };
	unsigned long mapped;
	int ret;

	mapped = orlix_tcti_test_map_instructions(test, instructions,
					    ARRAY_SIZE(instructions));
	KUNIT_ASSERT_NE(test, 0UL, mapped);
	regs.pc = mapped;
	regs.sp = STACK_TOP - 16;
	regs.pstate = PSR_MODE_EL0t;
	regs.syscallno = NO_SYSCALL;

	result = orlix_tcti_resume_user(current, &regs, current->mm);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_EXIT_SYSCALL, result.reason);
	KUNIT_EXPECT_EQ(test, 0L, result.status);
	KUNIT_EXPECT_EQ(test, mapped + 5 * sizeof(u32), result.pc);
	KUNIT_EXPECT_EQ(test, instructions[5], result.instruction);
	KUNIT_EXPECT_EQ(test, 42ULL, regs.regs[0]);
	KUNIT_EXPECT_EQ(test, mapped + 5 * sizeof(u32), regs.pc);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static u32 orlix_tcti_test_encode_branch_immediate(bool link, s32 immediate)
{
	return 0x14000000U | (link ? BIT(31) : 0) |
		((u32)immediate & (BIT(26) - 1));
}

static u32 orlix_tcti_test_encode_branch_conditional(u8 condition, s32 immediate)
{
	return 0x54000000U |
		(((u32)immediate & (BIT(19) - 1)) << 5) | condition;
}

static u32 orlix_tcti_test_encode_compare_branch(bool is_64bit, bool nonzero,
					    s32 immediate, u8 rt)
{
	return 0x34000000U | (is_64bit ? BIT(31) : 0) |
		(nonzero ? BIT(24) : 0) |
		(((u32)immediate & (BIT(19) - 1)) << 5) | rt;
}

static u32 orlix_tcti_test_encode_test_branch(bool nonzero, u8 test_bit,
					 s32 immediate, u8 rt)
{
	return 0x36000000U | ((u32)(test_bit & BIT(5)) << 26) |
		(nonzero ? BIT(24) : 0) |
		((u32)(test_bit & 0x1fU) << 19) |
		(((u32)immediate & (BIT(14) - 1)) << 5) | rt;
}

static u32 orlix_tcti_test_encode_branch_register(enum orlix_tcti_branch_register_op op,
					      u8 rn)
{
	u32 pattern;

	switch (op) {
	case ORLIX_TCTI_BRANCH_REGISTER_BR:
		pattern = 0xd61f0000U;
		break;
	case ORLIX_TCTI_BRANCH_REGISTER_BLR:
		pattern = 0xd63f0000U;
		break;
	case ORLIX_TCTI_BRANCH_REGISTER_RET:
		pattern = 0xd65f0000U;
		break;
	default:
		return 0;
	}

	return pattern | ((u32)rn << 5);
}

static u32 orlix_tcti_test_encode_move_register(u8 rd, u8 rn)
{
	/* ORR Xd, Xn, XZR, the architectural MOV register alias. */
	return 0xaa1f0000U | ((u32)rn << 5) | rd;
}

static u32 orlix_tcti_test_encode_system_register(bool write, u16 selector,
					   u8 rt)
{
	if (rt > 31U)
		return 0;
	return (write ? 0xd5100000U : 0xd5300000U) |
		((u32)selector << 5) | rt;
}

static u32 orlix_tcti_test_encode_adr(s32 immediate, u8 rd)
{
	u32 imm21 = (u32)immediate & (BIT(21) - 1);

	return 0x10000000U | ((imm21 & 0x3U) << 29) |
		((imm21 >> 2) << 5) | rd;
}

static void orlix_tcti_resume_user_executes_complete_baseline_control_flow(
	struct kunit *test)
{
	/*
	 * This executes the baseline control-flow families through the real engine,
	 * rather than only through the gadget unit path. Each conditional skips a
	 * poison move. BL enters a helper that makes an indirect BLR call, whose
	 * RET returns to a BR that restores the original direct-call continuation.
	 */
	u32 instructions[] = {
		0xd2800000U, /* mov x0, #0 */
		0,           /* cbz x0, .+8 */
		0xd29bd5a9U, /* mov x9, #0xdead */
		0xd2800021U, /* mov x1, #1 */
		0,           /* cbnz w1, .+8 */
		0xd29bd5a9U, /* mov x9, #0xdead */
		0xd2800002U, /* mov x2, #0 */
		0,           /* tbz x2, #63, .+8 */
		0xd29bd5a9U, /* mov x9, #0xdead */
		0xd2800023U, /* mov x3, #1 */
		0,           /* tbnz x3, #0, .+8 */
		0xd29bd5a9U, /* mov x9, #0xdead */
		0xeb00001fU, /* subs xzr, x0, x0 */
		0,           /* b.eq .+8 */
		0xd29bd5a9U, /* mov x9, #0xdead */
		0,           /* bl helper */
		0,           /* b svc */
		0xd29bd5a9U, /* mov x9, #0xdead */
		0xd4000001U, /* svc #0 */
		0xd503201fU, /* nop */
		0,           /* mov x6, x30 */
		0,           /* adr x5, indirect_helper */
		0,           /* blr x5 */
		0,           /* br x6 */
		0xd503201fU, /* nop */
		0xd2800544U, /* mov x4, #42 */
		0,           /* ret */
	};
	struct orlix_tcti_result result;
	struct pt_regs regs = { 0 };
	unsigned long mapped;
	int ret;

	instructions[1] = orlix_tcti_test_encode_compare_branch(true, false, 2, 0);
	instructions[4] = orlix_tcti_test_encode_compare_branch(false, true, 2, 1);
	instructions[7] = orlix_tcti_test_encode_test_branch(false, 63, 2, 2);
	instructions[10] = orlix_tcti_test_encode_test_branch(true, 0, 2, 3);
	instructions[13] = orlix_tcti_test_encode_branch_conditional(0, 2);
	instructions[15] = orlix_tcti_test_encode_branch_immediate(true, 5);
	instructions[16] = orlix_tcti_test_encode_branch_immediate(false, 2);
	instructions[20] = orlix_tcti_test_encode_move_register(6, 30);
	instructions[21] = orlix_tcti_test_encode_adr(16, 5);
	instructions[22] = orlix_tcti_test_encode_branch_register(
		ORLIX_TCTI_BRANCH_REGISTER_BLR, 5);
	instructions[23] = orlix_tcti_test_encode_branch_register(
		ORLIX_TCTI_BRANCH_REGISTER_BR, 6);
	instructions[26] = orlix_tcti_test_encode_branch_register(
		ORLIX_TCTI_BRANCH_REGISTER_RET, 30);

	mapped = orlix_tcti_test_map_instructions(test, instructions,
					    ARRAY_SIZE(instructions));
	KUNIT_ASSERT_NE(test, 0UL, mapped);
	regs.pc = mapped;
	regs.sp = STACK_TOP - 16;
	regs.pstate = PSR_MODE_EL0t;
	regs.syscallno = NO_SYSCALL;

	result = orlix_tcti_resume_user(current, &regs, current->mm);

	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_EXIT_SYSCALL, result.reason);
	KUNIT_EXPECT_EQ(test, 0L, result.status);
	KUNIT_EXPECT_EQ(test, mapped + 18 * sizeof(u32), result.pc);
	KUNIT_EXPECT_EQ(test, instructions[18], result.instruction);
	KUNIT_EXPECT_EQ(test, 42ULL, regs.regs[4]);
	KUNIT_EXPECT_EQ(test, 0ULL, regs.regs[9]);
	KUNIT_EXPECT_EQ(test, mapped + 16 * sizeof(u32), regs.regs[6]);
	KUNIT_EXPECT_EQ(test, mapped + 25 * sizeof(u32), regs.regs[5]);
	KUNIT_EXPECT_EQ(test, mapped + 23 * sizeof(u32), regs.regs[30]);
	KUNIT_EXPECT_NE(test, 0UL, regs.pstate & PSR_Z_BIT);
	KUNIT_EXPECT_EQ(test, mapped + 18 * sizeof(u32), regs.pc);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_resume_user_rejects_invalid_baseline_control_encodings(
	struct kunit *test)
{
	static const u32 invalid_instructions[] = {
		0x54000010U, /* BC.cond is HBC-conditioned, not B.cond. */
		0xd61f0001U, /* BR with a reserved low bit. */
		0xd69f03e0U, /* ERET is non-EL0. */
	};
	unsigned int index;

	for (index = 0; index < ARRAY_SIZE(invalid_instructions); index++) {
		struct orlix_tcti_result result;
		struct pt_regs regs = { 0 };
		unsigned long mapped;
		int ret;

		mapped = orlix_tcti_test_map_instructions(test,
			&invalid_instructions[index], 1);
		KUNIT_ASSERT_NE(test, 0UL, mapped);
		regs.pc = mapped;
		regs.sp = STACK_TOP - 16;
		regs.pstate = PSR_MODE_EL0t;
		regs.syscallno = NO_SYSCALL;
		regs.regs[0] = 0x1122334455667788ULL;

		result = orlix_tcti_resume_user(current, &regs, current->mm);

		KUNIT_EXPECT_EQ_MSG(test, ORLIX_TCTI_EXIT_UNSUPPORTED_INSTRUCTION,
			result.reason, "index=%u", index);
		KUNIT_EXPECT_EQ_MSG(test, -EOPNOTSUPP, result.status,
			"index=%u", index);
		KUNIT_EXPECT_EQ_MSG(test, mapped, result.pc, "index=%u", index);
		KUNIT_EXPECT_EQ_MSG(test, invalid_instructions[index],
			result.instruction, "index=%u", index);
		KUNIT_EXPECT_EQ_MSG(test, 0x1122334455667788ULL,
			regs.regs[0], "index=%u", index);
		KUNIT_EXPECT_EQ_MSG(test, mapped, regs.pc, "index=%u", index);

		ret = vm_munmap(mapped, PAGE_SIZE);
		KUNIT_EXPECT_EQ(test, 0, ret);
	}
}

