static void orlix_tcti_block_cache_returns_cached_program(struct kunit *test)
{
	struct orlix_tcti_gadget_word program[ORLIX_TCTI_SINGLE_INSTRUCTION_PROGRAM_WORDS];
	struct orlix_tcti_decoded_instruction decoded;
	struct mm_struct *mm = (struct mm_struct *)0x1000UL;
	struct orlix_tcti_block *block;
	struct pt_regs regs = {};
	unsigned long fault_address = 0;
	size_t word_count = 0;
	u64 generation;
	int ret;

	orlix_tcti_block_cache_reset_for_tests();
	decoded = orlix_tcti_decode_aarch64(0xd503201fU);
	ret = orlix_tcti_lower_decoded_instruction(&decoded, program,
					     ARRAY_SIZE(program),
					     &word_count);
	KUNIT_ASSERT_EQ(test, 0, ret);

	generation = orlix_tcti_code_generation(mm);
	ret = orlix_tcti_block_cache_insert(mm, 0x4000, 0x4004, generation, 1,
				      program, word_count, NULL);
	KUNIT_ASSERT_EQ(test, 0, ret);

	block = orlix_tcti_block_cache_lookup(mm, 0x4000, generation);
	KUNIT_ASSERT_NOT_NULL(test, block);
	KUNIT_EXPECT_EQ(test, 1U, block->instruction_count);
	KUNIT_EXPECT_EQ(test, (u32)word_count, block->program_words);

	regs.pc = 0x4000;
	ret = orlix_tcti_execute_gadget_program(NULL, &regs, block->program,
					  block->program_words, &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x4004ULL, regs.pc);
	orlix_tcti_block_put(block);

	orlix_tcti_block_cache_reset_for_tests();
}

static void orlix_tcti_gadget_program_executes_multiple_decoded_instructions(struct kunit *test)
{
	struct orlix_tcti_gadget_word program[ORLIX_TCTI_PROGRAM_WORDS_FOR_INSTRUCTIONS(2)];
	struct orlix_tcti_decoded_instruction decoded;
	unsigned long fault_address = 0;
	struct pt_regs regs = {};
	size_t word_count = 0;
	int ret;

	decoded = orlix_tcti_decode_aarch64(0xd503201fU);
	ret = orlix_tcti_append_decoded_instruction(&decoded, program,
					      ARRAY_SIZE(program),
					      &word_count);
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_append_decoded_instruction(&decoded, program,
					      ARRAY_SIZE(program),
					      &word_count);
	KUNIT_ASSERT_EQ(test, 0, ret);

	regs.pc = 0x8000;
	ret = orlix_tcti_execute_gadget_program(current->mm, &regs, program,
					  word_count, &fault_address);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x8008ULL, regs.pc);
}

