	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x7136d75e80ULL, regs.sp);
	KUNIT_EXPECT_EQ(test, 0x71274454acULL, regs.pc);
