static u32 orlix_tcti_test_encode_logical_shifted_register(bool is_64bit, u8 opc,
						       bool invert, u8 shift,
						       u8 rm, u8 amount,
						       u8 rn, u8 rd)
{
	return 0x0a000000U | (is_64bit ? BIT(31) : 0) |
		((u32)opc << 29) | ((u32)shift << 22) |
		(invert ? BIT(21) : 0) | ((u32)rm << 16) |
		((u32)amount << 10) | ((u32)rn << 5) | rd;
}

static void orlix_tcti_gadget_executes_complete_logical_shifted_register_family(
	struct kunit *test)
{
	const unsigned long nzcv_mask = PSR_N_BIT | PSR_Z_BIT |
		PSR_C_BIT | PSR_V_BIT;
	bool seen_rn[32] = {};
	bool seen_rm[32] = {};
	bool seen_rd[32] = {};
	unsigned int is_64bit;
	unsigned int opc;
	unsigned int invert;
	unsigned int shift;
	unsigned int amount;

	for (is_64bit = 0; is_64bit < 2; is_64bit++) {
		u8 width = is_64bit ? 64 : 32;
		u64 width_mask = is_64bit ? U64_MAX : U32_MAX;
		u64 sign_bit = is_64bit ? BIT_ULL(63) : BIT_ULL(31);

		for (opc = 0; opc < 4; opc++) {
			for (invert = 0; invert < 2; invert++) {
				for (shift = 0; shift < 4; shift++) {
					for (amount = 0; amount < 64; amount++) {
						struct orlix_tcti_decoded_instruction decoded;
						struct pt_regs regs = {};
						struct pt_regs before;
						bool valid = amount < width;
						u8 rn = (amount + opc) & 0x1fU;
						u8 rm = (31 - amount + shift) & 0x1fU;
						u8 rd = (amount + 3 * opc + invert) & 0x1fU;
						u64 left;
						u64 right;
						u64 shifted;
						u64 expected;
						u64 expected_registers[31];
						unsigned long expected_pstate;
						u32 instruction;
						unsigned int reg;
						int ret;

						instruction =
							orlix_tcti_test_encode_logical_shifted_register(
								is_64bit, opc, invert, shift,
								rm, amount, rn, rd);
						decoded = orlix_tcti_decode_aarch64(instruction);
						if (!valid) {
							KUNIT_EXPECT_EQ_MSG(
								test, ORLIX_TCTI_DECODE_UNSUPPORTED,
								decoded.decode_class,
								"accepted invalid sf=%u opc=%u N=%u shift=%u amount=%u instruction=%08x",
								is_64bit, opc, invert, shift,
								amount, instruction);
							continue;
						}

						KUNIT_ASSERT_EQ_MSG(
							test, ORLIX_TCTI_DECODE_LOGICAL_SHIFTED_REGISTER,
							decoded.decode_class,
							"rejected sf=%u opc=%u N=%u shift=%u amount=%u instruction=%08x",
							is_64bit, opc, invert, shift,
							amount, instruction);
						KUNIT_EXPECT_EQ(test, !!is_64bit,
							decoded.is_64bit);
						KUNIT_EXPECT_EQ(test, !!invert,
							decoded.invert_second_operand);
						KUNIT_EXPECT_EQ(test, opc == 3, decoded.set_flags);
						KUNIT_EXPECT_EQ(test,
							opc == 0 || opc == 3 ? ORLIX_TCTI_LOGICAL_AND :
							opc == 1 ? ORLIX_TCTI_LOGICAL_ORR : ORLIX_TCTI_LOGICAL_EOR,
							decoded.logical_op);
						KUNIT_EXPECT_EQ(test, shift, decoded.shift);
						KUNIT_EXPECT_EQ(test, amount,
							decoded.shift_amount);
						KUNIT_EXPECT_EQ(test, rn, decoded.rn);
						KUNIT_EXPECT_EQ(test, rm, decoded.rm);
						KUNIT_EXPECT_EQ(test, rd, decoded.rd);
						seen_rn[rn] = true;
						seen_rm[rm] = true;
						seen_rd[rd] = true;

						for (reg = 0; reg < 31; reg++)
							regs.regs[reg] =
								0xfedcba9876543210ULL ^
								((u64)instruction << (reg & 7)) ^ reg;
						regs.sp = 0x706a865abcULL;
						regs.pc = 0x2468ace000ULL;
						regs.pstate = nzcv_mask | 0x155UL;
						before = regs;
						memcpy(expected_registers, before.regs,
						       sizeof(expected_registers));
						left = rn == 31 ? 0 : before.regs[rn];
						right = rm == 31 ? 0 : before.regs[rm];
						left &= width_mask;
						right &= width_mask;
						switch (shift) {
						case 0:
							shifted = right << amount;
							break;
						case 1:
							shifted = right >> amount;
							break;
						case 2:
							shifted = right >> amount;
							if (amount && (right & sign_bit))
								shifted |= width_mask <<
									(width - amount);
							break;
						case 3:
							shifted = amount ?
								(right >> amount) |
								(right << (width - amount)) : right;
							break;
						default:
							KUNIT_FAIL(test, "invalid logical shift operation");
							return;
						}
						shifted &= width_mask;
						if (invert)
							shifted = ~shifted & width_mask;
						switch (opc) {
						case 0:
						case 3:
							expected = left & shifted;
							break;
						case 1:
							expected = left | shifted;
							break;
						case 2:
							expected = left ^ shifted;
							break;
						default:
							KUNIT_FAIL(test, "invalid logical operation");
							return;
						}
						expected &= width_mask;
						if (rd < 31)
							expected_registers[rd] = expected;
						expected_pstate = before.pstate;
						if (opc == 3) {
							unsigned long flags = 0;

							if (expected & sign_bit)
								flags |= PSR_N_BIT;
							if (!expected)
								flags |= PSR_Z_BIT;
							expected_pstate =
								(before.pstate & ~nzcv_mask) | flags;
						}

						ret = orlix_tcti_switch_debug_execute_decoded(
							NULL, &regs, &decoded, NULL);
						KUNIT_ASSERT_EQ(test, 0, ret);
						KUNIT_EXPECT_MEMEQ(test, expected_registers,
							regs.regs, sizeof(expected_registers));
						KUNIT_EXPECT_EQ(test, before.sp, regs.sp);
						KUNIT_EXPECT_EQ(test, expected_pstate, regs.pstate);
						KUNIT_EXPECT_EQ(test,
							before.pc + sizeof(u32), regs.pc);
					}
				}
			}
		}
	}

	for (amount = 0; amount < 32; amount++) {
		KUNIT_EXPECT_TRUE(test, seen_rn[amount]);
		KUNIT_EXPECT_TRUE(test, seen_rm[amount]);
		KUNIT_EXPECT_TRUE(test, seen_rd[amount]);
	}
}

static void orlix_tcti_switch_executes_logical_shifted_register(struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	int ret;

	regs.regs[1] = 0x123456789abcdef0ULL;
	regs.regs[8] = 0xffffffffffffffffULL;
	regs.pc = 0x233c8;

	decoded = orlix_tcti_decode_aarch64(0xaa0103f3U);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x123456789abcdef0ULL, regs.regs[19]);
	KUNIT_EXPECT_EQ(test, 0x233ccULL, regs.pc);

	decoded = orlix_tcti_decode_aarch64(0x2a0803e0U);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0xffffffffULL, regs.regs[0]);
	KUNIT_EXPECT_EQ(test, 0x233d0ULL, regs.pc);

	regs.regs[10] = 0xf0;
	regs.regs[11] = 0xf;
	regs.pstate = PSR_C_BIT | PSR_V_BIT;
	regs.pc = 0x22994;
	decoded = orlix_tcti_decode_aarch64(0xea0b015fU);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0xf0ULL, regs.regs[10]);
	KUNIT_EXPECT_NE(test, 0ULL, regs.pstate & PSR_Z_BIT);
	KUNIT_EXPECT_EQ(test, 0ULL, regs.pstate & PSR_C_BIT);
	KUNIT_EXPECT_EQ(test, 0x22998ULL, regs.pc);

	regs.regs[11] = 0x0000000fULL;
	regs.pc = 0x31060;
	decoded = orlix_tcti_decode_aarch64(0x2a2b03e9U);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0xfffffff0ULL, regs.regs[9]);
	KUNIT_EXPECT_EQ(test, 0x31064ULL, regs.pc);
}

static u64 orlix_tcti_test_ror_element(u64 value, u8 rotate, u8 width)
{
	u64 mask = width == 64 ? U64_MAX : BIT_ULL(width) - 1;

	rotate %= width;
	value &= mask;
	if (!rotate)
		return value;
	return ((value >> rotate) | (value << (width - rotate))) & mask;
}

static bool orlix_tcti_test_decode_logical_immediate(bool is_64bit, bool n,
						u8 immr, u8 imms, u64 *result)
{
	u8 concatenated = (n ? BIT(6) : 0) | ((~imms) & 0x3fU);
	u8 register_width = is_64bit ? 64 : 32;
	int length = -1;
	u8 bit;
	u8 levels;
	u8 element_width;
	u8 ones;
	u64 element;
	u64 expanded = 0;
	u8 offset;

	for (bit = 0; bit <= 6; bit++) {
		if (concatenated & BIT(bit))
			length = bit;
	}
	if (length < 1 || (!is_64bit && length == 6))
		return false;

	levels = BIT(length) - 1;
	if ((imms & levels) == levels)
		return false;
	element_width = BIT(length);
	ones = (imms & levels) + 1;
	element = BIT_ULL(ones) - 1;
	element = orlix_tcti_test_ror_element(element, immr & levels,
						element_width);
	for (offset = 0; offset < register_width; offset += element_width)
		expanded |= element << offset;
	*result = expanded;
	return true;
}

static u32 orlix_tcti_test_encode_logical_immediate(bool is_64bit, u8 opc, bool n,
					       u8 immr, u8 imms, u8 rn, u8 rd)
{
	return 0x12000000U | (is_64bit ? BIT(31) : 0) |
		((u32)opc << 29) | (n ? BIT(22) : 0) |
		((u32)immr << 16) | ((u32)imms << 10) |
		((u32)rn << 5) | rd;
}

static void orlix_tcti_gadget_executes_complete_logical_immediate_family(
	struct kunit *test)
{
	const unsigned long nzcv_mask = PSR_N_BIT | PSR_Z_BIT |
		PSR_C_BIT | PSR_V_BIT;
	bool seen_rn[32] = {};
	bool seen_rd[32] = {};
	bool seen_op[4] = {};
	unsigned int valid_encodings = 0;
	unsigned int invalid_encodings = 0;
	unsigned int is_64bit;
	unsigned int n;
	unsigned int immr;
	unsigned int imms;
	unsigned int opc;

	for (is_64bit = 0; is_64bit < 2; is_64bit++) {
		for (n = 0; n < 2; n++) {
			for (immr = 0; immr < 64; immr++) {
				for (imms = 0; imms < 64; imms++) {
					u64 logical_immediate = 0;
					bool valid = orlix_tcti_test_decode_logical_immediate(
						is_64bit, n, immr, imms,
						&logical_immediate);

					for (opc = 0; opc < 4; opc++) {
						struct orlix_tcti_decoded_instruction decoded;
						struct pt_regs regs = {};
						struct pt_regs before;
						u8 rn = (immr + opc) & 0x1fU;
						u8 rd = (imms + 3 * opc) & 0x1fU;
						u8 access_size = is_64bit ? sizeof(u64) : sizeof(u32);
						u64 width_mask = is_64bit ? U64_MAX : U32_MAX;
						u64 sign_bit = is_64bit ? BIT_ULL(63) : BIT_ULL(31);
						u64 left;
						u64 expected;
						u64 expected_registers[31];
						unsigned long expected_pstate;
						u32 instruction;
						unsigned int reg;
						int ret;

						instruction = orlix_tcti_test_encode_logical_immediate(
							is_64bit, opc, n, immr, imms, rn, rd);
						decoded = orlix_tcti_decode_aarch64(instruction);
						if (!valid) {
							KUNIT_EXPECT_EQ_MSG(
								test, ORLIX_TCTI_DECODE_UNSUPPORTED,
								decoded.decode_class,
								"accepted invalid sf=%u N=%u immr=%u imms=%u opc=%u instruction=%08x",
								is_64bit, n, immr, imms, opc,
								instruction);
							invalid_encodings++;
							continue;
						}

						valid_encodings++;
						seen_rn[rn] = true;
						seen_rd[rd] = true;
						seen_op[opc] = true;
						KUNIT_ASSERT_EQ_MSG(
							test, ORLIX_TCTI_DECODE_LOGICAL_IMMEDIATE,
							decoded.decode_class,
							"rejected sf=%u N=%u immr=%u imms=%u opc=%u instruction=%08x",
							is_64bit, n, immr, imms, opc,
							instruction);
						KUNIT_EXPECT_EQ(test, !!is_64bit,
							decoded.is_64bit);
						KUNIT_EXPECT_EQ(test, opc == 3, decoded.set_flags);
						KUNIT_EXPECT_EQ(test,
							opc == 0 || opc == 3 ? ORLIX_TCTI_LOGICAL_AND :
							opc == 1 ? ORLIX_TCTI_LOGICAL_ORR : ORLIX_TCTI_LOGICAL_EOR,
							decoded.logical_op);
						KUNIT_EXPECT_EQ(test, logical_immediate,
							decoded.logical_immediate);
						KUNIT_EXPECT_EQ(test, rn, decoded.rn);
						KUNIT_EXPECT_EQ(test, rd, decoded.rd);

						for (reg = 0; reg < 31; reg++)
							regs.regs[reg] =
								0xfedcba9876543210ULL ^
								((u64)instruction << (reg & 7)) ^ reg;
						regs.sp = 0x706a865abcULL;
						regs.pc = 0x2468ace000ULL;
						regs.pstate = nzcv_mask | 0x155UL;
						before = regs;
						memcpy(expected_registers, before.regs,
						       sizeof(expected_registers));
						left = rn == 31 ? 0 : before.regs[rn];
						if (access_size == sizeof(u32))
							left = (u32)left;
						switch (opc) {
						case 0:
						case 3:
							expected = left & logical_immediate;
							break;
						case 1:
							expected = left | logical_immediate;
							break;
						case 2:
							expected = left ^ logical_immediate;
							break;
						default:
							KUNIT_FAIL(test, "invalid logical test operation");
							return;
						}
						expected &= width_mask;
						if (rd < 31)
							expected_registers[rd] = expected;
						expected_pstate = before.pstate;
						if (opc == 3) {
							unsigned long flags = 0;

							if (expected & sign_bit)
								flags |= PSR_N_BIT;
							if (!expected)
								flags |= PSR_Z_BIT;
							expected_pstate =
								(before.pstate & ~nzcv_mask) | flags;
						}

						ret = orlix_tcti_switch_debug_execute_decoded(
							NULL, &regs, &decoded, NULL);
						KUNIT_ASSERT_EQ(test, 0, ret);
						KUNIT_EXPECT_MEMEQ(test, expected_registers,
							regs.regs, sizeof(expected_registers));
						KUNIT_EXPECT_EQ(test, before.sp, regs.sp);
						KUNIT_EXPECT_EQ(test, expected_pstate, regs.pstate);
						KUNIT_EXPECT_EQ(test, before.pc + sizeof(u32), regs.pc);
					}
				}
			}
		}
	}

	KUNIT_EXPECT_GT(test, valid_encodings, 0U);
	KUNIT_EXPECT_GT(test, invalid_encodings, 0U);
	for (opc = 0; opc < 4; opc++)
		KUNIT_EXPECT_TRUE(test, seen_op[opc]);
	for (opc = 0; opc < 32; opc++) {
		KUNIT_EXPECT_TRUE(test, seen_rn[opc]);
		KUNIT_EXPECT_TRUE(test, seen_rd[opc]);
	}
}

static void orlix_tcti_switch_executes_logical_immediate(struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	int ret;

	regs.regs[0] = 0xffffffffU;
	regs.regs[8] = 0x40U;
	regs.pc = 0x1ae14;

	decoded = orlix_tcti_decode_aarch64(0x12007808U);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x7fffffffULL, regs.regs[8]);
	KUNIT_EXPECT_EQ(test, 0x1ae18ULL, regs.pc);

	decoded = orlix_tcti_decode_aarch64(0x32190108U);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x7fffffffULL, regs.regs[8]);
	KUNIT_EXPECT_EQ(test, 0x1ae1cULL, regs.pc);

	regs.regs[8] = 0x40U;
	regs.pstate = PSR_C_BIT | PSR_V_BIT;
	decoded = orlix_tcti_decode_aarch64(0x7200191fU);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x40ULL, regs.regs[8]);
	KUNIT_EXPECT_EQ(test, 0ULL, regs.pstate & PSR_Z_BIT);
	KUNIT_EXPECT_EQ(test, 0ULL, regs.pstate & PSR_C_BIT);
	KUNIT_EXPECT_EQ(test, 0x1ae20ULL, regs.pc);
}

static u64 orlix_tcti_test_replicate_element(u64 element, u8 element_width,
				       u8 data_size)
{
	u64 result = 0;
	u8 offset;

	for (offset = 0; offset < data_size; offset += element_width)
		result |= element << offset;
	return result;
}

static void orlix_tcti_test_decode_bitfield_masks(bool is_64bit, u8 immr, u8 imms,
					     u64 *wmask, u64 *tmask)
{
	u8 data_size = is_64bit ? 64 : 32;
	u8 length = is_64bit ? 6 : 5;
	u8 levels = BIT(length) - 1;
	u8 element_width = BIT(length);
	u8 s = imms & levels;
	u8 r = immr & levels;
	u8 diff = (s - r) & levels;
	u64 welem = s == 63 ? U64_MAX : BIT_ULL(s + 1) - 1;
	u64 telem = diff == 63 ? U64_MAX : BIT_ULL(diff + 1) - 1;

	welem = orlix_tcti_test_ror_element(welem, r, element_width);
	*wmask = orlix_tcti_test_replicate_element(welem, element_width, data_size);
	*tmask = orlix_tcti_test_replicate_element(telem, element_width, data_size);
}

static u32 orlix_tcti_test_encode_bitfield(bool is_64bit, u8 opc, bool n,
				     u8 immr, u8 imms, u8 rn, u8 rd)
{
	return 0x13000000U | (is_64bit ? BIT(31) : 0) |
		((u32)opc << 29) | (n ? BIT(22) : 0) |
		((u32)immr << 16) | ((u32)imms << 10) |
		((u32)rn << 5) | rd;
}

static void orlix_tcti_gadget_executes_complete_bitfield_family(struct kunit *test)
{
	static const enum orlix_tcti_bitfield_op expected_ops[] = {
		ORLIX_TCTI_BITFIELD_SBFM,
		ORLIX_TCTI_BITFIELD_BFM,
		ORLIX_TCTI_BITFIELD_UBFM,
	};
	bool seen_rn[32] = {};
	bool seen_rd[32] = {};
	unsigned int is_64bit;
	unsigned int opc;
	unsigned int immr;
	unsigned int imms;

	for (is_64bit = 0; is_64bit < 2; is_64bit++) {
		u8 data_size = is_64bit ? 64 : 32;
		u64 width_mask = is_64bit ? U64_MAX : U32_MAX;

		for (opc = 0; opc < ARRAY_SIZE(expected_ops); opc++) {
			for (immr = 0; immr < data_size; immr++) {
				for (imms = 0; imms < data_size; imms++) {
					struct orlix_tcti_decoded_instruction decoded;
					struct pt_regs regs = {};
					struct pt_regs before;
					u8 rn = (immr + opc) & 0x1fU;
					u8 rd = (imms + 3 * opc) & 0x1fU;
					u64 wmask;
					u64 tmask;
					u64 source;
					u64 destination;
					u64 rotated;
					u64 bottom;
					u64 expected;
					u64 expected_registers[31];
					u32 instruction;
					unsigned int reg;
					int ret;

					instruction = orlix_tcti_test_encode_bitfield(
						is_64bit, opc, is_64bit, immr, imms,
						rn, rd);
					decoded = orlix_tcti_decode_aarch64(instruction);
					KUNIT_ASSERT_EQ_MSG(
						test, ORLIX_TCTI_DECODE_BITFIELD,
						decoded.decode_class,
						"rejected sf=%u opc=%u immr=%u imms=%u rn=%u rd=%u instruction=%08x",
						is_64bit, opc, immr, imms, rn, rd,
						instruction);
					KUNIT_EXPECT_EQ(test, !!is_64bit,
						decoded.is_64bit);
					KUNIT_EXPECT_EQ(test, expected_ops[opc],
						decoded.bitfield_op);
					KUNIT_EXPECT_EQ(test, immr,
						decoded.bitfield_immr);
					KUNIT_EXPECT_EQ(test, imms,
						decoded.bitfield_imms);
					KUNIT_EXPECT_EQ(test, rn, decoded.rn);
					KUNIT_EXPECT_EQ(test, rd, decoded.rd);
					seen_rn[rn] = true;
					seen_rd[rd] = true;

					for (reg = 0; reg < 31; reg++)
						regs.regs[reg] =
							0xfedcba9876543210ULL ^
							((u64)instruction << (reg & 7)) ^ reg;
					regs.sp = 0x706a865abcULL;
					regs.pc = 0x2468ace000ULL;
					regs.pstate = PSR_N_BIT | PSR_C_BIT | 0x155UL;
					before = regs;
					memcpy(expected_registers, before.regs,
					       sizeof(expected_registers));
					source = rn == 31 ? 0 : before.regs[rn];
					destination = rd == 31 ? 0 : before.regs[rd];
					source &= width_mask;
					destination &= width_mask;
					orlix_tcti_test_decode_bitfield_masks(
						is_64bit, immr, imms, &wmask, &tmask);
					rotated = orlix_tcti_test_ror_element(
						source, immr, data_size);
					bottom = rotated & wmask;
					switch (expected_ops[opc]) {
					case ORLIX_TCTI_BITFIELD_SBFM: {
						u64 top = source & BIT_ULL(imms) ?
							width_mask : 0;

						expected = (top & ~tmask) |
							(bottom & tmask);
						break;
					}
					case ORLIX_TCTI_BITFIELD_BFM:
						bottom = (destination & ~wmask) | bottom;
						expected = (destination & ~tmask) |
							(bottom & tmask);
						break;
					case ORLIX_TCTI_BITFIELD_UBFM:
						expected = bottom & tmask;
						break;
					default:
						KUNIT_FAIL(test, "invalid bitfield test operation");
						return;
					}
					expected &= width_mask;
					if (rd < 31)
						expected_registers[rd] = expected;

					ret = orlix_tcti_switch_debug_execute_decoded(
						NULL, &regs, &decoded, NULL);
					KUNIT_ASSERT_EQ(test, 0, ret);
					KUNIT_EXPECT_MEMEQ(test, expected_registers,
						regs.regs, sizeof(expected_registers));
					KUNIT_EXPECT_EQ(test, before.sp, regs.sp);
					KUNIT_EXPECT_EQ(test, before.pstate, regs.pstate);
					KUNIT_EXPECT_EQ(test, before.pc + sizeof(u32), regs.pc);
				}
			}
		}
	}

	for (opc = 0; opc < 32; opc++) {
		KUNIT_EXPECT_TRUE(test, seen_rn[opc]);
		KUNIT_EXPECT_TRUE(test, seen_rd[opc]);
	}
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x73000000U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x13400000U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x93000000U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x13200000U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x13008000U).decode_class);
}

static void orlix_tcti_switch_executes_bitfield(struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	int ret;

	regs.regs[22] = 0x12345678ULL;
	regs.regs[24] = 0x123456789abcdef0ULL;
	regs.regs[8] = 1;
	regs.regs[1] = 0xffff0000ULL;
	regs.regs[2] = 0xabcdULL;
	regs.pc = 0x6000;

	decoded = orlix_tcti_decode_aarch64(0x53083ed7U);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x56ULL, regs.regs[23]);
	KUNIT_EXPECT_EQ(test, 0x6004ULL, regs.pc);

	decoded = orlix_tcti_decode_aarch64(0xd350ff09U);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x123456789abcULL, regs.regs[9]);
	KUNIT_EXPECT_EQ(test, 0x6008ULL, regs.pc);

	decoded = orlix_tcti_decode_aarch64(0x13000100U);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0xffffffffULL, regs.regs[0]);
	KUNIT_EXPECT_EQ(test, 0x600cULL, regs.pc);

	decoded = orlix_tcti_decode_aarch64(0x33181c41U);
	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0xffffcd00ULL, regs.regs[1]);
	KUNIT_EXPECT_EQ(test, 0x6010ULL, regs.pc);
}

static u32 orlix_tcti_test_encode_extract(bool is_64bit, bool n, u8 rm,
				    u8 shift, u8 rn, u8 rd)
{
	return 0x13800000U | (is_64bit ? BIT(31) : 0) |
		(n ? BIT(22) : 0) | ((u32)rm << 16) |
		((u32)shift << 10) | ((u32)rn << 5) | rd;
}

static void orlix_tcti_gadget_executes_complete_extract_family(struct kunit *test)
{
	bool seen_rn[32] = {};
	bool seen_rm[32] = {};
	bool seen_rd[32] = {};
	unsigned int is_64bit;
	unsigned int n;
	unsigned int shift;
	unsigned int register_case;

	for (is_64bit = 0; is_64bit < 2; is_64bit++) {
		for (n = 0; n < 2; n++) {
			for (shift = 0; shift < 64; shift++) {
				for (register_case = 0; register_case < 32;
				     register_case++) {
					struct orlix_tcti_decoded_instruction decoded;
					struct pt_regs regs = {};
					struct pt_regs before;
					bool valid = is_64bit == n &&
						(is_64bit || shift < 32);
					u8 rn = register_case;
					u8 rm = (31 - register_case + shift) & 0x1fU;
					u8 rd = (register_case + 3 * shift) & 0x1fU;
					u8 width = is_64bit ? 64 : 32;
					u64 width_mask = is_64bit ? U64_MAX : U32_MAX;
					u64 high;
					u64 low;
					u64 expected;
					u64 expected_registers[31];
					u32 instruction;
					unsigned int reg;
					int ret;

					instruction = orlix_tcti_test_encode_extract(
						is_64bit, n, rm, shift, rn, rd);
					decoded = orlix_tcti_decode_aarch64(instruction);
					if (!valid) {
						KUNIT_EXPECT_EQ_MSG(
							test, ORLIX_TCTI_DECODE_UNSUPPORTED,
							decoded.decode_class,
							"accepted invalid sf=%u N=%u shift=%u rn=%u rm=%u rd=%u instruction=%08x",
							is_64bit, n, shift, rn, rm, rd,
							instruction);
						continue;
					}

					seen_rn[rn] = true;
					seen_rm[rm] = true;
					seen_rd[rd] = true;
					KUNIT_ASSERT_EQ_MSG(
						test, ORLIX_TCTI_DECODE_EXTRACT,
						decoded.decode_class,
						"rejected sf=%u N=%u shift=%u rn=%u rm=%u rd=%u instruction=%08x",
						is_64bit, n, shift, rn, rm, rd,
						instruction);
					KUNIT_EXPECT_EQ(test, !!is_64bit,
						decoded.is_64bit);
					KUNIT_EXPECT_EQ(test, shift, decoded.shift_amount);
					KUNIT_EXPECT_EQ(test, rn, decoded.rn);
					KUNIT_EXPECT_EQ(test, rm, decoded.rm);
					KUNIT_EXPECT_EQ(test, rd, decoded.rd);

					for (reg = 0; reg < 31; reg++)
						regs.regs[reg] =
							0xfedcba9876543210ULL ^
							((u64)instruction << (reg & 7)) ^ reg;
					regs.sp = 0x706a865abcULL;
					regs.pc = 0x2468ace000ULL;
					regs.pstate = PSR_N_BIT | PSR_C_BIT | 0x155UL;
					before = regs;
					memcpy(expected_registers, before.regs,
					       sizeof(expected_registers));
					high = rn == 31 ? 0 : before.regs[rn];
					low = rm == 31 ? 0 : before.regs[rm];
					high &= width_mask;
					low &= width_mask;
					expected = shift ?
						(low >> shift) | (high << (width - shift)) :
						low;
					expected &= width_mask;
					if (rd < 31)
						expected_registers[rd] = expected;

					ret = orlix_tcti_switch_debug_execute_decoded(
						NULL, &regs, &decoded, NULL);
					KUNIT_ASSERT_EQ(test, 0, ret);
					KUNIT_EXPECT_MEMEQ(test, expected_registers,
						regs.regs, sizeof(expected_registers));
					KUNIT_EXPECT_EQ(test, before.sp, regs.sp);
					KUNIT_EXPECT_EQ(test, before.pstate, regs.pstate);
					KUNIT_EXPECT_EQ(test, before.pc + sizeof(u32), regs.pc);
				}
			}
		}
	}

	for (register_case = 0; register_case < 32; register_case++) {
		KUNIT_EXPECT_TRUE(test, seen_rn[register_case]);
		KUNIT_EXPECT_TRUE(test, seen_rm[register_case]);
		KUNIT_EXPECT_TRUE(test, seen_rd[register_case]);
	}
}

