static u32 orlix_tcti_test_encode_data_processing_1source(bool is_64bit, u8 opcode,
						     u8 rn, u8 rd)
{
	return 0x5ac00000U | (is_64bit ? BIT(31) : 0) |
		((u32)opcode << 10) | ((u32)rn << 5) | rd;
}

static u64 orlix_tcti_test_reverse_bits(u64 value, u8 width)
{
	u64 result = 0;
	u8 bit;

	for (bit = 0; bit < width; bit++)
		result |= ((value >> bit) & 1) << (width - 1 - bit);
	return result;
}

static u64 orlix_tcti_test_reverse_bytes_in_lanes(u64 value, u8 width,
						     u8 lane_width)
{
	u64 result = 0;
	u8 lane;
	u8 byte;

	for (lane = 0; lane < width; lane += lane_width) {
		for (byte = 0; byte < lane_width / 8; byte++) {
			u8 source = lane + byte * 8;
			u8 destination = lane + lane_width - 8 - byte * 8;

			result |= ((value >> source) & 0xff) << destination;
		}
	}
	return result;
}

static u64 orlix_tcti_test_count_leading_zeros(u64 value, u8 width)
{
	u64 count = 0;
	int bit;

	for (bit = width - 1; bit >= 0; bit--) {
		if (value & BIT_ULL(bit))
			break;
		count++;
	}
	return count;
}

static u64 orlix_tcti_test_count_leading_sign_bits(u64 value, u8 width)
{
	bool sign = !!(value & BIT_ULL(width - 1));
	u64 count = 0;
	int bit;

	for (bit = width - 2; bit >= 0; bit--) {
		if (!!(value & BIT_ULL(bit)) != sign)
			break;
		count++;
	}
	return count;
}

static u64 orlix_tcti_test_count_trailing_zeros(u64 value, u8 width)
{
	u64 count = 0;
	u8 bit;

	for (bit = 0; bit < width; bit++) {
		if (value & BIT_ULL(bit))
			break;
		count++;
	}
	return count;
}

static u64 orlix_tcti_test_count_set_bits(u64 value, u8 width)
{
	u64 count = 0;
	u8 bit;

	for (bit = 0; bit < width; bit++)
		count += !!(value & BIT_ULL(bit));
	return count;
}

static u64 orlix_tcti_test_signed_abs(u64 value, u8 width)
{
	u64 mask = width == 64 ? U64_MAX : U32_MAX;

	value &= mask;
	if (value & BIT_ULL(width - 1))
		value = -value;
	return value & mask;
}

static void orlix_tcti_gadget_executes_complete_data_processing_1source_family(
	struct kunit *test)
{
	static const u64 source_values[] = {
		0,
		1,
		2,
		0x80000000ULL,
		0xffffffffULL,
		0x0123456789abcdefULL,
		0x8000000000000000ULL,
		0xffffffffffffffffULL,
	};
	bool seen_rn[32] = {};
	bool seen_rd[32] = {};
	unsigned int encoding_case;

	for (encoding_case = 0; encoding_case < BIT(12); encoding_case++) {
		struct orlix_tcti_decoded_instruction decoded;
		struct pt_regs regs = {};
		struct pt_regs before;
		u64 expected_registers[31];
		unsigned int selector = encoding_case;
		u8 rn = selector & 0x1fU;
		u8 opcode;
		bool is_64bit;
		u8 rd;
		bool valid;
		enum orlix_tcti_data_processing_1source_op expected_op = ORLIX_TCTI_DP1_RBIT;
		u8 width;
		u64 mask;
		u64 value;
		u64 expected;
		u32 instruction;
		unsigned int reg;
		int ret;

		selector >>= 5;
		opcode = selector & 0x3fU;
		selector >>= 6;
		is_64bit = selector & 0x1U;
		rd = (rn + opcode + is_64bit) & 0x1fU;
		valid = opcode <= 8 && (is_64bit || opcode != 3);
		if (valid) {
			switch (opcode) {
			case 0:
				expected_op = ORLIX_TCTI_DP1_RBIT;
				break;
			case 1:
				expected_op = ORLIX_TCTI_DP1_REV16;
				break;
			case 2:
				expected_op = is_64bit ? ORLIX_TCTI_DP1_REV32 :
					ORLIX_TCTI_DP1_REV;
				break;
			case 3:
				expected_op = ORLIX_TCTI_DP1_REV;
				break;
			case 4:
				expected_op = ORLIX_TCTI_DP1_CLZ;
				break;
			case 5:
				expected_op = ORLIX_TCTI_DP1_CLS;
				break;
			case 6:
				expected_op = ORLIX_TCTI_DP1_CTZ;
				break;
			case 7:
				expected_op = ORLIX_TCTI_DP1_CNT;
				break;
			case 8:
				expected_op = ORLIX_TCTI_DP1_ABS;
				break;
			}
		}

		instruction = orlix_tcti_test_encode_data_processing_1source(
			is_64bit, opcode, rn, rd);
		decoded = orlix_tcti_decode_aarch64(instruction);
		if (!valid) {
			KUNIT_EXPECT_EQ_MSG(
				test, ORLIX_TCTI_DECODE_UNSUPPORTED, decoded.decode_class,
				"accepted reserved data-processing one-source instruction %08x",
				instruction);
			continue;
		}

		KUNIT_ASSERT_EQ_MSG(
			test, ORLIX_TCTI_DECODE_DATA_PROCESSING_1SOURCE,
			decoded.decode_class,
			"rejected data-processing one-source instruction %08x",
			instruction);
		KUNIT_EXPECT_EQ(test, expected_op, decoded.dp1_op);
		KUNIT_EXPECT_EQ(test, is_64bit, decoded.is_64bit);
		KUNIT_EXPECT_EQ(test, rn, decoded.rn);
		KUNIT_EXPECT_EQ(test, rd, decoded.rd);
		seen_rn[rn] = true;
		seen_rd[rd] = true;

		for (reg = 0; reg < 31; reg++)
			regs.regs[reg] = 0xfedcba9876543210ULL ^
				((u64)instruction << (reg & 7)) ^ reg;
		if (rn < 31)
			regs.regs[rn] = source_values[(rn + opcode) & 7];
		regs.sp = 0x706a865abcULL;
		regs.pc = 0x2468ace000ULL;
		regs.pstate = PSR_N_BIT | PSR_Z_BIT | PSR_C_BIT |
			PSR_V_BIT | 0x155UL;
		before = regs;
		memcpy(expected_registers, before.regs,
		       sizeof(expected_registers));
		width = is_64bit ? 64 : 32;
		mask = is_64bit ? U64_MAX : U32_MAX;
		value = (rn == 31 ? 0 : before.regs[rn]) & mask;
		switch (expected_op) {
		case ORLIX_TCTI_DP1_RBIT:
			expected = orlix_tcti_test_reverse_bits(value, width);
			break;
		case ORLIX_TCTI_DP1_REV16:
			expected = orlix_tcti_test_reverse_bytes_in_lanes(
				value, width, 16);
			break;
		case ORLIX_TCTI_DP1_REV32:
			expected = orlix_tcti_test_reverse_bytes_in_lanes(
				value, width, 32);
			break;
		case ORLIX_TCTI_DP1_REV:
			expected = orlix_tcti_test_reverse_bytes_in_lanes(
				value, width, width);
			break;
		case ORLIX_TCTI_DP1_CLZ:
			expected = orlix_tcti_test_count_leading_zeros(value, width);
			break;
		case ORLIX_TCTI_DP1_CLS:
			expected = orlix_tcti_test_count_leading_sign_bits(value, width);
			break;
		case ORLIX_TCTI_DP1_CTZ:
			expected = orlix_tcti_test_count_trailing_zeros(value, width);
			break;
		case ORLIX_TCTI_DP1_CNT:
			expected = orlix_tcti_test_count_set_bits(value, width);
			break;
		case ORLIX_TCTI_DP1_ABS:
			expected = orlix_tcti_test_signed_abs(value, width);
			break;
		default:
			KUNIT_FAIL(test, "invalid data-processing one-source operation");
			return;
		}
		expected &= mask;
		if (rd < 31)
			expected_registers[rd] = expected;

		ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded,
							 NULL);
		KUNIT_ASSERT_EQ(test, 0, ret);
		KUNIT_EXPECT_MEMEQ(test, expected_registers, regs.regs,
				     sizeof(expected_registers));
		KUNIT_EXPECT_EQ(test, before.sp, regs.sp);
		KUNIT_EXPECT_EQ(test, before.pstate, regs.pstate);
		KUNIT_EXPECT_EQ(test, before.pc + sizeof(u32), regs.pc);
	}

	for (encoding_case = 0; encoding_case < 32; encoding_case++) {
		KUNIT_EXPECT_TRUE(test, seen_rn[encoding_case]);
		KUNIT_EXPECT_TRUE(test, seen_rd[encoding_case]);
	}
}

