static void orlix_tcti_switch_executes_complete_simd_modified_immediate_family(
	struct kunit *test)
{
	static const struct {
		u32 instruction;
		u64 initial;
		u64 expected;
	} cases[] = {
		{ 0x4f002640U, 0, 0x0000120000001200ULL },
		{ 0x6f014681U, 0, 0xffcbffffffcbffffULL },
		{ 0x4f0276c2U, 0x00ff00ff00ff00ffULL,
		  0x56ff00ff56ff00ffULL },
		{ 0x6f03b703U, ~0ULL, 0x87ff87ff87ff87ffULL },
		{ 0x4f04c744U, 0, 0x00009aff00009affULL },
		{ 0x6f05d785U, 0, 0xff430000ff430000ULL },
		{ 0x6f02e6a6U, 0, 0x00ff00ff00ff00ffULL },
		{ 0x4f03f607U, 0, 0x3f8000003f800000ULL },
		{ 0x6f00f408U, 0, 0x4000000000000000ULL },
	};
	struct pt_regs regs = {};
	size_t index;

	regs.pc = 0x8420;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		struct orlix_tcti_decoded_instruction decoded;
		u8 rd = cases[index].instruction & 0x1fU;
		int ret;

		current->thread.user_simd[rd * 2] = cases[index].initial;
		current->thread.user_simd[rd * 2 + 1] = cases[index].initial;
		current->thread.user_simd_valid = 0;
		decoded = orlix_tcti_decode_aarch64(cases[index].instruction);
		ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded,
							NULL);

		KUNIT_ASSERT_EQ(test, 0, ret);
		KUNIT_EXPECT_EQ(test, cases[index].expected,
				current->thread.user_simd[rd * 2]);
		KUNIT_EXPECT_EQ(test, cases[index].expected,
				current->thread.user_simd[rd * 2 + 1]);
		KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
		KUNIT_EXPECT_EQ(test, 0x8424ULL + index * sizeof(u32), regs.pc);
	}
}

static void orlix_tcti_gadget_executes_exhaustive_simd_modimm(struct kunit *test)
{
	u8 q;
	u8 op;
	u8 cmode;

	for (q = 0; q < 2; q++) {
		for (op = 0; op < 2; op++) {
			for (cmode = 0; cmode < 16; cmode++) {
				unsigned int immediate;

				if (!orlix_tcti_test_simd_modimm_is_valid(
					    q, op, cmode))
					continue;
				for (immediate = 0; immediate < 256;
				     immediate++) {
					u8 imm8 = immediate;
					u8 rd = immediate & 0x1fU;
					u32 instruction =
						orlix_tcti_test_encode_simd_modimm(
							q, op, false, cmode,
							imm8, rd);
					struct orlix_tcti_decoded_instruction decoded =
						orlix_tcti_decode_aarch64(
							instruction);
					struct pt_regs regs = {};
					struct pt_regs expected_regs;
					u64 expected_simd[ARRAY_SIZE(
						current->thread.user_simd)];
					u64 value =
						orlix_tcti_test_expand_simd_modimm(
							cmode, op, imm8);
					u64 low;
					u64 high;
					unsigned int index;
					int ret;

					for (index = 0;
					     index <
					     ARRAY_SIZE(
						     current->thread.user_simd);
					     index++)
						current->thread
							.user_simd[index] =
							0x1122334455667788ULL ^
							((u64)instruction
							 << 13) ^
							(0x0101010101010101ULL *
							 index);
					for (index = 0;
					     index < ARRAY_SIZE(regs.regs);
					     index++)
						regs.regs[index] =
							0x8877665544332211ULL ^
							((u64)instruction
							 << 7) ^
							index;
					regs.pc = 0x34567890000ULL;
					regs.sp = 0x456789a0000ULL;
					regs.pstate = PSR_Z_BIT | PSR_V_BIT |
						      0x155UL;
					expected_regs = regs;
					memcpy(expected_simd,
					       current->thread.user_simd,
					       sizeof(expected_simd));
					low = expected_simd[rd * 2];
					high = expected_simd[rd * 2 + 1];

					switch (orlix_tcti_test_simd_modimm_operation(
						cmode, op)) {
					case ORLIX_TCTI_SIMD_MODIMM_MOVI:
						low = value;
						high = value;
						break;
					case ORLIX_TCTI_SIMD_MODIMM_MVNI:
						low = ~value;
						high = ~value;
						break;
					case ORLIX_TCTI_SIMD_MODIMM_ORR:
						low |= value;
						high |= value;
						break;
					case ORLIX_TCTI_SIMD_MODIMM_BIC:
						low &= ~value;
						high &= ~value;
						break;
					}
					expected_simd[rd * 2] = low;
					expected_simd[rd * 2 + 1] = q ? high :
									0;
					current->thread.user_simd_valid = 0;

					ret = orlix_tcti_switch_debug_execute_decoded(
						NULL, &regs, &decoded, NULL);

					KUNIT_ASSERT_EQ(test, 0, ret);
					KUNIT_EXPECT_MEMEQ(
						test, current->thread.user_simd,
						expected_simd,
						sizeof(expected_simd));
					KUNIT_EXPECT_EQ(
						test, 1,
						current->thread.user_simd_valid);
					KUNIT_EXPECT_MEMEQ(test, regs.regs,
							   expected_regs.regs,
							   sizeof(regs.regs));
					KUNIT_EXPECT_EQ(test, expected_regs.sp,
							regs.sp);
					KUNIT_EXPECT_EQ(test,
							expected_regs.pstate,
							regs.pstate);
					KUNIT_EXPECT_EQ(test,
							expected_regs.pc +
								sizeof(u32),
							regs.pc);
				}
			}
		}
	}
}

