static u8 orlix_tcti_test_aes_inverse_substitute(u8 value)
{
	unsigned int index;

	for (index = 0; index < ARRAY_SIZE(orlix_tcti_test_aes_sbox); index++) {
		if (orlix_tcti_test_aes_sbox[index] == value)
			return index;
	}

	return 0;
}

static void orlix_tcti_test_aes_shift_rows(u8 state[16], bool inverse)
{
	u8 source[16];
	u8 column;
	u8 row;

	memcpy(source, state, sizeof(source));
	for (column = 0; column < 4; column++) {
		for (row = 0; row < 4; row++) {
			u8 source_column = inverse ?
				(column - row) & 3U : (column + row) & 3U;

			state[column * 4 + row] =
				source[source_column * 4 + row];
		}
	}
}

static u8 orlix_tcti_test_aes_gf_multiply(u8 left, u8 right)
{
	u8 result = 0;
	u8 bit;

	for (bit = 0; bit < 8; bit++) {
		if (right & BIT(bit))
			result ^= left;
		left = (left << 1) ^ ((left & BIT(7)) ? 0x1bU : 0);
	}

	return result;
}

static void orlix_tcti_test_aes_mix_columns(u8 state[16], bool inverse)
{
	u8 source[16];
	u8 column;

	memcpy(source, state, sizeof(source));
	for (column = 0; column < 4; column++) {
		u8 *result = state + column * 4;
		u8 *input = source + column * 4;

		if (inverse) {
			result[0] = orlix_tcti_test_aes_gf_multiply(input[0], 0x0e) ^
				orlix_tcti_test_aes_gf_multiply(input[1], 0x0b) ^
				orlix_tcti_test_aes_gf_multiply(input[2], 0x0d) ^
				orlix_tcti_test_aes_gf_multiply(input[3], 0x09);
			result[1] = orlix_tcti_test_aes_gf_multiply(input[0], 0x09) ^
				orlix_tcti_test_aes_gf_multiply(input[1], 0x0e) ^
				orlix_tcti_test_aes_gf_multiply(input[2], 0x0b) ^
				orlix_tcti_test_aes_gf_multiply(input[3], 0x0d);
			result[2] = orlix_tcti_test_aes_gf_multiply(input[0], 0x0d) ^
				orlix_tcti_test_aes_gf_multiply(input[1], 0x09) ^
				orlix_tcti_test_aes_gf_multiply(input[2], 0x0e) ^
				orlix_tcti_test_aes_gf_multiply(input[3], 0x0b);
			result[3] = orlix_tcti_test_aes_gf_multiply(input[0], 0x0b) ^
				orlix_tcti_test_aes_gf_multiply(input[1], 0x0d) ^
				orlix_tcti_test_aes_gf_multiply(input[2], 0x09) ^
				orlix_tcti_test_aes_gf_multiply(input[3], 0x0e);
		} else {
			result[0] = orlix_tcti_test_aes_gf_multiply(input[0], 2) ^
				orlix_tcti_test_aes_gf_multiply(input[1], 3) ^
				input[2] ^ input[3];
			result[1] = input[0] ^
				orlix_tcti_test_aes_gf_multiply(input[1], 2) ^
				orlix_tcti_test_aes_gf_multiply(input[2], 3) ^ input[3];
			result[2] = input[0] ^ input[1] ^
				orlix_tcti_test_aes_gf_multiply(input[2], 2) ^
				orlix_tcti_test_aes_gf_multiply(input[3], 3);
			result[3] = orlix_tcti_test_aes_gf_multiply(input[0], 3) ^
				input[1] ^ input[2] ^
				orlix_tcti_test_aes_gf_multiply(input[3], 2);
		}
	}
}

static void
orlix_tcti_test_aes_result(enum orlix_tcti_simd_vector_arithmetic_op operation,
		     const u8 destination[16], const u8 source[16],
		     u8 result[16])
{
	u8 index;

	memcpy(result, operation >= ORLIX_TCTI_SIMD_ARITH_AESMC ? source : destination,
	       16);
	switch (operation) {
	case ORLIX_TCTI_SIMD_ARITH_AESE:
		for (index = 0; index < 16; index++)
			result[index] = orlix_tcti_test_aes_sbox[result[index] ^
								     source[index]];
		orlix_tcti_test_aes_shift_rows(result, false);
		break;
	case ORLIX_TCTI_SIMD_ARITH_AESD:
		for (index = 0; index < 16; index++)
			result[index] =
				orlix_tcti_test_aes_inverse_substitute(result[index] ^
								 source[index]);
		orlix_tcti_test_aes_shift_rows(result, true);
		break;
	case ORLIX_TCTI_SIMD_ARITH_AESMC:
		orlix_tcti_test_aes_mix_columns(result, false);
		break;
	case ORLIX_TCTI_SIMD_ARITH_AESIMC:
		orlix_tcti_test_aes_mix_columns(result, true);
		break;
	default:
		break;
	}
}

static void orlix_tcti_test_aes_unpack(u64 low, u64 high, u8 bytes[16])
{
	u8 index;

	for (index = 0; index < sizeof(u64); index++) {
		bytes[index] = low >> (index * 8);
		bytes[index + sizeof(u64)] = high >> (index * 8);
	}
}

static void orlix_tcti_test_aes_pack(const u8 bytes[16], u64 *low, u64 *high)
{
	u8 index;

	*low = 0;
	*high = 0;
	for (index = 0; index < sizeof(u64); index++) {
		*low |= (u64)bytes[index] << (index * 8);
		*high |= (u64)bytes[index + sizeof(u64)] << (index * 8);
	}
}

static void orlix_tcti_switch_executes_simd_aes_known_vectors(struct kunit *test)
{
	struct {
		u32 instruction;
		u64 source_low;
		u64 source_high;
		u64 expected_low;
		u64 expected_high;
	} cases[] = {
		{ 0x4e284820U, 0xbfc6cdd4dbe2e9f0ULL,
		  0x878e959ca3aab1b8ULL, 0x61cd6c70c4e0e88cULL,
		  0xc2ba9b606ce146e7ULL },
		{ 0x4e285820U, 0xbfc6cdd4dbe2e9f0ULL,
		  0x878e959ca3aab1b8ULL, 0x6f3ac8609a47e217ULL,
		  0x2d1f9a9697a0b1fcULL },
		{ 0x4e286820U, 0x0706050403020100ULL,
		  0x0f0e0d0c0b0a0908ULL, 0x0104030605000702ULL,
		  0x090c0b0e0d080f0aULL },
		{ 0x4e287820U, 0x0706050403020100ULL,
		  0x0f0e0d0c0b0a0908ULL, 0x090c0b0e0d080f0aULL,
		  0x0104030605000702ULL },
	};
	struct pt_regs regs = {};
	size_t index;

	regs.pc = 0x87b0;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(cases[index].instruction);
		int ret;

		current->thread.user_simd[0] = 0x0706050403020100ULL;
		current->thread.user_simd[1] = 0x0f0e0d0c0b0a0908ULL;
		current->thread.user_simd[2] = cases[index].source_low;
		current->thread.user_simd[3] = cases[index].source_high;
		current->thread.user_simd_valid = 0;

		ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded,
							 NULL);
		KUNIT_ASSERT_EQ(test, 0, ret);
		KUNIT_EXPECT_EQ(test, cases[index].expected_low,
				current->thread.user_simd[0]);
		KUNIT_EXPECT_EQ(test, cases[index].expected_high,
				current->thread.user_simd[1]);
		KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
		KUNIT_EXPECT_EQ(test,
				0x87b0ULL + (index + 1) * sizeof(u32), regs.pc);
	}
}

static void orlix_tcti_test_initialize_aes_registers(u32 instruction)
{
	unsigned int word;

	for (word = 0; word < ARRAY_SIZE(current->thread.user_simd); word++)
		current->thread.user_simd[word] =
			0xfedcba9876543210ULL ^
			ror64((u64)instruction << (word & 7), word & 63) ^
			0x0101010101010101ULL * word;
}

static void orlix_tcti_gadget_executes_complete_aes_family(struct kunit *test)
{
	bool seen_rn[32] = {};
	bool seen_rd[32] = {};
	bool saw_alias = false;
	u8 operation_index;

	for (operation_index = 0; operation_index < 4; operation_index++) {
		enum orlix_tcti_simd_vector_arithmetic_op operation =
			ORLIX_TCTI_SIMD_ARITH_AESE + operation_index;
		u8 register_case;

		for (register_case = 0; register_case < 32; register_case++) {
			u8 rn = (register_case * 7 + operation_index) & 0x1fU;
			u8 rd = (register_case * 13 + operation_index * 3) &
				0x1fU;
			u32 instruction = 0x4e284800U |
				((u32)operation_index << 12) |
				((u32)rn << 5) | rd;
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);
			struct pt_regs regs = {};
			struct pt_regs before_regs;
			u64 before_simd[ARRAY_SIZE(current->thread.user_simd)];
			u64 expected_simd[ARRAY_SIZE(current->thread.user_simd)];
			u8 destination[16];
			u8 source[16];
			u8 result[16];
			unsigned int gpr;
			int ret;

			KUNIT_ASSERT_EQ(test,
					ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
					decoded.decode_class);
			KUNIT_EXPECT_EQ(test, operation,
					decoded.simd_arithmetic_op);
			KUNIT_EXPECT_EQ(test, 2 * sizeof(u64),
					decoded.access_size);
			KUNIT_EXPECT_EQ(test, 2 * sizeof(u64),
					decoded.result_size);
			KUNIT_EXPECT_EQ(test, rn, decoded.rn);
			KUNIT_EXPECT_EQ(test, rd, decoded.rd);
			KUNIT_EXPECT_TRUE(test, decoded.simd_fp);

			seen_rn[rn] = true;
			seen_rd[rd] = true;
			saw_alias |= rn == rd;
			orlix_tcti_test_initialize_aes_registers(instruction);
			memcpy(before_simd, current->thread.user_simd,
			       sizeof(before_simd));
			memcpy(expected_simd, before_simd, sizeof(expected_simd));
			orlix_tcti_test_aes_unpack(before_simd[rd * 2],
					     before_simd[rd * 2 + 1], destination);
			orlix_tcti_test_aes_unpack(before_simd[rn * 2],
					     before_simd[rn * 2 + 1], source);
			orlix_tcti_test_aes_result(operation, destination, source, result);
			orlix_tcti_test_aes_pack(result, &expected_simd[rd * 2],
					   &expected_simd[rd * 2 + 1]);

			for (gpr = 0; gpr < ARRAY_SIZE(regs.regs); gpr++)
				regs.regs[gpr] = 0xabcdef0000000000ULL |
						 gpr;
			regs.pc = 0x12345678000ULL;
			regs.sp = 0x98765432100ULL;
			regs.pstate = PSR_N_BIT | PSR_Z_BIT | 0x155UL;
			before_regs = regs;
			current->thread.user_simd_valid = 0;

			ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

			KUNIT_ASSERT_EQ(test, 0, ret);
			KUNIT_EXPECT_MEMEQ(test, current->thread.user_simd,
					   expected_simd, sizeof(expected_simd));
			KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
			KUNIT_EXPECT_MEMEQ(test, before_regs.regs, regs.regs,
					   sizeof(regs.regs));
			KUNIT_EXPECT_EQ(test, before_regs.sp, regs.sp);
			KUNIT_EXPECT_EQ(test, before_regs.pstate, regs.pstate);
			KUNIT_EXPECT_EQ(test, before_regs.pc + sizeof(u32),
					regs.pc);
		}
	}

	for (operation_index = 0; operation_index < 32; operation_index++) {
		KUNIT_EXPECT_TRUE(test, seen_rn[operation_index]);
		KUNIT_EXPECT_TRUE(test, seen_rd[operation_index]);
	}
	KUNIT_EXPECT_TRUE(test, saw_alias);

	for (operation_index = 0; operation_index < 2; operation_index++) {
		enum orlix_tcti_simd_vector_arithmetic_op operation =
			ORLIX_TCTI_SIMD_ARITH_AESE + operation_index;
		u8 chunk;

		for (chunk = 0; chunk < 16; chunk++) {
			u32 instruction = 0x4e284820U |
				((u32)operation_index << 12);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);
			struct pt_regs regs = { .pc = 0x12345678000ULL };
			u8 destination[16];
			u8 source[16] = {};
			u8 expected[16];
			u64 destination_low;
			u64 destination_high;
			u8 lane;
			int ret;

			for (lane = 0; lane < 16; lane++) {
				u8 value = chunk * 16 + lane;

				destination[lane] = operation_index ?
					orlix_tcti_test_aes_sbox[value] : value;
			}
			orlix_tcti_test_aes_result(operation, destination, source,
					     expected);
			orlix_tcti_test_aes_pack(destination, &destination_low,
					   &destination_high);
			current->thread.user_simd[0] = destination_low;
			current->thread.user_simd[1] = destination_high;
			current->thread.user_simd[2] = 0;
			current->thread.user_simd[3] = 0;
			current->thread.user_simd_valid = 0;

			ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

			KUNIT_ASSERT_EQ(test, 0, ret);
			{
				u64 expected_low;
				u64 expected_high;

				orlix_tcti_test_aes_pack(expected, &expected_low,
						   &expected_high);
				KUNIT_EXPECT_EQ(test, expected_low,
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, expected_high,
						current->thread.user_simd[1]);
			}
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_multiply_long_family(struct kunit *test)
{
	struct {
		u32 pattern;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0e20c000U, ORLIX_TCTI_SIMD_ARITH_SMULL },
		{ 0x2e20c000U, ORLIX_TCTI_SIMD_ARITH_UMULL },
		{ 0x0e208000U, ORLIX_TCTI_SIMD_ARITH_SMLAL },
		{ 0x2e208000U, ORLIX_TCTI_SIMD_ARITH_UMLAL },
		{ 0x0e20a000U, ORLIX_TCTI_SIMD_ARITH_SMLSL },
		{ 0x2e20a000U, ORLIX_TCTI_SIMD_ARITH_UMLSL },
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;

	regs.pc = 0x87c0;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		u8 q;
		u8 size;

		for (q = 0; q < 2; q++) {
			for (size = 0; size < 3; size++) {
				u8 source_size = BIT(size);
				u8 result_size = source_size * 2;
				u8 source_lane_count = sizeof(u64) /
						       source_size;
				u8 result_lane_count = 2 * sizeof(u64) /
						       result_size;
				u64 source_mask =
					GENMASK_ULL(source_size * 8 - 1, 0);
				u64 result_mask =
					GENMASK_ULL(result_size * 8 - 1, 0);
				bool signed_multiply =
					cases[index].operation ==
						ORLIX_TCTI_SIMD_ARITH_SMULL ||
					cases[index].operation ==
						ORLIX_TCTI_SIMD_ARITH_SMLAL ||
					cases[index].operation ==
						ORLIX_TCTI_SIMD_ARITH_SMLSL;
				bool accumulate =
					cases[index].operation !=
						ORLIX_TCTI_SIMD_ARITH_SMULL &&
					cases[index].operation !=
						ORLIX_TCTI_SIMD_ARITH_UMULL;
				bool subtract =
					cases[index].operation ==
						ORLIX_TCTI_SIMD_ARITH_SMLSL ||
					cases[index].operation ==
						ORLIX_TCTI_SIMD_ARITH_UMLSL;
				u64 left_value = signed_multiply ?
						 source_mask - 2 : 3;
				u64 right_value = 5;
				u64 product = signed_multiply ?
						 result_mask - 14 : 15;
				u64 expected_value = accumulate ?
						 (subtract ? 100 - product :
							     100 + product) :
						 product;
				u64 left = 0;
				u64 right = 0;
				u64 accumulator[2] = {};
				u64 expected[2] = {};
				u8 lane;
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;
				int ret;

				if (signed_multiply && accumulate)
					expected_value = subtract ? 115 : 85;
				else if (!signed_multiply && accumulate)
					expected_value = subtract ? 85 : 115;

				for (lane = 0; lane < source_lane_count; lane++) {
					u8 shift = lane * source_size * 8;

					left |= left_value << shift;
					right |= right_value << shift;
				}
				for (lane = 0; lane < result_lane_count; lane++) {
					u8 byte = lane * result_size;
					u8 word = byte / sizeof(u64);
					u8 shift = (byte % sizeof(u64)) * 8;

					accumulator[word] |= 100ULL << shift;
					expected[word] |=
						(expected_value & result_mask) << shift;
				}

				instruction = cases[index].pattern |
					      (q ? BIT(30) : 0) |
					      ((u32)size << 22) |
					      (2U << 16) | (1U << 5);
				decoded = orlix_tcti_decode_aarch64(instruction);
				current->thread.user_simd[0] = accumulator[0];
				current->thread.user_simd[1] = accumulator[1];
				current->thread.user_simd[2] = q ? U64_MAX : left;
				current->thread.user_simd[3] = q ? left : U64_MAX;
				current->thread.user_simd[4] = q ? U64_MAX : right;
				current->thread.user_simd[5] = q ? right : U64_MAX;
				current->thread.user_simd_valid = 0;

				ret = orlix_tcti_switch_debug_execute_decoded(
					NULL, &regs, &decoded, NULL);
				execution_count++;
				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, expected[0],
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, expected[1],
						current->thread.user_simd[1]);
				KUNIT_EXPECT_EQ(test, 1,
						current->thread.user_simd_valid);
				KUNIT_EXPECT_EQ(
					test,
					0x87c0ULL + execution_count * sizeof(u32),
					regs.pc);
			}
		}
	}
}

static void orlix_tcti_switch_executes_simd_pmull_known_vectors(struct kunit *test)
{
	struct pt_regs regs = {};
	u8 execution_count = 0;
	u8 q;
	u8 size;

	regs.pc = 0x87e0;
	for (q = 0; q < 2; q++) {
		for (size = 0; size < 4; size++) {
			u64 left;
			u64 right;
			u64 expected_low;
			u64 expected_high;
			u32 instruction;
			struct orlix_tcti_decoded_instruction decoded;
			int ret;

			if (size != 0 && size != 3)
				continue;

			if (size == 0) {
				left = 0x5757575757575757ULL;
				right = 0x1313131313131313ULL;
				expected_low = 0x0589058905890589ULL;
				expected_high = 0x0589058905890589ULL;
			} else {
				left = 0x8000000000000001ULL;
				right = 3;
				expected_low = 0x8000000000000003ULL;
				expected_high = 1;
			}

			instruction = 0x0e20e000U | (q ? BIT(30) : 0) |
				      ((u32)size << 22) | (2U << 16) |
				      (1U << 5);
			decoded = orlix_tcti_decode_aarch64(instruction);
			current->thread.user_simd[2] = q ? U64_MAX : left;
			current->thread.user_simd[3] = q ? left : U64_MAX;
			current->thread.user_simd[4] = q ? U64_MAX : right;
			current->thread.user_simd[5] = q ? right : U64_MAX;
			current->thread.user_simd_valid = 0;

			ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
							 &decoded, NULL);
			execution_count++;
			KUNIT_ASSERT_EQ(test, 0, ret);
			KUNIT_EXPECT_EQ(test, expected_low,
					current->thread.user_simd[0]);
			KUNIT_EXPECT_EQ(test, expected_high,
					current->thread.user_simd[1]);
			KUNIT_EXPECT_EQ(test, 1,
					current->thread.user_simd_valid);
			KUNIT_EXPECT_EQ(test,
					0x87e0ULL + execution_count * sizeof(u32),
					regs.pc);
		}
	}
}

static u16 orlix_tcti_test_polynomial_multiply_u8(u8 left, u8 right)
{
	u16 result = 0;
	u8 bit;

	for (bit = 0; bit < 8; bit++) {
		if (right & BIT(bit))
			result ^= (u16)left << bit;
	}

	return result;
}

static void orlix_tcti_test_polynomial_multiply_u64(u64 left, u64 right,
					      u64 *low, u64 *high)
{
	u64 result_low = 0;
	u64 result_high = 0;
	u8 bit;

	for (bit = 0; bit < 64; bit++) {
		if (!(right & BIT_ULL(bit)))
			continue;
		result_low ^= left << bit;
		if (bit)
			result_high ^= left >> (64 - bit);
	}

	*low = result_low;
	*high = result_high;
}

static void orlix_tcti_test_initialize_simd_registers(u32 instruction)
{
	unsigned int word;

	for (word = 0; word < ARRAY_SIZE(current->thread.user_simd); word++)
		current->thread.user_simd[word] =
			0x1020304050607080ULL ^
			rol64((u64)instruction << (word & 7), word & 63) ^ word;
}

static void
orlix_tcti_gadget_executes_complete_polynomial_multiply_family(struct kunit *test)
{
	bool seen_rn[32] = {};
	bool seen_rm[32] = {};
	bool seen_rd[32] = {};
	bool saw_source_alias = false;
	bool saw_destination_alias = false;
	u8 q;

	for (q = 0; q < 2; q++) {
		u8 size;

		for (size = 0; size < 4; size++) {
			u8 register_case;

			for (register_case = 0; register_case < 32;
			     register_case++) {
				struct orlix_tcti_decoded_instruction decoded;
				struct pt_regs regs = {};
				struct pt_regs before_regs;
				u64 before_simd[
					ARRAY_SIZE(current->thread.user_simd)];
				u64 expected_simd[
					ARRAY_SIZE(current->thread.user_simd)];
				u8 rn = register_case;
				u8 rm = (register_case * 7 + q) & 0x1fU;
				u8 rd = (register_case * 13 + q) & 0x1fU;
				u32 instruction = 0x0e209c00U | BIT(29) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | ((u32)rm << 16) |
					((u32)rn << 5) | rd;
				int ret;

				decoded = orlix_tcti_decode_aarch64(instruction);
				if (size) {
					KUNIT_EXPECT_EQ_MSG(
						test, ORLIX_TCTI_DECODE_UNSUPPORTED,
						decoded.decode_class,
						"accepted reserved PMUL size=%u q=%u instruction=%#x",
						size, q, instruction);
					continue;
				}

				KUNIT_ASSERT_EQ(test,
						ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
						decoded.decode_class);
				KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ARITH_PMUL,
						decoded.simd_arithmetic_op);
				KUNIT_EXPECT_EQ(test, sizeof(u8),
						decoded.access_size);
				KUNIT_EXPECT_EQ(test,
						q ? 2 * sizeof(u64) : sizeof(u64),
						decoded.result_size);
				KUNIT_EXPECT_EQ(test, rn, decoded.rn);
				KUNIT_EXPECT_EQ(test, rm, decoded.rm);
				KUNIT_EXPECT_EQ(test, rd, decoded.rd);

				seen_rn[rn] = true;
				seen_rm[rm] = true;
				seen_rd[rd] = true;
				saw_source_alias |= rn == rm;
				saw_destination_alias |= rd == rn || rd == rm;
				orlix_tcti_test_initialize_simd_registers(instruction);
				memcpy(before_simd, current->thread.user_simd,
				       sizeof(before_simd));
				memcpy(expected_simd, before_simd,
				       sizeof(expected_simd));
				{
					u64 result[2] = {};
					u8 lane_count = q ? 16 : 8;
					u8 lane;

					for (lane = 0; lane < lane_count; lane++) {
						u8 word = lane / 8;
						u8 shift = (lane % 8) * 8;
						u8 left = before_simd[rn * 2 + word] >>
							shift;
						u8 right = before_simd[rm * 2 + word] >>
							 shift;
						u8 product =
							orlix_tcti_test_polynomial_multiply_u8(
								left, right);

						result[word] |= (u64)product << shift;
					}
					expected_simd[rd * 2] = result[0];
					expected_simd[rd * 2 + 1] =
						q ? result[1] : 0;
				}

				regs.pc = 0x2468ace000ULL;
				regs.sp = 0x706a865abcULL;
				regs.pstate = PSR_N_BIT | PSR_C_BIT | 0x155UL;
				before_regs = regs;
				current->thread.user_simd_valid = 0;
				ret = orlix_tcti_switch_debug_execute_decoded(
					NULL, &regs, &decoded, NULL);
				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_MEMEQ(test, expected_simd,
						   current->thread.user_simd,
						   sizeof(expected_simd));
				KUNIT_EXPECT_EQ(test, 1,
						current->thread.user_simd_valid);
				KUNIT_EXPECT_MEMEQ(test, before_regs.regs, regs.regs,
						   sizeof(regs.regs));
				KUNIT_EXPECT_EQ(test, before_regs.sp, regs.sp);
				KUNIT_EXPECT_EQ(test, before_regs.pstate, regs.pstate);
				KUNIT_EXPECT_EQ(test, before_regs.pc + sizeof(u32),
						regs.pc);
			}
		}
	}

	for (q = 0; q < 2; q++) {
		u8 size;

		for (size = 0; size < 4; size++) {
			u8 register_case;

			for (register_case = 0; register_case < 32;
			     register_case++) {
				struct orlix_tcti_decoded_instruction decoded;
				struct pt_regs regs = {};
				struct pt_regs before_regs;
				u64 before_simd[
					ARRAY_SIZE(current->thread.user_simd)];
				u64 expected_simd[
					ARRAY_SIZE(current->thread.user_simd)];
				u64 result[2] = {};
				u8 rn = register_case;
				u8 rm = (register_case * 7 + q + size) & 0x1fU;
				u8 rd = (register_case * 13 + q + size) & 0x1fU;
				u32 instruction = 0x0e20e000U |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | ((u32)rm << 16) |
					((u32)rn << 5) | rd;
				int ret;

				decoded = orlix_tcti_decode_aarch64(instruction);
				if (size != 0 && size != 3) {
					KUNIT_EXPECT_EQ_MSG(
						test, ORLIX_TCTI_DECODE_UNSUPPORTED,
						decoded.decode_class,
						"accepted reserved PMULL size=%u q=%u instruction=%#x",
						size, q, instruction);
					continue;
				}

				KUNIT_ASSERT_EQ(test,
						ORLIX_TCTI_DECODE_SIMD_VECTOR_ARITHMETIC,
						decoded.decode_class);
				KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ARITH_PMULL,
						decoded.simd_arithmetic_op);
				KUNIT_EXPECT_EQ(test, BIT(size),
						decoded.access_size);
				KUNIT_EXPECT_EQ(test, 2 * sizeof(u64),
						decoded.result_size);
				KUNIT_EXPECT_EQ(test, q,
						decoded.simd_source_index);
				KUNIT_EXPECT_EQ(test, rn, decoded.rn);
				KUNIT_EXPECT_EQ(test, rm, decoded.rm);
				KUNIT_EXPECT_EQ(test, rd, decoded.rd);

				seen_rn[rn] = true;
				seen_rm[rm] = true;
				seen_rd[rd] = true;
				saw_source_alias |= rn == rm;
				saw_destination_alias |= rd == rn || rd == rm;
				orlix_tcti_test_initialize_simd_registers(instruction);
				memcpy(before_simd, current->thread.user_simd,
				       sizeof(before_simd));
				memcpy(expected_simd, before_simd,
				       sizeof(expected_simd));
				if (size == 0) {
					u64 left = before_simd[rn * 2 + q];
					u64 right = before_simd[rm * 2 + q];
					u8 lane;

					for (lane = 0; lane < 8; lane++) {
						u16 product =
							orlix_tcti_test_polynomial_multiply_u8(
								left >> (lane * 8),
								right >> (lane * 8));

						result[lane / 4] |= (u64)product <<
							((lane % 4) * 16);
					}
				} else {
					orlix_tcti_test_polynomial_multiply_u64(
						before_simd[rn * 2 + q],
						before_simd[rm * 2 + q],
						&result[0], &result[1]);
				}
				expected_simd[rd * 2] = result[0];
				expected_simd[rd * 2 + 1] = result[1];

				regs.pc = 0x13579bdf000ULL;
				regs.sp = 0x706a865abcULL;
				regs.pstate = PSR_Z_BIT | PSR_V_BIT | 0x155UL;
				before_regs = regs;
				current->thread.user_simd_valid = 0;
				ret = orlix_tcti_switch_debug_execute_decoded(
					NULL, &regs, &decoded, NULL);
				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_MEMEQ(test, expected_simd,
						   current->thread.user_simd,
						   sizeof(expected_simd));
				KUNIT_EXPECT_EQ(test, 1,
						current->thread.user_simd_valid);
				KUNIT_EXPECT_MEMEQ(test, before_regs.regs, regs.regs,
						   sizeof(regs.regs));
				KUNIT_EXPECT_EQ(test, before_regs.sp, regs.sp);
				KUNIT_EXPECT_EQ(test, before_regs.pstate, regs.pstate);
				KUNIT_EXPECT_EQ(test, before_regs.pc + sizeof(u32),
						regs.pc);
			}
		}
	}

	for (q = 0; q < 32; q++) {
		KUNIT_EXPECT_TRUE(test, seen_rn[q]);
		KUNIT_EXPECT_TRUE(test, seen_rm[q]);
		KUNIT_EXPECT_TRUE(test, seen_rd[q]);
	}
	KUNIT_EXPECT_TRUE(test, saw_source_alias);
	KUNIT_EXPECT_TRUE(test, saw_destination_alias);
}

static void orlix_tcti_switch_executes_complete_simd_mla_mls_family(struct kunit *test)
{
	struct pt_regs regs = {};
	u8 subtract;
	u8 q;
	u8 size;
	u8 execution_count = 0;

	regs.pc = 0x8800;
	for (subtract = 0; subtract < 2; subtract++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 3; size++) {
				u8 access_size = BIT(size);
				u8 result_size = q ? 16 : 8;
				u8 lane_count = result_size / access_size;
				u64 mask = GENMASK_ULL(access_size * 8 - 1, 0);
				u64 accumulator[2] = {};
				u64 left[2] = {};
				u64 right[2] = {};
				u64 expected[2] = {};
				u64 expected_value = subtract ? mask - 1 : 22;
				u8 lane;
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;
				int ret;

				for (lane = 0; lane < lane_count; lane++) {
					u8 byte = lane * access_size;
					u8 word = byte / sizeof(u64);
					u8 shift = (byte % sizeof(u64)) * 8;

					accumulator[word] |= 10ULL << shift;
					left[word] |= 3ULL << shift;
					right[word] |= 4ULL << shift;
					expected[word] |= expected_value << shift;
				}

				instruction = 0x0e209400U |
					(subtract ? BIT(29) : 0) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | (2U << 16) |
					(1U << 5);
				current->thread.user_simd[0] = accumulator[0];
				current->thread.user_simd[1] = accumulator[1];
				current->thread.user_simd[2] = left[0];
				current->thread.user_simd[3] = left[1];
				current->thread.user_simd[4] = right[0];
				current->thread.user_simd[5] = right[1];
				current->thread.user_simd_valid = 0;
				decoded = orlix_tcti_decode_aarch64(instruction);
				ret = orlix_tcti_switch_debug_execute_decoded(
					NULL, &regs, &decoded, NULL);

				execution_count++;
				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, expected[0],
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, expected[1],
						current->thread.user_simd[1]);
				KUNIT_EXPECT_EQ(test, 1,
						current->thread.user_simd_valid);
				KUNIT_EXPECT_EQ(test,
					0x8800ULL + execution_count * sizeof(u32),
					regs.pc);
			}
		}
	}

	current->thread.user_simd[2] = 0x0303030303030303ULL;
	current->thread.user_simd[3] = 0x0303030303030303ULL;
	current->thread.user_simd[4] = 0x0404040404040404ULL;
	current->thread.user_simd[5] = 0x0404040404040404ULL;
	{
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(0x4e229421U);
		int ret = orlix_tcti_switch_debug_execute_decoded(
			NULL, &regs, &decoded, NULL);

		KUNIT_ASSERT_EQ(test, 0, ret);
		KUNIT_EXPECT_EQ(test, 0x0f0f0f0f0f0f0f0fULL,
				current->thread.user_simd[2]);
		KUNIT_EXPECT_EQ(test, 0x0f0f0f0f0f0f0f0fULL,
				current->thread.user_simd[3]);
	}
}

static void orlix_tcti_switch_executes_complete_simd_min_max_family(struct kunit *test)
{
	struct pt_regs regs = {};
	u8 operation;
	u8 q;
	u8 size;
	u8 execution_count = 0;

	regs.pc = 0x8860;
	for (operation = 0; operation < 4; operation++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 3; size++) {
				u8 access_size = BIT(size);
				u8 result_size = q ? 16 : 8;
				u8 lane_count = result_size / access_size;
				u64 mask = GENMASK_ULL(access_size * 8 - 1, 0);
				u64 left[2] = {};
				u64 right[2] = {};
				u64 expected[2] = {};
				u64 expected_value =
					operation == 0 || operation == 3 ? 2 : mask - 2;
				u8 lane;
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;
				int ret;

				for (lane = 0; lane < lane_count; lane++) {
					u8 byte = lane * access_size;
					u8 word = byte / sizeof(u64);
					u8 shift = (byte % sizeof(u64)) * 8;

					left[word] |= (mask - 2) << shift;
					right[word] |= 2ULL << shift;
					expected[word] |= expected_value << shift;
				}

				instruction = 0x0e206400U |
					((operation & 1U) ? BIT(29) : 0) |
					((operation & 2U) ? BIT(11) : 0) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | (2U << 16) |
					(1U << 5);
				current->thread.user_simd[2] = left[0];
				current->thread.user_simd[3] = left[1];
				current->thread.user_simd[4] = right[0];
				current->thread.user_simd[5] = right[1];
				current->thread.user_simd_valid = 0;
				decoded = orlix_tcti_decode_aarch64(instruction);
				ret = orlix_tcti_switch_debug_execute_decoded(
					NULL, &regs, &decoded, NULL);

				execution_count++;
				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, expected[0],
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, expected[1],
						current->thread.user_simd[1]);
				KUNIT_EXPECT_EQ(test, 1,
						current->thread.user_simd_valid);
				KUNIT_EXPECT_EQ(test,
					0x8860ULL + execution_count * sizeof(u32),
					regs.pc);
			}
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_saturating_shift_left_immediate_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0f007400U, false, ORLIX_TCTI_SIMD_ARITH_SQSHL },
		{ 0x0f007400U, true, ORLIX_TCTI_SIMD_ARITH_UQSHL },
		{ 0x0f006400U, true, ORLIX_TCTI_SIMD_ARITH_SQSHLU },
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;
	u8 scalar;
	u8 q;
	u8 size;

	regs.pc = 0x88c0;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (scalar = 0; scalar < 2; scalar++) {
			for (q = 0; q < 2; q++) {
				if (scalar && q)
					continue;
				for (size = 0; size < 4; size++) {
					u8 access_size = BIT(size);
					u8 lane_bits = access_size * 8;
					u8 result_size = scalar ? access_size :
						(q ? 16 : 8);
					u8 lane_count = scalar ? 1 :
						result_size / access_size;
					u64 mask = GENMASK_ULL(lane_bits - 1, 0);
					u8 shift_amount;

					if (!scalar && !q && size == 3)
						continue;
					for (shift_amount = 0; shift_amount < lane_bits;
					     shift_amount++) {
						u64 source[2] = {};
						u64 expected[2] = {};
						bool saturated = false;
						u8 lane;
						u32 instruction;
						struct orlix_tcti_decoded_instruction decoded;
						int ret;

						for (lane = 0; lane < lane_count; lane++) {
							u8 byte = lane * access_size;
							u8 word = byte / 8;
							u8 shift = (byte % 8) * 8;
							u8 selector = (lane + shift_amount) % 3;
							u64 value;
							u64 lane_result;

							if (cases[index].operation ==
							    ORLIX_TCTI_SIMD_ARITH_UQSHL)
								value = selector == 0 ? mask : 1;
							else if (selector == 0)
								value = BIT_ULL(lane_bits - 1);
							else if (selector == 1)
								value = mask >> 1;
							else
								value = 1;
							source[word] |= value << shift;

							if (cases[index].operation ==
							    ORLIX_TCTI_SIMD_ARITH_UQSHL) {
								if (value > (mask >> shift_amount)) {
									lane_result = mask;
									saturated = true;
								} else {
									lane_result = value << shift_amount;
								}
							} else {
								s64 signed_value = sign_extend64(
									value, lane_bits - 1);

								if (cases[index].operation ==
								    ORLIX_TCTI_SIMD_ARITH_SQSHLU) {
									if (signed_value < 0) {
										lane_result = 0;
										saturated = true;
									} else if ((u64)signed_value >
										   (mask >> shift_amount)) {
										lane_result = mask;
										saturated = true;
									} else {
										lane_result = (u64)signed_value <<
											shift_amount;
									}
								} else {
									s64 minimum = lane_bits == 64 ? S64_MIN :
										-(1LL << (lane_bits - 1));
									s64 maximum = lane_bits == 64 ? S64_MAX :
										(1LL << (lane_bits - 1)) - 1;

									if (signed_value >
									    (maximum >> shift_amount)) {
										lane_result = (u64)maximum & mask;
										saturated = true;
									} else if (signed_value <
										   (minimum >> shift_amount)) {
										lane_result = (u64)minimum & mask;
										saturated = true;
									} else {
										lane_result = (u64)signed_value <<
											shift_amount;
									}
								}
							}
							expected[word] |=
								(lane_result & mask) << shift;
						}

						instruction = cases[index].pattern |
							(cases[index].u ? BIT(29) : 0) |
							(scalar ? BIT(28) | BIT(30) :
							 (q ? BIT(30) : 0)) |
							((u32)(lane_bits + shift_amount) << 16) |
							(1U << 5);
						current->thread.user_simd[0] = ~0ULL;
						current->thread.user_simd[1] = ~0ULL;
						current->thread.user_simd[2] = source[0];
						current->thread.user_simd[3] = source[1];
						current->thread.user_simd_valid = 0;
						current->thread.user_fpsr = 0x20;
						decoded = orlix_tcti_decode_aarch64(instruction);
						ret = orlix_tcti_switch_debug_execute_decoded(
							NULL, &regs, &decoded, NULL);

						execution_count++;
						KUNIT_ASSERT_EQ(test, 0, ret);
						KUNIT_EXPECT_EQ(test, expected[0],
								current->thread.user_simd[0]);
						KUNIT_EXPECT_EQ(test, expected[1],
								current->thread.user_simd[1]);
						KUNIT_EXPECT_EQ(test,
								0x20U | (saturated ?
								 BIT(27) : 0U),
								current->thread.user_fpsr);
						KUNIT_EXPECT_EQ(test,
								0x88c0ULL +
								execution_count * sizeof(u32),
								regs.pc);
					}
				}
			}
		}
	}
}

static u64 orlix_tcti_test_scalar_sqdm_long_result(u64 left, u64 right,
					     u64 accumulator, u8 source_bits,
					     bool accumulate, bool subtract,
					     bool *saturated)
{
	u8 result_bits = source_bits * 2;
	u64 source_mask = GENMASK_ULL(source_bits - 1, 0);
	u64 result_mask = GENMASK_ULL(result_bits - 1, 0);
	__int128 result;
	__int128 minimum = -((__int128)1 << (result_bits - 1));
	__int128 maximum = ((__int128)1 << (result_bits - 1)) - 1;

	result = (__int128)sign_extend64(left & source_mask, source_bits - 1) *
		 sign_extend64(right & source_mask, source_bits - 1) * 2;
	if (accumulate) {
		__int128 signed_accumulator =
			sign_extend64(accumulator & result_mask,
				      result_bits - 1);

		result = subtract ? signed_accumulator - result :
				    signed_accumulator + result;
	}
	if (result < minimum) {
		result = minimum;
		*saturated = true;
	} else if (result > maximum) {
		result = maximum;
		*saturated = true;
	}
	return (u64)result & result_mask;
}

static void orlix_tcti_test_execute_scalar_sqdm_long(struct kunit *test, u32 pattern,
						bool accumulate, bool subtract,
						u8 size, s64 left_value,
						s64 right_value, u8 rd, u8 rn,
						u8 rm)
{
	u8 source_bits = (1U << size) * 8;
	u32 instruction = pattern | ((u32)size << 22) | ((u32)rm << 16) |
			  ((u32)rn << 5) | rd;
	struct orlix_tcti_decoded_instruction decoded =
		orlix_tcti_decode_aarch64(instruction);
	struct pt_regs regs = {};
	struct pt_regs expected_regs;
	u64 expected_simd[ARRAY_SIZE(current->thread.user_simd)];
	u64 left;
	u64 right;
	u64 accumulator;
	u64 result;
	bool saturated = false;
	unsigned int word;
	int ret;

	for (word = 0; word < ARRAY_SIZE(current->thread.user_simd); word++)
		current->thread.user_simd[word] = 0x1020304050607080ULL ^
						 ((u64)instruction << 11) ^ word;
	current->thread.user_simd[rn * 2] = (u64)left_value;
	current->thread.user_simd[rm * 2] = (u64)right_value;
	current->thread.user_simd[rd * 2] ^= 0x55aa55aa55aa55aaULL;
	left = current->thread.user_simd[rn * 2];
	right = current->thread.user_simd[rm * 2];
	accumulator = current->thread.user_simd[rd * 2];
	memcpy(expected_simd, current->thread.user_simd, sizeof(expected_simd));
	result = orlix_tcti_test_scalar_sqdm_long_result(left, right, accumulator,
						    source_bits, accumulate,
						    subtract, &saturated);
	expected_simd[rd * 2] = result;
	expected_simd[rd * 2 + 1] = 0;
	for (word = 0; word < ARRAY_SIZE(regs.regs); word++)
		regs.regs[word] = 0x8877665544332211ULL ^ word;
	regs.pc = 0x45678000ULL;
	regs.sp = 0x56789000ULL;
	regs.pstate = PSR_N_BIT | PSR_C_BIT;
	expected_regs = regs;
	current->thread.user_fpsr = 0;
	current->thread.user_simd_valid = 0;

	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_MEMEQ(test, current->thread.user_simd, expected_simd,
			   sizeof(expected_simd));
	KUNIT_EXPECT_EQ(test, saturated ? BIT(27) : 0,
			current->thread.user_fpsr);
	KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
	KUNIT_EXPECT_MEMEQ(test, regs.regs, expected_regs.regs,
			   sizeof(regs.regs));
	KUNIT_EXPECT_EQ(test, expected_regs.sp, regs.sp);
	KUNIT_EXPECT_EQ(test, expected_regs.pstate, regs.pstate);
	KUNIT_EXPECT_EQ(test, expected_regs.pc + sizeof(u32), regs.pc);
}

static void orlix_tcti_gadget_executes_simd_scalar_sqdm_long(struct kunit *test)
{
	static const struct {
		u32 pattern;
		bool accumulate;
		bool subtract;
	} cases[] = {
		{ 0x5e209000U, true, false },
		{ 0x5e20b000U, true, true },
		{ 0x5e20d000U, false, false },
	};
	static const s64 values[] = { 0, 1, -1, S16_MIN, S16_MAX };
	static const struct {
		u8 rd;
		u8 rn;
		u8 rm;
	} registers[] = {
		{ 0, 1, 2 }, { 3, 3, 4 }, { 5, 6, 5 },
		{ 7, 8, 8 }, { 31, 31, 31 },
	};
	size_t case_index;
	u8 size;
	size_t left_index;
	size_t right_index;
	size_t register_index;

	for (case_index = 0; case_index < ARRAY_SIZE(cases); case_index++) {
		for (size = 1; size <= 2; size++) {
			for (left_index = 0; left_index < ARRAY_SIZE(values);
			     left_index++) {
				for (right_index = 0;
				     right_index < ARRAY_SIZE(values);
				     right_index++) {
					for (register_index = 0;
					     register_index < ARRAY_SIZE(registers);
					     register_index++) {
						const u8 rd = registers[register_index].rd;
						const u8 rn = registers[register_index].rn;
						const u8 rm = registers[register_index].rm;

						orlix_tcti_test_execute_scalar_sqdm_long(
							test, cases[case_index].pattern,
							cases[case_index].accumulate,
							cases[case_index].subtract, size,
							values[left_index],
							values[right_index], rd, rn, rm);
					}
				}
			}
		}
	}
}

static void orlix_tcti_gadget_executes_simd_vector_sqdm_long(struct kunit *test)
{
	static const struct {
		u32 pattern;
		bool accumulate;
		bool subtract;
	} cases[] = {
		{ 0x0e209000U, true, false },
		{ 0x0e20b000U, true, true },
		{ 0x0e20d000U, false, false },
	};
	static const struct {
		u8 rd;
		u8 rn;
		u8 rm;
	} registers[] = {
		{ 0, 1, 2 }, { 3, 3, 4 }, { 5, 6, 5 },
		{ 7, 8, 8 }, { 31, 31, 31 },
	};
	struct pt_regs regs = {};
	struct pt_regs expected_regs;
	size_t case_index;
	u8 q;
	u8 size;
	size_t register_index;
	u8 scenario;

	for (case_index = 0; case_index < ARRAY_SIZE(cases); case_index++) {
		for (q = 0; q < 2; q++) {
			for (size = 1; size <= 2; size++) {
				for (register_index = 0;
				     register_index < ARRAY_SIZE(registers);
				     register_index++) {
					for (scenario = 0; scenario < 3; scenario++) {
						u8 rd = registers[register_index].rd;
						u8 rn = registers[register_index].rn;
						u8 rm = registers[register_index].rm;
						bool accumulate =
							cases[case_index].accumulate;
						bool subtract =
							cases[case_index].subtract;
						u8 source_size = BIT(size);
						u8 source_bits = source_size * 8;
						u8 result_size = source_size * 2;
						u8 lane_count = 2 * sizeof(u64) /
								result_size;
						u64 source_mask =
							GENMASK_ULL(source_bits - 1, 0);
						u64 result_mask = GENMASK_ULL(
							result_size * 8 - 1, 0);
						s64 source_min =
							-(1LL << (source_bits - 1));
						s64 left_value = scenario == 0 ? 3 :
							 scenario == 1 ? source_min : -2;
						s64 right_value = scenario == 0 ? -5 :
							  scenario == 1 ? source_min : 7;
						s64 accumulator_value =
							scenario == 2 ? -100 : 100;
						u64 left_word =
							orlix_tcti_test_replicate_simd_immediate(
								left_value, source_size);
						u64 right_word =
							orlix_tcti_test_replicate_simd_immediate(
								right_value, source_size);
						u64 accumulator_word =
							orlix_tcti_test_replicate_simd_immediate(
								accumulator_value, result_size);
						u64 before_simd[
							ARRAY_SIZE(current->thread.user_simd)];
						u64 expected_simd[
							ARRAY_SIZE(current->thread.user_simd)];
						u64 left;
						u64 right;
						u64 accumulator[2];
						bool saturated = false;
						u32 instruction = cases[case_index].pattern |
							((u32)q << 30) |
							((u32)size << 22) |
							((u32)rm << 16) |
							((u32)rn << 5) | rd;
						struct orlix_tcti_decoded_instruction decoded =
							orlix_tcti_decode_aarch64(instruction);
						u8 lane;
						unsigned int word;
						int ret;

						for (word = 0;
						     word < ARRAY_SIZE(
							current->thread.user_simd);
						     word++)
							current->thread.user_simd[word] =
								0x1020304050607080ULL ^
								((u64)instruction << 7) ^ word;
						current->thread.user_simd[rd * 2] =
							accumulator_word;
						current->thread.user_simd[rd * 2 + 1] =
							accumulator_word;
						current->thread.user_simd[rn * 2 + q] =
							left_word;
						current->thread.user_simd[rm * 2 + q] =
							right_word;
						memcpy(before_simd,
						       current->thread.user_simd,
						       sizeof(before_simd));
						memcpy(expected_simd, before_simd,
						       sizeof(expected_simd));
						left = before_simd[rn * 2 + q];
						right = before_simd[rm * 2 + q];
						accumulator[0] = before_simd[rd * 2];
						accumulator[1] = before_simd[rd * 2 + 1];
						expected_simd[rd * 2] = 0;
						expected_simd[rd * 2 + 1] = 0;
						for (lane = 0; lane < lane_count; lane++) {
							u8 source_shift =
								lane * source_bits;
							u8 result_byte =
								lane * result_size;
							u8 result_word =
								result_byte / sizeof(u64);
							u8 result_shift =
								(result_byte % sizeof(u64)) * 8;
							u64 left_lane =
								(left >> source_shift) &
								source_mask;
							u64 right_lane =
								(right >> source_shift) &
								source_mask;
							u64 accumulator_lane =
								(accumulator[result_word] >>
								 result_shift) & result_mask;
							u64 result =
								orlix_tcti_test_scalar_sqdm_long_result(
									left_lane, right_lane,
									accumulator_lane,
									source_bits,
									accumulate, subtract,
									&saturated);

							expected_simd[rd * 2 + result_word] |=
								result << result_shift;
						}

						for (word = 0;
						     word < ARRAY_SIZE(regs.regs);
						     word++)
							regs.regs[word] =
								0x8877665544332211ULL ^ word;
						regs.pc = 0x45679000ULL;
						regs.sp = 0x56789000ULL;
						regs.pstate = PSR_N_BIT | PSR_C_BIT;
						expected_regs = regs;
						current->thread.user_fpsr = 0x20U;
						current->thread.user_simd_valid = 0;

						ret = orlix_tcti_switch_debug_execute_decoded(
							NULL, &regs, &decoded, NULL);

						KUNIT_ASSERT_EQ(test, 0, ret);
						KUNIT_EXPECT_MEMEQ(
							test, current->thread.user_simd,
							expected_simd,
							sizeof(expected_simd));
						KUNIT_EXPECT_EQ(
							test,
							0x20U |
								(saturated ? BIT(27) : 0U),
							current->thread.user_fpsr);
						KUNIT_EXPECT_EQ(
							test, 1,
							current->thread.user_simd_valid);
						KUNIT_EXPECT_MEMEQ(
							test, regs.regs,
							expected_regs.regs,
							sizeof(regs.regs));
						KUNIT_EXPECT_EQ(test, expected_regs.sp,
								regs.sp);
						KUNIT_EXPECT_EQ(test,
								expected_regs.pstate,
								regs.pstate);
						KUNIT_EXPECT_EQ(
							test,
							expected_regs.pc + sizeof(u32),
							regs.pc);
					}
				}
			}
		}
	}
}

static u64 orlix_tcti_test_mixed_saturating_add_result(u64 destination, u64 source,
						 u8 bits,
						 bool unsigned_destination,
						 bool *saturated)
{
	u64 mask = GENMASK_ULL(bits - 1, 0);
	__int128 result;
	__int128 minimum;
	__int128 maximum;

	if (unsigned_destination) {
		result = (__int128)(destination & mask) +
			 sign_extend64(source & mask, bits - 1);
		minimum = 0;
		maximum = mask;
	} else {
		result = (__int128)sign_extend64(destination & mask, bits - 1) +
			 (source & mask);
		minimum = -((__int128)1 << (bits - 1));
		maximum = ((__int128)1 << (bits - 1)) - 1;
	}
	if (result < minimum) {
		result = minimum;
		*saturated = true;
	} else if (result > maximum) {
		result = maximum;
		*saturated = true;
	}
	return (u64)result & mask;
}

static void orlix_tcti_test_execute_scalar_mixed_saturating_add(
	struct kunit *test, bool unsigned_destination, u8 size, u64 destination,
	u64 source, u8 rd, u8 rn)
{
	u8 bits = (1U << size) * 8;
	u32 instruction = 0x0e203800U |
			  (unsigned_destination ? BIT(29) : 0) |
			  BIT(28) | BIT(30) | ((u32)size << 22) |
			  ((u32)rn << 5) | rd;
	struct orlix_tcti_decoded_instruction decoded =
		orlix_tcti_decode_aarch64(instruction);
	struct pt_regs regs = {};
	u64 expected_simd[ARRAY_SIZE(current->thread.user_simd)];
	u64 result;
	bool saturated = false;
	unsigned int word;
	int ret;

	for (word = 0; word < ARRAY_SIZE(current->thread.user_simd); word++)
		current->thread.user_simd[word] = 0xa5a5000000000000ULL ^
						 ((u64)instruction << 9) ^ word;
	current->thread.user_simd[rd * 2] = destination;
	current->thread.user_simd[rn * 2] = source;
	destination = current->thread.user_simd[rd * 2];
	source = current->thread.user_simd[rn * 2];
	memcpy(expected_simd, current->thread.user_simd, sizeof(expected_simd));
	result = orlix_tcti_test_mixed_saturating_add_result(
		destination, source, bits, unsigned_destination, &saturated);
	expected_simd[rd * 2] = result;
	expected_simd[rd * 2 + 1] = 0;
	for (word = 0; word < ARRAY_SIZE(regs.regs); word++)
		regs.regs[word] = 0x1234567800000000ULL ^ word;
	regs.pc = 0x56789000ULL;
	regs.sp = 0x6789a000ULL;
	regs.pstate = PSR_Z_BIT | PSR_V_BIT;
	current->thread.user_fpsr = 0;
	current->thread.user_simd_valid = 0;

	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_MEMEQ(test, current->thread.user_simd, expected_simd,
			   sizeof(expected_simd));
	KUNIT_EXPECT_EQ(test, saturated ? BIT(27) : 0,
			current->thread.user_fpsr);
	KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
	KUNIT_EXPECT_EQ(test, 0x56789004ULL, regs.pc);
	KUNIT_EXPECT_EQ(test, 0x6789a000ULL, regs.sp);
	KUNIT_EXPECT_EQ(test, PSR_Z_BIT | PSR_V_BIT, regs.pstate);
	for (word = 0; word < ARRAY_SIZE(regs.regs); word++)
		KUNIT_EXPECT_EQ(test, 0x1234567800000000ULL ^ word,
				regs.regs[word]);
}

static void orlix_tcti_gadget_executes_simd_scalar_mixed_saturating_add(
	struct kunit *test)
{
	u8 unsigned_destination;
	u8 size;
	u8 scenario;
	u8 alias;

	for (unsigned_destination = 0; unsigned_destination < 2;
	     unsigned_destination++) {
		for (size = 0; size < 4; size++) {
			u8 bits = (1U << size) * 8;
			u64 mask = GENMASK_ULL(bits - 1, 0);
			u64 signed_maximum = mask >> 1;
			u64 signed_minimum = BIT_ULL(bits - 1);
			u64 destinations[] = {
				0, signed_maximum, signed_minimum, mask, 1,
			};
			u64 sources[] = { 0, 1, 1, mask, mask };

			for (scenario = 0; scenario < ARRAY_SIZE(destinations);
			     scenario++) {
				for (alias = 0; alias < 2; alias++)
					orlix_tcti_test_execute_scalar_mixed_saturating_add(
						test, unsigned_destination, size,
						destinations[scenario], sources[scenario],
						alias ? 3 : 0, alias ? 3 : 1);
			}
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_scalar_shift_immediate_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		bool left_shift;
		bool insert;
		bool signed_shift;
		bool rounding;
		bool accumulate;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0f005400U, false, true, false, false, false, false,
		  ORLIX_TCTI_SIMD_ARITH_SHL },
		{ 0x0f005400U, true, true, true, false, false, false,
		  ORLIX_TCTI_SIMD_ARITH_SLI },
		{ 0x0f004400U, true, false, true, false, false, false,
		  ORLIX_TCTI_SIMD_ARITH_SRI },
		{ 0x0f000400U, false, false, false, true, false, false,
		  ORLIX_TCTI_SIMD_ARITH_SSHR },
		{ 0x0f000400U, true, false, false, false, false, false,
		  ORLIX_TCTI_SIMD_ARITH_USHR },
		{ 0x0f001400U, false, false, false, true, false, true,
		  ORLIX_TCTI_SIMD_ARITH_SSRA },
		{ 0x0f001400U, true, false, false, false, false, true,
		  ORLIX_TCTI_SIMD_ARITH_USRA },
		{ 0x0f002400U, false, false, false, true, true, false,
		  ORLIX_TCTI_SIMD_ARITH_SRSHR },
		{ 0x0f002400U, true, false, false, false, true, false,
		  ORLIX_TCTI_SIMD_ARITH_URSHR },
		{ 0x0f003400U, false, false, false, true, true, true,
		  ORLIX_TCTI_SIMD_ARITH_SRSRA },
		{ 0x0f003400U, true, false, false, false, true, true,
		  ORLIX_TCTI_SIMD_ARITH_URSRA },
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;

	regs.pc = 0x8880;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		u8 minimum = cases[index].left_shift ? 0 : 1;
		u8 maximum = cases[index].left_shift ? 63 : 64;
		u8 shift_amount;

		for (shift_amount = minimum; shift_amount <= maximum;
		     shift_amount++) {
			u64 source = 0xa5a5a5a5a5a5a5a5ULL;
			u64 destination = 0x5a5a5a5a5a5a5a5aULL;
			u64 expected;
			u8 immediate = cases[index].left_shift ?
				64 + shift_amount : 128 - shift_amount;
			u32 instruction = cases[index].pattern |
				(cases[index].u ? BIT(29) : 0) |
				BIT(30) | BIT(28) | ((u32)immediate << 16) |
				(1U << 5);
			struct orlix_tcti_decoded_instruction decoded;
			int ret;

			if (cases[index].left_shift) {
				u64 preserved = shift_amount == 0 ? 0 :
					GENMASK_ULL(shift_amount - 1, 0);

				expected = source << shift_amount;
				if (cases[index].insert)
					expected |= destination & preserved;
			} else if (cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SRI) {
				u64 preserved = shift_amount == 64 ? ~0ULL :
					~GENMASK_ULL(64 - shift_amount - 1, 0);
				u64 shifted = shift_amount == 64 ? 0 :
					source >> shift_amount;

				expected = (destination & preserved) | shifted;
			} else if (cases[index].signed_shift) {
				s64 signed_source = (s64)source;
				s64 signed_result = shift_amount == 64 ? -1 :
					signed_source >> shift_amount;

				if (cases[index].rounding)
					signed_result +=
						(source >> (shift_amount - 1)) & 1U;
				expected = (u64)signed_result;
			} else {
				expected = shift_amount == 64 ? 0 :
					source >> shift_amount;
				if (cases[index].rounding)
					expected +=
						(source >> (shift_amount - 1)) & 1U;
			}
			if (cases[index].accumulate)
				expected += destination;

			current->thread.user_simd[0] = destination;
			current->thread.user_simd[1] = ~0ULL;
			current->thread.user_simd[2] = source;
			current->thread.user_simd[3] = ~0ULL;
			current->thread.user_simd_valid = 0;
			decoded = orlix_tcti_decode_aarch64(instruction);
			ret = orlix_tcti_switch_debug_execute_decoded(
				NULL, &regs, &decoded, NULL);

			execution_count++;
			KUNIT_ASSERT_EQ(test, 0, ret);
			KUNIT_EXPECT_EQ(test, expected,
					current->thread.user_simd[0]);
			KUNIT_EXPECT_EQ(test, 0ULL,
					current->thread.user_simd[1]);
			KUNIT_EXPECT_EQ(test, 1,
					current->thread.user_simd_valid);
			KUNIT_EXPECT_EQ(test,
					0x8880ULL + execution_count * sizeof(u32),
					regs.pc);
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_shift_left_insert_immediate_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		bool right_insert;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0f005400U, false, false, ORLIX_TCTI_SIMD_ARITH_SHL },
		{ 0x0f005400U, true, false, ORLIX_TCTI_SIMD_ARITH_SLI },
		{ 0x0f004400U, true, true, ORLIX_TCTI_SIMD_ARITH_SRI },
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;
	u8 q;
	u8 size;

	regs.pc = 0x8840;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 4; size++) {
				u8 access_size = BIT(size);
				u8 lane_bits = access_size * 8;
				u8 minimum = cases[index].right_insert ? 1 : 0;
				u8 maximum = cases[index].right_insert ?
					lane_bits : lane_bits - 1;
				u8 shift_amount;

				if (!q && size == 3)
					continue;
				for (shift_amount = minimum; shift_amount <= maximum;
				     shift_amount++) {
					u8 result_size = q ? 16 : 8;
					u8 lane_count = result_size / access_size;
					u64 mask = GENMASK_ULL(lane_bits - 1, 0);
					u64 source[2] = {};
					u64 destination[2] = {};
					u64 expected[2] = {};
					u8 lane;
					u32 instruction;
					struct orlix_tcti_decoded_instruction decoded;
					int ret;

					for (lane = 0; lane < lane_count; lane++) {
						u8 byte = lane * access_size;
						u8 word = byte / 8;
						u8 shift = (byte % 8) * 8;
						u64 value = (0xa5a5a5a5a5a5a5a5ULL + lane) & mask;
						u64 original =
							(0x5a5a5a5a5a5a5a5aULL ^ lane) & mask;
						u64 lane_result;

						source[word] |= value << shift;
						destination[word] |= original << shift;
						if (cases[index].right_insert) {
							u64 preserved = shift_amount == lane_bits ?
								mask : mask & ~GENMASK_ULL(
									lane_bits - shift_amount - 1, 0);
							u64 shifted = shift_amount == lane_bits ? 0 :
								value >> shift_amount;

							lane_result = (original & preserved) | shifted;
						} else {
							u64 preserved = shift_amount == 0 ? 0 :
								GENMASK_ULL(shift_amount - 1, 0);

							lane_result = value << shift_amount;
							if (cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SLI)
								lane_result |= original & preserved;
						}
						expected[word] |= (lane_result & mask) << shift;
					}

					instruction = cases[index].pattern |
						(cases[index].u ? BIT(29) : 0) |
						(q ? BIT(30) : 0) |
						((u32)(cases[index].right_insert ?
							2 * lane_bits - shift_amount :
							lane_bits + shift_amount) << 16) |
						(1U << 5);
					current->thread.user_simd[0] = destination[0];
					current->thread.user_simd[1] = destination[1];
					current->thread.user_simd[2] = source[0];
					current->thread.user_simd[3] = source[1];
					current->thread.user_simd_valid = 0;
					decoded = orlix_tcti_decode_aarch64(instruction);
					ret = orlix_tcti_switch_debug_execute_decoded(
						NULL, &regs, &decoded, NULL);

					execution_count++;
					KUNIT_ASSERT_EQ(test, 0, ret);
					KUNIT_EXPECT_EQ(test, expected[0],
							current->thread.user_simd[0]);
					KUNIT_EXPECT_EQ(test, expected[1],
							current->thread.user_simd[1]);
					KUNIT_EXPECT_EQ(test, 1,
							current->thread.user_simd_valid);
					KUNIT_EXPECT_EQ(test,
							0x8840ULL + execution_count * sizeof(u32),
							regs.pc);
				}
			}
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_shift_right_immediate_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0f000400U, false, ORLIX_TCTI_SIMD_ARITH_SSHR },
		{ 0x0f000400U, true, ORLIX_TCTI_SIMD_ARITH_USHR },
		{ 0x0f001400U, false, ORLIX_TCTI_SIMD_ARITH_SSRA },
		{ 0x0f001400U, true, ORLIX_TCTI_SIMD_ARITH_USRA },
		{ 0x0f002400U, false, ORLIX_TCTI_SIMD_ARITH_SRSHR },
		{ 0x0f002400U, true, ORLIX_TCTI_SIMD_ARITH_URSHR },
		{ 0x0f003400U, false, ORLIX_TCTI_SIMD_ARITH_SRSRA },
		{ 0x0f003400U, true, ORLIX_TCTI_SIMD_ARITH_URSRA },
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;
	u8 q;
	u8 size;

	regs.pc = 0x8820;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 4; size++) {
				u8 access_size = BIT(size);
				u8 lane_bits = access_size * 8;
				u8 shift_amount;

				if (!q && size == 3)
					continue;
				for (shift_amount = 1; shift_amount <= lane_bits;
				     shift_amount++) {
					u8 result_size = q ? 16 : 8;
					u8 lane_count = result_size / access_size;
					u64 mask = GENMASK_ULL(lane_bits - 1, 0);
					u64 source[2] = {};
					u64 accumulator[2] = {};
					u64 expected[2] = {};
					bool signed_shift = !cases[index].u;
					bool rounding = cases[index].operation ==
						ORLIX_TCTI_SIMD_ARITH_SRSHR ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_URSHR ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SRSRA ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_URSRA;
					bool accumulate = cases[index].operation ==
						ORLIX_TCTI_SIMD_ARITH_SSRA ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_USRA ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SRSRA ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_URSRA;
					u8 lane;
					u32 instruction;
					struct orlix_tcti_decoded_instruction decoded;
					int ret;

					for (lane = 0; lane < lane_count; lane++) {
						u8 byte = lane * access_size;
						u8 word = byte / 8;
						u8 shift = (byte % 8) * 8;
						u64 value = lane % 2 == 0 ? mask :
							(5ULL << (shift_amount == lane_bits ?
								0 : shift_amount)) & mask;
						u64 shifted;

						source[word] |= value << shift;
						accumulator[word] |= 10ULL << shift;
						if (signed_shift) {
							s64 signed_value = sign_extend64(value,
								lane_bits - 1);
							s64 signed_result = shift_amount == lane_bits ?
								(signed_value < 0 ? -1 : 0) :
								signed_value >> shift_amount;

							if (rounding)
								signed_result +=
									(value >> (shift_amount - 1)) & 1U;
							shifted = (u64)signed_result & mask;
						} else {
							shifted = shift_amount == lane_bits ? 0 :
								value >> shift_amount;
							if (rounding)
								shifted +=
									(value >> (shift_amount - 1)) & 1U;
						}
						if (accumulate)
							shifted += 10;
						expected[word] |= (shifted & mask) << shift;
					}

					instruction = cases[index].pattern |
						(cases[index].u ? BIT(29) : 0) |
						(q ? BIT(30) : 0) |
						((u32)(2 * lane_bits - shift_amount) << 16) |
						(1U << 5);
					current->thread.user_simd[0] = accumulator[0];
					current->thread.user_simd[1] = accumulator[1];
					current->thread.user_simd[2] = source[0];
					current->thread.user_simd[3] = source[1];
					current->thread.user_simd_valid = 0;
					decoded = orlix_tcti_decode_aarch64(instruction);
					ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
									 &decoded, NULL);
					execution_count++;

					KUNIT_ASSERT_EQ(test, 0, ret);
					KUNIT_EXPECT_EQ(test, expected[0],
							current->thread.user_simd[0]);
					KUNIT_EXPECT_EQ(test, expected[1],
							current->thread.user_simd[1]);
					KUNIT_EXPECT_EQ(test, 1,
							current->thread.user_simd_valid);
				}
			}
		}
	}

	KUNIT_EXPECT_EQ(test, 0x8820ULL + execution_count * sizeof(u32), regs.pc);
}

static void
orlix_tcti_switch_executes_complete_simd_shift_narrow_family(struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0f008400U, false, ORLIX_TCTI_SIMD_ARITH_SHRN },
		{ 0x0f008c00U, false, ORLIX_TCTI_SIMD_ARITH_RSHRN },
		{ 0x0f009400U, false, ORLIX_TCTI_SIMD_ARITH_SQSHRN },
		{ 0x0f009400U, true, ORLIX_TCTI_SIMD_ARITH_UQSHRN },
		{ 0x0f009c00U, false, ORLIX_TCTI_SIMD_ARITH_SQRSHRN },
		{ 0x0f009c00U, true, ORLIX_TCTI_SIMD_ARITH_UQRSHRN },
		{ 0x0f008400U, true, ORLIX_TCTI_SIMD_ARITH_SQSHRUN },
		{ 0x0f008c00U, true, ORLIX_TCTI_SIMD_ARITH_SQRSHRUN },
	};
	const u64 preserved_low = 0xfedcba9876543210ULL;
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;
	u8 q;
	u8 size;

	regs.pc = 0x8840;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 3; size++) {
				u8 source_size = 2U << size;
				u8 narrow_size = source_size / 2;
				u8 source_bits = source_size * 8;
				u8 narrow_bits = narrow_size * 8;
				u8 shifts[] = { 1, narrow_bits };
				u8 shift_index;

				for (shift_index = 0; shift_index < ARRAY_SIZE(shifts);
				     shift_index++) {
					u8 shift = shifts[shift_index];
					u8 lane_count = 16 / source_size;
					u64 source_mask = GENMASK_ULL(source_bits - 1, 0);
					u64 result_mask = GENMASK_ULL(narrow_bits - 1, 0);
					u64 source[2] = {};
					u64 expected = 0;
					bool signed_source =
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQSHRN ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQRSHRN ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQSHRUN ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQRSHRUN;
					bool unsigned_result =
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_UQSHRN ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_UQRSHRN ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQSHRUN ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQRSHRUN;
					bool rounding =
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_RSHRN ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQRSHRN ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_UQRSHRN ||
						cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQRSHRUN;
					bool saturating =
						cases[index].operation != ORLIX_TCTI_SIMD_ARITH_SHRN &&
						cases[index].operation != ORLIX_TCTI_SIMD_ARITH_RSHRN;
					bool expected_qc = false;
					u8 lane;
					u32 instruction;
					struct orlix_tcti_decoded_instruction decoded;
					int ret;

					for (lane = 0; lane < lane_count; lane++) {
						u8 value_class = lane % 3;
						u64 value = value_class == 0 && signed_source ?
							source_mask :
							value_class == 1 ?
							((result_mask + 1) << shift) & source_mask :
							(5ULL << shift) |
							BIT_ULL(shift - 1);
						u64 result;
						u8 source_byte = lane * source_size;
						u8 source_word = source_byte / 8;
						u8 source_shift = (source_byte % 8) * 8;

						if (signed_source) {
							s64 shifted = sign_extend64(value,
								source_bits - 1) >> shift;

							if (rounding)
								shifted += (value >> (shift - 1)) & 1U;
							if (unsigned_result && shifted < 0) {
								result = 0;
								expected_qc = true;
							} else if (unsigned_result &&
								   (u64)shifted > result_mask) {
								result = result_mask;
								expected_qc = true;
							} else if (!unsigned_result && saturating &&
								   shifted < -(s64)BIT_ULL(narrow_bits - 1)) {
								result = BIT_ULL(narrow_bits - 1);
								expected_qc = true;
							} else if (!unsigned_result && saturating &&
								   shifted >
								   (s64)BIT_ULL(narrow_bits - 1) - 1) {
								result = BIT_ULL(narrow_bits - 1) - 1;
								expected_qc = true;
							} else {
								result = (u64)shifted & result_mask;
							}
						} else {
							u64 shifted = value >> shift;

							if (rounding)
								shifted += (value >> (shift - 1)) & 1U;
							if (saturating && shifted > result_mask) {
								result = result_mask;
								expected_qc = true;
							} else {
								result = shifted & result_mask;
							}
						}

						source[source_word] |= value << source_shift;
						expected |= result << (lane * narrow_bits);
					}

					instruction = cases[index].pattern |
						(cases[index].u ? BIT(29) : 0) |
						(q ? BIT(30) : 0) |
						((u32)(source_bits - shift) << 16) |
						(1U << 5);
					current->thread.user_simd[0] = preserved_low;
					current->thread.user_simd[1] = ~preserved_low;
					current->thread.user_simd[2] = source[0];
					current->thread.user_simd[3] = source[1];
					current->thread.user_simd_valid = 0;
					current->thread.user_fpsr = 0;
					decoded = orlix_tcti_decode_aarch64(instruction);
					ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
									 &decoded, NULL);
					execution_count++;

					KUNIT_ASSERT_EQ(test, 0, ret);
					KUNIT_EXPECT_EQ(test, q ? preserved_low : expected,
							current->thread.user_simd[0]);
					KUNIT_EXPECT_EQ(test, q ? expected : 0,
							current->thread.user_simd[1]);
					KUNIT_EXPECT_EQ(test, expected_qc,
							!!(current->thread.user_fpsr & BIT(27)));
				}
			}
		}
	}

	KUNIT_EXPECT_EQ(test, 0x8840ULL + execution_count * sizeof(u32), regs.pc);
}

static void
orlix_tcti_switch_executes_complete_simd_scalar_shift_narrow_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x5f009400U, ORLIX_TCTI_SIMD_ARITH_SQSHRN },
		{ 0x7f009400U, ORLIX_TCTI_SIMD_ARITH_UQSHRN },
		{ 0x5f009c00U, ORLIX_TCTI_SIMD_ARITH_SQRSHRN },
		{ 0x7f009c00U, ORLIX_TCTI_SIMD_ARITH_UQRSHRN },
		{ 0x7f008400U, ORLIX_TCTI_SIMD_ARITH_SQSHRUN },
		{ 0x7f008c00U, ORLIX_TCTI_SIMD_ARITH_SQRSHRUN },
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;

	regs.pc = 0x89a0;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		u8 size;

		for (size = 0; size < 3; size++) {
			u8 source_bits = 16U << size;
			u8 narrow_bits = source_bits / 2;
			u64 source_mask = GENMASK_ULL(source_bits - 1, 0);
			u64 result_mask = GENMASK_ULL(narrow_bits - 1, 0);
			u64 value;
			u64 expected;
			bool saturated;
			u32 instruction = cases[index].pattern |
					  ((u32)(source_bits - 1) << 16) |
					  (1U << 5);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);
			int ret;

			switch (cases[index].operation) {
			case ORLIX_TCTI_SIMD_ARITH_SQSHRN:
				value = BIT_ULL(source_bits - 1) - 1;
				expected = BIT_ULL(narrow_bits - 1) - 1;
				saturated = true;
				break;
			case ORLIX_TCTI_SIMD_ARITH_UQSHRN:
				value = source_mask;
				expected = result_mask;
				saturated = true;
				break;
			case ORLIX_TCTI_SIMD_ARITH_SQSHRUN:
				value = source_mask;
				expected = 0;
				saturated = true;
				break;
			default:
				value = 3;
				expected = 2;
				saturated = false;
				break;
			}

			current->thread.user_simd[0] = U64_MAX;
			current->thread.user_simd[1] = U64_MAX;
			current->thread.user_simd[2] = value;
			current->thread.user_simd[3] = U64_MAX;
			current->thread.user_fpsr = 0x20;
			current->thread.user_simd_valid = 0;

			ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
							 &decoded, NULL);
			execution_count++;
			KUNIT_ASSERT_EQ(test, 0, ret);
			KUNIT_EXPECT_EQ(test, expected,
					current->thread.user_simd[0]);
			KUNIT_EXPECT_EQ(test, 0ULL,
					current->thread.user_simd[1]);
			KUNIT_EXPECT_EQ(test,
					0x20U | (saturated ? BIT(27) : 0),
					current->thread.user_fpsr);
			KUNIT_EXPECT_EQ(test, 1,
					current->thread.user_simd_valid);
			KUNIT_EXPECT_EQ(test,
					0x89a0ULL + execution_count * sizeof(u32),
					regs.pc);
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_scalar_saturating_narrow_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0e214800U, false, ORLIX_TCTI_SIMD_ARITH_SQXTN },
		{ 0x0e214800U, true, ORLIX_TCTI_SIMD_ARITH_UQXTN },
		{ 0x0e212800U, true, ORLIX_TCTI_SIMD_ARITH_SQXTUN },
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;

	regs.pc = 0x89c0;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		u8 size;

		for (size = 0; size < 3; size++) {
			u8 narrow_bits = 8U << size;
			u8 source_bits = narrow_bits * 2;
			u64 source_mask = GENMASK_ULL(source_bits - 1, 0);
			u64 result_mask = GENMASK_ULL(narrow_bits - 1, 0);
			u64 value;
			u64 expected;
			u32 instruction = cases[index].pattern | BIT(28) | BIT(30) |
				(cases[index].u ? BIT(29) : 0) |
				((u32)size << 22) | (1U << 5);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);
			int ret;

			current->thread.user_simd[0] = U64_MAX;
			current->thread.user_simd[1] = U64_MAX;
			current->thread.user_simd[2] = 42;
			current->thread.user_simd[3] = U64_MAX;
			current->thread.user_fpsr = 0x20;
			current->thread.user_simd_valid = 0;
			ret = orlix_tcti_switch_debug_execute_decoded(
				NULL, &regs, &decoded, NULL);

			execution_count++;
			KUNIT_ASSERT_EQ(test, 0, ret);
			KUNIT_EXPECT_EQ(test, 42ULL,
					current->thread.user_simd[0]);
			KUNIT_EXPECT_EQ(test, 0ULL,
					current->thread.user_simd[1]);
			KUNIT_EXPECT_EQ(test, 0x20U, current->thread.user_fpsr);

			if (cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQXTN) {
				value = BIT_ULL(narrow_bits - 1);
				expected = value - 1;
			} else if (cases[index].operation == ORLIX_TCTI_SIMD_ARITH_UQXTN) {
				value = result_mask + 1;
				expected = result_mask;
			} else {
				value = source_mask;
				expected = 0;
			}
			current->thread.user_simd[0] = U64_MAX;
			current->thread.user_simd[1] = U64_MAX;
			current->thread.user_simd[2] = value;
			current->thread.user_simd[3] = U64_MAX;
			current->thread.user_fpsr = 0x20;
			current->thread.user_simd_valid = 0;
			ret = orlix_tcti_switch_debug_execute_decoded(
				NULL, &regs, &decoded, NULL);

			execution_count++;
			KUNIT_ASSERT_EQ(test, 0, ret);
			KUNIT_EXPECT_EQ(test, expected,
					current->thread.user_simd[0]);
			KUNIT_EXPECT_EQ(test, 0ULL,
					current->thread.user_simd[1]);
			KUNIT_EXPECT_EQ(test, 0x20U | BIT(27),
					current->thread.user_fpsr);
			KUNIT_EXPECT_EQ(test, 1,
					current->thread.user_simd_valid);
			KUNIT_EXPECT_EQ(test,
					0x89c0ULL + execution_count * sizeof(u32),
					regs.pc);
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_saturating_narrow_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0e214800U, ORLIX_TCTI_SIMD_ARITH_SQXTN },
		{ 0x2e214800U, ORLIX_TCTI_SIMD_ARITH_UQXTN },
		{ 0x2e212800U, ORLIX_TCTI_SIMD_ARITH_SQXTUN },
	};
	const u64 preserved_low = 0x0123456789abcdefULL;
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;
	u8 q;
	u8 size;

	regs.pc = 0x8870;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 3; size++) {
				u8 wide_size = 2U << size;
				u8 narrow_size = wide_size / 2;
				u8 lane_count = 16 / wide_size;
				u8 narrow_bits = narrow_size * 8;
				u8 wide_bits = wide_size * 8;
				u64 source_mask = GENMASK_ULL(wide_bits - 1, 0);
				u64 result_mask = GENMASK_ULL(narrow_bits - 1, 0);
				u64 signed_minimum = BIT_ULL(narrow_bits - 1);
				u64 signed_maximum = signed_minimum - 1;
				u64 source[2] = {};
				u64 expected = 0;
				u8 lane;
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;
				int ret;

				for (lane = 0; lane < lane_count; lane++) {
					u8 value_class = lane % 3;
					u64 value;
					u64 result;
					u8 source_byte = lane * wide_size;
					u8 source_word = source_byte / 8;
					u8 source_shift = (source_byte % 8) * 8;

					if (cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQXTN) {
						value = value_class == 0 ?
							(source_mask + 1 - signed_minimum - 1) &
								source_mask :
							value_class == 1 ? signed_maximum + 1 : 42;
						result = value_class == 0 ? signed_minimum :
							value_class == 1 ? signed_maximum : 42;
					} else if (cases[index].operation ==
						   ORLIX_TCTI_SIMD_ARITH_UQXTN) {
						value = value_class == 1 ? result_mask + 1 :
							value_class == 2 ? 42 : 0;
						result = value_class == 1 ? result_mask : value;
					} else {
						value = value_class == 0 ? source_mask :
							value_class == 1 ? result_mask + 1 : 42;
						result = value_class == 0 ? 0 :
							value_class == 1 ? result_mask : 42;
					}

					source[source_word] |=
						(value & source_mask) << source_shift;
					expected |= (result & result_mask) <<
						(lane * narrow_bits);
				}

				instruction = cases[index].pattern |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | (1U << 5);
				current->thread.user_simd[0] = preserved_low;
				current->thread.user_simd[1] = ~preserved_low;
				current->thread.user_simd[2] = source[0];
				current->thread.user_simd[3] = source[1];
				current->thread.user_simd_valid = 0;
				current->thread.user_fpsr = 0;
				decoded = orlix_tcti_decode_aarch64(instruction);
				ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
								 &decoded, NULL);
				execution_count++;

				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, q ? preserved_low : expected,
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, q ? expected : 0,
						current->thread.user_simd[1]);
				KUNIT_EXPECT_TRUE(test,
						current->thread.user_fpsr & BIT(27));
			}
		}
	}

	{
		const u64 source_low = 0x0004000300020001ULL;
		const u64 source_high = 0x0008000700060005ULL;
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(0x4e214800U);
		int ret;

		current->thread.user_simd[0] = source_low;
		current->thread.user_simd[1] = source_high;
		current->thread.user_simd_valid = 0;
		current->thread.user_fpsr = 0;
		ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);
		execution_count++;

		KUNIT_ASSERT_EQ(test, 0, ret);
		KUNIT_EXPECT_EQ(test, source_low, current->thread.user_simd[0]);
		KUNIT_EXPECT_EQ(test, 0x0807060504030201ULL,
				current->thread.user_simd[1]);
		KUNIT_EXPECT_FALSE(test, current->thread.user_fpsr & BIT(27));
	}

	KUNIT_EXPECT_EQ(test, 0x8870ULL + execution_count * sizeof(u32), regs.pc);
}

static void
orlix_tcti_switch_executes_complete_simd_add_sub_narrow_high_family(
	struct kunit *test)
{
	const u64 preserved_low = 0x8877665544332211ULL;
	struct pt_regs regs = {};
	u32 execution_count = 0;
	u8 operation;
	u8 q;
	u8 size;

	regs.pc = 0x8890;
	for (operation = 0; operation < 4; operation++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 3; size++) {
				u8 wide_size = 2U << size;
				u8 narrow_size = wide_size / 2;
				u8 lane_count = 16 / wide_size;
				u8 narrow_bits = narrow_size * 8;
				u64 wide_mask = GENMASK_ULL(wide_size * 8 - 1, 0);
				u64 half = BIT_ULL(narrow_bits - 1);
				u64 left_value =
					(((operation & 1U) ? 7ULL : 3ULL) << narrow_bits) |
					half;
				u64 right_value = 2ULL << narrow_bits;
				u64 expected_value = operation & 2U ? 6 : 5;
				u64 left[2] = {};
				u64 right[2] = {};
				u64 narrowed = 0;
				u8 lane;
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;
				int ret;

				for (lane = 0; lane < lane_count; lane++) {
					u8 source_byte = lane * wide_size;
					u8 source_word = source_byte / 8;
					u8 source_shift = (source_byte % 8) * 8;

					left[source_word] |=
						(left_value & wide_mask) << source_shift;
					right[source_word] |=
						(right_value & wide_mask) << source_shift;
					narrowed |= expected_value <<
						(lane * narrow_size * 8);
				}

				instruction = 0x0e204000U |
					(operation & 1U ? BIT(13) : 0) |
					(operation & 2U ? BIT(29) : 0) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) |
					(2U << 16) | (1U << 5);
				current->thread.user_simd[0] = preserved_low;
				current->thread.user_simd[1] = ~preserved_low;
				current->thread.user_simd[2] = left[0];
				current->thread.user_simd[3] = left[1];
				current->thread.user_simd[4] = right[0];
				current->thread.user_simd[5] = right[1];
				current->thread.user_simd_valid = 0;
				decoded = orlix_tcti_decode_aarch64(instruction);
				ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
								 &decoded, NULL);
				execution_count++;

				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, q ? preserved_low : narrowed,
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, q ? narrowed : 0,
						current->thread.user_simd[1]);
				KUNIT_EXPECT_EQ(test, 1,
						current->thread.user_simd_valid);
			}
		}
	}

	KUNIT_EXPECT_EQ(test, 0x8890ULL + execution_count * sizeof(u32), regs.pc);
}

static void
orlix_tcti_switch_executes_complete_simd_absolute_difference_long_family(
	struct kunit *test)
{
	struct pt_regs regs = {};
	u32 execution_count = 0;
	u8 operation;
	u8 q;
	u8 size;

	regs.pc = 0x88a0;
	for (operation = 0; operation < 4; operation++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 3; size++) {
				u8 access_size = BIT(size);
				u8 wide_size = access_size * 2;
				u8 source_lane_count = 16 / access_size;
				u8 result_lane_count = 16 / wide_size;
				u64 narrow_mask =
					GENMASK_ULL(access_size * 8 - 1, 0);
				u64 wide_mask = GENMASK_ULL(wide_size * 8 - 1, 0);
				u64 accumulator[2] = {};
				u64 left[2] = {};
				u64 right[2] = {};
				u64 expected[2] = {};
				u64 expected_value = operation == 0 ? 5 :
					operation == 1 ? narrow_mask - 4 :
					operation == 2 ? 15 : narrow_mask + 6;
				u8 lane;
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;
				int ret;

				for (lane = 0; lane < source_lane_count; lane++) {
					u8 byte = lane * access_size;
					u8 word = byte / 8;
					u8 shift = (byte % 8) * 8;
					bool selected = q ? lane >= result_lane_count :
						lane < result_lane_count;

					left[word] |=
						(selected ? narrow_mask - 2 : 1) << shift;
					right[word] |=
						(selected ? 2 : narrow_mask) << shift;
				}
				for (lane = 0; lane < result_lane_count; lane++) {
					u8 byte = lane * wide_size;
					u8 word = byte / 8;
					u8 shift = (byte % 8) * 8;

					accumulator[word] |= 10ULL << shift;
					expected[word] |=
						(expected_value & wide_mask) << shift;
				}

				instruction =
					(operation & 2U ? 0x0e205000U : 0x0e207000U) |
					(operation & 1U ? BIT(29) : 0) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) |
					(2U << 16) | (1U << 5);
				current->thread.user_simd[0] = accumulator[0];
				current->thread.user_simd[1] = accumulator[1];
				current->thread.user_simd[2] = left[0];
				current->thread.user_simd[3] = left[1];
				current->thread.user_simd[4] = right[0];
				current->thread.user_simd[5] = right[1];
				current->thread.user_simd_valid = 0;
				decoded = orlix_tcti_decode_aarch64(instruction);
				ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
								 &decoded, NULL);
				execution_count++;

				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, expected[0],
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, expected[1],
						current->thread.user_simd[1]);
				KUNIT_EXPECT_EQ(test, 1,
						current->thread.user_simd_valid);
			}
		}
	}

	KUNIT_EXPECT_EQ(test, 0x88a0ULL + execution_count * sizeof(u32), regs.pc);
}

static void
orlix_tcti_switch_executes_complete_simd_absolute_difference_family(struct kunit *test)
{
	struct pt_regs regs = {};
	u8 operation;
	u8 q;
	u8 size;
	u8 execution_count = 0;

	regs.pc = 0x88c0;
	for (operation = 0; operation < 4; operation++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 3; size++) {
				u8 access_size = BIT(size);
				u8 result_size = q ? 16 : 8;
				u8 lane_count = result_size / access_size;
				u64 mask = GENMASK_ULL(access_size * 8 - 1, 0);
				u64 accumulator[2] = {};
				u64 left[2] = {};
				u64 right[2] = {};
				u64 expected[2] = {};
				u64 expected_value = operation == 0 ? 5 :
					operation == 1 ? mask - 4 :
					operation == 2 ? 15 : 5;
				u8 lane;
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;
				int ret;

				for (lane = 0; lane < lane_count; lane++) {
					u8 byte = lane * access_size;
					u8 word = byte / sizeof(u64);
					u8 shift = (byte % sizeof(u64)) * 8;

					accumulator[word] |= 10ULL << shift;
					left[word] |= (mask - 2) << shift;
					right[word] |= 2ULL << shift;
					expected[word] |= expected_value << shift;
				}

				instruction = 0x0e207400U |
					((operation & 1U) ? BIT(29) : 0) |
					((operation & 2U) ? BIT(11) : 0) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | (2U << 16) |
					(1U << 5);
				current->thread.user_simd[0] = accumulator[0];
				current->thread.user_simd[1] = accumulator[1];
				current->thread.user_simd[2] = left[0];
				current->thread.user_simd[3] = left[1];
				current->thread.user_simd[4] = right[0];
				current->thread.user_simd[5] = right[1];
				current->thread.user_simd_valid = 0;
				decoded = orlix_tcti_decode_aarch64(instruction);
				ret = orlix_tcti_switch_debug_execute_decoded(
					NULL, &regs, &decoded, NULL);

				execution_count++;
				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, expected[0],
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, expected[1],
						current->thread.user_simd[1]);
				KUNIT_EXPECT_EQ(test, 1,
						current->thread.user_simd_valid);
				KUNIT_EXPECT_EQ(test,
					0x88c0ULL + execution_count * sizeof(u32),
					regs.pc);
			}
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_scalar_integer_unary_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		u8 minimum_size;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0e20b800U, false, 3, ORLIX_TCTI_SIMD_ARITH_ABS },
		{ 0x0e20b800U, true, 3, ORLIX_TCTI_SIMD_ARITH_NEG },
		{ 0x0e207800U, false, 0, ORLIX_TCTI_SIMD_ARITH_SQABS },
		{ 0x0e207800U, true, 0, ORLIX_TCTI_SIMD_ARITH_SQNEG },
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	u8 index;

	regs.pc = 0x88c0;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		u8 size;

		for (size = cases[index].minimum_size; size < 4; size++) {
			u8 bits = 8U << size;
			u64 mask = GENMASK_ULL(bits - 1, 0);
			u64 minimum = BIT_ULL(bits - 1);
			u64 boundaries[] = {
				0, 1, mask, minimum, minimum + 1, minimum - 1,
			};
			u16 value_index;
			u16 value_count = size ? ARRAY_SIZE(boundaries) : 256;

			for (value_index = 0; value_index < value_count; value_index++) {
				u64 value = size ? boundaries[value_index] :
					value_index;
				u64 expected;
				bool saturated = false;
				u32 instruction = cases[index].pattern | BIT(28) |
					BIT(30) | (cases[index].u ? BIT(29) : 0) |
					((u32)size << 22) | (1U << 5);
				struct orlix_tcti_decoded_instruction decoded =
					orlix_tcti_decode_aarch64(instruction);
				int ret;

				switch (cases[index].operation) {
				case ORLIX_TCTI_SIMD_ARITH_ABS:
					expected = value & minimum ? -value & mask : value;
					break;
				case ORLIX_TCTI_SIMD_ARITH_NEG:
					expected = -value & mask;
					break;
				case ORLIX_TCTI_SIMD_ARITH_SQABS:
					if (value == minimum) {
						expected = minimum - 1;
						saturated = true;
					} else {
						expected = value & minimum ?
							-value & mask : value;
					}
					break;
				case ORLIX_TCTI_SIMD_ARITH_SQNEG:
					if (value == minimum) {
						expected = minimum - 1;
						saturated = true;
					} else {
						expected = -value & mask;
					}
					break;
				default:
					KUNIT_FAIL(test, "unexpected scalar unary operation");
					return;
				}

				current->thread.user_simd[0] = U64_MAX;
				current->thread.user_simd[1] = U64_MAX;
				current->thread.user_simd[2] = value;
				current->thread.user_simd[3] = U64_MAX;
				current->thread.user_fpsr = 0x20;
				current->thread.user_simd_valid = 0;
				ret = orlix_tcti_switch_debug_execute_decoded(
					NULL, &regs, &decoded, NULL);

				execution_count++;
				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, expected,
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, 0ULL,
						current->thread.user_simd[1]);
				KUNIT_EXPECT_EQ(test,
						0x20U | (saturated ? BIT(27) : 0U),
						current->thread.user_fpsr);
				KUNIT_EXPECT_EQ(test, 1,
						current->thread.user_simd_valid);
				KUNIT_EXPECT_EQ(test,
						0x88c0ULL + execution_count * sizeof(u32),
						regs.pc);
			}
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_integer_unary_family(struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		u8 maximum_size;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} cases[] = {
		{ 0x0e20b800U, false, 3, ORLIX_TCTI_SIMD_ARITH_ABS },
		{ 0x0e20b800U, true, 3, ORLIX_TCTI_SIMD_ARITH_NEG },
		{ 0x0e207800U, false, 3, ORLIX_TCTI_SIMD_ARITH_SQABS },
		{ 0x0e207800U, true, 3, ORLIX_TCTI_SIMD_ARITH_SQNEG },
		{ 0x0e204800U, false, 2, ORLIX_TCTI_SIMD_ARITH_CLS },
		{ 0x0e204800U, true, 2, ORLIX_TCTI_SIMD_ARITH_CLZ },
		{ 0x0e200800U, false, 2, ORLIX_TCTI_SIMD_ARITH_REV64 },
		{ 0x0e200800U, true, 1, ORLIX_TCTI_SIMD_ARITH_REV32 },
	};
	struct {
		u32 instruction;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
	} byte_cases[] = {
		{ 0x0e201820U, ORLIX_TCTI_SIMD_ARITH_REV16 },
		{ 0x0e205820U, ORLIX_TCTI_SIMD_ARITH_CNT },
		{ 0x2e205820U, ORLIX_TCTI_SIMD_ARITH_NOT },
		{ 0x2e605820U, ORLIX_TCTI_SIMD_ARITH_RBIT },
	};
	const u64 base_source[2] = {
		0x80ff017f10204008ULL,
		0x0102040810204080ULL,
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;
	u8 q;
	u8 size;

	regs.pc = 0x8980;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size <= cases[index].maximum_size; size++) {
				u8 access_size = BIT(size);
				u8 result_size = q ? 16 : 8;
				u8 bits = access_size * 8;
				u8 lane_count = result_size / access_size;
				u64 mask = GENMASK_ULL(bits - 1, 0);
				u64 source[2] = { base_source[0], base_source[1] };
				u64 expected[2] = {};
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;
				int ret;
				u8 lane;

				if (!q && size == 3)
					continue;
				source[0] = (source[0] & ~mask) | BIT_ULL(bits - 1);
				instruction = cases[index].pattern |
					(cases[index].u ? BIT(29) : 0) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | (1U << 5);

				if (cases[index].operation == ORLIX_TCTI_SIMD_ARITH_REV64 ||
				    cases[index].operation == ORLIX_TCTI_SIMD_ARITH_REV32) {
					u8 group_size = cases[index].operation ==
						ORLIX_TCTI_SIMD_ARITH_REV64 ? 8 : 4;
					u8 byte;

					for (byte = 0; byte < result_size; byte++) {
						u8 value = source[byte / 8] >>
							((byte % 8) * 8);
						u8 group_offset = byte & (group_size - 1);
						u8 element_offset = group_offset % access_size;
						u8 destination =
							(byte & ~(group_size - 1)) + group_size -
							access_size -
							(group_offset / access_size) * access_size +
							element_offset;

						expected[destination / 8] |=
							(u64)value << ((destination % 8) * 8);
					}
				} else {
					for (lane = 0; lane < lane_count; lane++) {
						u8 byte = lane * access_size;
						u8 word = byte / 8;
						u8 shift = (byte % 8) * 8;
						u64 value = (source[word] >> shift) & mask;
						u64 lane_result = 0;

						switch (cases[index].operation) {
						case ORLIX_TCTI_SIMD_ARITH_ABS:
							lane_result = value & BIT_ULL(bits - 1) ?
								(-value & mask) : value;
							break;
						case ORLIX_TCTI_SIMD_ARITH_NEG:
							lane_result = -value & mask;
							break;
						case ORLIX_TCTI_SIMD_ARITH_SQABS:
							lane_result = value == BIT_ULL(bits - 1) ?
								BIT_ULL(bits - 1) - 1 :
								value & BIT_ULL(bits - 1) ?
								(-value & mask) : value;
							break;
						case ORLIX_TCTI_SIMD_ARITH_SQNEG:
							lane_result = value == BIT_ULL(bits - 1) ?
								BIT_ULL(bits - 1) - 1 :
								(-value & mask);
							break;
						case ORLIX_TCTI_SIMD_ARITH_CLS: {
							bool sign = value & BIT_ULL(bits - 1);
							int bit;

							for (bit = bits - 2; bit >= 0; bit--) {
								if (!!(value & BIT_ULL(bit)) != sign)
									break;
								lane_result++;
							}
							break;
						}
						default: {
							int bit;

							for (bit = bits - 1; bit >= 0; bit--) {
								if (value & BIT_ULL(bit))
									break;
								lane_result++;
							}
							break;
						}
						}
						expected[word] |= (lane_result & mask) << shift;
					}
				}

				current->thread.user_simd[2] = source[0];
				current->thread.user_simd[3] = source[1];
				current->thread.user_simd_valid = 0;
				current->thread.user_fpsr = 0;
				decoded = orlix_tcti_decode_aarch64(instruction);
				ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
								 &decoded, NULL);
				execution_count++;

				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, expected[0],
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, expected[1],
						current->thread.user_simd[1]);
				if (cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQABS ||
				    cases[index].operation == ORLIX_TCTI_SIMD_ARITH_SQNEG)
					KUNIT_EXPECT_TRUE(test,
						current->thread.user_fpsr & BIT(27));
			}
		}
	}

	for (index = 0; index < ARRAY_SIZE(byte_cases); index++) {
		for (q = 0; q < 2; q++) {
			u8 result_size = q ? 16 : 8;
			u64 expected[2] = {};
			struct orlix_tcti_decoded_instruction decoded;
			int ret;
			u8 byte;

			for (byte = 0; byte < result_size; byte++) {
				u8 value = base_source[byte / 8] >> ((byte % 8) * 8);
				u8 destination = byte;

				if (byte_cases[index].operation == ORLIX_TCTI_SIMD_ARITH_REV16)
					destination ^= 1U;
				else if (byte_cases[index].operation == ORLIX_TCTI_SIMD_ARITH_CNT)
					value = hweight8(value);
				else if (byte_cases[index].operation == ORLIX_TCTI_SIMD_ARITH_NOT)
					value = ~value;
				else {
					u8 reversed = 0;
					u8 bit;

					for (bit = 0; bit < 8; bit++)
						reversed |= ((value >> bit) & 1U) <<
							(7U - bit);
					value = reversed;
				}
				expected[destination / 8] |=
					(u64)value << ((destination % 8) * 8);
			}

			current->thread.user_simd[2] = base_source[0];
			current->thread.user_simd[3] = base_source[1];
			current->thread.user_simd_valid = 0;
			decoded = orlix_tcti_decode_aarch64(byte_cases[index].instruction |
							 (q ? BIT(30) : 0));
			ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded,
							 NULL);
			execution_count++;

			KUNIT_ASSERT_EQ(test, 0, ret);
			KUNIT_EXPECT_EQ(test, expected[0],
					current->thread.user_simd[0]);
			KUNIT_EXPECT_EQ(test, expected[1],
					current->thread.user_simd[1]);
		}
	}

	KUNIT_EXPECT_EQ(test, 0x8980ULL + execution_count * sizeof(u32), regs.pc);
}

static void
orlix_tcti_switch_executes_complete_simd_scalar_compare_zero_family(
	struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		enum orlix_tcti_simd_vector_compare_op operation;
	} cases[] = {
		{ 0x0e208800U, false, ORLIX_TCTI_SIMD_COMPARE_CMGT },
		{ 0x0e208800U, true, ORLIX_TCTI_SIMD_COMPARE_CMGE },
		{ 0x0e209800U, false, ORLIX_TCTI_SIMD_COMPARE_CMEQ },
		{ 0x0e209800U, true, ORLIX_TCTI_SIMD_COMPARE_CMLE },
		{ 0x0e20a800U, false, ORLIX_TCTI_SIMD_COMPARE_CMLT },
	};
	const u64 values[] = {
		0, 1, U64_MAX, BIT_ULL(63), BIT_ULL(63) + 1, S64_MAX,
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;

	regs.pc = 0x8b00;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		size_t value_index;

		for (value_index = 0; value_index < ARRAY_SIZE(values);
		     value_index++) {
			s64 value = (s64)values[value_index];
			bool matches;
			u32 instruction = cases[index].pattern | BIT(28) | BIT(30) |
				(cases[index].u ? BIT(29) : 0) | (3U << 22) |
				(1U << 5);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);
			int ret;

			switch (cases[index].operation) {
			case ORLIX_TCTI_SIMD_COMPARE_CMGT:
				matches = value > 0;
				break;
			case ORLIX_TCTI_SIMD_COMPARE_CMGE:
				matches = value >= 0;
				break;
			case ORLIX_TCTI_SIMD_COMPARE_CMEQ:
				matches = value == 0;
				break;
			case ORLIX_TCTI_SIMD_COMPARE_CMLE:
				matches = value <= 0;
				break;
			case ORLIX_TCTI_SIMD_COMPARE_CMLT:
				matches = value < 0;
				break;
			default:
				KUNIT_FAIL(test, "unexpected scalar compare operation");
				return;
			}

			current->thread.user_simd[0] = 0x1111111111111111ULL;
			current->thread.user_simd[1] = 0x2222222222222222ULL;
			current->thread.user_simd[2] = values[value_index];
			current->thread.user_simd[3] = U64_MAX;
			current->thread.user_simd_valid = 0;
			ret = orlix_tcti_switch_debug_execute_decoded(
				NULL, &regs, &decoded, NULL);

			execution_count++;
			KUNIT_ASSERT_EQ(test, 0, ret);
			KUNIT_EXPECT_EQ(test, matches ? U64_MAX : 0ULL,
					current->thread.user_simd[0]);
			KUNIT_EXPECT_EQ(test, 0ULL,
					current->thread.user_simd[1]);
			KUNIT_EXPECT_EQ(test, 1,
					current->thread.user_simd_valid);
			KUNIT_EXPECT_EQ(test,
					0x8b00ULL + execution_count * sizeof(u32),
					regs.pc);
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_compare_zero_family(struct kunit *test)
{
	struct {
		u32 pattern;
		bool u;
		enum orlix_tcti_simd_vector_compare_op operation;
	} cases[] = {
		{ 0x0e208800U, false, ORLIX_TCTI_SIMD_COMPARE_CMGT },
		{ 0x0e208800U, true, ORLIX_TCTI_SIMD_COMPARE_CMGE },
		{ 0x0e209800U, false, ORLIX_TCTI_SIMD_COMPARE_CMEQ },
		{ 0x0e209800U, true, ORLIX_TCTI_SIMD_COMPARE_CMLE },
		{ 0x0e20a800U, false, ORLIX_TCTI_SIMD_COMPARE_CMLT },
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;
	u8 q;
	u8 size;

	regs.pc = 0x8a80;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 4; size++) {
				u8 access_size = BIT(size);
				u8 result_size = q ? 16 : 8;
				u8 lane_count = result_size / access_size;
				u8 bits = access_size * 8;
				u64 mask = GENMASK_ULL(bits - 1, 0);
				u64 source[2] = {};
				u64 expected[2] = {};
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;
				int ret;
				u8 lane;

				if (!q && size == 3)
					continue;
				for (lane = 0; lane < lane_count; lane++) {
					u8 byte = lane * access_size;
					u8 word = byte / 8;
					u8 shift = (byte % 8) * 8;
					u8 value_class = lane % 3;
					u64 value = value_class == 0 ? BIT_ULL(bits - 1) :
						value_class == 1 ? 0 : 1;
					bool matches;

					source[word] |= value << shift;
					switch (cases[index].operation) {
					case ORLIX_TCTI_SIMD_COMPARE_CMGT:
						matches = value_class == 2;
						break;
					case ORLIX_TCTI_SIMD_COMPARE_CMGE:
						matches = value_class != 0;
						break;
					case ORLIX_TCTI_SIMD_COMPARE_CMEQ:
						matches = value_class == 1;
						break;
					case ORLIX_TCTI_SIMD_COMPARE_CMLE:
						matches = value_class != 2;
						break;
					default:
						matches = value_class == 0;
						break;
					}
					expected[word] |= (matches ? mask : 0) << shift;
				}

				instruction = cases[index].pattern |
					(cases[index].u ? BIT(29) : 0) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | (1U << 5);
				current->thread.user_simd[2] = source[0];
				current->thread.user_simd[3] = source[1];
				current->thread.user_simd_valid = 0;
				decoded = orlix_tcti_decode_aarch64(instruction);
				ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
								 &decoded, NULL);
				execution_count++;

				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, expected[0],
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, expected[1],
						current->thread.user_simd[1]);
			}
		}
	}

	KUNIT_EXPECT_EQ(test, 0x8a80ULL + execution_count * sizeof(u32), regs.pc);
}

static void
orlix_tcti_switch_executes_complete_simd_scalar_register_compare_family(
	struct kunit *test)
{
	struct {
		u8 opcode;
		bool u;
		enum orlix_tcti_simd_vector_compare_op operation;
	} cases[] = {
		{ 6, false, ORLIX_TCTI_SIMD_COMPARE_CMGT },
		{ 6, true, ORLIX_TCTI_SIMD_COMPARE_CMHI },
		{ 7, false, ORLIX_TCTI_SIMD_COMPARE_CMGE },
		{ 7, true, ORLIX_TCTI_SIMD_COMPARE_CMHS },
		{ 17, false, ORLIX_TCTI_SIMD_COMPARE_CMTST },
		{ 17, true, ORLIX_TCTI_SIMD_COMPARE_CMEQ },
	};
	struct {
		u64 left;
		u64 right;
	} values[] = {
		{ 0, 0 },
		{ 1, 1 },
		{ 1, 2 },
		{ U64_MAX, 1 },
		{ BIT_ULL(63), 0 },
		{ S64_MAX, U64_MAX },
	};
	struct pt_regs regs = {};
	u32 execution_count = 0;
	size_t index;

	regs.pc = 0x8c00;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		size_t value_index;

		for (value_index = 0; value_index < ARRAY_SIZE(values);
		     value_index++) {
			u64 left = values[value_index].left;
			u64 right = values[value_index].right;
			bool matches;
			u32 instruction = 0x0e200400U | BIT(28) | BIT(30) |
				(cases[index].u ? BIT(29) : 0) | (3U << 22) |
				((u32)cases[index].opcode << 11) | (2U << 16) |
				(1U << 5);
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);
			int ret;

			switch (cases[index].operation) {
			case ORLIX_TCTI_SIMD_COMPARE_CMTST:
				matches = (left & right) != 0;
				break;
			case ORLIX_TCTI_SIMD_COMPARE_CMEQ:
				matches = left == right;
				break;
			case ORLIX_TCTI_SIMD_COMPARE_CMGT:
				matches = (s64)left > (s64)right;
				break;
			case ORLIX_TCTI_SIMD_COMPARE_CMHI:
				matches = left > right;
				break;
			case ORLIX_TCTI_SIMD_COMPARE_CMGE:
				matches = (s64)left >= (s64)right;
				break;
			case ORLIX_TCTI_SIMD_COMPARE_CMHS:
				matches = left >= right;
				break;
			default:
				KUNIT_FAIL(test, "unexpected scalar register compare");
				return;
			}

			current->thread.user_simd[0] = 0x1111111111111111ULL;
			current->thread.user_simd[1] = 0x2222222222222222ULL;
			current->thread.user_simd[2] = left;
			current->thread.user_simd[3] = U64_MAX;
			current->thread.user_simd[4] = right;
			current->thread.user_simd[5] = U64_MAX;
			current->thread.user_simd_valid = 0;
			ret = orlix_tcti_switch_debug_execute_decoded(
				NULL, &regs, &decoded, NULL);

			execution_count++;
			KUNIT_ASSERT_EQ(test, 0, ret);
			KUNIT_EXPECT_EQ(test, matches ? U64_MAX : 0ULL,
					current->thread.user_simd[0]);
			KUNIT_EXPECT_EQ(test, 0ULL,
					current->thread.user_simd[1]);
			KUNIT_EXPECT_EQ(test, 1,
					current->thread.user_simd_valid);
			KUNIT_EXPECT_EQ(test,
					0x8c00ULL + execution_count * sizeof(u32),
					regs.pc);
		}
	}
}

static void
orlix_tcti_switch_executes_complete_simd_register_compare_family(struct kunit *test)
{
	struct {
		enum orlix_tcti_simd_vector_compare_op operation;
		u8 opcode;
		bool u;
	} cases[] = {
		{ ORLIX_TCTI_SIMD_COMPARE_CMTST, 17, false },
		{ ORLIX_TCTI_SIMD_COMPARE_CMEQ, 17, true },
		{ ORLIX_TCTI_SIMD_COMPARE_CMGT, 6, false },
		{ ORLIX_TCTI_SIMD_COMPARE_CMHI, 6, true },
		{ ORLIX_TCTI_SIMD_COMPARE_CMGE, 7, false },
		{ ORLIX_TCTI_SIMD_COMPARE_CMHS, 7, true },
	};
	struct pt_regs regs = {};
	size_t index;
	u8 q;
	u8 size;
	u8 execution_count = 0;

	regs.pc = 0x8920;
	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (q = 0; q < 2; q++) {
			for (size = 0; size < 4; size++) {
				u8 access_size = BIT(size);
				u8 result_size = q ? 16 : 8;
				u8 lane_count;
				u64 mask;
				u64 left[2] = {};
				u64 right[2] = {};
				u64 expected[2] = {};
				u64 left_value;
				u64 right_value = 2;
				bool matches = cases[index].operation !=
					ORLIX_TCTI_SIMD_COMPARE_CMGT;
				u8 lane;
				u32 instruction;
				struct orlix_tcti_decoded_instruction decoded;
				int ret;

				if (!q && size == 3)
					continue;

				lane_count = result_size / access_size;
				mask = GENMASK_ULL(access_size * 8 - 1, 0);
				if (cases[index].operation == ORLIX_TCTI_SIMD_COMPARE_CMTST)
					left_value = 3;
				else if (cases[index].operation == ORLIX_TCTI_SIMD_COMPARE_CMGT ||
					 cases[index].operation == ORLIX_TCTI_SIMD_COMPARE_CMHI)
					left_value = mask - 2;
				else
					left_value = 2;
				for (lane = 0; lane < lane_count; lane++) {
					u8 byte = lane * access_size;
					u8 word = byte / sizeof(u64);
					u8 shift = (byte % sizeof(u64)) * 8;

					left[word] |= left_value << shift;
					right[word] |= right_value << shift;
					expected[word] |=
						(matches ? mask : 0) << shift;
				}

				instruction = 0x0e200400U |
					((u32)cases[index].opcode << 11) |
					(cases[index].u ? BIT(29) : 0) |
					(q ? BIT(30) : 0) |
					((u32)size << 22) | (2U << 16) |
					(1U << 5);
				current->thread.user_simd[2] = left[0];
				current->thread.user_simd[3] = left[1];
				current->thread.user_simd[4] = right[0];
				current->thread.user_simd[5] = right[1];
				current->thread.user_simd_valid = 0;
				decoded = orlix_tcti_decode_aarch64(instruction);
				ret = orlix_tcti_switch_debug_execute_decoded(
					NULL, &regs, &decoded, NULL);

				execution_count++;
				KUNIT_ASSERT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, expected[0],
						current->thread.user_simd[0]);
				KUNIT_EXPECT_EQ(test, expected[1],
						current->thread.user_simd[1]);
				KUNIT_EXPECT_EQ(test, 1,
						current->thread.user_simd_valid);
				KUNIT_EXPECT_EQ(test,
					0x8920ULL + execution_count * sizeof(u32),
					regs.pc);
			}
		}
	}
}

