static void orlix_tcti_gadget_executes_complete_simd_fp_scalar_unary_family(
	struct kunit *test)
{
	static const struct {
		u32 instruction;
		enum orlix_tcti_simd_vector_arithmetic_op operation;
		u64 source;
		u64 expected;
	} cases[] = {
		{ 0x5ea1d800U, ORLIX_TCTI_SIMD_ARITH_FRECPE,
		  0x40000000U, 0x3eff8000U },
		{ 0x5ee1d800U, ORLIX_TCTI_SIMD_ARITH_FRECPE,
		  0x4000000000000000ULL, 0x3fdff00000000000ULL },
		{ 0x5ea1f800U, ORLIX_TCTI_SIMD_ARITH_FRECPX,
		  0x40000000U, 0x3f800000U },
		{ 0x5ee1f800U, ORLIX_TCTI_SIMD_ARITH_FRECPX,
		  0x4000000000000000ULL, 0x3ff0000000000000ULL },
		{ 0x7ea1d800U, ORLIX_TCTI_SIMD_ARITH_FRSQRTE,
		  0x40800000U, 0x3eff8000U },
		{ 0x7ee1d800U, ORLIX_TCTI_SIMD_ARITH_FRSQRTE,
		  0x4010000000000000ULL, 0x3fdff00000000000ULL },
		{ 0x7e616800U, ORLIX_TCTI_SIMD_ARITH_FCVTXN,
		  0x3ff8000000000000ULL, 0x3fc00000U },
	};
	unsigned int case_index;
	u8 rd;
	u8 rn;

	for (case_index = 0; case_index < ARRAY_SIZE(cases); case_index++) {
		for (rd = 0; rd < 32; rd++) {
			for (rn = 0; rn < 32; rn++)
				orlix_tcti_test_execute_simd_fp_scalar_unary_case(
					test, cases[case_index].instruction,
					cases[case_index].operation,
					cases[case_index].source,
					cases[case_index].expected, 0, BIT(27),
					rd, rn);
		}
	}
}

static void orlix_tcti_gadget_executes_simd_fp_scalar_unary_special_cases(
	struct kunit *test)
{
	u8 rounding_mode;

	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x5ea1d800U, ORLIX_TCTI_SIMD_ARITH_FRECPE, 0,
		0x7f800000U, 0, BIT(27) | BIT(1), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x5ea1d800U, ORLIX_TCTI_SIMD_ARITH_FRECPE, 1,
		0x7f800000U, BIT(24), BIT(27) | BIT(7) | BIT(1), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x5ee1d800U, ORLIX_TCTI_SIMD_ARITH_FRECPE,
		0x7ff0000000000001ULL, 0x7ff8000000000001ULL, 0,
		BIT(27) | BIT(0), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x5ea1d800U, ORLIX_TCTI_SIMD_ARITH_FRECPE, 0x7f800001U,
		0x7fc00000U, BIT(25), BIT(27) | BIT(0), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x5ea1f800U, ORLIX_TCTI_SIMD_ARITH_FRECPX, 0,
		0x7f000000U, 0, BIT(27), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x5ee1f800U, ORLIX_TCTI_SIMD_ARITH_FRECPX, 1,
		0x7fe0000000000000ULL, BIT(24), BIT(27) | BIT(7), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x5ee1f800U, ORLIX_TCTI_SIMD_ARITH_FRECPX,
		0x7ff0000000000001ULL, 0x7ff8000000000001ULL, 0,
		BIT(27) | BIT(0), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x5ea1f800U, ORLIX_TCTI_SIMD_ARITH_FRECPX, 0x7f800001U,
		0x7fc00000U, BIT(25), BIT(27) | BIT(0), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x7ea1d800U, ORLIX_TCTI_SIMD_ARITH_FRSQRTE, 0,
		0x7f800000U, 0, BIT(27) | BIT(1), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x7ea1d800U, ORLIX_TCTI_SIMD_ARITH_FRSQRTE, 1,
		0x7f800000U, BIT(24), BIT(27) | BIT(7) | BIT(1), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x7ee1d800U, ORLIX_TCTI_SIMD_ARITH_FRSQRTE,
		0xc010000000000000ULL, 0x7ff8000000000000ULL, 0,
		BIT(27) | BIT(0), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x7ea1d800U, ORLIX_TCTI_SIMD_ARITH_FRSQRTE, 0x7f800001U,
		0x7fc00000U, BIT(25), BIT(27) | BIT(0), 0, 1);
	for (rounding_mode = 0; rounding_mode < 4; rounding_mode++)
		orlix_tcti_test_execute_simd_fp_scalar_unary_case(
			test, 0x7e616800U, ORLIX_TCTI_SIMD_ARITH_FCVTXN,
			0x3ff0000010000000ULL, 0x3f800001U,
			(unsigned long)rounding_mode << 22,
			BIT(27) | BIT(4), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x7e616800U, ORLIX_TCTI_SIMD_ARITH_FCVTXN,
		0x7ff0000000000001ULL, 0x7fc00000U, 0,
		BIT(27) | BIT(0), 0, 1);
	orlix_tcti_test_execute_simd_fp_scalar_unary_case(
		test, 0x7e616800U, ORLIX_TCTI_SIMD_ARITH_FCVTXN,
		0x7ff0000000000001ULL, 0x7fc00000U, BIT(25),
		BIT(27) | BIT(0), 0, 1);
}

static void orlix_tcti_test_execute_simd_fp_pairwise(
	struct kunit *test, u32 pattern,
	enum orlix_tcti_simd_reduction_op operation, u8 access_size, u8 rd, u8 rn,
	u64 first, u64 second, u64 expected, unsigned long fpcr,
	unsigned long expected_fpsr)
{
	u32 instruction = pattern |
		(access_size == sizeof(u64) ? BIT(22) : 0) |
		((u32)rn << 5) | rd;
	struct orlix_tcti_decoded_instruction decoded =
		orlix_tcti_decode_aarch64(instruction);
	struct pt_regs regs = {};
	u64 before_simd[ARRAY_SIZE(current->thread.user_simd)];
	u64 expected_simd[ARRAY_SIZE(current->thread.user_simd)];
	unsigned int word;
	int ret;

	KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_REDUCTION,
			decoded.decode_class);
	KUNIT_ASSERT_EQ(test, operation, decoded.simd_reduction_op);
	for (word = 0; word < ARRAY_SIZE(before_simd); word++)
		before_simd[word] = 0xe6e6000000000000ULL ^
				    ((u64)instruction << 5) ^ word;
	if (access_size == sizeof(u32)) {
		before_simd[rn * 2] = (first & GENMASK_ULL(31, 0)) |
					    (second << 32);
	} else {
		before_simd[rn * 2] = first;
		before_simd[rn * 2 + 1] = second;
	}
	memcpy(current->thread.user_simd, before_simd, sizeof(before_simd));
	memcpy(expected_simd, before_simd, sizeof(expected_simd));
	expected_simd[rd * 2] = expected;
	expected_simd[rd * 2 + 1] = 0;
	for (word = 0; word < ARRAY_SIZE(regs.regs); word++)
		regs.regs[word] = 0xbce0000000000000ULL ^ word;
	regs.pc = 0x81b92000ULL;
	regs.sp = 0x81ca3000ULL;
	regs.pstate = PSR_N_BIT | PSR_C_BIT;
	current->thread.user_fpcr = fpcr;
	current->thread.user_fpsr = BIT(27);
	current->thread.user_simd_valid = 0;

	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_MEMEQ(test, expected_simd, current->thread.user_simd,
			   sizeof(expected_simd));
	KUNIT_EXPECT_EQ(test, fpcr, current->thread.user_fpcr);
	KUNIT_EXPECT_EQ(test, expected_fpsr, current->thread.user_fpsr);
	KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
	KUNIT_EXPECT_EQ(test, 0x81b92004ULL, regs.pc);
	KUNIT_EXPECT_EQ(test, 0x81ca3000ULL, regs.sp);
	KUNIT_EXPECT_EQ(test, PSR_N_BIT | PSR_C_BIT, regs.pstate);
	for (word = 0; word < ARRAY_SIZE(regs.regs); word++)
		KUNIT_EXPECT_EQ(test, 0xbce0000000000000ULL ^ word,
				regs.regs[word]);
}

static void orlix_tcti_gadget_executes_complete_simd_fp_pairwise_family(
	struct kunit *test)
{
	static const struct {
		u32 pattern;
		enum orlix_tcti_simd_reduction_op operation;
		u32 expected_s;
		u64 expected_d;
	} cases[] = {
		{ 0x7e30d800U, ORLIX_TCTI_SIMD_REDUCTION_FADDP,
		  0x40000000U, 0x4000000000000000ULL },
		{ 0x7e30c800U, ORLIX_TCTI_SIMD_REDUCTION_FMAXNMP,
		  0x40400000U, 0x4008000000000000ULL },
		{ 0x7e30f800U, ORLIX_TCTI_SIMD_REDUCTION_FMAXP,
		  0x40400000U, 0x4008000000000000ULL },
		{ 0x7eb0c800U, ORLIX_TCTI_SIMD_REDUCTION_FMINNMP,
		  0xbf800000U, 0xbff0000000000000ULL },
		{ 0x7eb0f800U, ORLIX_TCTI_SIMD_REDUCTION_FMINP,
		  0xbf800000U, 0xbff0000000000000ULL },
	};
	unsigned int case_index;
	u8 alias;

	for (case_index = 0; case_index < ARRAY_SIZE(cases); case_index++) {
		for (alias = 0; alias < 2; alias++) {
			u8 rd = alias ? 31 : 0;
			u8 rn = alias ? 31 : 1;

			orlix_tcti_test_execute_simd_fp_pairwise(
				test, cases[case_index].pattern,
				cases[case_index].operation, sizeof(u32), rd, rn,
				0x40400000U, 0xbf800000U,
				cases[case_index].expected_s, 0, BIT(27));
			orlix_tcti_test_execute_simd_fp_pairwise(
				test, cases[case_index].pattern,
				cases[case_index].operation, sizeof(u64), rd, rn,
				0x4008000000000000ULL, 0xbff0000000000000ULL,
				cases[case_index].expected_d, 0, BIT(27));
		}
	}
}

