enum orlix_tcti_test_simd_copy_kind {
	ORLIX_TCTI_TEST_SIMD_COPY_SCALAR_DUP,
	ORLIX_TCTI_TEST_SIMD_COPY_VECTOR_DUP,
	ORLIX_TCTI_TEST_SIMD_COPY_GPR_DUP,
	ORLIX_TCTI_TEST_SIMD_COPY_INS_GPR,
	ORLIX_TCTI_TEST_SIMD_COPY_INS_ELEMENT,
	ORLIX_TCTI_TEST_SIMD_COPY_UMOV,
	ORLIX_TCTI_TEST_SIMD_COPY_SMOV,
};

static void orlix_tcti_test_simd_copy_case(struct kunit *test, u32 instruction,
				     enum orlix_tcti_test_simd_copy_kind kind,
				     u8 access_size, u8 result_size,
				     u8 source_lane, u8 destination_lane,
				     bool seen_rn[32], bool seen_rd[32],
				     bool *saw_alias)
{
	struct orlix_tcti_decoded_instruction decoded =
		orlix_tcti_decode_aarch64(instruction);
	struct pt_regs regs = {};
	struct pt_regs expected_regs;
	u64 before_simd[ARRAY_SIZE(current->thread.user_simd)];
	u64 expected_simd[ARRAY_SIZE(current->thread.user_simd)];
	u8 rn = (instruction >> 5) & 0x1fU;
	u8 rd = instruction & 0x1fU;
	u64 value;
	unsigned int index;
	bool writes_simd;
	int ret;

	KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_ELEMENT_MOVE,
			decoded.decode_class);
	KUNIT_EXPECT_EQ(test, access_size, decoded.access_size);
	KUNIT_EXPECT_EQ(test, result_size, decoded.result_size);
	KUNIT_EXPECT_EQ(test, rn, decoded.rn);
	KUNIT_EXPECT_EQ(test, rd, decoded.rd);

	seen_rn[rn] = true;
	seen_rd[rd] = true;
	*saw_alias |= rn == rd;

	for (index = 0; index < ARRAY_SIZE(current->thread.user_simd); index++)
		current->thread.user_simd[index] =
			0x1020304050607080ULL ^ ((u64)instruction << 17) ^
			(0x0101010101010101ULL * index);
	for (index = 0; index < ARRAY_SIZE(regs.regs); index++)
		regs.regs[index] = 0x8877665544332200ULL ^
				   ((u64)instruction << 11) ^ index;
	regs.pc = 0x12345678000ULL;
	regs.sp = 0x23456789000ULL;
	regs.pstate = PSR_N_BIT | PSR_C_BIT | 0x155UL;

	memcpy(before_simd, current->thread.user_simd, sizeof(before_simd));
	memcpy(expected_simd, before_simd, sizeof(expected_simd));
	expected_regs = regs;
	writes_simd = kind != ORLIX_TCTI_TEST_SIMD_COPY_UMOV &&
		      kind != ORLIX_TCTI_TEST_SIMD_COPY_SMOV;
	current->thread.user_simd_valid = writes_simd ? 0 : 1;

	switch (kind) {
	case ORLIX_TCTI_TEST_SIMD_COPY_SCALAR_DUP:
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ELEMENT_MOVE_DUP,
				decoded.simd_element_move_op);
		KUNIT_EXPECT_TRUE(test, decoded.simd_scalar);
		KUNIT_EXPECT_EQ(test, source_lane, decoded.simd_source_index);
		value = orlix_tcti_test_simd_lane(before_simd, rn, access_size,
					    source_lane);
		expected_simd[rd * 2] = 0;
		expected_simd[rd * 2 + 1] = 0;
		orlix_tcti_test_set_simd_lane(expected_simd, rd, access_size, 0,
					value);
		break;
	case ORLIX_TCTI_TEST_SIMD_COPY_VECTOR_DUP:
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ELEMENT_MOVE_DUP,
				decoded.simd_element_move_op);
		KUNIT_EXPECT_FALSE(test, decoded.immediate);
		KUNIT_EXPECT_EQ(test, source_lane, decoded.simd_source_index);
		value = orlix_tcti_test_simd_lane(before_simd, rn, access_size,
					    source_lane);
		expected_simd[rd * 2] = 0;
		expected_simd[rd * 2 + 1] = 0;
		for (index = 0; index < result_size / access_size; index++)
			orlix_tcti_test_set_simd_lane(expected_simd, rd, access_size,
						index, value);
		break;
	case ORLIX_TCTI_TEST_SIMD_COPY_GPR_DUP:
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ELEMENT_MOVE_DUP,
				decoded.simd_element_move_op);
		KUNIT_EXPECT_TRUE(test, decoded.immediate);
		value = rn == 31 ? 0 : regs.regs[rn];
		expected_simd[rd * 2] = 0;
		expected_simd[rd * 2 + 1] = 0;
		for (index = 0; index < result_size / access_size; index++)
			orlix_tcti_test_set_simd_lane(expected_simd, rd, access_size,
						index, value);
		break;
	case ORLIX_TCTI_TEST_SIMD_COPY_INS_GPR:
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ELEMENT_MOVE_INS_GPR,
				decoded.simd_element_move_op);
		KUNIT_EXPECT_EQ(test, destination_lane,
				decoded.simd_destination_index);
		value = rn == 31 ? 0 : regs.regs[rn];
		orlix_tcti_test_set_simd_lane(expected_simd, rd, access_size,
					destination_lane, value);
		break;
	case ORLIX_TCTI_TEST_SIMD_COPY_INS_ELEMENT:
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ELEMENT_MOVE_INS_ELEMENT,
				decoded.simd_element_move_op);
		KUNIT_EXPECT_EQ(test, source_lane, decoded.simd_source_index);
		KUNIT_EXPECT_EQ(test, destination_lane,
				decoded.simd_destination_index);
		value = orlix_tcti_test_simd_lane(before_simd, rn, access_size,
					    source_lane);
		orlix_tcti_test_set_simd_lane(expected_simd, rd, access_size,
					destination_lane, value);
		break;
	case ORLIX_TCTI_TEST_SIMD_COPY_UMOV:
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ELEMENT_MOVE_UMOV,
				decoded.simd_element_move_op);
		KUNIT_EXPECT_EQ(test, source_lane, decoded.simd_source_index);
		value = orlix_tcti_test_simd_lane(before_simd, rn, access_size,
					    source_lane);
		if (rd != 31)
			expected_regs.regs[rd] = value;
		break;
	case ORLIX_TCTI_TEST_SIMD_COPY_SMOV:
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_SIMD_ELEMENT_MOVE_SMOV,
				decoded.simd_element_move_op);
		KUNIT_EXPECT_EQ(test, source_lane, decoded.simd_source_index);
		value = orlix_tcti_test_simd_lane(before_simd, rn, access_size,
					    source_lane);
		value = sign_extend64(value, access_size * 8 - 1);
		if (result_size == sizeof(u32))
			value = (u32)value;
		if (rd != 31)
			expected_regs.regs[rd] = value;
		break;
	}

	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_MEMEQ(test, current->thread.user_simd, expected_simd,
			   sizeof(expected_simd));
	KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
	KUNIT_EXPECT_MEMEQ(test, regs.regs, expected_regs.regs,
			   sizeof(regs.regs));
	KUNIT_EXPECT_EQ(test, expected_regs.sp, regs.sp);
	KUNIT_EXPECT_EQ(test, expected_regs.pstate, regs.pstate);
	KUNIT_EXPECT_EQ(test, expected_regs.pc + sizeof(u32), regs.pc);
}

static void orlix_tcti_gadget_executes_complete_simd_copy_family(struct kunit *test)
{
	bool seen_rn[32] = {};
	bool seen_rd[32] = {};
	bool saw_alias = false;
	u8 size;
	u8 q;
	u8 register_case;

	for (size = 0; size < 4; size++) {
		u8 access_size = BIT(size);
		u8 lane_count = 16 / access_size;
		u8 source_lane;

		for (source_lane = 0; source_lane < lane_count; source_lane++) {
			u8 imm5 = BIT(size) | (source_lane << (size + 1));

			for (register_case = 0; register_case < 32;
			     register_case++) {
				u8 rn = register_case;
				u8 rd = (register_case * 13) & 0x1fU;
				u32 instruction = 0x5e000400U |
						  ((u32)imm5 << 16) |
						  ((u32)rn << 5) | rd;

				orlix_tcti_test_simd_copy_case(test, instruction,
							 ORLIX_TCTI_TEST_SIMD_COPY_SCALAR_DUP,
							 access_size, access_size,
							 source_lane, 0, seen_rn,
							 seen_rd, &saw_alias);
			}
		}
	}

	for (q = 0; q < 2; q++) {
		for (size = 0; size < 4; size++) {
			u8 access_size = BIT(size);
			u8 lane_count = 16 / access_size;
			u8 source_lane;

			if (!q && size == 3)
				continue;
			for (source_lane = 0; source_lane < lane_count;
			     source_lane++) {
				u8 imm5 = BIT(size) |
					  (source_lane << (size + 1));

				for (register_case = 0; register_case < 32;
				     register_case++) {
					u8 rn = register_case;
					u8 rd = (register_case * 13) & 0x1fU;
					u32 instruction = 0x0e000400U |
							  (q ? BIT(30) : 0) |
							  ((u32)imm5 << 16) |
							  ((u32)rn << 5) | rd;

					orlix_tcti_test_simd_copy_case(test, instruction,
								 ORLIX_TCTI_TEST_SIMD_COPY_VECTOR_DUP,
								 access_size, q ? 16 : 8,
								 source_lane, 0, seen_rn,
								 seen_rd, &saw_alias);
				}
			}
		}
	}

	for (q = 0; q < 2; q++) {
		for (size = 0; size < 4; size++) {
			u8 access_size = BIT(size);

			if (!q && size == 3)
				continue;
			for (register_case = 0; register_case < 32;
			     register_case++) {
				u8 rn = register_case;
				u8 rd = (register_case * 13) & 0x1fU;
				u32 instruction = 0x0e000c00U |
						  (q ? BIT(30) : 0) |
						  ((u32)BIT(size) << 16) |
						  ((u32)rn << 5) | rd;

				orlix_tcti_test_simd_copy_case(test, instruction,
							 ORLIX_TCTI_TEST_SIMD_COPY_GPR_DUP,
							 access_size, q ? 16 : 8, 0, 0,
							 seen_rn, seen_rd, &saw_alias);
			}
		}
	}

	for (size = 0; size < 4; size++) {
		u8 access_size = BIT(size);
		u8 lane_count = 16 / access_size;
		u8 destination_lane;

		for (destination_lane = 0; destination_lane < lane_count;
		     destination_lane++) {
			u8 imm5 = BIT(size) | (destination_lane << (size + 1));

			for (register_case = 0; register_case < 32;
			     register_case++) {
				u8 rn = register_case;
				u8 rd = (register_case * 13) & 0x1fU;
				u32 instruction = 0x4e001c00U |
						  ((u32)imm5 << 16) |
						  ((u32)rn << 5) | rd;

				orlix_tcti_test_simd_copy_case(test, instruction,
							 ORLIX_TCTI_TEST_SIMD_COPY_INS_GPR,
							 access_size, access_size, 0,
							 destination_lane, seen_rn,
							 seen_rd, &saw_alias);
			}
		}
	}

	for (size = 0; size < 4; size++) {
		u8 access_size = BIT(size);
		u8 lane_count = 16 / access_size;
		u8 destination_lane;

		for (destination_lane = 0; destination_lane < lane_count;
		     destination_lane++) {
			u8 source_lane;
			u8 imm5 = BIT(size) | (destination_lane << (size + 1));

			for (source_lane = 0; source_lane < lane_count;
			     source_lane++) {
				u8 imm4 = source_lane << size;

				for (register_case = 0; register_case < 32;
				     register_case++) {
					u8 rn = register_case;
					u8 rd = (register_case * 13) & 0x1fU;
					u32 instruction = 0x6e000400U |
							  ((u32)imm5 << 16) |
							  ((u32)imm4 << 11) |
							  ((u32)rn << 5) | rd;

					orlix_tcti_test_simd_copy_case(test, instruction,
								 ORLIX_TCTI_TEST_SIMD_COPY_INS_ELEMENT,
								 access_size, 16,
								 source_lane, destination_lane,
								 seen_rn, seen_rd, &saw_alias);
				}
			}
		}
	}

	for (q = 0; q < 2; q++) {
		for (size = 0; size < 4; size++) {
			u8 access_size = BIT(size);
			u8 lane_count = 16 / access_size;
			u8 source_lane;

			if ((!q && size == 3) || (q && size != 3))
				continue;
			for (source_lane = 0; source_lane < lane_count;
			     source_lane++) {
				u8 imm5 = BIT(size) |
					  (source_lane << (size + 1));

				for (register_case = 0; register_case < 32;
				     register_case++) {
					u8 rn = register_case;
					u8 rd = (register_case * 13) & 0x1fU;
					u32 instruction = 0x0e003c00U |
							  (q ? BIT(30) : 0) |
							  ((u32)imm5 << 16) |
							  ((u32)rn << 5) | rd;

					orlix_tcti_test_simd_copy_case(test, instruction,
								 ORLIX_TCTI_TEST_SIMD_COPY_UMOV,
								 access_size, q ? 8 : 4,
								 source_lane, 0, seen_rn,
								 seen_rd, &saw_alias);
				}
			}
		}
	}

	for (q = 0; q < 2; q++) {
		for (size = 0; size < 3; size++) {
			u8 access_size = BIT(size);
			u8 lane_count = 16 / access_size;
			u8 source_lane;

			if (!q && size > 1)
				continue;
			for (source_lane = 0; source_lane < lane_count;
			     source_lane++) {
				u8 imm5 = BIT(size) |
					  (source_lane << (size + 1));

				for (register_case = 0; register_case < 32;
				     register_case++) {
					u8 rn = register_case;
					u8 rd = (register_case * 13) & 0x1fU;
					u32 instruction = 0x0e002c00U |
							  (q ? BIT(30) : 0) |
							  ((u32)imm5 << 16) |
							  ((u32)rn << 5) | rd;

					orlix_tcti_test_simd_copy_case(test, instruction,
								 ORLIX_TCTI_TEST_SIMD_COPY_SMOV,
								 access_size, q ? 8 : 4,
								 source_lane, 0, seen_rn,
								 seen_rd, &saw_alias);
				}
			}
		}
	}

	for (register_case = 0; register_case < 32; register_case++) {
		KUNIT_EXPECT_TRUE(test, seen_rn[register_case]);
		KUNIT_EXPECT_TRUE(test, seen_rd[register_case]);
	}
	KUNIT_EXPECT_TRUE(test, saw_alias);
}

static void orlix_tcti_decode_rejects_reserved_simd_copy_encodings(struct kunit *test)
{
	static const u32 instructions[] = {
		0x5e000400U, /* dup scalar with zero imm5 */
		0x5e100400U, /* dup scalar with unsupported 128-bit element */
		0x0e000400U, /* dup element with zero imm5 */
		0x0e080400U, /* dup 64-bit element into a 64-bit vector */
		0x0e000c00U, /* dup gpr with zero imm5 */
		0x0e030c00U, /* dup gpr with non-power-of-two imm5 */
		0x0e080c00U, /* dup 64-bit gpr into a 64-bit vector */
		0x4e001c00U, /* ins gpr with zero imm5 */
		0x4e101c00U, /* ins gpr with unsupported 128-bit element */
		0x6e000400U, /* ins element with zero imm5 */
		0x6e040c00U, /* ins element with misaligned source lane */
		0x0e083c00U, /* umov 64-bit element to a 32-bit result */
		0x4e043c00U, /* umov 32-bit element to a 64-bit result */
		0x0e042c00U, /* smov 32-bit element to a 32-bit result */
		0x4e082c00U, /* smov with unsupported 64-bit element */
	};
	size_t index;

	for (index = 0; index < ARRAY_SIZE(instructions); index++) {
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(instructions[index]);

		KUNIT_EXPECT_EQ_MSG(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
				    decoded.decode_class,
				    "reserved copy encoding %#x decoded",
				    instructions[index]);
	}
}

static bool
orlix_tcti_test_permute_operation(u8 encoding,
			    enum orlix_tcti_simd_element_move_op *operation)
{
	switch (encoding) {
	case 1:
		*operation = ORLIX_TCTI_SIMD_ELEMENT_MOVE_UZP1;
		return true;
	case 2:
		*operation = ORLIX_TCTI_SIMD_ELEMENT_MOVE_TRN1;
		return true;
	case 3:
		*operation = ORLIX_TCTI_SIMD_ELEMENT_MOVE_ZIP1;
		return true;
	case 5:
		*operation = ORLIX_TCTI_SIMD_ELEMENT_MOVE_UZP2;
		return true;
	case 6:
		*operation = ORLIX_TCTI_SIMD_ELEMENT_MOVE_TRN2;
		return true;
	case 7:
		*operation = ORLIX_TCTI_SIMD_ELEMENT_MOVE_ZIP2;
		return true;
	default:
		return false;
	}
}

static void
orlix_tcti_test_permute_case(struct kunit *test, u8 encoding, u8 q, u8 size,
		       u8 register_case,
	bool seen_rn[32], bool seen_rm[32], bool seen_rd[32],
	bool *saw_source_alias, bool *saw_destination_alias)
{
	u8 rn = register_case;
	u8 rm = (register_case * 7 + encoding + size + q) & 0x1fU;
	u8 rd = (register_case * 13 + encoding * 3 + size + q) & 0x1fU;
	u32 instruction = 0x0e000800U | (q ? BIT(30) : 0) |
		((u32)size << 22) | ((u32)rm << 16) |
		((u32)encoding << 12) | ((u32)rn << 5) | rd;
	struct orlix_tcti_decoded_instruction d = orlix_tcti_decode_aarch64(instruction);
	enum orlix_tcti_simd_element_move_op operation;
	bool valid_operation = orlix_tcti_test_permute_operation(encoding, &operation);
	struct pt_regs regs = {};
	struct pt_regs before_regs;
	u64 before_simd[ARRAY_SIZE(current->thread.user_simd)];
	u64 expected_simd[ARRAY_SIZE(current->thread.user_simd)];
	u8 access_size;
	u8 result_size;
	u8 lane_count;
	u8 half;
	u8 destination_lane;
	unsigned int gpr;
	int ret;

	if (!valid_operation || (!q && size == 3)) {
		KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
				d.decode_class);
		return;
	}

	access_size = BIT(size);
	result_size = q ? 2 * sizeof(u64) : sizeof(u64);
	lane_count = result_size / access_size;
	half = lane_count / 2;
	KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_SIMD_VECTOR_ELEMENT_MOVE,
			d.decode_class);
	KUNIT_EXPECT_EQ(test, operation, d.simd_element_move_op);
	KUNIT_EXPECT_EQ(test, access_size, d.access_size);
	KUNIT_EXPECT_EQ(test, result_size, d.result_size);
	KUNIT_EXPECT_EQ(test, rn, d.rn);
	KUNIT_EXPECT_EQ(test, rm, d.rm);
	KUNIT_EXPECT_EQ(test, rd, d.rd);
	KUNIT_EXPECT_TRUE(test, d.simd_fp);

	seen_rn[rn] = true;
	seen_rm[rm] = true;
	seen_rd[rd] = true;
	*saw_source_alias |= rn == rm;
	*saw_destination_alias |= rd == rn || rd == rm;
	orlix_tcti_test_initialize_simd_registers(instruction);
	memcpy(before_simd, current->thread.user_simd, sizeof(before_simd));
	memcpy(expected_simd, before_simd, sizeof(expected_simd));
	expected_simd[rd * 2] = 0;
	expected_simd[rd * 2 + 1] = 0;
	for (destination_lane = 0; destination_lane < lane_count;
	     destination_lane++) {
		u8 source_reg;
		u8 source_lane;
		u8 destination_byte = destination_lane * access_size;
		u8 destination_word = destination_byte / sizeof(u64);
		u8 destination_shift =
			(destination_byte % sizeof(u64)) * 8;
		u64 value;

		switch (operation) {
		case ORLIX_TCTI_SIMD_ELEMENT_MOVE_UZP1:
		case ORLIX_TCTI_SIMD_ELEMENT_MOVE_UZP2:
			source_reg = destination_lane >= half ? rm : rn;
			source_lane = (destination_lane % half) * 2 +
				(operation == ORLIX_TCTI_SIMD_ELEMENT_MOVE_UZP2);
			break;
		case ORLIX_TCTI_SIMD_ELEMENT_MOVE_TRN1:
		case ORLIX_TCTI_SIMD_ELEMENT_MOVE_TRN2:
			source_reg = destination_lane & 1U ? rm : rn;
			source_lane = (destination_lane / 2) * 2 +
				(operation == ORLIX_TCTI_SIMD_ELEMENT_MOVE_TRN2);
			break;
		case ORLIX_TCTI_SIMD_ELEMENT_MOVE_ZIP1:
		case ORLIX_TCTI_SIMD_ELEMENT_MOVE_ZIP2:
			source_reg = destination_lane & 1U ? rm : rn;
			source_lane = destination_lane / 2 +
				(operation == ORLIX_TCTI_SIMD_ELEMENT_MOVE_ZIP2 ?
				 half : 0);
			break;
		default:
			KUNIT_FAIL(test, "unexpected permute operation %u",
				   operation);
			return;
		}
		value = orlix_tcti_test_simd_lane(before_simd, source_reg,
					    access_size, source_lane);
		expected_simd[rd * 2 + destination_word] |=
			value << destination_shift;
	}

	for (gpr = 0; gpr < ARRAY_SIZE(regs.regs); gpr++)
		regs.regs[gpr] = 0x5678000000000000ULL | gpr;
	regs.pc = 0x10293847000ULL;
	regs.sp = 0x56473829100ULL;
	regs.pstate = PSR_Z_BIT | PSR_V_BIT | 0x155UL;
	before_regs = regs;
	current->thread.user_simd_valid = 0;

	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &d, NULL);

	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_MEMEQ(test, current->thread.user_simd, expected_simd,
			   sizeof(expected_simd));
	KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
	KUNIT_EXPECT_MEMEQ(test, before_regs.regs, regs.regs,
			   sizeof(regs.regs));
	KUNIT_EXPECT_EQ(test, before_regs.sp, regs.sp);
	KUNIT_EXPECT_EQ(test, before_regs.pstate, regs.pstate);
	KUNIT_EXPECT_EQ(test, before_regs.pc + sizeof(u32), regs.pc);
}

static void
orlix_tcti_gadget_executes_complete_simd_permute_family(struct kunit *test)
{
	bool seen_rn[32] = {};
	bool seen_rm[32] = {};
	bool seen_rd[32] = {};
	bool saw_source_alias = false;
	bool saw_destination_alias = false;
	u8 encoding;

	for (encoding = 0; encoding < 8; encoding++) {
		u8 q;

		for (q = 0; q < 2; q++) {
			u8 size;

			for (size = 0; size < 4; size++) {
				u8 register_case;

				for (register_case = 0; register_case < 32;
				     register_case++)
					orlix_tcti_test_permute_case(test, encoding, q, size,
							       register_case, seen_rn, seen_rm,
						seen_rd, &saw_source_alias,
						&saw_destination_alias);
			}
		}
	}

	for (encoding = 0; encoding < 32; encoding++) {
		KUNIT_EXPECT_TRUE(test, seen_rn[encoding]);
		KUNIT_EXPECT_TRUE(test, seen_rm[encoding]);
		KUNIT_EXPECT_TRUE(test, seen_rd[encoding]);
	}
	KUNIT_EXPECT_TRUE(test, saw_source_alias);
	KUNIT_EXPECT_TRUE(test, saw_destination_alias);
}

