static void orlix_tcti_switch_executes_mlibc_cpuset_count_from_mapped_mm(struct kunit *test)
{
	static const u32 instructions[] = {
		0x6f00e400U, /* movi v0.2d, #0 */
		0xbc404541U, /* ldr s1, [x10], #0x4 */
		0x2f08a421U, /* ushll v1.8h, v1.8b, #0 */
		0x2f10a421U, /* ushll v1.4s, v1.4h, #0 */
		0x4ea11c22U, /* mov v2.16b, v1.16b */
		0x6f3f0423U, /* ushr v3.4s, v1.4s, #1 */
		0x6f3e0424U, /* ushr v4.4s, v1.4s, #2 */
		0x6f3d0425U, /* ushr v5.4s, v1.4s, #3 */
		0x6f3c0426U, /* ushr v6.4s, v1.4s, #4 */
		0x6f3b0427U, /* ushr v7.4s, v1.4s, #5 */
		0x6f0717c2U, /* bic v2.4s, #0xfe */
		0x6f0317c3U, /* bic v3.4s, #0x7e */
		0x6f0117c4U, /* bic v4.4s, #0x3e */
		0x6f0017c5U, /* bic v5.4s, #0x1e */
		0x6f0015c6U, /* bic v6.4s, #0xe */
		0x6f0014c7U, /* bic v7.4s, #0x6 */
		0x4ea08440U, /* add v0.4s, v2.4s, v0.4s */
		0x6f3a0422U, /* ushr v2.4s, v1.4s, #6 */
		0x4ea08460U, /* add v0.4s, v3.4s, v0.4s */
		0x4ea484a3U, /* add v3.4s, v5.4s, v4.4s */
		0x4ea684e4U, /* add v4.4s, v7.4s, v6.4s */
		0x6f001442U, /* bic v2.4s, #0x2 */
		0x4ea08460U, /* add v0.4s, v3.4s, v0.4s */
		0x4ea48442U, /* add v2.4s, v2.4s, v4.4s */
		0x4ea08440U, /* add v0.4s, v2.4s, v0.4s */
		0x6f391420U, /* usra v0.4s, v1.4s, #7 */
		0x4eb1b800U, /* addv s0, v0.4s */
		0x1e260008U, /* fmov w8, s0 */
	};
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	u8 cpuset[8] = {};
	u8 observed[8] = {};
	unsigned long mapped;
	int ret;
	u32 i;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	cpuset[1] = 0x08;
	ret = orlix_tcti_write_user_data(current->mm, mapped, cpuset, sizeof(cpuset));
	KUNIT_ASSERT_EQ(test, 0, ret);

	current->thread.user_simd[0] = 0xffffffffffffffffULL;
	current->thread.user_simd[1] = 0xffffffffffffffffULL;
	current->thread.user_simd[2] = 0;
	current->thread.user_simd[3] = 0;
	current->thread.user_simd_valid = 0;
	regs.regs[10] = mapped;
	regs.regs[8] = 0xffffffffffffffffULL;
	regs.pc = 0x8da0;

	for (i = 0; i < ARRAY_SIZE(instructions); i++) {
		decoded = orlix_tcti_decode_aarch64(instructions[i]);
		KUNIT_ASSERT_NE(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
				decoded.decode_class);
		ret = orlix_tcti_switch_debug_execute_decoded(current->mm, &regs,
							&decoded, NULL);
		KUNIT_ASSERT_EQ(test, 0, ret);
	}

	ret = orlix_tcti_read_user_data(current->mm, mapped, observed,
				  sizeof(observed));
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x08U, observed[1]);
	KUNIT_EXPECT_EQ(test, mapped + 4, regs.regs[10]);
	KUNIT_EXPECT_EQ(test, 1ULL, regs.regs[8]);
	KUNIT_EXPECT_EQ(test, 1ULL, current->thread.user_simd[0]);
	KUNIT_EXPECT_EQ(test, 0ULL, current->thread.user_simd[1]);
	KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
	KUNIT_EXPECT_EQ(test, 0x8e10ULL, regs.pc);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_switch_executes_simd_ld1r_4s_from_mapped_mm(struct kunit *test)
{
	static const u8 lane[] = { 0x44, 0x33, 0x22, 0x11 };
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	unsigned long fault_address = 0;
	unsigned long mapped;
	u64 packed;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	ret = orlix_tcti_write_user_data(current->mm, mapped, lane, sizeof(lane));
	KUNIT_ASSERT_EQ(test, 0, ret);

	current->thread.user_simd[0] = 0xffffffffffffffffULL;
	current->thread.user_simd[1] = 0xffffffffffffffffULL;
	current->thread.user_simd_valid = 0;
	regs.regs[8] = mapped;
	regs.pc = 0x8e20;

	decoded = orlix_tcti_decode_aarch64(0x4d40c900U);
	ret = orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
						&fault_address);

	packed = 0x1122334411223344ULL;
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, mapped, fault_address);
	KUNIT_EXPECT_EQ(test, packed, current->thread.user_simd[0]);
	KUNIT_EXPECT_EQ(test, packed, current->thread.user_simd[1]);
	KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
	KUNIT_EXPECT_EQ(test, 0x8e24ULL, regs.pc);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_switch_executes_complete_simd_single_structure_family(
	struct kunit *test)
{
	static const u8 source[] = { 0x5a, 0x6b, 0x7c, 0x8d };
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	unsigned long fault_address = 0;
	unsigned long mapped;
	u8 observed = 0;
	u8 index;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
		MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));
	KUNIT_ASSERT_EQ(test, 0,
		orlix_tcti_write_user_data(current->mm, mapped, source, sizeof(source)));

	current->thread.user_simd[0] = 0x8877665544332211ULL;
	current->thread.user_simd[1] = 0x1122334455667788ULL;
	current->thread.user_simd_valid = 0;
	regs.regs[8] = mapped;
	regs.pc = 0x8e80;
	decoded = orlix_tcti_decode_aarch64(0x4d400100U);
	KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_SIMD_LOAD_STORE_SINGLE_STRUCTURE,
		decoded.decode_class);
	KUNIT_ASSERT_EQ(test, 0,
		orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
			&fault_address));
	KUNIT_EXPECT_EQ(test, mapped, fault_address);
	KUNIT_EXPECT_EQ(test, 0x8877665544332211ULL,
		current->thread.user_simd[0]);
	KUNIT_EXPECT_EQ(test, 0x112233445566775aULL,
		current->thread.user_simd[1]);
	KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);

	for (index = 0; index < 4; index++) {
		u8 reg = (31 + index) & 0x1fU;

		current->thread.user_simd[reg * 2] = U64_MAX;
		current->thread.user_simd[reg * 2 + 1] = U64_MAX;
	}
	regs.regs[8] = mapped;
	decoded = orlix_tcti_decode_aarch64(0x4d60211fU);
	KUNIT_ASSERT_EQ(test, 0,
		orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
			&fault_address));
	for (index = 0; index < 4; index++) {
		u8 reg = (31 + index) & 0x1fU;

		KUNIT_EXPECT_EQ(test, U64_MAX,
			current->thread.user_simd[reg * 2]);
		KUNIT_EXPECT_EQ(test, (U64_MAX & ~0xffULL) | source[index],
			current->thread.user_simd[reg * 2 + 1]);
	}

	current->thread.user_simd[1] =
		(current->thread.user_simd[1] & ~0xffULL) | 0xa5U;
	regs.regs[8] = mapped + 16;
	decoded = orlix_tcti_decode_aarch64(0x4d000100U);
	KUNIT_ASSERT_EQ(test, 0,
		orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
			&fault_address));
	KUNIT_ASSERT_EQ(test, 0,
		orlix_tcti_read_user_data(current->mm, mapped + 16, &observed,
			sizeof(observed)));
	KUNIT_EXPECT_EQ(test, 0xa5U, observed);

	regs.regs[8] = mapped + 1;
	decoded = orlix_tcti_decode_aarch64(0x4ddf0100U);
	KUNIT_ASSERT_EQ(test, 0,
		orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
			&fault_address));
	KUNIT_EXPECT_EQ(test, mapped + 2, regs.regs[8]);

	regs.regs[8] = mapped + 2;
	regs.regs[9] = 7;
	decoded = orlix_tcti_decode_aarch64(0x4dc90100U);
	KUNIT_ASSERT_EQ(test, 0,
		orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
			&fault_address));
	KUNIT_EXPECT_EQ(test, mapped + 9, regs.regs[8]);

	regs.regs[8] = mapped;
	decoded = orlix_tcti_decode_aarch64(0x4d60e11eU);
	KUNIT_ASSERT_EQ(test, 0,
		orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
			&fault_address));
	for (index = 0; index < 4; index++) {
		u8 reg = (30 + index) & 0x1fU;
		u64 packed = source[index] * 0x0101010101010101ULL;

		KUNIT_EXPECT_EQ(test, packed,
			current->thread.user_simd[reg * 2]);
		KUNIT_EXPECT_EQ(test, packed,
			current->thread.user_simd[reg * 2 + 1]);
	}

	current->thread.user_simd[0] = 0;
	current->thread.user_simd[1] = U64_MAX;
	regs.regs[8] = mapped;
	decoded = orlix_tcti_decode_aarch64(0x0d40c100U);
	KUNIT_ASSERT_EQ(test, 0,
		orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
			&fault_address));
	KUNIT_EXPECT_EQ(test, 0x5a5a5a5a5a5a5a5aULL,
		current->thread.user_simd[0]);
	KUNIT_EXPECT_EQ(test, 0ULL, current->thread.user_simd[1]);
	KUNIT_EXPECT_EQ(test, 0x8e9cULL, regs.pc);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_switch_executes_complete_simd_multiple_structure_family(
	struct kunit *test)
{
	static const u16 interleaved_load[] = {
		0x0100, 0x1110, 0x0302, 0x1312,
		0x0504, 0x1514, 0x0706, 0x1716,
	};
	static const u64 sequential_load[] = {
		0x0706050403020100ULL, 0x0f0e0d0c0b0a0908ULL,
		0x1716151413121110ULL, 0x1f1e1d1c1b1a1918ULL,
		0x2726252423222120ULL, 0x2f2e2d2c2b2a2928ULL,
		0x3736353433323130ULL, 0x3f3e3d3c3b3a3938ULL,
	};
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	unsigned long fault_address = 0;
	unsigned long mapped;
	u64 observed[2] = {};
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, 2 * PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	ret = orlix_tcti_write_user_data(current->mm, mapped, interleaved_load,
				   sizeof(interleaved_load));
	KUNIT_ASSERT_EQ(test, 0, ret);
	current->thread.user_simd[3 * 2 + 1] = U64_MAX;
	current->thread.user_simd[4 * 2 + 1] = U64_MAX;
	regs.regs[10] = mapped;
	regs.pc = 0x8ea0;
	decoded = orlix_tcti_decode_aarch64(0x0c408543U);
	ret = orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
						 &fault_address);
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x0706050403020100ULL,
		current->thread.user_simd[3 * 2]);
	KUNIT_EXPECT_EQ(test, 0x1716151413121110ULL,
		current->thread.user_simd[4 * 2]);
	KUNIT_EXPECT_EQ(test, 0ULL, current->thread.user_simd[3 * 2 + 1]);
	KUNIT_EXPECT_EQ(test, 0ULL, current->thread.user_simd[4 * 2 + 1]);

	current->thread.user_simd[5 * 2] = 0x0706050403020100ULL;
	current->thread.user_simd[6 * 2] = 0x1716151413121110ULL;
	regs.regs[11] = mapped + 32;
	decoded = orlix_tcti_decode_aarch64(0x0c008965U);
	ret = orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
						 &fault_address);
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = orlix_tcti_read_user_data(current->mm, mapped + 32, observed,
				  sizeof(observed));
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x1312111003020100ULL, observed[0]);
	KUNIT_EXPECT_EQ(test, 0x1716151407060504ULL, observed[1]);

	ret = orlix_tcti_write_user_data(current->mm, mapped + 64, sequential_load,
				   sizeof(sequential_load));
	KUNIT_ASSERT_EQ(test, 0, ret);
	regs.regs[24] = mapped + 64;
	decoded = orlix_tcti_decode_aarch64(0x4cdf231eU);
	ret = orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
						 &fault_address);
	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, sequential_load[0], current->thread.user_simd[30 * 2]);
	KUNIT_EXPECT_EQ(test, sequential_load[1], current->thread.user_simd[30 * 2 + 1]);
	KUNIT_EXPECT_EQ(test, sequential_load[2], current->thread.user_simd[31 * 2]);
	KUNIT_EXPECT_EQ(test, sequential_load[3], current->thread.user_simd[31 * 2 + 1]);
	KUNIT_EXPECT_EQ(test, sequential_load[4], current->thread.user_simd[0]);
	KUNIT_EXPECT_EQ(test, sequential_load[5], current->thread.user_simd[1]);
	KUNIT_EXPECT_EQ(test, sequential_load[6], current->thread.user_simd[2]);
	KUNIT_EXPECT_EQ(test, sequential_load[7], current->thread.user_simd[3]);
	KUNIT_EXPECT_EQ(test, mapped + 128, regs.regs[24]);
	KUNIT_EXPECT_EQ(test, 0x8eacULL, regs.pc);

	ret = vm_munmap(mapped, 2 * PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_switch_reports_simd_multiple_structure_fault_order(
	struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	unsigned long fault_address = 0;
	unsigned long mapped;
	u64 source = 0x1716151413121110ULL;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, 2 * PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));
	ret = orlix_tcti_write_user_data(current->mm, mapped + PAGE_SIZE - sizeof(source),
				   &source, sizeof(source));
	KUNIT_ASSERT_EQ(test, 0, ret);
	ret = sys_mprotect(mapped + PAGE_SIZE, PAGE_SIZE, PROT_NONE);
	KUNIT_ASSERT_EQ(test, 0, ret);

	regs.regs[10] = mapped + PAGE_SIZE - sizeof(source);
	regs.pc = 0x8ec0;
	decoded = orlix_tcti_decode_aarch64(0x0c408543U);
	ret = orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
						 &fault_address);
	KUNIT_EXPECT_NE(test, 0, ret);
	KUNIT_EXPECT_EQ(test, mapped + PAGE_SIZE, fault_address);
	KUNIT_EXPECT_EQ(test, 0x8ec0ULL, regs.pc);

	ret = vm_munmap(mapped, 2 * PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static u8 *orlix_tcti_test_simd_register_bytes(u8 reg)
{
	return (u8 *)&current->thread.user_simd[(reg & 0x1fU) * 2];
}

static void orlix_tcti_test_initialize_simd_structure_registers(
	u8 rd, u8 count, u8 before[4][16])
{
	u8 index;

	for (index = 0; index < count; index++) {
		u8 *bytes = orlix_tcti_test_simd_register_bytes(rd + index);
		u8 byte;

		for (byte = 0; byte < 16; byte++)
			bytes[byte] = 0x40U ^ (index * 0x31U) ^ byte;
		memcpy(before[index], bytes, 16);
	}
}

static void orlix_tcti_switch_exhausts_simd_single_structure_execution(
	struct kunit *test)
{
	unsigned long mapped;
	u16 control;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
		MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	for (control = 0; control < BIT(9); control++) {
		u8 size = control & 0x3U;
		bool s = control & BIT(2);
		u8 opcode = (control >> 3) & 0x7U;
		bool r = control & BIT(6);
		bool load = control & BIT(7);
		bool q = control & BIT(8);
		bool replicate = load && !s &&
			(opcode == 6 || opcode == 7);
		u8 count;
		u8 access_size;
		u8 before[4][16];
		u8 memory[64];
		u8 observed[64] = {};
		struct pt_regs regs = {};
		unsigned long fault_address = 0;
		u32 instruction;
		struct orlix_tcti_decoded_instruction decoded;
		u8 index;

		if (!orlix_tcti_test_simd_single_structure_is_legal(
				false, load, 0, opcode, s, size))
			continue;

		instruction = orlix_tcti_test_encode_simd_single_structure(
			q, false, load, r, 0, opcode, s, size, 20, 29);
		decoded = orlix_tcti_decode_aarch64(instruction);
		count = decoded.simd_structure_count;
		access_size = decoded.access_size;
		for (index = 0; index < sizeof(memory); index++)
			memory[index] = 0x80U ^ index ^ control;
		orlix_tcti_test_initialize_simd_structure_registers(29, count, before);
		current->thread.user_simd[28 * 2] = 0x2828282828282828ULL;
		current->thread.user_simd[1 * 2] = 0x0101010101010101ULL;
		if (load) {
			ret = orlix_tcti_write_user_data(current->mm, mapped, memory,
				count * access_size);
			KUNIT_ASSERT_EQ(test, 0, ret);
		}
		regs.regs[20] = mapped;
		regs.pc = 0x9100;
		ret = orlix_tcti_switch_debug_execute_decoded(
			current->mm, &regs, &decoded, &fault_address);
		KUNIT_ASSERT_EQ_MSG(test, 0, ret, "instruction=%08x", instruction);

		if (load) {
			for (index = 0; index < count; index++) {
				u8 expected[16];

				if (replicate) {
					u8 byte;
					u8 vector_bytes = q ? 16 : 8;

					memset(expected, 0, sizeof(expected));
					for (byte = 0; byte < vector_bytes; byte++)
						expected[byte] = memory[
							index * access_size +
							byte % access_size];
				} else {
					memcpy(expected, before[index], sizeof(expected));
					memcpy(expected +
						decoded.simd_lane_index * access_size,
						memory + index * access_size,
						access_size);
				}
				KUNIT_EXPECT_MEMEQ(test, expected,
					orlix_tcti_test_simd_register_bytes(29 + index),
					sizeof(expected));
			}
		} else {
			ret = orlix_tcti_read_user_data(current->mm, mapped, observed,
				count * access_size);
			KUNIT_ASSERT_EQ(test, 0, ret);
			for (index = 0; index < count; index++)
				KUNIT_EXPECT_MEMEQ(test,
					before[index] +
						decoded.simd_lane_index * access_size,
					observed + index * access_size,
					access_size);
		}
		KUNIT_EXPECT_EQ(test, 0x9104ULL, regs.pc);
		KUNIT_EXPECT_EQ(test, 0x2828282828282828ULL,
			current->thread.user_simd[28 * 2]);
		KUNIT_EXPECT_EQ(test, 0x0101010101010101ULL,
			current->thread.user_simd[1 * 2]);
	}

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_test_expect_simd_multiple_load(
	struct kunit *test, const u8 memory[64], u8 count, u8 vector_bytes,
	u8 access_size, bool interleaved)
{
	u8 index;

	for (index = 0; index < count; index++) {
		u8 expected[16] = {};
		u8 byte;

		for (byte = 0; byte < vector_bytes; byte++) {
			u8 source = interleaved ?
				((byte / access_size) * count + index) *
					access_size + byte % access_size :
				index * vector_bytes + byte;

			expected[byte] = memory[source];
		}
		KUNIT_EXPECT_MEMEQ(test, expected,
			orlix_tcti_test_simd_register_bytes(29 + index),
			sizeof(expected));
	}
}

static void orlix_tcti_test_expect_simd_multiple_store(
	struct kunit *test, const u8 before[4][16], const u8 observed[64],
	u8 count, u8 vector_bytes, u8 access_size, bool interleaved)
{
	u8 index;

	for (index = 0; index < count * vector_bytes; index++) {
		u8 reg_index;
		u8 byte;

		if (interleaved) {
			reg_index = (index / access_size) % count;
			byte = (index / (count * access_size)) * access_size +
				index % access_size;
		} else {
			reg_index = index / vector_bytes;
			byte = index % vector_bytes;
		}
		KUNIT_EXPECT_EQ(test, before[reg_index][byte], observed[index]);
	}
}

static void orlix_tcti_test_execute_simd_multiple_structure_case(
	struct kunit *test, unsigned long mapped, u8 q, u8 size,
	u8 opcode, bool load)
{
	u8 count = orlix_tcti_test_simd_multiple_structure_count(opcode);
	u8 vector_bytes = q ? 16 : 8;
	u8 access_size = BIT(size);
	bool interleaved = opcode == 0 || opcode == 4 || opcode == 8;
	u8 before[4][16];
	u8 memory[64];
	u8 observed[64] = {};
	struct pt_regs regs = {};
	unsigned long fault_address = 0;
	u32 instruction = orlix_tcti_test_encode_simd_multiple_structure(
		q, false, load, 0, opcode, size, 20, 29);
	struct orlix_tcti_decoded_instruction decoded =
		orlix_tcti_decode_aarch64(instruction);
	u8 index;
	int ret;

	for (index = 0; index < sizeof(memory); index++)
		memory[index] = 0xc0U ^ index ^ (opcode << 1) ^ (load << 6);
	orlix_tcti_test_initialize_simd_structure_registers(29, count, before);
	current->thread.user_simd[28 * 2] = 0x2828282828282828ULL;
	current->thread.user_simd[1 * 2] = 0x0101010101010101ULL;
	if (load) {
		ret = orlix_tcti_write_user_data(current->mm, mapped, memory,
			count * vector_bytes);
		KUNIT_ASSERT_EQ(test, 0, ret);
	}
	regs.regs[20] = mapped;
	regs.pc = 0x9200;
	ret = orlix_tcti_switch_debug_execute_decoded(
		current->mm, &regs, &decoded, &fault_address);
	KUNIT_ASSERT_EQ_MSG(test, 0, ret, "instruction=%08x", instruction);

	if (load) {
		orlix_tcti_test_expect_simd_multiple_load(
			test, memory, count, vector_bytes,
			access_size, interleaved);
	} else {
		ret = orlix_tcti_read_user_data(current->mm, mapped, observed,
			count * vector_bytes);
		KUNIT_ASSERT_EQ(test, 0, ret);
		orlix_tcti_test_expect_simd_multiple_store(
			test, before, observed, count, vector_bytes,
			access_size, interleaved);
	}
	KUNIT_EXPECT_EQ(test, 0x9204ULL, regs.pc);
	KUNIT_EXPECT_EQ(test, 0x2828282828282828ULL,
		current->thread.user_simd[28 * 2]);
	KUNIT_EXPECT_EQ(test, 0x0101010101010101ULL,
		current->thread.user_simd[1 * 2]);
}

static void orlix_tcti_switch_exhausts_simd_multiple_structure_execution(
	struct kunit *test)
{
	static const u8 opcodes[] = { 0, 2, 4, 6, 7, 8, 10 };
	unsigned long mapped;
	u8 q;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
		MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	for (q = 0; q < 2; q++) {
		u8 size;

		for (size = 0; size < 4; size++) {
			u8 opcode_index;

			for (opcode_index = 0;
			     opcode_index < ARRAY_SIZE(opcodes); opcode_index++) {
				orlix_tcti_test_execute_simd_multiple_structure_case(
					test, mapped, q, size,
					opcodes[opcode_index], false);
				orlix_tcti_test_execute_simd_multiple_structure_case(
					test, mapped, q, size,
					opcodes[opcode_index], true);
			}
		}
	}

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_switch_executes_ldrsw_sign_extension_from_mapped_mm(struct kunit *test)
{
	const u32 value = 0xffffffcdU;
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	unsigned long fault_address = 0;
	unsigned long mapped;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	ret = orlix_tcti_write_user_data(current->mm, mapped + 24, &value,
				   sizeof(value));
	KUNIT_ASSERT_EQ(test, 0, ret);

	regs.regs[2] = mapped;
	regs.regs[8] = 0;
	regs.pc = 0x8e40;
	decoded = orlix_tcti_decode_aarch64(0xb9801848U);

	ret = orlix_tcti_switch_debug_execute_decoded(current->mm, &regs, &decoded,
						&fault_address);

	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, mapped + 24, fault_address);
	KUNIT_EXPECT_EQ(test, 0xffffffffffffffcdULL, regs.regs[8]);
	KUNIT_EXPECT_EQ(test, 0x8e44ULL, regs.pc);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static void orlix_tcti_switch_executes_complete_simd_small_signed_memory_family(
	struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	unsigned long fault_address = 0;
	unsigned long mapped;
	u16 value16;
	u8 value8;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
		MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	current->thread.user_simd[12] = 0xaaULL;
	regs.regs[11] = mapped;
	regs.pc = 0x9000;
	decoded = orlix_tcti_decode_aarch64(0x3c001166U);
	ret = orlix_tcti_switch_debug_execute_decoded(
		current->mm, &regs, &decoded, &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	ret = orlix_tcti_read_user_data(current->mm, mapped + 1, &value8,
		sizeof(value8));
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0xaaU, value8);

	value8 = 0x5a;
	ret = orlix_tcti_write_user_data(current->mm, mapped + 7, &value8,
		sizeof(value8));
	KUNIT_ASSERT_EQ(test, 0, ret);
	current->thread.user_simd[4] = ~0ULL;
	current->thread.user_simd[5] = ~0ULL;
	regs.regs[3] = mapped;
	decoded = orlix_tcti_decode_aarch64(0x3c407062U);
	ret = orlix_tcti_switch_debug_execute_decoded(
		current->mm, &regs, &decoded, &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x5aULL, current->thread.user_simd[4]);
	KUNIT_EXPECT_EQ(test, 0ULL, current->thread.user_simd[5]);

	current->thread.user_simd[8] = 0xbeefULL;
	regs.regs[5] = mapped + 16;
	decoded = orlix_tcti_decode_aarch64(0x7c1fe0a4U);
	ret = orlix_tcti_switch_debug_execute_decoded(
		current->mm, &regs, &decoded, &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	ret = orlix_tcti_read_user_data(current->mm, mapped + 14, &value16,
		sizeof(value16));
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0xbeefU, value16);

	value16 = 0x1234;
	ret = orlix_tcti_write_user_data(current->mm, mapped + 24, &value16,
		sizeof(value16));
	KUNIT_ASSERT_EQ(test, 0, ret);
	current->thread.user_simd[12] = ~0ULL;
	current->thread.user_simd[13] = ~0ULL;
	regs.regs[7] = mapped + 16;
	decoded = orlix_tcti_decode_aarch64(0x7c4080e6U);
	ret = orlix_tcti_switch_debug_execute_decoded(
		current->mm, &regs, &decoded, &fault_address);
	KUNIT_EXPECT_EQ(test, 0, ret);
	KUNIT_EXPECT_EQ(test, 0x1234ULL, current->thread.user_simd[12]);
	KUNIT_EXPECT_EQ(test, 0ULL, current->thread.user_simd[13]);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

