static void orlix_tcti_test_execute_fp_scalar_native_one_source(
	struct kunit *test, u32 pattern, u8 rd, u8 rn, u64 source,
	u64 expected, unsigned long fpcr, unsigned long expected_fpsr)
{
	u32 instruction = pattern | ((u32)rn << 5) | rd;
	struct orlix_tcti_decoded_instruction decoded =
		orlix_tcti_decode_aarch64(instruction);
	struct pt_regs regs = {};
	u64 before_simd[ARRAY_SIZE(current->thread.user_simd)];
	u64 expected_simd[ARRAY_SIZE(current->thread.user_simd)];
	unsigned int word;
	int ret;

	KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_1SOURCE,
			decoded.decode_class);
	for (word = 0; word < ARRAY_SIZE(before_simd); word++)
		before_simd[word] = 0xd9d9000000000000ULL ^
			((u64)instruction << 9) ^ word;
	before_simd[rn * 2] = source;
	before_simd[rn * 2 + 1] = 0x123456789abcdef0ULL;
	memcpy(current->thread.user_simd, before_simd, sizeof(before_simd));
	memcpy(expected_simd, before_simd, sizeof(expected_simd));
	expected_simd[rd * 2] = expected;
	expected_simd[rd * 2 + 1] = 0;
	for (word = 0; word < ARRAY_SIZE(regs.regs); word++)
		regs.regs[word] = 0xdef0000000000000ULL ^ word;
	regs.pc = 0xb1b92000ULL;
	regs.sp = 0xb1ca3000ULL;
	regs.pstate = PSR_Z_BIT | PSR_C_BIT;
	current->thread.user_fpcr = fpcr;
	current->thread.user_fpsr = BIT(27);
	current->thread.user_simd_valid = 0;

	ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs, &decoded, NULL);

	KUNIT_ASSERT_EQ(test, 0, ret);
	KUNIT_EXPECT_MEMEQ(test, expected_simd, current->thread.user_simd,
			   sizeof(expected_simd));
	KUNIT_EXPECT_EQ(test, fpcr, current->thread.user_fpcr);
	KUNIT_EXPECT_EQ(test, expected_fpsr, current->thread.user_fpsr);
	KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
	KUNIT_EXPECT_EQ(test, 0xb1b92004ULL, regs.pc);
	KUNIT_EXPECT_EQ(test, 0xb1ca3000ULL, regs.sp);
	KUNIT_EXPECT_EQ(test, PSR_Z_BIT | PSR_C_BIT, regs.pstate);
	for (word = 0; word < ARRAY_SIZE(regs.regs); word++)
		KUNIT_EXPECT_EQ(test, 0xdef0000000000000ULL ^ word,
				regs.regs[word]);
}

static void orlix_tcti_gadget_executes_complete_fp_scalar_native_1source_family(
	struct kunit *test)
{
	static const struct {
		u32 pattern;
		u64 source;
		u64 expected;
	} ordinary[] = {
		{ 0x1e22c000U, 0x3fc00000U, 0x3ff8000000000000ULL },
		{ 0x1e624000U, 0x3ff8000000000000ULL, 0x3fc00000U },
		{ 0x1e21c000U, 0x40800000U, 0x40000000U },
		{ 0x1e61c000U, 0x4010000000000000ULL,
		  0x4000000000000000ULL },
	};
	unsigned int index;
	u8 reg;

	for (index = 0; index < ARRAY_SIZE(ordinary); index++) {
		for (reg = 0; reg < 32; reg++) {
			u8 rn = (reg * 11) & 0x1fU;

			orlix_tcti_test_execute_fp_scalar_native_one_source(
				test, ordinary[index].pattern, reg, rn,
				ordinary[index].source, ordinary[index].expected, 0,
				BIT(27));
		}
		orlix_tcti_test_execute_fp_scalar_native_one_source(
			test, ordinary[index].pattern, 31, 31,
			ordinary[index].source, ordinary[index].expected, 0,
			BIT(27));
	}

	orlix_tcti_test_execute_fp_scalar_native_one_source(
		test, 0x1e624000U, 0, 1, 0x3ff0000010000000ULL,
		0x3f800000U, 0, BIT(27) | BIT(4));
	orlix_tcti_test_execute_fp_scalar_native_one_source(
		test, 0x1e624000U, 0, 1, 0x3ff0000010000000ULL,
		0x3f800001U, BIT(22), BIT(27) | BIT(4));
	orlix_tcti_test_execute_fp_scalar_native_one_source(
		test, 0x1e22c000U, 0, 1, 0x7f800001U,
		0x7ff8000000000000ULL, BIT(25), BIT(27) | BIT(0));
	orlix_tcti_test_execute_fp_scalar_native_one_source(
		test, 0x1e21c000U, 0, 1, 0xbf800000U, 0x7fc00000U,
		BIT(25), BIT(27) | BIT(0));
	orlix_tcti_test_execute_fp_scalar_native_one_source(
		test, 0x1e61c000U, 0, 1, 0x7ff0000000000001ULL,
		0x7ff8000000000000ULL, BIT(25), BIT(27) | BIT(0));
}

static void orlix_tcti_gadget_executes_complete_fp_scalar_move_family(
	struct kunit *test)
{
	u8 precision;
	u8 rd;

	for (precision = 0; precision < 2; precision++) {
		for (rd = 0; rd < 32; rd++) {
			u8 rn = (rd * 5) & 0x1fU;
			u32 instruction = (precision ? 0x1e604000U :
				0x1e204000U) | ((u32)rn << 5) | rd;
			struct orlix_tcti_decoded_instruction decoded =
				orlix_tcti_decode_aarch64(instruction);
			struct pt_regs regs = {};
			u64 before_simd[ARRAY_SIZE(current->thread.user_simd)];
			u8 untouched = (rd + 1) & 0x1fU;
			u64 source = 0x89abcdef76543210ULL ^ instruction;
			unsigned int word;
			int ret;

			KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_MOVE,
				decoded.decode_class);
			for (word = 0; word < ARRAY_SIZE(before_simd); word++)
				before_simd[word] = 0xebeb000000000000ULL ^ word;
			before_simd[rn * 2] = source;
			memcpy(current->thread.user_simd, before_simd,
			       sizeof(before_simd));
			regs.pc = 0xc1b92000ULL;
			current->thread.user_simd_valid = 1;

			ret = orlix_tcti_switch_debug_execute_decoded(
				NULL, &regs, &decoded, NULL);

			KUNIT_ASSERT_EQ(test, 0, ret);
			KUNIT_EXPECT_EQ(test, precision ? source : (u32)source,
				current->thread.user_simd[rd * 2]);
			KUNIT_EXPECT_EQ(test, 0ULL,
				current->thread.user_simd[rd * 2 + 1]);
			if (untouched != rd) {
				KUNIT_EXPECT_EQ(test, before_simd[untouched * 2],
					current->thread.user_simd[untouched * 2]);
				KUNIT_EXPECT_EQ(test, before_simd[untouched * 2 + 1],
					current->thread.user_simd[untouched * 2 + 1]);
			}
			KUNIT_EXPECT_EQ(test, 1, current->thread.user_simd_valid);
			KUNIT_EXPECT_EQ(test, 0xc1b92004ULL, regs.pc);
		}
	}
}

static int orlix_tcti_test_execute_decoded_gadget(
	struct pt_regs *regs, const struct orlix_tcti_decoded_instruction *decoded);

static void orlix_tcti_decode_exhaustive_fp_scalar_transfer_family(
	struct kunit *test)
{
	static const struct {
		u32 pattern;
		enum orlix_tcti_fp_scalar_move_op operation;
		u8 access_size;
	} cases[] = {
		{ 0x1e260000U, ORLIX_TCTI_FP_MOVE_SIMD_TO_GPR, sizeof(u32) },
		{ 0x1e270000U, ORLIX_TCTI_FP_MOVE_GPR_TO_SIMD, sizeof(u32) },
		{ 0x9e660000U, ORLIX_TCTI_FP_MOVE_SIMD_TO_GPR, sizeof(u64) },
		{ 0x9e670000U, ORLIX_TCTI_FP_MOVE_GPR_TO_SIMD, sizeof(u64) },
		{ 0x9eae0000U, ORLIX_TCTI_FP_MOVE_SIMD_HIGH_TO_GPR, sizeof(u64) },
		{ 0x9eaf0000U, ORLIX_TCTI_FP_MOVE_GPR_TO_SIMD_HIGH, sizeof(u64) },
	};
	const u32 fixed_mask = 0xfffffc00U;
	size_t i;
	u8 reg;
	u8 bit;

	for (i = 0; i < ARRAY_SIZE(cases); i++) {
		for (reg = 0; reg < 32; reg++) {
			struct orlix_tcti_decoded_instruction decoded;

			decoded = orlix_tcti_decode_aarch64(cases[i].pattern |
						       ((u32)reg << 5) | reg);
			KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_MOVE,
					decoded.decode_class);
			KUNIT_EXPECT_EQ(test, cases[i].operation,
					decoded.fp_move_op);
			KUNIT_EXPECT_EQ(test, reg, decoded.rd);
			KUNIT_EXPECT_EQ(test, reg, decoded.rn);
			KUNIT_EXPECT_EQ(test, cases[i].access_size,
					decoded.access_size);
			KUNIT_EXPECT_EQ(test, cases[i].access_size,
					decoded.result_size);
		}

		for (bit = 10; bit < 32; bit++) {
			struct orlix_tcti_decoded_instruction decoded;

			if (!(fixed_mask & BIT(bit)))
				continue;
			decoded = orlix_tcti_decode_aarch64(cases[i].pattern ^ BIT(bit));
			KUNIT_EXPECT_FALSE(test,
				decoded.decode_class == ORLIX_TCTI_DECODE_FP_SCALAR_MOVE &&
				decoded.fp_move_op == cases[i].operation &&
				decoded.access_size == cases[i].access_size);
		}
	}
}

static void orlix_tcti_gadget_executes_complete_fp_scalar_transfer_family(
	struct kunit *test)
{
	static const struct {
		u32 pattern;
		enum orlix_tcti_fp_scalar_move_op operation;
		u8 access_size;
	} cases[] = {
		{ 0x1e260000U, ORLIX_TCTI_FP_MOVE_SIMD_TO_GPR, sizeof(u32) },
		{ 0x1e270000U, ORLIX_TCTI_FP_MOVE_GPR_TO_SIMD, sizeof(u32) },
		{ 0x9e660000U, ORLIX_TCTI_FP_MOVE_SIMD_TO_GPR, sizeof(u64) },
		{ 0x9e670000U, ORLIX_TCTI_FP_MOVE_GPR_TO_SIMD, sizeof(u64) },
		{ 0x9eae0000U, ORLIX_TCTI_FP_MOVE_SIMD_HIGH_TO_GPR, sizeof(u64) },
		{ 0x9eaf0000U, ORLIX_TCTI_FP_MOVE_GPR_TO_SIMD_HIGH, sizeof(u64) },
	};
	const u64 gpr_source = 0x8877665544332211ULL;
	const u64 simd_low = 0x0123456789abcdefULL;
	const u64 simd_high = 0xfedcba9876543210ULL;
	size_t i;

	for (i = 0; i < ARRAY_SIZE(cases); i++) {
		struct orlix_tcti_decoded_instruction decoded;
		struct pt_regs regs;
		u64 expected_low = simd_low;
		u64 expected_high = simd_high;
		u64 expected_gpr = 0xa5a5a5a5a5a5a5a5ULL;
		int ret;

		decoded = orlix_tcti_decode_aarch64(cases[i].pattern | (1U << 5));
		KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_MOVE,
				decoded.decode_class);
		KUNIT_ASSERT_EQ(test, cases[i].operation, decoded.fp_move_op);

		memset(&regs, 0, sizeof(regs));
		regs.pc = 0xc200 + i * sizeof(u32);
		regs.regs[0] = expected_gpr;
		regs.regs[1] = gpr_source;
		regs.regs[9] = 0x1122334455667788ULL;
		regs.sp = 0x8877665544332210ULL;
		regs.pstate = PSR_N_BIT | PSR_C_BIT;
		current->thread.user_simd[0] = simd_low;
		current->thread.user_simd[1] = simd_high;
		current->thread.user_simd[2] = simd_low;
		current->thread.user_simd[3] = simd_high;
		current->thread.user_simd[62] = 0x0f1e2d3c4b5a6978ULL;
		current->thread.user_simd[63] = 0x8796a5b4c3d2e1f0ULL;
		current->thread.user_fpcr = BIT(22);
		current->thread.user_fpsr = BIT(27);

		switch (cases[i].operation) {
		case ORLIX_TCTI_FP_MOVE_SIMD_TO_GPR:
			expected_gpr = simd_low;
			if (cases[i].access_size == sizeof(u32))
				expected_gpr = (u32)simd_low;
			break;
		case ORLIX_TCTI_FP_MOVE_GPR_TO_SIMD:
			expected_low = gpr_source;
			if (cases[i].access_size == sizeof(u32))
				expected_low = (u32)gpr_source;
			expected_high = 0;
			break;
		case ORLIX_TCTI_FP_MOVE_SIMD_HIGH_TO_GPR:
			expected_gpr = simd_high;
			break;
		case ORLIX_TCTI_FP_MOVE_GPR_TO_SIMD_HIGH:
			expected_high = gpr_source;
			break;
		default:
			KUNIT_FAIL(test, "unexpected scalar transfer operation");
			return;
		}

		ret = orlix_tcti_test_execute_decoded_gadget(&regs, &decoded);

		KUNIT_ASSERT_EQ(test, 0, ret);
		KUNIT_EXPECT_EQ(test, expected_gpr, regs.regs[0]);
		KUNIT_EXPECT_EQ(test, expected_low, current->thread.user_simd[0]);
		KUNIT_EXPECT_EQ(test, expected_high,
				current->thread.user_simd[1]);
		KUNIT_EXPECT_EQ(test, simd_low, current->thread.user_simd[2]);
		KUNIT_EXPECT_EQ(test, simd_high, current->thread.user_simd[3]);
		KUNIT_EXPECT_EQ(test, 0x0f1e2d3c4b5a6978ULL,
				current->thread.user_simd[62]);
		KUNIT_EXPECT_EQ(test, 0x8796a5b4c3d2e1f0ULL,
				current->thread.user_simd[63]);
		KUNIT_EXPECT_EQ(test, 0x1122334455667788ULL, regs.regs[9]);
		KUNIT_EXPECT_EQ(test, 0x8877665544332210ULL, regs.sp);
		KUNIT_EXPECT_EQ(test, PSR_N_BIT | PSR_C_BIT, regs.pstate);
		KUNIT_EXPECT_EQ(test, BIT(22), current->thread.user_fpcr);
		KUNIT_EXPECT_EQ(test, BIT(27), current->thread.user_fpsr);
		KUNIT_EXPECT_EQ(test, 0xc204 + i * sizeof(u32), regs.pc);
	}
}

