static void orlix_tcti_switch_preserves_compiler_rt_pair_frame(struct kunit *test)
{
	static const u32 store_instructions[] = {
		0xad0583e1U, /* stp q1, q0, [sp, #176] */
		0xa90d57f6U, /* stp x22, x21, [sp, #208] */
		0xa90e4ff4U, /* stp x20, x19, [sp, #224] */
	};
	static const u32 load_instructions[] = {
		0xa94e4ff4U, /* ldp x20, x19, [sp, #224] */
		0xa94d57f6U, /* ldp x22, x21, [sp, #208] */
		0xad4583e1U, /* ldp q1, q0, [sp, #176] */
	};
	const u64 q0_low = 0x0011223344556677ULL;
	const u64 q0_high = 0x8899aabbccddeeffULL;
	const u64 q1_low = 0x1021324354657687ULL;
	const u64 q1_high = 0x98a9bacbdcedfe0fULL;
	const u64 x19 = 0x1919191919191919ULL;
	const u64 x20 = 0x2020202020202020ULL;
	const u64 x21 = 0x2121212121212121ULL;
	const u64 x22 = 0x2222222222222222ULL;
	struct orlix_tcti_decoded_instruction decoded;
	struct pt_regs regs = {};
	unsigned long fault_address = 0;
	unsigned long mapped;
	unsigned int i;
	int ret;

	KUNIT_ASSERT_NOT_NULL(test, current->mm);
	mapped = ksys_mmap_pgoff(0, PAGE_SIZE, PROT_READ | PROT_WRITE,
				 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
	KUNIT_ASSERT_FALSE(test, IS_ERR_VALUE(mapped));

	regs.sp = mapped;
	regs.pc = 0x9500;
	regs.regs[19] = x19;
	regs.regs[20] = x20;
	regs.regs[21] = x21;
	regs.regs[22] = x22;
	current->thread.user_simd[0] = q0_low;
	current->thread.user_simd[1] = q0_high;
	current->thread.user_simd[2] = q1_low;
	current->thread.user_simd[3] = q1_high;
	current->thread.user_simd_valid = 1;

	for (i = 0; i < ARRAY_SIZE(store_instructions); i++) {
		decoded = orlix_tcti_decode_aarch64(store_instructions[i]);
		KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
				decoded.decode_class);
		ret = orlix_tcti_switch_debug_execute_decoded(current->mm, &regs,
							 &decoded, &fault_address);
		KUNIT_ASSERT_EQ(test, 0, ret);
	}

	KUNIT_EXPECT_EQ(test, mapped, regs.sp);
	regs.regs[19] = 0;
	regs.regs[20] = 0;
	regs.regs[21] = 0;
	regs.regs[22] = 0;
	current->thread.user_simd[0] = 0;
	current->thread.user_simd[1] = 0;
	current->thread.user_simd[2] = 0;
	current->thread.user_simd[3] = 0;

	for (i = 0; i < ARRAY_SIZE(load_instructions); i++) {
		decoded = orlix_tcti_decode_aarch64(load_instructions[i]);
		KUNIT_ASSERT_EQ(test, ORLIX_TCTI_DECODE_LOAD_STORE_PAIR,
				decoded.decode_class);
		ret = orlix_tcti_switch_debug_execute_decoded(current->mm, &regs,
							 &decoded, &fault_address);
		KUNIT_ASSERT_EQ(test, 0, ret);
	}

	KUNIT_EXPECT_EQ(test, mapped, regs.sp);
	KUNIT_EXPECT_EQ(test, x19, regs.regs[19]);
	KUNIT_EXPECT_EQ(test, x20, regs.regs[20]);
	KUNIT_EXPECT_EQ(test, x21, regs.regs[21]);
	KUNIT_EXPECT_EQ(test, x22, regs.regs[22]);
	KUNIT_EXPECT_EQ(test, q0_low, current->thread.user_simd[0]);
	KUNIT_EXPECT_EQ(test, q0_high, current->thread.user_simd[1]);
	KUNIT_EXPECT_EQ(test, q1_low, current->thread.user_simd[2]);
	KUNIT_EXPECT_EQ(test, q1_high, current->thread.user_simd[3]);
	KUNIT_EXPECT_EQ(test, 0x9518ULL, regs.pc);

	ret = vm_munmap(mapped, PAGE_SIZE);
	KUNIT_EXPECT_EQ(test, 0, ret);
}

static u32 orlix_tcti_test_encode_fp_round_to_gpr(u8 rounding, u8 opcode,
					    bool is_64bit,
					    bool source_double,
					    u8 rd, u8 rn)
{
	return 0x1e200000U | ((u32)rounding << 19) |
	       ((u32)opcode << 16) | (is_64bit ? BIT(31) : 0) |
	       (source_double ? BIT(22) : 0) | ((u32)rn << 5) | rd;
}

static void orlix_tcti_decode_exhaustive_fp_round_to_gpr_family(struct kunit *test)
{
	static const struct {
		u8 rounding;
		u8 opcode;
		enum orlix_tcti_fp_int_convert_op operation;
	} cases[] = {
		{ 0, 0, ORLIX_TCTI_FP_INT_FCVTNS },
		{ 0, 1, ORLIX_TCTI_FP_INT_FCVTNU },
		{ 1, 0, ORLIX_TCTI_FP_INT_FCVTPS },
		{ 1, 1, ORLIX_TCTI_FP_INT_FCVTPU },
		{ 2, 0, ORLIX_TCTI_FP_INT_FCVTMS },
		{ 2, 1, ORLIX_TCTI_FP_INT_FCVTMU },
		{ 3, 0, ORLIX_TCTI_FP_INT_FCVTZS },
		{ 3, 1, ORLIX_TCTI_FP_INT_FCVTZU },
		{ 0, 4, ORLIX_TCTI_FP_INT_FCVTAS },
		{ 0, 5, ORLIX_TCTI_FP_INT_FCVTAU },
	};
	size_t index;
	u8 is_64bit;
	u8 source_double;
	u8 rd;
	u8 rn;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (is_64bit = 0; is_64bit < 2; is_64bit++) {
			for (source_double = 0; source_double < 2;
			     source_double++) {
				for (rd = 0; rd < 32; rd++) {
					for (rn = 0; rn < 32; rn++) {
						struct orlix_tcti_decoded_instruction decoded =
							orlix_tcti_decode_aarch64(
								orlix_tcti_test_encode_fp_round_to_gpr(
									cases[index].rounding,
									cases[index].opcode,
									is_64bit,
									source_double,
									rd, rn));

						KUNIT_EXPECT_EQ(test,
								ORLIX_TCTI_DECODE_FP_INT_CONVERT,
								decoded.decode_class);
						KUNIT_EXPECT_EQ(test,
								cases[index].operation,
								decoded.fp_int_op);
						KUNIT_EXPECT_EQ(test, rd, decoded.rd);
						KUNIT_EXPECT_EQ(test, rn, decoded.rn);
						KUNIT_EXPECT_EQ(test,
								source_double ? sizeof(u64) :
											sizeof(u32),
								decoded.access_size);
						KUNIT_EXPECT_EQ(test,
								is_64bit ? sizeof(u64) :
										   sizeof(u32),
								decoded.result_size);
					}
				}
			}
		}
	}
}

static void orlix_tcti_decode_fp_round_to_gpr_preserves_existing_transfers(
	struct kunit *test)
{
	struct orlix_tcti_decoded_instruction decoded;

	decoded = orlix_tcti_decode_aarch64(0x1e260020U);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_MOVE,
			decoded.decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_FP_MOVE_SIMD_TO_GPR, decoded.fp_move_op);
	decoded = orlix_tcti_decode_aarch64(0x1e270020U);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_FP_SCALAR_MOVE,
			decoded.decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_FP_MOVE_GPR_TO_SIMD, decoded.fp_move_op);
}

static void orlix_tcti_switch_executes_fp_round_to_gpr_family(struct kunit *test)
{
	static const struct {
		u8 rounding;
		u8 opcode;
		enum orlix_tcti_fp_int_convert_op operation;
		u64 positive;
		u64 negative32;
		u64 negative64;
	} cases[] = {
		{ 0, 0, ORLIX_TCTI_FP_INT_FCVTNS, 2, 0xfffffffeULL, ~1ULL },
		{ 0, 1, ORLIX_TCTI_FP_INT_FCVTNU, 2, 0, 0 },
		{ 1, 0, ORLIX_TCTI_FP_INT_FCVTPS, 2, 0xffffffffULL, ~0ULL },
		{ 1, 1, ORLIX_TCTI_FP_INT_FCVTPU, 2, 0, 0 },
		{ 2, 0, ORLIX_TCTI_FP_INT_FCVTMS, 1, 0xfffffffeULL, ~1ULL },
		{ 2, 1, ORLIX_TCTI_FP_INT_FCVTMU, 1, 0, 0 },
		{ 3, 0, ORLIX_TCTI_FP_INT_FCVTZS, 1, 0xffffffffULL, ~0ULL },
		{ 3, 1, ORLIX_TCTI_FP_INT_FCVTZU, 1, 0, 0 },
		{ 0, 4, ORLIX_TCTI_FP_INT_FCVTAS, 2, 0xfffffffeULL, ~1ULL },
		{ 0, 5, ORLIX_TCTI_FP_INT_FCVTAU, 2, 0, 0 },
	};
	struct pt_regs regs;
	size_t index;
	u8 is_64bit;
	u8 source_double;

	for (index = 0; index < ARRAY_SIZE(cases); index++) {
		for (is_64bit = 0; is_64bit < 2; is_64bit++) {
			for (source_double = 0; source_double < 2;
			     source_double++) {
				struct orlix_tcti_decoded_instruction decoded;
				u64 expected_negative = cases[index].negative32;
				int ret;

				if (is_64bit)
					expected_negative = cases[index].negative64;

				memset(&regs, 0xa5, sizeof(regs));
				regs.pc = 0x9500;
				current->thread.user_fpcr = BIT(22) | BIT(23);
				current->thread.user_fpsr = 0;
				current->thread.user_simd[14] = source_double ?
					0x3ff8000000000000ULL : 0x3fc00000ULL;
				current->thread.user_simd[15] = 0x55aa55aa55aa55aaULL;
				decoded = orlix_tcti_decode_aarch64(
					orlix_tcti_test_encode_fp_round_to_gpr(
						cases[index].rounding,
						cases[index].opcode, is_64bit,
						source_double, 24, 7));
				KUNIT_ASSERT_EQ(test, cases[index].operation,
						decoded.fp_int_op);
				ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
									 &decoded, NULL);
				KUNIT_EXPECT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, cases[index].positive,
						regs.regs[24]);
				KUNIT_EXPECT_EQ(test, 0x9504ULL, regs.pc);
				KUNIT_EXPECT_EQ(test,
						0x55aa55aa55aa55aaULL,
						current->thread.user_simd[15]);

				regs.pc = 0x9600;
				current->thread.user_fpsr = 0;
				current->thread.user_simd[14] = source_double ?
					0xbff8000000000000ULL : 0xbfc00000ULL;
				ret = orlix_tcti_switch_debug_execute_decoded(NULL, &regs,
									 &decoded, NULL);
				KUNIT_EXPECT_EQ(test, 0, ret);
				KUNIT_EXPECT_EQ(test, expected_negative,
						regs.regs[24]);
				KUNIT_EXPECT_EQ(test, 0x9604ULL, regs.pc);
				if (cases[index].opcode & 1)
					KUNIT_EXPECT_TRUE(test,
							  current->thread.user_fpsr & BIT(0));
			}
		}
	}
}

