static void orlix_tcti_cssc_scalar_source_bindings(struct kunit *test)
{
	size_t index;

	for (index = 0; index < ARRAY_SIZE(orlix_tcti_cssc_scalar_source_leaves);
	     index++) {
		const struct orlix_tcti_cssc_scalar_source_leaf *leaf =
			&orlix_tcti_cssc_scalar_source_leaves[index];
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(leaf->pattern);

		KUNIT_EXPECT_NE_MSG(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
			decoded.decode_class, "%u %s", leaf->ordinal, leaf->name);
	}
}

static void orlix_tcti_cssc_scalar_executes_production_path(struct kunit *test)
{
	size_t index;

	for (index = 0; index < ARRAY_SIZE(orlix_tcti_cssc_scalar_source_leaves);
	     index++) {
		const struct orlix_tcti_cssc_scalar_source_leaf *leaf =
			&orlix_tcti_cssc_scalar_source_leaves[index];
		struct pt_regs regs = { };
		struct orlix_tcti_decoded_instruction decoded =
			orlix_tcti_decode_aarch64(leaf->pattern | 3U | (4U << 5) |
					    (5U << 16));

		regs.regs[4] = leaf->left;
		regs.regs[5] = leaf->right;
		KUNIT_ASSERT_EQ_MSG(test, 0,
			orlix_tcti_execute_decoded_semantics(NULL, &regs, &decoded, NULL),
			"%u %s", leaf->ordinal, leaf->name);
		KUNIT_EXPECT_EQ_MSG(test, leaf->expected, regs.regs[3],
			"%u %s", leaf->ordinal, leaf->name);
		KUNIT_EXPECT_EQ(test, (unsigned long)sizeof(u32), regs.pc);
	}
}

static void orlix_tcti_cssc_scalar_rejects_reserved_encodings(struct kunit *test)
{
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x5ac02400U).decode_class);
	KUNIT_EXPECT_EQ(test, ORLIX_TCTI_DECODE_UNSUPPORTED,
		orlix_tcti_decode_aarch64(0x1ac07000U).decode_class);
}

